// Function to get the user code from localStorage
async function getUserCode() {
  const questionData = await chrome.storage.local.get("question_data");
  if (!questionData) return null;

  let questionId: string;
  try {
    const parsedData = questionData.question_data;
    questionId = parsedData?.questionId || "";
  } catch (error) {
    console.error("Failed to parse question_data:", error);
    return null;
  }

  if (!questionId) return null;

  const regex = new RegExp(`^${questionId}.*-updated-time$`);
  let mostRecentKey = "";
  let mostRecentTimestamp = -Infinity;

  Object.keys(localStorage).forEach((key) => {
    // console.log('scrapedData key', key,regex , regex.test(key),localStorage[key], questionId)
    if (regex.test(key)) {
      const timestamp = Number(localStorage[key]);
      if (timestamp > mostRecentTimestamp) {
        mostRecentTimestamp = timestamp;
        mostRecentKey = key;
      }
    }
  });

  if (!mostRecentKey) {
    return null;
  }

  const userCodeIdentifierKey = mostRecentKey.split("-")[0];
  if (!userCodeIdentifierKey) {
    return null;
  }
  // console.log('scrapedData userCodeIdentifierKey', mostRecentKey, userCodeIdentifierKey, localStorage.getItem(userCodeIdentifierKey))
  return localStorage.getItem(userCodeIdentifierKey);
}

// Utility function to handle onBeforeScrape actions
async function handleOnBeforeScrape(parentElement: Element, onBeforeScrape: any) {
  if (!onBeforeScrape || !onBeforeScrape.clickSelector) return;

  const clickableElements = parentElement.querySelectorAll(onBeforeScrape.clickSelector);
  for (const element of clickableElements) {
    try {
      (element as HTMLElement).click();
      // Wait a bit for any animations/changes to complete
      await new Promise(resolve => setTimeout(resolve, 500));
    } catch (error) {
      console.error("Failed to click element:", error);
    }
  }
}

// Utility function to scrape content from the page
async function scrapeContent(content: any[]): Promise<string> {
  let scrapedData = "";
  for (const item of content) {
    if (item.useFunction) {
      const userCode = await item.functionName();
      if (userCode) {
        scrapedData += item.prefix + userCode + "\n";
      }
    } else {
      const selectors = Array.isArray(item.jsPath) ? item.jsPath : [item.jsPath];
      // Try each selector in order until we find a match
      let foundMatch = false;
      for (const selector of selectors) {
        const elements = document.querySelectorAll(selector);
        if (elements.length > 0) {
          for (const element of elements) {
            const elementText = item.toScrape === "innerText" ? element.innerText : element.innerHTML;
            if (!item.validate || item.validate(elementText)) {
              const data = item.prefix + elementText;
              scrapedData += data.trim() + "\n";
              foundMatch = true;
              break; // Exit the elements loop after first valid match
            }
          }
          if (foundMatch) break; // Exit the selectors loop if we found a valid match
        }
      }
    }
  }
  return scrapedData;
}

// Function to check if the current URL matches the regex pattern
function urlMatches(pattern: string) {
  const regex = new RegExp(pattern.replace("*", ".*"));
  return regex.test(window.location.href);
}

// Main function to scrape data based on the current domain and URL
export default async function scrapeData(url?: string) {
  const currentHost = url ? new URL(url).host : document.location.host;
  let scrapedData = "";
  let patternMatched = false;
  if (!config.domains.hasOwnProperty(currentHost)) {
    const domainConfig = config?.default;
    if (domainConfig.patterns) {
      for (const pattern of domainConfig.patterns) {
        scrapedData += await scrapeContent(pattern.content);
        patternMatched = true;
      }
    }
    let finalScrapedData = scrapedData.slice(0, 10000);
    return finalScrapedData;
  }
  const domainConfig = config.domains[currentHost];

  if (domainConfig.patterns) {
    for (const pattern of domainConfig.patterns) {
      if (urlMatches(pattern.urlRegex)) {
        scrapedData += await scrapeContent(pattern.content);
        patternMatched = true;
      }
    }
  }

  if (currentHost === "takeuforward.org") {
    const isCodingProblem = document.querySelector(".react-split");
    if (isCodingProblem) {
      scrapedData += await scrapeContent(domainConfig.monacoEditorContent);
      patternMatched = true;
    }
  }

  if (!patternMatched && domainConfig.default) {
    scrapedData += await scrapeContent(domainConfig.default);
  }

  let finalScrapedData = scrapedData.slice(0, 10000);

  return finalScrapedData;
}
