// ChatGPT prompt capture for chat.openai.com and chatgpt.com
import { extractTextFromElement, normalizeWhitespace } from "../utils/text-utils";

declare global {
    interface Window {
        __mentorai_chatgpt_injected__?: boolean;
    }
}

(function initChatGPTCapture() {
    try {
        if (window.__mentorai_chatgpt_injected__) return;
        window.__mentorai_chatgpt_injected__ = true;
    } catch (_) { }

    // Support both ProseMirror contenteditable and fallback textarea
    const INPUT_SELECTORS = [
        'div.ProseMirror#prompt-textarea[contenteditable="true"]',
        'div.ProseMirror[contenteditable="true"]',
        '#prompt-textarea[contenteditable="true"]',
        'div[contenteditable="true"][id="prompt-textarea"]',
        'textarea[name="prompt-textarea"]',
        'textarea._fallbackTextarea_38p30_2',
        'textarea[data-testid="promptTextarea"]',
        'textarea[placeholder*="Send a message"]',
        'textarea[aria-label*="Send"]',
        'form textarea',
    ];

    const SEND_BUTTON_SELECTORS = [
        'button[data-testid="send-button"]',
        'button[aria-label*="Send"]',
        '[data-testid="composer-trailing-actions"] button',
        'form button[type="submit"]',
    ];

    const USER_MESSAGE_NODE_SELECTORS = [
        '[data-message-author-role="user"]',
        '[data-testid^="conversation-turn-"][data-role="user"]',
        '[data-testid^="conversation-turn"][data-message-author-role="user"]',
        '[data-testid="message-bubble-user"]',
    ];

    const CONVERSATION_CONTAINER_SELECTORS = [
        '[data-testid="conversation-turns"]',
        'main [role="feed"]',
        'main div:has([data-message-author-role])',
        'main',
    ];

    let isComposing = false;
    let urlAtInit = location.href;

    // Dedup window (per conversation + normalized query)
    const recentQueries = new Map<string, number>();
    const RECENT_TTL_MS = 10000;

    // Per-conversation user message counters for query_type labeling
    const conversationCounters = new Map<string, number>();

    const getConversationIdFromUrl = (): string | null => {
        const m = location.pathname.match(/\/c\/([a-zA-Z0-9\-]+)/);
        return m ? m[1] : null;
    };

    const conversationKey = (): string => [location.host, getConversationIdFromUrl() || location.pathname].join("|");

    const ensureCounterInitializedFromDom = () => {
        const key = conversationKey();
        if (conversationCounters.has(key)) return;
        const container = getConversationContainer();
        const existing = queryAllAny(USER_MESSAGE_NODE_SELECTORS, container).length;
        conversationCounters.set(key, existing);
    };

    const makeDedupKey = (query: string): string => {
        return [conversationKey(), normalizeWhitespace(query)].join("|");
    };

    const isRecentAndMark = (key: string): boolean => {
        const now = Date.now();
        const prev = recentQueries.get(key);
        if (prev && now - prev < RECENT_TTL_MS) return true;
        recentQueries.set(key, now);
        for (const [k, t] of recentQueries) {
            if (now - t > RECENT_TTL_MS) recentQueries.delete(k);
        }
        return false;
    };

    const isVisible = (el: Element | null): boolean => {
        if (!el) return false;
        const rect = (el as HTMLElement).getBoundingClientRect();
        const style = window.getComputedStyle(el as Element);
        return rect.width > 0 && rect.height > 0 && style.visibility !== "hidden" && style.display !== "none";
    };

    const queryAny = (selectors: string[], root: ParentNode = document): Element | null => {
        for (const sel of selectors) {
            const el = (root as Element | Document).querySelector(sel);
            if (el && isVisible(el)) return el as Element;
        }
        return null;
    };

    const queryAllAny = (selectors: string[], root: ParentNode = document): Element[] => {
        const result: Element[] = [];
        for (const sel of selectors) {
            (root as Element | Document).querySelectorAll(sel).forEach((el) => {
                if (isVisible(el)) result.push(el);
            });
        }
        return result;
    };

    const getPromptEditor = (): Element | null => queryAny(INPUT_SELECTORS);
    const getSendButtons = (): Element[] => queryAllAny(SEND_BUTTON_SELECTORS);
    const getConversationContainer = (): Element => queryAny(CONVERSATION_CONTAINER_SELECTORS) || document.body;

    const sendLearningQueryEvent = (query: string, meta?: Record<string, any>) => {
        const key = conversationKey();
        const count = conversationCounters.get(key) || 0;
        const queryType = count === 0 ? "initial" : "followup";

        const eventPayload = {
            action: "sendAnalytics",
            url: location.href,
            eventName: "Query Captured",
            eventProperties: {
                platform: "chatgpt",
                conversationId: getConversationIdFromUrl(),
                query: normalizeWhitespace(query),
                query_type: queryType,
                ...meta,
            },
        };
        try {
            chrome.runtime.sendMessage(eventPayload);
        } catch (e) { }

        // increment counter after dispatch
        conversationCounters.set(key, count + 1);
    };

    const dispatchFinal = (query: string, meta?: Record<string, any>) => {
        ensureCounterInitializedFromDom();
        const norm = normalizeWhitespace(query);
        if (!norm) return;
        const dKey = makeDedupKey(norm);
        if (isRecentAndMark(dKey)) return;
        sendLearningQueryEvent(norm, meta);
    };

    const extractEditorText = (el: Element | null): string => {
        if (!el) return "";
        if (el instanceof HTMLTextAreaElement) return el.value || "";
        return normalizeWhitespace((el as HTMLElement).innerText || el.textContent || "");
    };

    const observeUserMessages = () => {
        const container = getConversationContainer();

        const tryHandleNode = (node: Node) => {
            if (node.nodeType !== Node.ELEMENT_NODE) return;
            const el = node as Element;
            let userNode: Element | null = null;
            if (USER_MESSAGE_NODE_SELECTORS.some((sel) => (el as any).matches?.(sel))) {
                userNode = el;
            } else {
                userNode = queryAny(USER_MESSAGE_NODE_SELECTORS, el);
            }
            if (userNode) {
                const text = extractTextFromElement(userNode);
                const norm = normalizeWhitespace(text);
                if (norm) {
                    dispatchFinal(norm, { captured_by: "dom-message-insert" });
                }
            }
        };

        // Initialize counter from existing DOM
        ensureCounterInitializedFromDom();

        // Initial sweep (optional capture of last user message on load)
        const existing = queryAllAny(USER_MESSAGE_NODE_SELECTORS, container);
        if (existing.length > 0) {
            const last = existing[existing.length - 1];
            const text = extractTextFromElement(last);
            const norm = normalizeWhitespace(text);
            if (norm) {
                // do not dispatch; counter already initialized
            }
        }

        const mo = new MutationObserver((mutations) => {
            for (const m of mutations) {
                m.addedNodes.forEach(tryHandleNode);
                // detect edits to existing user messages
                let targetEl: Element | null = null;
                const t = m.target as Node;
                if (t.nodeType === Node.ELEMENT_NODE) targetEl = t as Element;
                else targetEl = (t as any).parentElement || null;
                if (targetEl) {
                    const userAncestor = (targetEl as any).closest?.(USER_MESSAGE_NODE_SELECTORS.join(","));
                    if (userAncestor) {
                        const text = extractTextFromElement(userAncestor);
                        const norm = normalizeWhitespace(text);
                        if (norm) {
                            dispatchFinal(norm, { captured_by: "dom-message-edit" });
                        }
                    }
                }
            }
        });

        mo.observe(container, { childList: true, subtree: true, characterData: true });
    };

    const wireInputListeners = () => {
        let editor = getPromptEditor();

        const bindKeydown = (el: Element) => {
            el.addEventListener(
                "keydown",
                (e: Event) => {
                    try {
                        const ke = e as KeyboardEvent;
                        if (isComposing) return;
                        if (ke.key !== "Enter") return;
                        if (ke.shiftKey || ke.ctrlKey || ke.altKey || ke.metaKey) return;
                        const val = extractEditorText(el);
                        if (normalizeWhitespace(val)) {
                            dispatchFinal(val, { captured_by: "keydown-enter" });
                        }
                    } catch { }
                },
                true
            );
        };

        // IME composition guards
        document.addEventListener("compositionstart", () => (isComposing = true), true);
        document.addEventListener("compositionend", () => (isComposing = false), true);

        // Submit listener (covers Enter when the site uses a form)
        document.addEventListener(
            "submit",
            (e) => {
                try {
                    const form = e.target as HTMLFormElement;
                    if (!(form instanceof HTMLFormElement)) return;
                    const inputEl = (queryAny(INPUT_SELECTORS, form) as Element) || form.querySelector("textarea");
                    const val = extractEditorText(inputEl as Element);
                    if (normalizeWhitespace(val)) {
                        dispatchFinal(val, { captured_by: "submit-event" });
                    }
                } catch { }
            },
            true
        );

        if (editor) bindKeydown(editor);

        // Send button clicks
        const bindSendButtons = () => {
            getSendButtons().forEach((btn: any) => {
                if ((btn as any).__mentorai_bound__) return;
                (btn as any).__mentorai_bound__ = true;

                btn.addEventListener(
                    "click",
                    () => {
                        try {
                            const el = getPromptEditor() || editor;
                            const val = extractEditorText(el as Element);
                            if (normalizeWhitespace(val)) {
                                dispatchFinal(val, { captured_by: "send-button" });
                            }
                        } catch { }
                    },
                    true
                );
            });
        };

        bindSendButtons();

        // Re-bind on DOM changes
        const rebinder = new MutationObserver(() => {
            editor = getPromptEditor();
            if (editor) bindKeydown(editor);
            bindSendButtons();
        });
        rebinder.observe(document.documentElement, { childList: true, subtree: true });
    };

    const observeSpaNavigation = (onNavigate?: () => void) => {
        const notifyIfChanged = () => {
            if (urlAtInit !== location.href) {
                urlAtInit = location.href;
                onNavigate?.();
                // reset counter on navigation
                conversationCounters.delete(conversationKey());
            }
        };
        const wrapHistory = (type: "pushState" | "replaceState") => {
            const orig = history[type];
            (history as any)[type] = function () {
                const ret = orig.apply(this, arguments as any);
                setTimeout(notifyIfChanged, 0);
                return ret;
            };
        };
        wrapHistory("pushState");
        wrapHistory("replaceState");
        window.addEventListener("popstate", notifyIfChanged);
        setInterval(notifyIfChanged, 1000);
    };

    // Only activate on ChatGPT domains
    const isChatGPTDomain = /(^|\.)chatgpt\.com$/.test(location.hostname) || /(^|\.)openai\.com$/.test(location.hostname) || location.hostname === "chat.openai.com";
    if (!isChatGPTDomain) return;

    observeUserMessages();
    wireInputListeners();
    observeSpaNavigation(() => {
        // no-op, selectors will rebind via MutationObserver
    });
})(); 