import React from 'react'
import { MentorAi } from '../../../src/types/type'
import chatSmile from '../../assets/icons/chat-smile.svg'
import brain from '../../assets/icons/brain.svg'
import code from '../../assets/icons/code.svg'

interface SelectionWidgetProps {
  mentoraiData: MentorAi;
  position: {
    x: number;
    y: number;
  } | null;
  selectedText: string | undefined;
}

const SelectionWidget: React.FC<SelectionWidgetProps> = ({mentoraiData, position, selectedText }) => {

  const handleDirectActionClick = (action: string) => {
    const currentUrl = window.location.href;
    chrome.runtime.sendMessage({
      action: "easyActionClicked",
      easy_action: action,
      easy_action_title:action,
      url: currentUrl,
      is_side_panel_opened: false,
      section_title: "Selection Widget",
      easy_action_message: action,
    })
  }

  const handleAskInChatAction=(action:string)=>{
    chrome.runtime.sendMessage({ action: "openSidePanel" }, (response) => {
      setTimeout(() => {
        chrome.runtime.sendMessage({
          action: "askInChat",
          text:selectedText
        })
      }, 3000)
    })
    const currentUrl = window.location.href;
    chrome.runtime.sendMessage({ action: "sendAnalytics", url: currentUrl, eventName: 'Button Clicked', eventProperties: {
      button_name: "Ask In Chat",
      text:selectedText,
      url: currentUrl,
    } })
  }

  const hasEditorParent = () => {
    if (!position) return false;
    const selection = window.getSelection();
    if (!selection?.rangeCount) return false;
    
    let element = selection.getRangeAt(0).commonAncestorContainer as Element;
    if (element.nodeType === Node.TEXT_NODE) {
      element = element.parentElement as Element;
    }
    
    while (element) {
      if (element.id === 'editor') return true;
      element = element.parentElement as Element;
    }
    return false;
  };

  const baseActions = [
    {
      icon:chatSmile,
      text:"Ask In Chat",
      onClick:handleAskInChatAction
    }
  ];

  const editorActions = [
    {
      icon:brain,
      text:"Explain",
      onClick:handleDirectActionClick
    },
    {
      icon:code,
      text:"Check Syntax",
      onClick:handleDirectActionClick
    }
  ];

  const actions = hasEditorParent() ? [...baseActions, ...editorActions] : baseActions;
  const isWidgetVisibleOnPageTap = position?.x == 5 && position?.y === 5 && !hasEditorParent()
  if (!position || isWidgetVisibleOnPageTap) return null;

  return (
    <div
      className="fixed z-50 bg-[#06060B] border border-[#363645] rounded-[12px] p-[6px] shadow-[0px_4px_8px_0px_rgba(255,255,255,0.04)]"
      style={{
        left: position.x,
        top: position.y,
        transform: 'translateY(8px)',
      }}
    >
      <div className="flex items-center gap-[4px]">
        <img
          src={mentoraiData?.aiPhotoUrl || mentoraiData?.photoUrl || ""}
          className="h-[16px] w-[16px] rounded-full"
          alt="avatar"
        />
        <span className='w-[1px] h-[16px] bg-[#363645] rounded-[8px]'/>
        {actions.map((action, index) => (
          <button key={index} className='flex items-center gap-[4px] pl-[4px] pr-[6px] rounded-[8px] transition-all duration-300 hover:bg-[#212431]' onClick={()=>action.onClick(action.text)}> 
            <img src={action.icon} alt={action.text} className='w-[16px] h-[16px]'/>
            <span className='text-[12px] text-[#F2F2F2]'>{action.text}</span>
          </button>
        ))}
      </div>
    </div>
  );
};

export default SelectionWidget;