import React, { createContext, ReactNode, useContext, useEffect, useState } from "react";

interface PageContextType {
  isLeetCodeSite: boolean;
  isYouTubeSite: boolean;
  isLeetCodeProblemPage: boolean;
  isGeekForGeeksSite: boolean;
  isChatGPTSite: boolean;
  currentUrl: string;
  isYoutubeLearningVideo: boolean;
  setIsYoutubeLearningVideo: (isYoutubeLearningVideo: boolean) => void;
  isSidePanelOpen: boolean;
  setIsSidePanelOpen: (isSidePanelOpen: boolean) => void;
  llmClassificationResponse: any;
  setLlmClassificationResponse: (llmClassificationResponse: any) => void;
  hideWidgetForThisTab: boolean;
  setHideWidgetForThisTab: (hideWidgetForThisTab: boolean) => void;
  hideWidgetFor24Hours: boolean;
  setHideWidgetFor24Hours: (hideWidgetFor24Hours: boolean) => void;
  disabledSites: string[];
  setDisabledSites: (disabledSites: string[]) => void;
}

const defaultContextValues: PageContextType = {
  isLeetCodeSite: false,
  isYouTubeSite: false,
  isLeetCodeProblemPage: false,
  isGeekForGeeksSite: false,
  isChatGPTSite: false,
  currentUrl: "",
  isYoutubeLearningVideo: false,
  setIsYoutubeLearningVideo: () => {},
  isSidePanelOpen: false,
  setIsSidePanelOpen: () => {},
  llmClassificationResponse: null,
  setLlmClassificationResponse: () => {},
  hideWidgetForThisTab: false,
  setHideWidgetForThisTab: () => {},
  hideWidgetFor24Hours: false,
  setHideWidgetFor24Hours: () => {},
  disabledSites: [],
  setDisabledSites: () => {}
};

export const PageContext = createContext<PageContextType>(defaultContextValues);

export const PageContextProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isSidePanelOpen, setIsSidePanelOpen] = useState(false);
  const [isLeetCodeSite, setIsLeetCodeSite] = useState(window.location.hostname === "leetcode.com");
  const [isYouTubeSite, setIsYouTubeSite] = useState(window.location.hostname === "www.youtube.com/watch");
  const [isYoutubeLearningVideo, setIsYoutubeLearningVideo] = useState(false);
  const [isLeetCodeProblemPage, setIsLeetCodeProblemPage] = useState(window.location.href.includes("https://leetcode.com/problems/"));
  const [isGeekForGeeksSite, setIsGeekForGeeksSite] = useState(window.location.href.includes("https://www.geeksforgeeks.org/problems"));
  const [isChatGPTSite, setIsChatGPTSite] = useState(window.location.href.includes("chatgpt.com"));
  const [currentUrl, setCurrentUrl] = useState(window.location.href);
  const [llmClassificationResponse, setLlmClassificationResponse] = useState<any>({
    done: false,
    learningVideo: false,
  });

  const [hideWidgetForThisTab, setHideWidgetForThisTab] = useState(false);
  const [hideWidgetFor24Hours, setHideWidgetFor24Hours] = useState(false);
  const [disabledSites, setDisabledSites] = useState<string[]>([]);

  const handleMessage = (message: any, sender: any, sendResponse: any) => {
    if (message.action === "updateContentScriptOnTabUpdate" && message.url) {
      try {
        const url = window.location.href;
        setCurrentUrl(url);
        setIsLeetCodeSite(url.includes("leetcode.com"));
        setIsYouTubeSite(url.includes("youtube.com/"));
        setIsLeetCodeProblemPage(url.includes("https://leetcode.com/problems/"));
        setIsGeekForGeeksSite(url.includes("https://www.geeksforgeeks.org/problems"));
        setIsChatGPTSite(url.includes("chatgpt.com"));
      } catch (error) {
        console.error("Error parsing URL in PageContext:", error);
      }
    }
    if (message.action === "sendYoutubeVideoCategory" && message.url) {
      const LEARNING_CATEGORIES = new Set([
        'Education',            // 27
        'Howto & Style',        // 26
        'Science & Technology',  // 28
        'People & Blogs'
      ]);
      setIsYoutubeLearningVideo(LEARNING_CATEGORIES.has(message.videoCategory));
    }
    return true;
  };

  // Listen for tab updates
  useEffect(() => {
    chrome.runtime.sendMessage({ action: "get_window_id" }, (response) => {
      chrome.storage.local.get("is_side_panel_opened").then(result => {
        setIsSidePanelOpen(result.is_side_panel_opened?.[response.windowId] || false);
      });
    });

    chrome.runtime.onMessage.addListener(handleMessage);

    return () => {
      chrome.runtime.onMessage.removeListener(handleMessage);
    };
  }, []);

  const storageListener = (changes: { [key: string]: chrome.storage.StorageChange }) => {
    if (changes.widget_disabled_sites) {
      setDisabledSites(changes.widget_disabled_sites.newValue || []);
    }
  }

  // Initial values based on the current URL
  useEffect(() => {
    try {
      const url = window.location.href;
      const urlObj = new URL(url);
      
      setCurrentUrl(url);
      setIsLeetCodeSite(urlObj.hostname === "leetcode.com");
      setIsYouTubeSite(urlObj.hostname === "www.youtube.com" && urlObj.pathname === "/watch");
      setIsLeetCodeProblemPage(url.includes("https://leetcode.com/problems/"));
      setIsChatGPTSite(url.includes("chatgpt.com"));
    } catch (error) {
      console.error("Error setting initial URL state in PageContext:", error);
    }

    chrome.storage.local.get(["widget_hide_until", "widget_disabled_sites", "hide_widget_for_this_tab"]).then(result => {
      const hideUntil = result.widget_hide_until;
      if (hideUntil && hideUntil > Date.now()) {
        setHideWidgetFor24Hours(true);
      }
      const disabledSites = result.widget_disabled_sites;
      if (disabledSites) {
        setDisabledSites(disabledSites);
      }
      const hideWidgetForThisTab = result.hide_widget_for_this_tab;
      if (hideWidgetForThisTab) {
        chrome.runtime.sendMessage({ action: "get_tab_id" }, (response) => {
          if (hideWidgetForThisTab === response.tabId) {
            setHideWidgetForThisTab(true);
          }
        });
      }
    });

    chrome.storage.onChanged.addListener(storageListener);

    return () => {
      chrome.storage.onChanged.removeListener(storageListener);
    }
  }, []);

  // Memoize the context value to prevent unnecessary re-renders
  const contextValue = React.useMemo(
    () => ({
      isLeetCodeSite,
      isYouTubeSite,
      isLeetCodeProblemPage,
      isGeekForGeeksSite,
      isChatGPTSite,
      currentUrl,
      isYoutubeLearningVideo,
      setIsYoutubeLearningVideo,
      isSidePanelOpen,
      setIsSidePanelOpen,
      llmClassificationResponse,
      setLlmClassificationResponse,
      hideWidgetForThisTab,
      setHideWidgetForThisTab,
      hideWidgetFor24Hours,
      setHideWidgetFor24Hours,
      disabledSites,
      setDisabledSites
    }),
    [isLeetCodeSite, isYouTubeSite, isLeetCodeProblemPage, isGeekForGeeksSite, isChatGPTSite, currentUrl, isYoutubeLearningVideo, isSidePanelOpen, hideWidgetForThisTab, hideWidgetFor24Hours, disabledSites]
  );

  return (
    <PageContext.Provider
      value={contextValue}
    >
      {children}
    </PageContext.Provider>
  );
};

export const usePageContext = () => {
  const context = useContext(PageContext);
  if (!context) {
    throw new Error("usePageContext must be used within a PageContextProvider");
  }
  return context;
};

