import React from 'react';
import { AnimatePresence } from 'framer-motion';
import { LoaderWithThreeDots } from "../../../../common/loader/loader";
import type { WidgetContentProps } from '../types';
import MentorAiButton from '../../../../common/button/mentorai-button';
import ArrowRightIcon from '../../../assets/icons/arrow-right2.svg'

export const WidgetContent: React.FC<WidgetContentProps> = ({
  widgetState,
  isSidePanelOpen,
  handleStartSession,
  menteeData
}) => {
  const sessionStartText = {
    "leetcode.com": `Hey ${menteeData?.name?.split(" ")[0]}, let’s solve this together! Use the quick guidance buttons on the LeetCode screen or chat with me for help.`,
    "youtube.com": `Hey ${menteeData?.name?.split(" ")[0]}, I’ll turn on “Learning Session” for this video. If it doesn’t work, I’m right here to answer your questions or discuss!`,
    "default": `Hey ${menteeData?.name?.split(" ")[0]}, welcome to our learning session! I’m right here to discuss the topic with you or answer your questions.`
  }

  const getCurrentHostnameText = () => {
    const hostname = window.location.hostname;
    const matchingKey = Object.keys(sessionStartText).find(key =>
      key !== 'default' && hostname.includes(key)
    );
    return sessionStartText[matchingKey as keyof typeof sessionStartText] || sessionStartText.default;
  }

  return (
    <div className="flex items-center justify-center">
      <AnimatePresence mode="wait">
        {widgetState === "page_reading" && (
          <div className="flex items-center mr-[10px] gap-1">
            <LoaderWithThreeDots width="20" height="20" />
            <span className="text-[12px] italic leading-[18px] tracking-[-0.12px] whitespace-nowrap text-[#F2F2F2]">
              Reading{" "}
              <span className="bg-gradient-to-r from-[#F2F2F2] via-[#F2F2F2] !to-[#575762] bg-clip-text text-transparent">
                page contents
              </span>
            </span>
          </div>
        )}
        {widgetState === "hover" && !isSidePanelOpen && (
          <p className="text-[12px] font-bold text-[#A5A1F7] mr-[8px] whitespace-nowrap flex items-center gap-[1px]">
            Open Chat
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M6.25 5.5C6.66421 5.5 7 5.16421 7 4.75C7 4.33579 6.66421 4 6.25 4C5.83579 4 5.5 4.33579 5.5 4.75C5.5 5.16421 5.83579 5.5 6.25 5.5ZM6.25 8.75C6.66421 8.75 7 8.4142 7 8C7 7.5858 6.66421 7.25 6.25 7.25C5.83579 7.25 5.5 7.5858 5.5 8C5.5 8.4142 5.83579 8.75 6.25 8.75ZM7 11.25C7 11.6642 6.66421 12 6.25 12C5.83579 12 5.5 11.6642 5.5 11.25C5.5 10.8358 5.83579 10.5 6.25 10.5C6.66421 10.5 7 10.8358 7 11.25ZM9.75 5.5C10.1642 5.5 10.5 5.16421 10.5 4.75C10.5 4.33579 10.1642 4 9.75 4C9.3358 4 9 4.33579 9 4.75C9 5.16421 9.3358 5.5 9.75 5.5ZM10.5 8C10.5 8.4142 10.1642 8.75 9.75 8.75C9.3358 8.75 9 8.4142 9 8C9 7.5858 9.3358 7.25 9.75 7.25C10.1642 7.25 10.5 7.5858 10.5 8ZM9.75 12C10.1642 12 10.5 11.6642 10.5 11.25C10.5 10.8358 10.1642 10.5 9.75 10.5C9.3358 10.5 9 10.8358 9 11.25C9 11.6642 9.3358 12 9.75 12Z" fill="#DDDDDF" />
            </svg>
          </p>
        )}
        {widgetState === "start_session" && (
          <div className='flex flex-col px-[12px] pb-[16px] gap-[16px]'>
            <p className="text-[14px] leading-[22px] text-mentorai-text-soft font-bricolage-grotesque">
              {getCurrentHostnameText()}
            </p>
            <MentorAiButton type='primary' size='small' onClick={handleStartSession} classNames='w-full !-tracking-[0.14px] !h-[32px] !text-[14px] !leading-[22px]'>
              Start Session
              <img src={ArrowRightIcon} alt="arrow-right" className='w-[16px] h-[16px] ml-[4px]' />
            </MentorAiButton>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}