import React from 'react';
import { useCustomUI } from '../../../contexts/custom-ui-context/custom-ui-context';
import MentorAiActiveAvatar from '../../mentorai-active-avatar/mentorai-active-avatar';
import MentorAiButton from '../../../../common/button/mentorai-button';
import CompletedIcon from '../../../assets/icons/completed.svg';
import CompletedGrayIcon from '../../../assets/icons/completed-gray.svg';
import { formatTimeDurationFromSeconds } from '../../../utils/learning-session-helper';
import { timeToSeconds } from '../../../../src/utils/str-time-to-seconds';

const CreatedOverlay: React.FC = () => {
  // Destructure new individual states and core learningSession from context
  const {
    learningSession,
    startSelectedSection,
    setSelectedSection, // Use direct setter
    currentSection,
    mentoraiData,
    extractingThumbnails,
    playerMode,
    trackCustomUIEvent,
    getSectionProperties
  } = useCustomUI();

  const isPlayerModeDefault = playerMode === 'DEFAULT';

  const totalSections = learningSession?.sections?.length || 0;
  // Calculate total quizzes correctly by summing quizzes in each section
  const totalQuizzes = learningSession?.sections?.reduce((acc, section) => acc + (section.quizzes?.length || 0), 0) || 0;
  const totalQuizSections = learningSession?.sections?.filter(section => (section.quizzes?.length || 0) > 0).length || 0;
  const currentVideoTimeInSeconds = document.querySelector("video")?.currentTime || 0;
  const currentVideoTime = formatTimeDurationFromSeconds(currentVideoTimeInSeconds);

  const handleStartFromBeginning = () => {
    setSelectedSection(0);
    setTimeout(() => {
      // Call this after selection if immediate start is intended
      startSelectedSection();
    }, 0);
    trackCustomUIEvent("Button Clicked", {
      button_name: "View First Section",
      section: getSectionProperties(0),
    })
  };

  const handleStartFromNow = () => {
    const currentSectionIdx = currentSection || 0; // Use the direct currentSection state
    setSelectedSection(currentSectionIdx);
    setTimeout(() => {
      startSelectedSection(currentVideoTimeInSeconds); // Similar to above, defer actual start or link to a specific play button
    }, 0);
    trackCustomUIEvent("Button Clicked", {
      button_name: "View Current Section",
      section: getSectionProperties(currentSectionIdx),
    })
  };

  const isCurrentVideoDurationIsBetweenFirstSection = currentVideoTimeInSeconds > timeToSeconds(learningSession?.sections[0]?.startTime || '00:00') && currentVideoTimeInSeconds < timeToSeconds(learningSession?.sections[0]?.endTime || '00:00')


  return (
    <div className='flex flex-col'  >
      <div style={{ display: 'flex', gap: 8, marginBottom: 16, marginTop: 16 }}>
        <MentorAiActiveAvatar mentoraiData={mentoraiData} avatarClassName={isPlayerModeDefault ? "h-[16px] w-[16px]" : "h-[20px] w-[20px]"} />
        <p style={{
          fontWeight: 500,
          fontSize: isPlayerModeDefault ? 14 : 16,
          lineHeight: isPlayerModeDefault ? "22px" : "26px",
          color: '#DDDDDF',
          letterSpacing: isPlayerModeDefault ? "0.084px" : "0.096px"
        }}>{mentoraiData?.name} <span style={{ color: '#94939F' }}>Session Created!</span></p>
      </div>

      <div style={{ marginTop: 16 }}>
        <div style={{ display: 'flex', flexDirection: "column", alignItems: 'flex-start', gap: isPlayerModeDefault ? 4 : 8, marginBottom: isPlayerModeDefault ? 24 : 44 }}>
          <div className="flex gap-2">
            <img src={CompletedIcon} alt="completed" className='w-4 h-4' style={{ width: isPlayerModeDefault ? "16px" : "20px", height: isPlayerModeDefault ? "16px" : "20px", marginTop: "4px" }} />
            <p style={{
              fontWeight: 500, lineHeight: isPlayerModeDefault ? '26px' : '30px',
              fontSize: isPlayerModeDefault ? 18 : 20, color: '#DDDDDF'
            }}>Scanned video contents</p>
          </div>
          <p style={{ color: '#94939F', fontSize: isPlayerModeDefault ? 14 : 16, fontWeight: 500, lineHeight: isPlayerModeDefault ? '22px' : '26px', letterSpacing: isPlayerModeDefault ? '0.084px' : '0.096px' }}>First, I need to dig deep into the video to understand its flow.</p>
        </div>

        <div style={{ display: 'flex', flexDirection: "column", alignItems: 'flex-start', gap: isPlayerModeDefault ? 4 : 8, marginBottom: isPlayerModeDefault ? 24 : 44 }}>
          <div className="flex gap-2">
            <img src={CompletedIcon} alt="completed" className='w-4 h-4' style={{ width: isPlayerModeDefault ? "16px" : "20px", height: isPlayerModeDefault ? "16px" : "20px", marginTop: "4px" }} />
            <p style={{
              fontWeight: 500, lineHeight: isPlayerModeDefault ? '26px' : '30px',
              fontSize: isPlayerModeDefault ? 18 : 20, color: '#fff', marginBottom: 4
            }}>Turned video into {totalSections} bite-sized sections</p>
          </div>
          <p style={{ color: '#94939F', fontSize: isPlayerModeDefault ? 14 : 16, fontWeight: 500, lineHeight: isPlayerModeDefault ? '22px' : '26px', letterSpacing: isPlayerModeDefault ? '0.084px' : '0.096px' }}>I'll organise this into small, easy-to-follow slides, each with a quick summary.</p>
        </div>

        <div style={{ display: 'flex', flexDirection: "column", alignItems: 'flex-start', gap: isPlayerModeDefault ? 4 : 8, marginBottom: isPlayerModeDefault ? 0 : 16 }}>
          <div className="flex gap-2">
            <img src={totalQuizzes > 0 ? CompletedIcon : CompletedGrayIcon} alt="completed" className='w-4 h-4' style={{ width: isPlayerModeDefault ? "16px" : "20px", height: isPlayerModeDefault ? "16px" : "20px", marginTop: "4px" }} />
            <p style={{
              fontWeight: 500, lineHeight: isPlayerModeDefault ? '26px' : '30px',
              fontSize: isPlayerModeDefault ? 18 : 20, color: '#fff', marginBottom: 4
            }}>
              {totalQuizzes > 0 ?
                `Added ${totalQuizzes} quizzes in ${totalQuizSections} sections`
                :
                `No quizzes needed for this one!`
              }
            </p>
          </div>
          <p style={{ color: '#94939F', fontSize: isPlayerModeDefault ? 14 : 16, fontWeight: 500, lineHeight: isPlayerModeDefault ? '22px' : '26px', letterSpacing: isPlayerModeDefault ? '0.084px' : '0.096px' }}>
            {totalQuizzes > 0 ?
              `I'll add quick quizzes inside key sections to test your understanding as we move!`:
              `The concepts are easy to follow - no quizzes needed this time!`
            }
          </p>
        </div>
      </div>

      <div style={{ display: 'flex', gap: 12, marginTop: 24, marginBottom: 24, flexWrap: "wrap" }}>
        <MentorAiButton type="primary" size="large" classNames=' !w-fit whitespace-nowrap' style={{ height: isPlayerModeDefault ? "32px" : "40px", paddingLeft: isPlayerModeDefault ? "12px" : "24px", paddingRight: isPlayerModeDefault ? "12px" : "24px" }} onClick={handleStartFromBeginning}>
          <span style={{ fontWeight: 500, fontSize: 14, lineHeight: '22px' }}>
            View First Section
          </span>
        </MentorAiButton>
        {!isCurrentVideoDurationIsBetweenFirstSection && (
          <MentorAiButton type="secondary" size="large" classNames=' !w-fit whitespace-nowrap' style={{ height: isPlayerModeDefault ? "32px" : "40px", paddingLeft: isPlayerModeDefault ? "12px" : "24px", paddingRight: isPlayerModeDefault ? "12px" : "24px" }} onClick={handleStartFromNow}>
            <span style={{ fontWeight: 500, fontSize: 14, lineHeight: '22px' }}>
              View Current Section {extractingThumbnails ? "" : currentVideoTime}
            </span>
          </MentorAiButton>
        )}
      </div>
    </div>
  );
};

export default CreatedOverlay; 