import { motion, AnimatePresence } from "framer-motion";
import LeecoIcon from "../../../../assets/icons/leeco-icon.svg";
import ArrowDouble from "../../../../assets/icons/double-arrow-right.svg";
import SparkleVector from "../../../../assets/icons/sparkle-vector-icon.svg";
import HideEye from "../../../../assets/icons/hide-eye.svg";
import useLeecoHelp from "./use-leeco-help";
import { useCustomUI } from "../../../../contexts/custom-ui-context/custom-ui-context";
import ClickAwayListener from "../../../../../src/custom-hooks/use-clickaway-listner";
import MentorAiButton from "../../../../../common/button/mentorai-button";

const LeecoHelp = () => {
  const {
    isHovered,
    showEasyActions,
    setShowEasyActions,
    isDoubleArrowHovered,
    setIsLeecoIconHovered,
    isLeecoIconHovered,
    setIsDoubleArrowHovered,
    isHidden,
    isVideoFirstLoad,
    showConfirmationModal,
    setShowConfirmationModal,
    showHideEye,
    defaultEasyActionOptions,
    showCurrentDynamicEasyAction,
    currentDynamicEasyAction,
    hideCurrentDynamicEasyAction,
    setShowHideEye,
    handleMouseEnter,
    handleMouseLeave,
    setIsHovered,
    handleEasyActionClick,
    setIsHidden
  } = useLeecoHelp();

  const { playerMode } = useCustomUI();

  if (isHidden) return null;

  const optionsToShow = showCurrentDynamicEasyAction
    ? [currentDynamicEasyAction]
    : currentDynamicEasyAction.follow_up !== "" ? [
      ...defaultEasyActionOptions.slice(0, 2),
      currentDynamicEasyAction
    ] : defaultEasyActionOptions;

  const shouldShowEasyActions = showCurrentDynamicEasyAction || showEasyActions;
  // const shouldShowEasyActions = true;

  return (
    <div className="flex items-end gap-[4px] pt-5 pb-2 pl-2" onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave}>
      {/* Easy Actions */}
      <div className="flex items-end justify-end gap-[4px] flex-wrap">
        {(showHideEye && !showCurrentDynamicEasyAction) &&
          <div className="relative">
            <motion.img
              key={`hide-eye-${showHideEye}`}
              src={HideEye}
              alt="hide eye"
              style={{
                padding: "6px"
              }}
              className="rounded-full cursor-pointer backdrop-blur-[4px] h-[30px] w-[30px] justify-center items-center flex bg-[rgba(0,0,0,0.64)] hover:bg-[rgba(0,0,0,0.75)]"
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.8 }}
              transition={{ duration: 0.45 }}
              onClick={() => {
                setShowConfirmationModal(!showConfirmationModal)
                chrome.runtime.sendMessage({
                  action: "sendAnalytics",
                  url: window.location.href,
                  eventName: "Turn Off Suggestions Toggled",
                  eventProperties: {
                    toggled: showConfirmationModal ? 'off' : 'on',
                  },
                });
              }}
            />

            {showConfirmationModal &&
              <ClickAwayListener>
                <motion.div
                  initial={{ opacity: 0, y: 5 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: 5 }}
                  transition={{ duration: 0.2 }}
                  style={{ width: '270px', padding: '12px' }} className="absolute bottom-[38px] left-[0px] rounded-[12px] bg-[rgba(0,0,0,0.64)] backdrop-blur-[4px]">
                  <h2 className="text-[#F1F1F1] text-[14px] font-semibold font-bricolage-grotesque leading-[17px] -tracking-[0.14px] mb-1">
                    Turn off suggestions for now?
                  </h2>

                  <p className="text-[#AAA] text-[12px] font-normal font-manrope leading-[18px]">
                    To show them again, just refresh this video or switch to another one.
                  </p>

                  <div className="flex w-full justify-between gap-2" style={{ marginTop: '16px' }}>
                    <MentorAiButton
                      type="error"
                      size="small"
                      classNames="w-full !h-[28px] !text-[12px] !font-medium !leading-[18px] !tracking-[-0.18px]"
                      onClick={() => {
                        setShowConfirmationModal(false)
                        setShowEasyActions(false)
                        setIsHovered(false)
                        setIsHidden(true)
                        chrome.runtime.sendMessage({
                          action: "sendAnalytics",
                          url: window.location.href,
                          eventName: "Button Clicked",
                          eventProperties: {
                            button_name: "Yes, turn of",
                          },
                        });
                      }}
                    >
                      Yes, turn off
                    </MentorAiButton>
                    <MentorAiButton
                      type="outlined"
                      size="small"
                      classNames="w-full !h-[28px] !text-[12px] !font-medium !leading-[18px] !tracking-[-0.18px]"
                      onClick={() => {
                        setShowConfirmationModal(false)
                        chrome.runtime.sendMessage({
                          action: "sendAnalytics",
                          url: window.location.href,
                          eventName: "Button Clicked",
                          eventProperties: {
                            button_name: "No, keep them",
                          },
                        });
                      }}
                    >
                      No, keep them
                    </MentorAiButton>
                  </div>
                </motion.div>
              </ClickAwayListener>
            }
          </div>
        }
        {optionsToShow.map((action, index) => (
          <AnimatePresence key={`easy-action-${index}-${action.follow_up}`}>
            {shouldShowEasyActions && (
              <motion.div
                key={`easy-action-${index}-${action.follow_up}`}
                initial={{ opacity: 0, x: 16 }}
                animate={{ opacity: 1, x: 0 }}
                exit="exit"
                custom={index}
                variants={{
                  exit: (index) => ({
                    opacity: 0,
                    x: 16,
                    transition: {
                      delay: index * 0.15,
                      duration: 0.15,
                      ease: "easeOut",
                    },
                  }),
                }}
                transition={{
                  duration: 0.15,
                  delay: isHovered || isVideoFirstLoad ? (optionsToShow.length - 1 - index) * 0.15 : 0,
                  ease: "easeOut",
                }}
              >
                <button
                  className="flex items-center gap-[6px] bg-[rgba(0,0,0,0.64)] hover:bg-[rgba(0,0,0,0.75)] pl-[8px] pr-[12px] py-[6px] rounded-[38px] cursor-pointer"
                  style={{
                    backdropFilter: "blur(4px)",
                  }}
                  onClick={() => {
                    handleEasyActionClick(action.follow_up, action.category);
                  }}
                >
                  <img src={SparkleVector} alt="Sparkle" className="w-[10px] h-[10px] shrink-0" />
                  <span className="text-[#DDDDDF] text-[14px] font-medium font-manrope -tracking-[0.14px]">
                    {action.follow_up}
                  </span>
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        ))}
      </div>

      {/* Leeco Icon */}
      <motion.div
        className={`relative bg-[rgba(39,39,39,0.20)] rounded-full group cursor-pointer ${playerMode === "FULLSCREEN" ? "h-[44px] w-[44px] min-h-[44px] min-w-[44px] " : "h-[36px] w-[36px] min-h-[36px] min-w-[36px]"
          } flex items-center justify-center`}
        animate={{
          opacity: showCurrentDynamicEasyAction ? 1 : (isHovered || isVideoFirstLoad ? 1 : 0.64),
        }}
        transition={{
          opacity: { duration: 0.05 },
        }}
      >

        <img
          onMouseEnter={() => { setIsLeecoIconHovered(true) }}
          onMouseLeave={() => { setIsLeecoIconHovered(false) }}
          src={LeecoIcon}
          alt="Leeco Icon"
          className={`${playerMode === "FULLSCREEN" ? "h-[40px] w-[40px] min-h-[40px] min-w-[40px]" : "h-[32px] w-[32px] min-h-[32px] min-w-[32px]"} rounded-full`}
          onClick={() => {
            chrome.runtime.sendMessage({ action: "openSidePanel" })
          }}
        />

        <AnimatePresence>
          <div className="absolute right-[-2px] top-[0px]">
            <AnimatePresence>
              {isDoubleArrowHovered && (
                <motion.div
                  className="absolute bottom-[20px] right-0 bg-[#4B4E63] text-white text-[12px] leading-[15px] tracking-[0.12px] px-[6px] py-[4px] rounded-lg whitespace-nowrap z-50"
                  initial={{ opacity: 0, y: 5 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: 5 }}
                  transition={{ duration: 0.2 }}
                >
                  Minimise Suggestions
                </motion.div>
              )}
            </AnimatePresence>
            {(isDoubleArrowHovered || isLeecoIconHovered) &&
              <motion.img
                onMouseEnter={() => { setIsDoubleArrowHovered(true) }}
                onMouseLeave={() => { setIsDoubleArrowHovered(false) }}
                src={ArrowDouble}
                alt="Cross Circle"
                className={`rounded-full cursor-pointer bg-[rgba(0,0,0,0.20)] hover:bg-[rgba(0,0,0,0.44)] flex justify-center items-center ${playerMode === "DEFAULT" ? ' h-[14px] w-[14px]' : ' h-[16px] w-[16px]'}`}
                style={{
                  backdropFilter: "blur(4px)",
                }}
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.8 }}
                transition={{ duration: 0.15 }}
                onClick={() => {
                  setShowEasyActions(false)
                  setShowConfirmationModal(false)
                  setShowHideEye(false)
                  chrome.runtime.sendMessage({
                    action: "sendAnalytics",
                    url: window.location.href,
                    eventName: "Button Clicked",
                    eventProperties: {
                      button_name: "Minimise Suggestions",
                      url: window.location.href,
                    },
                  });
                }}
              />
            }
          </div>
        </AnimatePresence>
      </motion.div>
    </div>
  );
};

export default LeecoHelp;
