import React from 'react'
import {  handleAibackendDelete, handleAibackendPost } from '../../../core/Axios'
import { useCustomUI } from '../../contexts/custom-ui-context/custom-ui-context';
import { cleanYoutubeUrl } from '../../utils/clean-youtube-url';

const useDeleteInteractionsCta = () => {
    const {
        userInteractionData,
      } = useCustomUI();

    const handleDeleteInteractions = () => {
        console.log("Delete Interactions")
        handleAibackendDelete(`/user-interactions/delete/${userInteractionData?.recordId}`, {})
    }

    const handleDeleteResourcesData = () => {
        console.log("Delete Resources Data")
        handleAibackendPost(`/resources/remove_resource_fields`, {
            url: cleanYoutubeUrl(window.location.href),
            fields: ["detailedSummary", "quizzes", "glossary", "cheatsheet"]
        }, false)
    }
    
  return {
    handleDeleteInteractions,
    handleDeleteResourcesData
  }
}

export default useDeleteInteractionsCta