import { useState } from "react"
import ClickAwayListener from "../../../../../src/custom-hooks/use-clickaway-listner"
import { AnimatePresence, motion } from "framer-motion"
import MentorAiButton from "../../../../../common/button/mentorai-button"
import CloseIcon from "../../../../../src/assets/close-icon.svg";
import CloseIconHovered from "../../../../../src/assets/close-icon-hovered.svg";
import { usePageContext } from "../../../../contexts/page-context/page-context";

const DisableButton = () => {
  const {setHideWidgetForThisTab, setHideWidgetFor24Hours, disabledSites, setDisabledSites, isSidePanelOpen} = usePageContext()
  const [showDisableOptions, setDisableOptions]=useState(false)

  const handleDisableOptions = (e:React.MouseEvent<HTMLDivElement>) => {
    e.stopPropagation()
    setDisableOptions((prev)=>!prev)
    chrome.runtime.sendMessage({
      action:"sendAnalytics",
      url: window.location.href,
      eventName: "Extension Widget Cross Clicked",
      eventProperties: {
        sidepanel_state:isSidePanelOpen ? "open" : "closed",
      },
    })
  }

  const handleHideForThisTab = async (e:React.MouseEvent<HTMLDivElement>) => {
    e.stopPropagation()
    setHideWidgetForThisTab(true)
    setDisableOptions(false)
    chrome.runtime.sendMessage({ action: "get_tab_id" }, (response) => {
      const tabId = response?.tabId
      chrome.storage.local.set({ hide_widget_for_this_tab: tabId })
    })
    chrome.runtime.sendMessage({
      action:"sendAnalytics",
      url: window.location.href,
      eventName: "Extension Disabled",
      eventProperties: {
        disabled_for: "tab",
        disabled_url:window.location.href,
        disabled_url_domain:window.location.hostname,
        url: window.location.href,
        sidepanel_state:isSidePanelOpen ? "open" : "closed",
      },
    })
  }

  const handleHideFor24Hours = async (e:React.MouseEvent<HTMLDivElement>) => {
    e.stopPropagation()
    const hideUntil = Date.now() + 24 * 60 * 60 * 1000
    setHideWidgetFor24Hours(true)
    await chrome.storage.local.set({ widget_hide_until: hideUntil })
    setDisableOptions(false)
    chrome.runtime.sendMessage({
      action:"sendAnalytics",
      url: window.location.href,
      eventName: "Extension Disabled",
      eventProperties: {
        disabled_for: "day",
        disabled_url:window.location.href,
        url: window.location.href,
        sidepanel_state:isSidePanelOpen ? "open" : "closed",
      },
    })
  }


  const handleDisableForThisSite = async (e:React.MouseEvent<HTMLDivElement>) => {
    e.stopPropagation()
    const hostName = window.location.hostname
    if (!hostName) return
    const newDisabledSites = [...disabledSites, hostName]
    await chrome.storage.local.set({ widget_disabled_sites: newDisabledSites })
    setDisabledSites(newDisabledSites)
    setDisableOptions(false)
    chrome.runtime.sendMessage({
      action:"sendAnalytics",
      url: window.location.href,
      eventName: "Extension Disabled",
      eventProperties: {
        disabled_for: "site",
        disabled_url:window.location.href,
        disabled_url_domain:hostName,
        sidepanel_state:isSidePanelOpen ? "open" : "closed",
      },
    })
  }

  const options=[
    {
      id:1,
      type:"temporary",
      title:"Hide for this tab only",
      onClick:handleHideForThisTab
    },
    {
      id:2,
      type:"temporary",
      title:"Hide for 24 hours",
      description:"This will hide the widget for 24 hours on all sites",
      onClick:handleHideFor24Hours
    },
    {
      id:3,
      type:"permanent",
      title:"Disable for this site",
      description:"This will hide the widget permanently on this site",
      onClick:handleDisableForThisSite
    }
  ]

  return (
    <>
    <AnimatePresence mode="popLayout">
      {showDisableOptions && (
        <ClickAwayListener onClickAway={() => setDisableOptions(false)} ignoreKey="disable-popup" className="absolute bottom-[45px] right-[5px] ">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 20 }}
              transition={{ type: "spring", stiffness: 500, damping: 30 }}
              className="w-[198px] bg-mentorai-bg-strong rounded-xl p-2 z-10"
            >
              <div className="flex flex-col gap-[6px]">
                  {options.filter(option=>option.type==="temporary").map((option)=>(
                    <div key={option.id} className="px-[8px] py-[4px] rounded-[12px] transition-all duration-300 hover:bg-mentorai-bg-sub cursor-pointer" onClick={option.onClick}>
                      <p className="text-mentorai-text-soft text-[12px] font-medium">{option.title}</p>
                    </div>
                  ))}
              </div>
              <hr className="w-[166px] h-[1px] border-0 my-[6px] mx-auto" style={{ background: "#43434D" }} />
              <div className="">
                  {options.filter(option=>option.type==="permanent").map((option)=>(
                    <div key={option.id} className="px-[8px] py-[4px] rounded-[12px] transition-all duration-300 hover:bg-mentorai-bg-sub cursor-pointer" onClick={option.onClick}>
                      <p className="text-mentorai-text-soft text-[12px] font-medium">{option.title}</p>
                    </div>
                  ))}
              </div>
              <p className="text-mentorai-text-sub text-[10px] font-medium mt-[6px] pl-[8px] pb-[4px]">You can enable this again in Settings</p>
            </motion.div>
        </ClickAwayListener>
      )}
      </AnimatePresence>
      <MentorAiButton classNames="!cursor-pointer !rounded-full transition-all duration-100 group !w-[14px] !h-[14px] absolute top-[-4px] left-[0px] !z-[10000] !border-none !p-0 !bg-mentorai-bg-strong !hover:bg-mentorai-bg-sub"
        customAttribute={{
          name:"data-clickaway-ignore",
          value:"disable-popup"
        }}
        onClick={handleDisableOptions}>
        <img src={CloseIcon} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] flex group-hover:hidden" />
        <img src={CloseIconHovered} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] hidden group-hover:flex" />
      </MentorAiButton>
    </>
  )
}

export default DisableButton