import { normalizeWhitespace } from "../utils/text-utils";

declare global {
    interface Window {
        __mentorai_gemini_injected__?: boolean;
    }
}

(function initGeminiCapture() {
    try {
        if (window.__mentorai_gemini_injected__) return;
        window.__mentorai_gemini_injected__ = true;
    } catch (_) { }

    const isGeminiDomain = /(^|\.)gemini\.google\.com$/.test(location.hostname) || /(^|\.)bard\.google\.com$/.test(location.hostname) || /(^|\.)aistudio\.google\.com$/.test(location.hostname);
    if (!isGeminiDomain) return;

    const INPUT_SELECTORS = [
        'rich-textarea .ql-editor[contenteditable="true"]',
        '.ql-editor.textarea.new-input-ui[contenteditable="true"]',
        'div[contenteditable="true"][role="textbox"]',
    ];

    const SEND_BUTTON_SELECTORS = [
        'button.send-button.submit',
        'button[aria-label="Send message"]',
        '.send-button-container button',
    ];

    let isComposing = false;
    let urlAtInit = location.href;

    const recentQueries = new Map<string, number>();
    const RECENT_TTL_MS = 10000;

    // Per-conversation counters to label query_type
    const conversationCounters = new Map<string, number>();
    const conversationKey = (): string => [location.host, location.pathname, location.search, location.hash].join("|");

    const isVisible = (el: Element | null): boolean => {
        if (!el) return false;
        const rect = (el as HTMLElement).getBoundingClientRect();
        const style = window.getComputedStyle(el as Element);
        return rect.width > 0 && rect.height > 0 && style.visibility !== "hidden" && style.display !== "none";
    };

    const queryAny = (selectors: string[], root: ParentNode = document): Element | null => {
        for (const sel of selectors) {
            const el = (root as Element | Document).querySelector(sel);
            if (el && isVisible(el)) return el as Element;
        }
        return null;
    };

    const queryAllAny = (selectors: string[], root: ParentNode = document): Element[] => {
        const result: Element[] = [];
        for (const sel of selectors) {
            (root as Element | Document).querySelectorAll(sel).forEach((el) => {
                if (isVisible(el)) result.push(el);
            });
        }
        return result;
    };

    const getPromptEditor = (): Element | null => queryAny(INPUT_SELECTORS);
    const getSendButtons = (): Element[] => queryAllAny(SEND_BUTTON_SELECTORS);

    const getConversationIdFromUrl = (): string => {
        return location.pathname + location.search + location.hash;
    };

    const makeKey = (query: string): string => {
        return [conversationKey(), normalizeWhitespace(query)].join("|");
    };

    const isRecentAndMark = (key: string): boolean => {
        const now = Date.now();
        const prev = recentQueries.get(key);
        if (prev && now - prev < RECENT_TTL_MS) return true;
        recentQueries.set(key, now);
        for (const [k, t] of recentQueries) {
            if (now - t > RECENT_TTL_MS) recentQueries.delete(k);
        }
        return false;
    };

    const extractEditorText = (el: Element | null): string => {
        if (!el) return "";
        if (el instanceof HTMLTextAreaElement) return el.value || "";
        return normalizeWhitespace((el as HTMLElement).innerText || (el as HTMLElement).textContent || "");
    };

    const sendLearningQueryEvent = (query: string, meta?: Record<string, any>) => {
        const key = conversationKey();
        const count = conversationCounters.get(key) || 0;
        const queryType = count === 0 ? "initial" : "followup";

        const eventPayload = {
            action: "sendAnalytics",
            url: location.href,
            eventName: "Query Captured",
            eventProperties: {
                platform: "gemini",
                conversationId: getConversationIdFromUrl(),
                query: normalizeWhitespace(query),
                query_type: queryType,
                ...meta,
            },
        };
        try {
            chrome.runtime.sendMessage(eventPayload);
        } catch (e) { }

        conversationCounters.set(key, count + 1);
    };

    const dispatchFinal = (query: string, meta?: Record<string, any>) => {
        const norm = normalizeWhitespace(query);
        if (!norm) return;
        const key = makeKey(norm);
        if (isRecentAndMark(key)) return;
        sendLearningQueryEvent(norm, meta);
    };

    const wireInputListeners = () => {
        let editor = getPromptEditor();

        const bindKeydown = (el: Element) => {
            el.addEventListener(
                "keydown",
                (e: Event) => {
                    try {
                        const ke = e as KeyboardEvent;
                        if (isComposing) return;
                        if (ke.key !== "Enter") return;
                        if (ke.shiftKey || ke.ctrlKey || ke.altKey || ke.metaKey) return;
                        const val = extractEditorText(el);
                        if (normalizeWhitespace(val)) {
                            dispatchFinal(val, { captured_by: "keydown-enter" });
                        }
                    } catch { }
                },
                true
            );
        };

        document.addEventListener("compositionstart", () => (isComposing = true), true);
        document.addEventListener("compositionend", () => (isComposing = false), true);

        document.addEventListener(
            "submit",
            (e) => {
                try {
                    const form = e.target as HTMLFormElement;
                    if (!(form instanceof HTMLFormElement)) return;
                    const inputEl = (queryAny(INPUT_SELECTORS, form) as Element) || form.querySelector("textarea");
                    const val = extractEditorText(inputEl as Element);
                    if (normalizeWhitespace(val)) {
                        dispatchFinal(val, { captured_by: "submit-event" });
                    }
                } catch { }
            },
            true
        );

        if (editor) bindKeydown(editor);

        const bindSendButtons = () => {
            getSendButtons().forEach((btn: any) => {
                if ((btn as any).__mentorai_bound__) return;
                (btn as any).__mentorai_bound__ = true;
                btn.addEventListener(
                    "click",
                    () => {
                        try {
                            const el = getPromptEditor() || editor;
                            const val = extractEditorText(el as Element);
                            if (normalizeWhitespace(val)) {
                                dispatchFinal(val, { captured_by: "send-button" });
                            }
                        } catch { }
                    },
                    true
                );
            });
        };

        bindSendButtons();

        const rebinder = new MutationObserver(() => {
            editor = getPromptEditor();
            if (editor) bindKeydown(editor);
            bindSendButtons();
        });
        rebinder.observe(document.documentElement, { childList: true, subtree: true });
    };

    const observeSpaNavigation = (onNavigate?: () => void) => {
        const notifyIfChanged = () => {
            if (urlAtInit !== location.href) {
                urlAtInit = location.href;
                onNavigate?.();
                conversationCounters.delete(conversationKey());
            }
        };
        const wrapHistory = (type: "pushState" | "replaceState") => {
            const orig = history[type];
            (history as any)[type] = function () {
                const ret = orig.apply(this, arguments as any);
                setTimeout(notifyIfChanged, 0);
                return ret;
            };
        };
        wrapHistory("pushState");
        wrapHistory("replaceState");
        window.addEventListener("popstate", notifyIfChanged);
        setInterval(notifyIfChanged, 1000);
    };

    wireInputListeners();
    observeSpaNavigation(() => {
        // no-op
    });
})(); 