import axios from "axios";

const fetchMentorai = async () => {
  try{
    const {mentorai} = await chrome.storage.local.get("mentorai")
    const response   = await axios.get(
        `${import.meta.env.VITE_PREPLACED_BACKEND_AI_URL}/mentor-ai/mentors/${
        mentorai?.mentorai || "pro-pilot"
        }`
    );
    return response.data.find((item: any) => item.mode === 'Live');
  }catch(error){
    console.error("Error fetching mentorai from storage:", error);
  }
};

export default fetchMentorai;
