import React, { FC, useMemo } from "react";
import useEndSectionQuizComponent from "./use-end-section-quiz-component";
import { useCustomUI } from "../../../contexts/custom-ui-context/custom-ui-context";
import RadioSelectedIcon from "../../../assets/icons/quiz-option-radio-selected.svg";
import RadioUnselectedIcon from "../../../assets/icons/quiz-option-radio-unselected.svg";
import Correct from "../../../assets/icons/correct.svg";
import Incorrect from "../../../assets/icons/incorrect.svg";
import { motion, AnimatePresence } from "framer-motion";
import MentorAiButton from "../../../../common/button/mentorai-button";
import { cn } from "../../../../utils/cn";
import MentorAiAvatarHeader from "./components/mentorai-avatar-header";
import BrainIcon from "../../../assets/icons/brain-line.svg";
import MentorAiActiveAvatar from "../../mentorai-active-avatar/mentorai-active-avatar";
import { useChat } from "../../../contexts/chat-context/chat-context";
// import { getYoutubeVideoPlayHead } from "../../../utils/get-youtube-video-length";
// import { getYoutubeVideoLength } from "../../../utils/get-youtube-video-length";
// import { shuffleQuiz } from "../../../utils/learning-session-helper";

interface EndSectionQuizComponentProps {
  sectionIndex: number;
  isSidePanelOpen: boolean
}

const EndSectionQuizComponent: FC<EndSectionQuizComponentProps> = ({ sectionIndex, isSidePanelOpen }) => {
  const {
    learningSession,
    currentSection,
    currentQuizIndex,
    answerQuiz,
    nextQuiz,
    mentoraiData,
    setSectionEndScreen,
    playerMode,
    trackCustomUIEvent,
    getCurrentSectionProperties
  } = useCustomUI();

  const isPlayerModeDefault = playerMode === "DEFAULT";
  const { sendMessage, isLiveMessageStreaming, setSelectedYouTubeSideSectionTab } = useChat();

  if (!learningSession || !learningSession.sections[sectionIndex]) {
    return null;
  }

  const section = learningSession.sections[sectionIndex];
  const quizzes = section.quizzes || [];

  const handleSubmitAnswer = (answerIdx: number) => {
    answerQuiz(sectionIndex, currentQuizIndex, answerIdx);
  };


  const handleGetAHint = () => {
    // setSelectedYouTubeSideSectionTab("Chat")
    const currentQuestionData = JSON.stringify(currentQuiz)
    // console.log("currentQuestionData", currentQuestionData)

    if (!isSidePanelOpen) {
      chrome.runtime.sendMessage({ action: "openSidePanel" }).then(() => {
        setTimeout(() => {
          chrome.runtime.sendMessage({
            action: "easyActionClicked",
            easy_action: "I need a hint",
            easy_action_title: "I need a hint",
            url: window.location.href,
            is_side_panel_opened: false,
            section_title: "YouTube Quiz",
            easy_action_message: "I need a hint",
            additional_message: `SelectedText: ${currentQuestionData}. \n Above is the quiz question I need the hint for. Do not provide direct solution, just provide a hint.`
          })
        }, 3000);
      });
    } else {
      chrome.runtime.sendMessage({
        action: "easyActionClicked",
        easy_action: "I need a hint",
        easy_action_title: "I need a hint",
        url: window.location.href,
        is_side_panel_opened: true,
        section_title: "YouTube Quiz",
        easy_action_message: "I need a hint",
        additional_message: `SelectedText: ${currentQuestionData}. \n Above is the quiz question I need the hint for. Do not provide direct solution, just provide a hint.`
      })
    }

    // trackCustomUIEvent("Easy Action Clicked", {
    //   section: getCurrentSectionProperties(),
    //   question: currentQuiz?.question,
    //   info: {
    //     easy_action: "Get a Hint",
    //     easy_action_title: "Get a Hint",
    //     section_title: "YouTube Quiz",
    //     easy_action_message: "I need a hint",
    //   },
    // })

    // TODO: Add a Analytics Event for this, Have commented the below one as this sends the message in sidepanel too.
    // chrome.runtime.sendMessage({
    //   action: "easyActionClicked",
    //   easy_action: "Get a Hint",
    //   easy_action_title: "Get a Hint",
    //   url: window.location.href,
    //   is_side_panel_opened: false,
    //   section_title: "YouTube Quiz",
    //   additional_message: `SelectedText: ${currentQuestionData}`,
    //   easy_action_message: "Get a Hint",
    //   event_properties: {
    //     question: currentQuiz.question,
    //     current_duration: getYoutubeVideoPlayHead(),
    //     video_duration: getYoutubeVideoLength()
    //   },
    // })
  }

  const handleDiveDeeper = () => {
    // setSelectedYouTubeSideSectionTab("Chat")

    if (!isSidePanelOpen) {
      chrome.runtime.sendMessage({ action: "openSidePanel" }).then(() => {
        setTimeout(() => {
          chrome.runtime.sendMessage({
            action: "easyActionClicked",
            easy_action: "I want to understand about this more in detail.",
            easy_action_title: "I want to understand about this more in detail.",
            url: window.location.href,
            is_side_panel_opened: false,
            section_title: "YouTube Quiz",
            easy_action_message: "I want to understand about this more in detail.",
            additional_message: `SelectedText: ${currentQuiz.question}. \n Above is the quiz question I want to understand more about.`
          })
        }, 3000);
      });
    } else {
      chrome.runtime.sendMessage({
        action: "easyActionClicked",
        easy_action: "I want to understand about this more in detail.",
        easy_action_title: "I want to understand about this more in detail.",
        url: window.location.href,
        is_side_panel_opened: true,
        section_title: "YouTube Quiz",
        easy_action_message: "I want to understand about this more in detail.",
        additional_message: `SelectedText: ${currentQuiz.question}. \n Above is the quiz question I want to understand more about.`
      })
    }
    // trackCustomUIEvent("Easy Action Clicked", {
    //   section: getCurrentSectionProperties(),
    //   question: currentQuiz?.question,
    //   info: {
    //     easy_action: "Dive Deeper",
    //     easy_action_title: "Dive Deeper",
    //     section_title: "YouTube Quiz",
    //     easy_action_message: "I want to understand about this more in detail.",
    //   },
    // })

    // TODO: Add a Analytics Event for this, Have commented the below one as this sends the message in sidepanel too.
    // chrome.runtime.sendMessage({
    //   action: "easyActionClicked",
    //   easy_action: "Dive Deeper",
    //   easy_action_title: "Dive Deeper",
    //   url: window.location.href,
    //   is_side_panel_opened: false, 
    //   section_title: "YouTube Quiz",
    //   additional_message: `SelectedText: ${currentQuestionData}`,
    //   easy_action_message: "Dive Deeper",
    //   event_properties: {
    //     question: currentQuiz.question,
    //     current_duration: getYoutubeVideoPlayHead(),
    //     video_duration: getYoutubeVideoLength()
    //   },
    // })
  }

  const {
    currentQuiz,
    selectedOption,
    setSelectedOption,
    quizSubmissionStatus,
    handleSubmit,
    handleNext,
    submitted,
    totalQuizzes,
    flattenedQuizzes,
  } = useEndSectionQuizComponent({
    quizzes,
    currentQuizIndex,
    onSubmitAnswer: handleSubmitAnswer,
    onNextQuiz: nextQuiz,
    sectionIndex,
  });

  if (!currentQuiz) {
    return null;
  }

  const getCtaTexts = () => {
    if (quizSubmissionStatus === 'default') {
      return {
        rightCta: "Get a Hint",
        leftCta: <span className="flex items-center gap-1">Submit &rarr;</span>,
      };
    } else {
      // const hasMoreQuizzes = currentQuizIndex + 1 < totalQuizzes;
      return {
        rightCta: "Dive Deeper",
        leftCta: <span className="flex items-center">Next &rarr;</span>
      };
    }
  };

  const ctaTexts = getCtaTexts();

  return (
    <div className="w-full h-full flex flex-col"   >
      <MentorAiAvatarHeader
        mentoraiData={mentoraiData}
        primaryStatus={<span style={{ color: "#FFE097", fontWeight: "600" }}>🏁 Completing :</span>}
        secondaryStatus={
          <span style={{ color: "#94939F", fontWeight: "500", display: "flex", alignItems: "center", gap: "4px" }}>
            <img src={BrainIcon} alt="section-icon" className="w-[20px] h-[20px]" />
            Quiz {currentQuizIndex + 1} of {totalQuizzes}
          </span>
        }
      />


      <p className="text-[#DDDDDF] w-full"
        style={{
          fontSize: "20px",
          fontWeight: 500,
          lineHeight: "28px",
          letterSpacing: "-0.24px",
          marginTop: "16px",
        }}
      >
        {currentQuiz.question}
      </p>


      <div
        className="relative flex flex-col w-full"
        style={{ gap: "16px", marginTop: "24px" }}
      >
        <div className="w-[85%] flex flex-col" style={{ gap: "16px" }}>
          <AnimatePresence mode="wait">
            {currentQuiz.options.map((opt: any, idx: number) => {
              const optionIndex = idx;
              const correctAnswer = currentQuiz.answer;
              const isSelected = selectedOption === optionIndex;
              const isCorrectOption = correctAnswer === optionIndex;
              const showCorrectIncorrectBanner = (quizSubmissionStatus === "correct" && isSelected) || (quizSubmissionStatus === "incorrect" && isSelected);

              const base =
                "flex items-start gap-6 justify-between w-full rounded-b-xl rounded-t-xl border border-mentorai-stroke-strong " +
                `bg-[rgba(20,22,31,0.75)] text-[#94939F] ${quizSubmissionStatus === "default" ? "hover:bg-[rgba(33,36,49,0.75)] cursor-pointer" : ""}`;

              let state = "";

              if (quizSubmissionStatus === "default") {
                if (isSelected) state = "bg-mentorai-primary-base text-mentorai-text-white hover:bg-mentorai-primary-base border-0";
              } else if (quizSubmissionStatus === "correct") {
                if (isSelected) state = `bg-[rgba(26,117,68,0.65)] text-mentorai-text-white !border-0 ${showCorrectIncorrectBanner ? "rounded-t-none" : ""}`;
              } else if (quizSubmissionStatus === "incorrect") {
                if (isCorrectOption) state = `bg-[rgba(26,117,68,0.65)] text-mentorai-text-white !border-0 ${showCorrectIncorrectBanner ? "rounded-t-none" : ""}`;
                else if (isSelected) state = `bg-[rgba(139,62,24,0.65)]  text-mentorai-text-white !border-0 ${showCorrectIncorrectBanner ? "rounded-t-none" : ""}`;
              }

              return (
                <motion.div
                  key={optionIndex}
                  className="w-full"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ duration: 0.2, delay: idx * 0.1 }}
                  layout
                >
                  <AnimatePresence>
                    {showCorrectIncorrectBanner && (
                      <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: "auto" }}
                        exit={{ opacity: 0, height: 0 }}
                        transition={{ duration: 0.2 }}
                        className={`flex items-center gap-0.5 self-stretch py-1 px-3 rounded-tl-xl rounded-tr-xl text-[10px] font-semibold leading-[14px] uppercase
                          ${quizSubmissionStatus === "correct" ? "bg-[rgba(26,117,68,0.65)] text-[#84ebb4] border-b border-b-[#1DAF61]" : "bg-[rgba(139,62,24,0.65)] text-[#FFBA97] border-b border-b-[#AD4E1F]"}
                          `}
                      >
                        <img src={quizSubmissionStatus === "correct" ? Correct : Incorrect} alt="status" className="" />
                        <span className="text-[10px] font-semibold leading-[14px] uppercase">
                          {quizSubmissionStatus === "correct" ? "🎉" : "👀"}
                        </span>
                      </motion.div>
                    )}
                  </AnimatePresence>
                  <label
                    className={cn(base, state)}
                    style={{ padding: "12px" }}
                  >
                    <div className="flex items-start justify-start" style={{ gap: "8px" }}>
                      {isSelected
                        ? <img src={RadioSelectedIcon} alt="radio" className="w-[16px] h-[20px]" />
                        : <img src={RadioUnselectedIcon} alt="radio" className="w-[16px] h-[20px]" />}

                      <input
                        type="radio"
                        name="language"
                        className="hidden"
                        checked={isSelected}
                        onChange={() => setSelectedOption(optionIndex)}
                      />

                      <span
                        className={`tracking-[0.16px] ${isSelected || (quizSubmissionStatus === "incorrect" && isCorrectOption)
                          ? "text-mentorai-text-white"
                          : "text-[#94939F]"}`}
                        style={{ fontSize: "16px", fontWeight: 500 }}
                      >
                        {opt}
                      </span>
                    </div>
                  </label>
                </motion.div>
              );
            })}
          </AnimatePresence>
        </div>



        <div className="flex w-full items-center" style={{ marginTop: "24px", gap: "8px" }}>
          <MentorAiButton
            type="primary"
            size="medium"
            classNames={cn(`transition !w-fit
                  ${selectedOption === null && quizSubmissionStatus === 'default' ? "opacity-80" : ""}`)}
            disabled={selectedOption === null && quizSubmissionStatus === 'default'}
            style={{
              cursor: (selectedOption === null && quizSubmissionStatus === 'default') ? "not-allowed" : "pointer",
              paddingLeft: isPlayerModeDefault ? "12px" : "24px",
              paddingRight: isPlayerModeDefault ? "8px" : '18px',
              height: isPlayerModeDefault ? "32px" : "40px"
            }}
            onClick={quizSubmissionStatus === 'default' ? handleSubmit : handleNext}
          >
            <div
              className="flex items-center whitespace-nowrap truncate line-clamp-1"
              style={{ gap: "4px" }}
            >
              <span style={{ fontSize: "14px", fontWeight: 500, lineHeight: "22px", letterSpacing: "0.084px" }}>
                {ctaTexts.leftCta}
              </span>
            </div>
          </MentorAiButton>

          <MentorAiButton
            type="outlined"
            size="medium"
            disabled={isLiveMessageStreaming}
            onClick={isLiveMessageStreaming ? () => { } : (quizSubmissionStatus === 'default' ? handleGetAHint : handleDiveDeeper)}
            classNames=" !w-fit"
            style={{
              paddingLeft: isPlayerModeDefault ? "8px" : "18px",
              paddingRight: isPlayerModeDefault ? "12px" : "24px",
              height: isPlayerModeDefault ? "32px" : "40px"
            }}
          >
            <div className={`flex items-center`} style={{ gap: "4px", fontSize: "14px", fontWeight: 500, lineHeight: "22px", letterSpacing: "0.084px" }}>
              <MentorAiActiveAvatar mentoraiData={mentoraiData} avatarClassName="h-[20px] w-[20px]" />
              {ctaTexts.rightCta}
            </div>
          </MentorAiButton>
        </div>
      </div>
    </div>
  );
};

export default EndSectionQuizComponent; 