import { useCallback } from 'react';

interface TranscriptionRecord {
  url: string;
  timestamp: number;
  expirationTime: number;
}

const STORAGE_KEY = 'transcription_fetched_tracker';
const MAX_RECORDS = 50;
const EXPIRATION_DAYS = 10;
const EXPIRATION_MS = EXPIRATION_DAYS * 24 * 60 * 60 * 1000;

const useTranscriptionQueue = () => {
  
  const cleanupRecords = async (queue: Record<string, TranscriptionRecord>): Promise<Record<string, TranscriptionRecord>> => {
    const now = Date.now();
    
    // Filter out expired records
    const validRecords = Object.entries(queue).filter(
      ([_, record]) => now < record.expirationTime
    );
    
    // Sort by timestamp (newest first) and keep only MAX_RECORDS
    const sortedRecords = validRecords
      .sort(([_, a], [__, b]) => b.timestamp - a.timestamp)
      .slice(0, MAX_RECORDS);
    
    // Convert back to object
    const cleanedQueue: Record<string, TranscriptionRecord> = {};
    sortedRecords.forEach(([url, record]) => {
      cleanedQueue[url] = record;
    });
    
    return cleanedQueue;
  };

  const storeCurrentURL = useCallback(async (cleanedUrl: string) => {
    try {
      const now = Date.now();
      
      // Get existing queue
      const result = await chrome.storage.local.get(STORAGE_KEY);
      const existingQueue: Record<string, TranscriptionRecord> = result[STORAGE_KEY] || {};
      
      // Create new record
      const newRecord: TranscriptionRecord = {
        url: cleanedUrl,
        timestamp: now,
        expirationTime: now + EXPIRATION_MS
      };
      
      // Add new record
      const updatedQueue = {
        ...existingQueue,
        [cleanedUrl]: newRecord
      };
      
      // Cleanup expired records and enforce limit
      const cleanedQueue = await cleanupRecords(updatedQueue);
      
      // Save back to storage
      await chrome.storage.local.set({
        [STORAGE_KEY]: cleanedQueue
      });
      
      console.log('URL stored in transcription queue:', cleanedUrl);
    } catch (error) {
      console.error('Error storing URL in transcription queue:', error);
    }
  }, []);

  const shouldFetchTranscription = useCallback(async (cleanedUrl: string): Promise<boolean> => {
    try {
      const result = await chrome.storage.local.get(STORAGE_KEY);
      const queue: Record<string, TranscriptionRecord> = result[STORAGE_KEY] || {};
      
      const existingRecord = queue[cleanedUrl];
      
      // Check if record exists and is not expired
      if (existingRecord && Date.now() < existingRecord.expirationTime) {
        console.log('URL already stored and valid - skip transcription:', cleanedUrl);
        return false; // ❌ Don't fetch transcription
      }
      
      // Record doesn't exist or is expired - store it and fetch transcription
      await storeCurrentURL(cleanedUrl);
      console.log('URL stored - fetch transcription:', cleanedUrl);
      return true; // ✅ Fetch transcription
      
    } catch (error) {
      console.error('Error checking transcription queue:', error);
      // On error, default to fetching transcription
      return true;
    }
  }, [storeCurrentURL]);

  return {
    shouldFetchTranscription
  };
};

export default useTranscriptionQueue;