/**
 * Centralized delay configuration for LinkedIn Auto Apply
 * All delays are in milliseconds [min, max]
 */
export const DELAYS = {
    // Pre-click Easy Apply delays (REVERTED to slower values)
    EASY_APPLY: {
        PRE_CLICK: [1000, 2000] as const,           // Delay before clicking Easy Apply button (reverted from 500-1000)
        MODAL_WAIT: [2000, 3000] as const,          // Wait for modal to appear (reverted from 1500-2000)
    },

    // Form field delays (keeping optimized values)
    FORM_FIELDS: {
        BETWEEN_FIELDS: [150, 300] as const,        // Delay between filling each field
        LOCATION_INITIAL: [150, 250] as const,      // Initial delay for location field
        LOCATION_CHAR_TYPE: [30, 60] as const,      // Delay between each character typed
        LOCATION_AUTOCOMPLETE: [600, 1000] as const, // Wait for autocomplete dropdown
        LOCATION_SELECT: [150, 250] as const,       // Delay after selecting autocomplete option
    },

    // Apply flow delays (keeping optimized values)
    APPLY_FLOW: {
        BEFORE_SUBMIT: [1000, 1500] as const,       // Delay before clicking submit
        AFTER_SUBMIT: [2000, 3000] as const,        // Wait after submission
        CLOSE_MODAL: [500, 1000] as const,          // Delay before closing success modal
        NEXT_REVIEW: [500, 1000] as const,          // Delay before clicking Next/Review
        AFTER_NEXT: [1500, 2000] as const,          // Wait after clicking Next/Review
        EXIT_MODAL: [500, 1000] as const,           // Delay for exiting/dismissing modal
    },

    // Job processing delays (keeping optimized values)
    JOB_PROCESSING: {
        SCROLL_TO_JOB: [300, 600] as const,         // Scroll to job delay
        JOB_DETAILS_LOAD: [1500, 2500] as const,    // Wait for job details
        POST_APPLY_SUCCESS: [1500, 2500] as const,  // Delay after successful apply
        POST_SKIP: [500, 1000] as const,            // Delay after skipping a job
    },

    // Scrolling delays (keeping optimized values)
    SCROLLING: {
        BETWEEN_SCROLLS: [800, 1200] as const,      // Delay between scroll attempts
        AFTER_SCROLL: [300, 600] as const,          // Wait after final scroll
    },

    // Initial setup delays (keeping optimized values)
    INITIAL: {
        FILTER_ENABLE: [1500, 2000] as const,       // Wait for filter to enable
        JOBS_LOAD: [1500, 2000] as const,           // Wait for jobs to load initially
        PAGE_LOAD: [2000, 3000] as const,           // Wait for new page to load
    },
} as const;

// Helper type for delay tuples
export type DelayTuple = readonly [number, number];
