import React from 'react';
import type { WidgetAvatarProps } from '../types';

export const WidgetAvatar: React.FC<WidgetAvatarProps> = ({ photoUrl }) => (
  <div className="relative">
    {photoUrl ? (
      <img
        src={photoUrl}
        className="h-[32px] w-[32px] rounded-full min-h-[32px] min-w-[32px]"
        alt="avatar"
      />
    ) : (
      <div className="w-[32px] h-[32px] rounded-full bg-[#000] min-h-[32px] min-w-[32px]" />
    )}
    <span className="absolute -bottom-[1px] -right-[2px] border-[2px] border-[#000] w-[10px] h-[10px] rounded-full bg-[#1FC16B]" />
  </div>
); 