import { hasValidArticleContent, findBestArticle } from './article-content-validator';

export interface ScrapedContentItem {
  type: 'text' | 'image' | 'heading';
  content: string;
  index: number;
  altText?: string;
  caption?: string;
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
}

export interface ScrapedData {
  items: ScrapedContentItem[];
  totalItems: number;
  url: string;
  timestamp: number;
}

export interface MarkdownScrapedData {
  markdown: string;
  totalItems: number;
  url: string;
  timestamp: number;
  title?: string;
  description?: string;
}


/**
 * Converts image to markdown format
 */
function imageToMarkdown(imageUrl: string, altText?: string, caption?: string): string {
  const alt = altText || 'Image';
  let markdown = `![${alt}](${imageUrl})`;

  if (caption) {
    markdown += `\n\n*${caption}*`;
  }

  return markdown + '\n\n';
}

/**
 * Extracts page title for markdown header
 */
function extractPageTitle(): string {
  // Try multiple sources for title in order of preference
  const titleElement = document.querySelector('title');
  const h1Element = document.querySelector('h1');
  const metaTitle = document.querySelector('meta[property="og:title"]')?.getAttribute('content');
  const metaTwitterTitle = document.querySelector('meta[name="twitter:title"]')?.getAttribute('content');

  if (metaTitle) {
    return metaTitle.trim();
  }

  if (metaTwitterTitle) {
    return metaTwitterTitle.trim();
  }

  if (titleElement?.textContent) {
    return titleElement.textContent.trim();
  }

  if (h1Element?.textContent) {
    return h1Element.textContent.trim();
  }

  return 'Scraped Content';
}

/**
 * Extracts page description from meta tags and content
 */
function extractPageDescription(): string {
  // Try multiple sources for description in order of preference
  const metaDescription = document.querySelector('meta[name="description"]')?.getAttribute('content');
  const metaOgDescription = document.querySelector('meta[property="og:description"]')?.getAttribute('content');
  const metaTwitterDescription = document.querySelector('meta[name="twitter:description"]')?.getAttribute('content');
  
  // Try to find a summary or intro paragraph
  const summaryElement = document.querySelector('p[class*="summary"], p[class*="intro"], p[class*="lead"], .summary, .intro, .lead');
  
  if (metaOgDescription) {
    return metaOgDescription.trim();
  }

  if (metaTwitterDescription) {
    return metaTwitterDescription.trim();
  }

  if (metaDescription) {
    return metaDescription.trim();
  }

  if (summaryElement?.textContent) {
    const summaryText = summaryElement.textContent.trim();
    if (summaryText.length > 20 && summaryText.length < 500) {
      return summaryText;
    }
  }

  // Try to get the first substantial paragraph
  const firstParagraph = document.querySelector('article p, .content p, main p');
  if (firstParagraph?.textContent) {
    const paragraphText = firstParagraph.textContent.trim();
    if (paragraphText.length > 50 && paragraphText.length < 300) {
      return paragraphText;
    }
  }

  return '';
}

/**
 * Converts scraped data to markdown format
 */
export function convertToMarkdown(scrapedData: ScrapedData): MarkdownScrapedData {
  const title = extractPageTitle();
  const description = extractPageDescription();
  
  let markdown = `# ${title}\n\n`;
  
  // Add description if available
  if (description) {
    markdown += `> ${description}\n\n---\n\n`;
  }

  // Convert items to markdown with proper formatting
  scrapedData.items.forEach(item => {
    if (item.type === 'heading') {
      const level = Math.min(Math.max(item.headingLevel || 2, 1), 6);
      const headingText = item.content.trim();
      if (headingText) {
        markdown += `${'#'.repeat(level)} ${headingText}\n\n`;
      }
    } else if (item.type === 'text') {
      const textContent = item.content.trim();
      if (textContent) {
        // Check if it's a list (starts with -)
        if (textContent.includes('\n- ')) {
          markdown += `${textContent}\n\n`;
        } else {
          // Regular paragraph
          markdown += `${textContent}\n\n`;
        }
      }
    } else if (item.type === 'image') {
      markdown += imageToMarkdown(item.content, item.altText, item.caption);
    }
  });

  return {
    markdown,
    totalItems: scrapedData.totalItems,
    url: scrapedData.url,
    timestamp: scrapedData.timestamp,
    title,
    description
  };
}

/**
 * Extracts text content from an element, cleaning it up
 */
function extractTextContent(element: Element): string {
  // Clone the element to avoid modifying the original DOM
  const clonedElement = element.cloneNode(true) as Element;

  // Remove script and style elements from the clone
  const scripts = clonedElement.querySelectorAll('script, style, nav, header, footer, aside');
  scripts.forEach(script => script.remove());

  // Get text content and clean it up
  let text = clonedElement.textContent || (clonedElement as HTMLElement).innerText || '';

  // Clean up whitespace and normalize
  text = text.replace(/\s+/g, ' ').trim();
  
  // Remove excessive whitespace and normalize line breaks
  text = text.replace(/\n\s*\n/g, '\n').trim();

  return text;
}


/**
 * Extracts list items as simple markdown bullets
 */
function extractListText(element: Element): string | null {
  const tag = element.tagName?.toLowerCase();
  if (tag !== 'ul' && tag !== 'ol') {
    return null;
  }

  const items = Array.from(element.querySelectorAll(':scope > li'));
  if (items.length === 0) {
    return null;
  }

  const lines: string[] = [];
  items.forEach((li, index) => {
    const text = extractTextContent(li);
    if (text) {
      if (tag === 'ol') {
        lines.push(`${index + 1}. ${text}`);
      } else {
        lines.push(`- ${text}`);
      }
    }
  });

  return lines.join('\n');
}


/**
 * Extracts image data with alt text and captions
 */
function extractImageData(element: Element): Array<{ url: string, alt: string, caption?: string }> {
  const images = element.querySelectorAll('img');
  const imageData: Array<{ url: string, alt: string, caption?: string }> = [];

  images.forEach(img => {
    const src = img.src || img.getAttribute('data-src') || img.getAttribute('data-lazy-src');
    if (src && isValidImageUrl(src)) {
      const alt = img.alt || img.getAttribute('title') || 'Image';

      // Look for caption in nearby elements
      let caption: string | undefined;
      const parent = img.parentElement;
      if (parent) {
        // Check for figcaption
        const figcaption = parent.querySelector('figcaption');
        if (figcaption) {
          caption = figcaption.textContent?.trim();
        } else {
          // Check for caption in next sibling
          const nextSibling = img.nextElementSibling;
          if (nextSibling && (nextSibling.classList.contains('caption') || nextSibling.classList.contains('image-caption'))) {
            caption = nextSibling.textContent?.trim();
          }
        }
      }

      imageData.push({
        url: src,
        alt,
        caption
      });
    }
  });

  return imageData;
}

/**
 * Validates if an image URL is worth scraping
 */
function isValidImageUrl(url: string): boolean {
  // Skip data URLs (base64 encoded images)
  if (url.startsWith('data:')) {
    return false;
  }

  // Skip placeholder images
  const placeholderKeywords = [
    'loading',
    'spinner',
    'blank',
    'avatar',
    'icon',
    'logo',
    'ad',
    'advertisement'
  ];

  const lowerUrl = url.toLowerCase();
  for (const keyword of placeholderKeywords) {
    if (lowerUrl.includes(keyword)) {
      return false;
    }
  }

  // Skip very small images (likely icons)
  const sizeMatch = url.match(/[?&](?:w|width)=(\d+)/);
  if (sizeMatch && parseInt(sizeMatch[1]) < 100) {
    return false;
  }

  // Skip images with no file extension or common image extensions
  const hasImageExtension = /\.(jpg|jpeg|png|gif|webp|svg|bmp|tiff)(\?|$)/i.test(url);
  if (!hasImageExtension && !url.includes('image') && !url.includes('photo')) {
    return false;
  }

  return true;
}

/**
 * Scrapes content from article elements, prioritizing those with substantial content
 */
export function scrapeArticleContent(): ScrapedData {
  try {
    const result = findBestArticle();

    if (!result.hasValidArticle || !result.validArticle) {
      console.log('No article with sufficient content found for scraping');
      return {
        items: [],
        totalItems: 0,
        url: window.location.href,
        timestamp: Date.now()
      };
    }

    const bestArticle = result.validArticle;

    const items: ScrapedContentItem[] = [];
    let index = 0;

    // Process the best article
    try {
      // Get all children of the article
      const children = Array.from(bestArticle.children);

      children.forEach(child => {
        try {
          // Headings
          const tagName = child.tagName?.toLowerCase();
          if (tagName && /^h[1-6]$/.test(tagName)) {
            const level = parseInt(tagName[1] || '2', 10) as 1 | 2 | 3 | 4 | 5 | 6;
            const headingText = extractTextContent(child);
            if (headingText) {
              items.push({
                type: 'heading',
                content: headingText,
                headingLevel: level,
                index: index++
              });
            }
          } else {
            // Lists
            const listText = extractListText(child);
            if (listText) {
              items.push({
                type: 'text',
                content: listText,
                index: index++
              });
            } else {
              // Paragraph/other text
              const textContent = extractTextContent(child);
              if (textContent && textContent.length > 10) {
                items.push({
                  type: 'text',
                  content: textContent,
                  index: index++
                });
              }
            }
          }

          // Extract images with enhanced data
          const imageData = extractImageData(child);
          imageData.forEach(imgData => {
            items.push({
              type: 'image',
              content: imgData.url,
              index: index++,
              altText: imgData.alt,
              caption: imgData.caption
            });
          });
        } catch (childError) {
          console.warn('Error processing child element:', childError);
        }
      });
    } catch (articleError) {
      console.warn('Error processing article element:', articleError);
    }

    return {
      items,
      totalItems: items.length,
      url: window.location.href,
      timestamp: Date.now()
    };
  } catch (error) {
    console.error('Error in scrapeArticleContent:', error);
    return {
      items: [],
      totalItems: 0,
      url: window.location.href,
      timestamp: Date.now()
    };
  }
}

/**
 * Scrapes content ONLY from article tags
 */
export function scrapePageContent(): ScrapedData {
  const items: ScrapedContentItem[] = [];
  let index = 0;

  const articleElements = document.querySelectorAll('article');

  if (articleElements.length > 0) {
    // Process article elements
    articleElements.forEach(article => {
      const children = Array.from(article.children);

      children.forEach(child => {
        const tagName = child.tagName?.toLowerCase();
        if (tagName && /^h[1-6]$/.test(tagName)) {
          const level = parseInt(tagName[1] || '2', 10) as 1 | 2 | 3 | 4 | 5 | 6;
          const headingText = extractTextContent(child);
          if (headingText) {
            items.push({
              type: 'heading',
              content: headingText,
              headingLevel: level,
              index: index++
            });
          }
        } else {
          const listText = extractListText(child);
          if (listText) {
            items.push({
              type: 'text',
              content: listText,
              index: index++
            });
          } else {
            const textContent = extractTextContent(child);
            if (textContent && textContent.length > 10) {
              items.push({
                type: 'text',
                content: textContent,
                index: index++
              });
            }
          }
        }

        // Extract images with enhanced data
        const imageData = extractImageData(child);
        imageData.forEach(imgData => {
          items.push({
            type: 'image',
            content: imgData.url,
            index: index++,
            altText: imgData.alt,
            caption: imgData.caption
          });
        });
      });
    });
  }

  return {
    items,
    totalItems: items.length,
    url: window.location.href,
    timestamp: Date.now()
  };
}


export function scrapeContent(): ScrapedData {
  try {
    if (hasValidArticleContent()) {
      return scrapeArticleContent();
    }
    return {
      items: [],
      totalItems: 0,
      url: window.location.href,
      timestamp: Date.now()
    };
  } catch (error) {
    console.error('Error during content scraping:', error);
    return {
      items: [],
      totalItems: 0,
      url: window.location.href,
      timestamp: Date.now()
    };
  }
}

/**
 * Scrapes content and returns it in markdown format
 */
export function scrapeContentAsMarkdown(): MarkdownScrapedData {
  try {
    const scrapedData = scrapeContent();
    if (scrapedData.totalItems === 0 || !scrapedData.items || scrapedData.items.length === 0) {
      console.warn('No content found to scrape');
      return {
        markdown: '',
        totalItems: 0,
        url: window.location.href,
        timestamp: Date.now(),
        title: extractPageTitle(),
        description: extractPageDescription()
      };
    }

    const markdownData = convertToMarkdown(scrapedData);
    if (!markdownData.markdown) {
      return {
        markdown: '',
        totalItems: 0,
        url: window.location.href,
        timestamp: Date.now(),
        title: extractPageTitle(),
        description: extractPageDescription()
      };
    }

    return markdownData;
  } catch (error) {
    console.error('Error during markdown content scraping:', error);
    return {
      markdown: '',
      totalItems: 0,
      url: window.location.href,
      timestamp: Date.now(),
      title: 'Error',
      description: ''
    };
  }
}