import React, { useState, useMemo } from "react";
import ReactMarkdown from "react-markdown";
import { timeToSeconds } from "../../../../../src/utils/str-time-to-seconds";
import ArrowUp2 from "../../../../assets/icons/arrow-up2.svg";
import ArrowUp2Hover from "../../../../assets/icons/arrow-up2-hover.svg";
import ArrowDown from "../../../../assets/icons/arrow-dow.svg";
import ArrowDownHover from "../../../../assets/icons/arrow-dow-hover.svg";
import { getYoutubeVideoLength, getYoutubeVideoPlayHead } from "../../../../utils/get-youtube-video-length";
import { useCustomUI } from "../../../../contexts/custom-ui-context/custom-ui-context";
import { useChat } from "../../../../contexts/chat-context/chat-context";

const Summary = ({ markdown, mentorAiData, isSidePanelOpen, isYouTubeThemeDark }: { markdown: any, mentorAiData: any, isSidePanelOpen: boolean, isYouTubeThemeDark: boolean }) => {

    // const { trackCustomUIEvent } = useCustomUI();
    // const { sendMessage, setSelectedYouTubeSideSectionTab } = useChat();
    const handleSUmmeryFollowupClick = (message: string, selectedText: string) => {
        // sendMessage(message, true, `SelectedText: ${selectedText}`, true)
        // trackCustomUIEvent("Easy Action Clicked", {
        //     info: {
        //         easy_action: message,
        //         easy_action_title: message,
        //         section_title: "Summary",
        //         easy_action_message: message,
        //     },
        // });

        // Open side panel and send message there
        if (!isSidePanelOpen) {
            chrome.runtime.sendMessage({ action: "openSidePanel" }).then(() => {
                setTimeout(() => {
                    chrome.runtime.sendMessage({
                        action: "easyActionClicked",
                        easy_action: message,
                        easy_action_title: message,
                        url: window.location.href,
                        is_side_panel_opened: false,
                        section_title: "Summary",
                        easy_action_message: message,
                        additional_message: `SelectedText: ${selectedText}`
                    })
                }, 3000);
            });
        } else {
            chrome.runtime.sendMessage({
                action: "easyActionClicked",
                easy_action: message,
                easy_action_title: message,
                url: window.location.href,
                is_side_panel_opened: true,
                section_title: "Summary",
                easy_action_message: message,
                additional_message: `SelectedText: ${selectedText}`
            })
        }
    }

    function parseSummaryMarkdown(md: any) {
        if (!md) {
            return { summaryText: "", summaryFollowUp: "", insights: [] };
        }

        try {
            // Try to split by section headers
            let sections = md.split(/\n## /).filter(Boolean);

            // If no sections found, treat the entire text as summary
            if (sections.length === 0) {
                return { summaryText: md, summaryFollowUp: "", insights: [] };
            }

            // Add the prefix back to each section except the first one
            sections = sections.map((s: string, i: number) =>
                i === 0 && !s.startsWith("Video Summary") ? s : `## ${s}`
            );

            const summaryBlock = sections.find((s: any) => s.includes("## Video Summary"));
            const insightBlock = sections.find((s: any) =>
                s.includes("## Timestamped Insights")
            );

            // ---------- Top summary text ----------
            let summaryText = "";
            let summaryFollowUp = "";

            if (summaryBlock) {
                // Remove the header to get just the content
                summaryText = summaryBlock.replace(/^## Video Summary\s*/i, "");

                // Extract the follow-up question if it exists
                const followUpMatch = summaryText.match(/- \*\*Follow-up:\*\*\s*(.*)/);
                if (followUpMatch) {
                    summaryFollowUp = followUpMatch[1];
                    // Remove the follow-up line from summary text
                    summaryText = summaryText.replace(/- \*\*Follow-up:\*\*\s*.*/, "").trim();
                }
            }

            // ---------- Insights ----------
            const insights: any[] = [];
            if (insightBlock) {
                const lines = insightBlock.split("\n").slice(1); // drop section heading
                let current: any = null;

                lines.forEach((raw: any) => {
                    if (!raw) return; // Skip empty lines

                    const line = raw.trimEnd();

                    // Only process timestamp headers that match the expected format
                    if (line.startsWith("### ")) {
                        try {
                            const match = line.match(/^### ([0-9:]+)\s+(.*)/);
                            if (match) {
                                const [, ts, headline] = match;
                                // Save previous insight before starting a new one
                                if (current) insights.push(current);
                                current = {
                                    timestamp: ts,
                                    headline: headline || "Insight",
                                    details: "",
                                    followUp: "",
                                    state: "collapsed",
                                };
                            }
                        } catch (e) {
                            console.warn("Error parsing timestamp header:", e);
                            // Continue processing even if one header fails
                        }
                        return;
                    }

                    // Try to parse metadata lines
                    if (current && line.startsWith("- **")) {
                        try {
                            const metaMatch = line.match(/-\s+\*\*(.+?):\*\*\s*(.*)/);
                            if (metaMatch) {
                                const [, key, val = ""] = metaMatch;
                                switch (key.toLowerCase()) {
                                    case "details":
                                        current.details = val;
                                        break;
                                    case "follow-up":
                                        current.followUp = val;
                                        break;
                                    case "state":
                                        current.state = val === "expanded" ? "expanded" : "collapsed";
                                        break;
                                    default:
                                        break;
                                }
                            }
                        } catch (e) {
                            console.warn("Error parsing metadata line:", e);
                        }
                    } else if (current) {
                        // Append content to details if it's not a metadata line
                        // This handles multi-line content in details
                        current.details += line + "\n";
                    }
                });

                // Don't forget to add the last insight
                if (current) insights.push(current);
            }

            return { summaryText, summaryFollowUp, insights };
        } catch (error) {
            console.error("Error parsing markdown:", error);
            // Return gracefully with available data even if parsing fails
            return {
                summaryText: md,
                summaryFollowUp: "",
                insights: []
            };
        }
    }

    try {
        const { summaryText, summaryFollowUp, insights } = useMemo(
            () => parseSummaryMarkdown(markdown),
            [markdown]
        );
        return (
            <div
                className="font-manrope"
                style={{
                    fontSize: "16px",
                    fontWeight: "400",
                    letterSpacing: "0.096px",
                    lineHeight: "24px",
                    color: isYouTubeThemeDark ? "#AAAAAA" : "#606060",
                }}
            >
                <p style={{
                    fontSize: "14px",
                    fontWeight: "400",
                    color: isYouTubeThemeDark ? "#AAAAAA" : "#606060",
                    marginBottom: "20px",
                    lineHeight: "22px"
                }}>
                    <ReactMarkdown className="">{summaryText}</ReactMarkdown>
                </p>

                {summaryFollowUp && summaryFollowUp.trim() && (
                    <p style={{
                        display: "flex",
                        gap: "8px",
                    }}>
                        <div className="relative mt-[3px] h-[18px]">
                            {mentorAiData?.photoUrl || mentorAiData?.aiPhotoUrl ? (
                                <img
                                    style={{
                                        minWidth: "16px",
                                        minHeight: "16px",
                                    }}
                                    src={mentorAiData?.photoUrl || mentorAiData?.aiPhotoUrl}
                                    className="h-[16px] w-[16px] rounded-full"
                                    alt="avatar"
                                />
                            ) : (
                                <div className="w-[16px] h-[16px] rounded-full bg-[#000]" />
                            )}
                            <span className={`absolute -bottom-[1px] -right-[2px] border-[2px] w-[8px] h-[8px] rounded-full bg-[#1FC16B] ${isYouTubeThemeDark ? ' !border-[#272727]' : ' !border-[#F2F2F2]'}`} />
                        </div>

                        <div onClick={() => handleSUmmeryFollowupClick(summaryFollowUp, JSON.stringify(markdown))} style={{ display: "flex", gap: "8px", fontWeight: 500, color: "var(--youtube-primary-color, #A5A1F7)", cursor: "pointer", fontSize: 14, lineHeight: "22px", letterSpacing: "0.084px" }} className="hover:!text-[var(--youtube-primary-color)] max-w-[92%]">
                            {summaryFollowUp}
                        </div>
                    </p>
                )}


                <hr style={{
                    border: "none",
                    height: "1px",
                    backgroundColor: isYouTubeThemeDark ? "#30333c" : "#0000000a",
                    margin: "32px 0"
                }} />

                {insights.map((insight, index) => (
                    <>
                        <InsightItem key={insight.timestamp} insight={insight} isFirst={index === 0} mentorAiData={mentorAiData} isSidePanelOpen={isSidePanelOpen} markdown={markdown} isYouTubeThemeDark={isYouTubeThemeDark} />
                        {index !== insights.length - 1 && (
                            <hr style={{
                                border: "none",
                                height: "1px",
                                backgroundColor: isYouTubeThemeDark ? "#30333c" : "#0000000a",
                                marginBottom: "24px"
                            }} />
                        )}
                    </>
                ))}
            </div >
        )
    } catch (error) {
        console.error("Error parsing summary markdown", error);
        return (
            <p className="font-manrope" style={{
                fontSize: "14px",
                fontWeight: "400",
                color: isYouTubeThemeDark ? "#AAAAAA" : "#606060",
                marginBottom: "20px",
                lineHeight: "22px"
            }}>
                <ReactMarkdown className="">{markdown}</ReactMarkdown>
            </p>
        );
    }
}

export default Summary



const InsightItem = ({ insight, isFirst, mentorAiData, isSidePanelOpen, markdown, isYouTubeThemeDark }: { insight: any, isFirst?: boolean, mentorAiData: any, isSidePanelOpen: boolean, markdown: any, isYouTubeThemeDark: boolean }) => {
    const [open, setOpen] = useState(isFirst || insight.state === "expanded");
    const [isHovering, setIsHovering] = useState(null);
    // const { trackCustomUIEvent } = useCustomUI();
    // const { sendMessage, setSelectedYouTubeSideSectionTab } = useChat();

    const handleInsightFollowup = (message: string, selectedText: string) => {
        // sendMessage(message, true, `SelectedText: ${selectedText}`, true)
        // trackCustomUIEvent("Easy Action Clicked", {
        //     info: {
        //         easy_action: message,
        //         easy_action_title: message,
        //         section_title: "Summary",
        //         easy_action_message: message,
        //     },
        // });

        // Open side panel and send message there
        if (!isSidePanelOpen) {
            chrome.runtime.sendMessage({ action: "openSidePanel" }).then(() => {
                setTimeout(() => {
                    chrome.runtime.sendMessage({
                        action: "easyActionClicked",
                        easy_action: message,
                        easy_action_title: message,
                        url: window.location.href,
                        is_side_panel_opened: false,
                        section_title: "Summary",
                        easy_action_message: message,
                        additional_message: `SelectedText: ${selectedText}`
                    })
                }, 3000);
            });
        } else {
            chrome.runtime.sendMessage({
                action: "easyActionClicked",
                easy_action: message,
                easy_action_title: message,
                url: window.location.href,
                is_side_panel_opened: true,
                section_title: "Summary",
                easy_action_message: message,
                additional_message: `SelectedText: ${selectedText}`
            })
        }
    }

    const handleTimestampClick = (timestamp: string) => {
        const videoElement = document.querySelector("video");
        if (videoElement) {
            videoElement.currentTime = timeToSeconds(timestamp);
        }
        videoElement?.scrollIntoView({ behavior: "smooth" });
    }

    return (
        <div className="font-manrope" style={{ marginBottom: "24px" }}>
            <div style={{ display: "flex", alignItems: "flex-start" }}>
                <span
                    onClick={() => {
                        handleTimestampClick(insight.timestamp)
                        chrome.runtime.sendMessage({
                            action: "sendAnalytics",
                            url: window.location.href,
                            eventName: "MentorAi Revision Notes Timestamp Clicked",
                            eventProperties: {
                                timestamp: insight.timestamp,
                                section_name: insight.headline
                            },
                        })
                    }}
                    style={{
                        background: isYouTubeThemeDark ? "#ffffff1a" : "#0000001a",
                        color: "var(--youtube-primary-color, #A5A1F7)",
                        fontWeight: 500,
                        fontSize: 14,
                        borderRadius: 4,
                        padding: "4px",
                        cursor: "pointer",
                        lineHeight: "22px",
                        marginRight: 12,
                    }}
                    className="hover:!bg-[#ffffff1a] hover:!text-[var(--youtube-primary-color)] font-interDisplay"
                >
                    {insight.timestamp}
                </span>

                <div style={{ flexGrow: 1 }}>
                    <h4 style={{ fontSize: 14, fontWeight: 500, color: isYouTubeThemeDark ? "#DDDDDF" : "#0F0F0F", lineHeight: "22px", letterSpacing: "0.096px" }}>{insight.headline}</h4>
                    <span onMouseEnter={() => setIsHovering(insight.index)} onMouseLeave={() => setIsHovering(null)} onClick={() => {
                        setOpen(!open)
                        chrome.runtime.sendMessage({
                            action: "sendAnalytics",
                            url: window.location.href,
                            eventName: "MentorAi Revision Notes Section Expanded",
                            eventProperties: {
                                tab_name: "Summary",
                                section_name: insight.headline,
                                current_duration: getYoutubeVideoPlayHead(),
                                video_duration: getYoutubeVideoLength()
                            },
                        })
                    }}
                        style={{ fontSize: 14, lineHeight: "22px", letterSpacing: "0.084px", color: "var(--youtube-primary-color, #A5A1F7)", display: "flex", alignItems: "center", gap: "4px", cursor: "pointer", marginTop: "8px", fontWeight: 500 }} className="transition-all duration-100 hover:!text-[var(--youtube-primary-color)]">
                        {open ? "Collapse" : "Expand"}
                        {open ? <img src={isHovering === insight.index ? ArrowUp2Hover : ArrowUp2} alt="Collapse" /> : <img src={isHovering === insight.index ? ArrowDownHover : ArrowDown} alt="Expand" />}
                    </span>
                </div>
            </div>

            {open && (
                <div className="font-manrope" style={{ marginLeft: 54, marginTop: 12, fontSize: "16px", fontWeight: "400", letterSpacing: "0.096px", lineHeight: "24px", color: isYouTubeThemeDark ? "#AAAAAA" : "#606060" }}>
                    <p style={{
                        fontSize: "14px",
                        fontWeight: "400",
                        color: isYouTubeThemeDark ? "#AAAAAA" : "#606060",
                        marginBottom: "20px",
                        lineHeight: "22px"
                    }}>
                        <ReactMarkdown className="">{insight.details}</ReactMarkdown>
                    </p>

                    {insight.followUp && insight.followUp.trim() && (
                        <p className="flex " style={{ marginTop: 24, gap: "8px" }}>
                            <div className="relative mt-[3px] h-[18px]">
                                {mentorAiData?.photoUrl || mentorAiData?.aiPhotoUrl ? (
                                    <img style={{
                                        minWidth: "16px",
                                        minHeight: "16px",
                                    }}
                                        src={mentorAiData?.photoUrl || mentorAiData?.aiPhotoUrl}
                                        className="h-[16px] w-[16px] rounded-full"
                                        alt="avatar"
                                    />
                                ) : (
                                    <div className="w-[16px] h-[16px] rounded-full bg-[#000]" />
                                )}
                                <span className={`absolute -bottom-[1px] -right-[2px] border-[2px] w-[8px] h-[8px] rounded-full bg-[#1FC16B] ${isYouTubeThemeDark ? ' !border-[#272727]' : ' !border-[#F2F2F2]'}`} />
                            </div>


                            <div onClick={() => handleInsightFollowup(insight.followUp, JSON.stringify(markdown))} style={{ display: "flex", gap: "8px", fontWeight: 500, color: "var(--youtube-primary-color, #A5A1F7)", cursor: "pointer", fontSize: 14, lineHeight: "22px", letterSpacing: "0.084px" }} className="hover:!text-[var(--youtube-primary-color)] max-w-[92%]">
                                {insight.followUp}
                            </div>
                        </p>
                    )}
                </div>
            )}
        </div>
    );
};