import { motion, AnimatePresence } from 'framer-motion'
import Button from '../../../src/components/common/common-button'
import LeecoAvatar from '../../../src/assets/leeco_profile.webp'
import { LoaderWithThreeDots } from '../../../common/loader/loader'

const BlogSessionCard = ({ 
  handleLeaningCTAClick, 
  sessionState, 
  onMouseEnter, 
  onMouseLeave,
  showCard
}: { 
  handleLeaningCTAClick: () => void, 
  sessionState: any,
  onMouseEnter?: () => void,
  onMouseLeave?: () => void,
  showCard: boolean
}) => {
    return (
        <AnimatePresence>
            {showCard && (
                <motion.div
                    className="absolute bottom-[0px] right-[44px] flex items-start justify-between gap-2.5 self-stretch pt-[14px] pr-[10px] pb-[16px] pl-[12px] rounded-2xl bg-[#0E121B] w-[390px]"
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0, }}
                    exit={{ opacity: 0, y: -10, }}
                    transition={{
                        duration: 0.3,
                        ease: "easeOut",
                        type: "tween"
                    }}
                    onMouseEnter={onMouseEnter}
                    onMouseLeave={onMouseLeave}
                >
                    <img
                        src={LeecoAvatar}
                        alt="leeco avatar"
                        className="w-[24px] h-[24px] min-w-[24px] min-h-[24px] rounded-full"
                    />

                    <div className="flex flex-col items-start gap-[13px]">
                        <div
                            className="flex flex-col items-start gap-1 self-stretch"
                        >
                            <div className="self-stretch text-white font-bricolage-grotesque font-semibold leading-[20px] text-[13px] tracking-[0.065px]">Read this Blog with Leeco AI</div>
                            <div className="self-stretch text-white/80 text-[13px] leading-[21px] tracking-[-0.078px] font-manrope">{sessionState?.sessionData ? 'Great learning so far! Continue learning faster & smarter with Leeco.' : 'Learn smarter with Leeco for interactive highlights, quizzes, so you retain this forever.'}</div>
                        </div>

                        <Button
                            disabled={sessionState?.isLoading || sessionState?.ctaLoading}
                            onClick={() => {
                                chrome.runtime.sendMessage({
                                    action: "sendAnalytics",
                                    url: window.location.href,
                                    eventName: "Button Clicked",
                                    eventProperties: {
                                        button_name: sessionState?.sessionData ? 'Continue Learning' : 'Start Learning',
                                        location: "Quick Action"
                                    }
                                });
                                handleLeaningCTAClick();
                            }}
                            className={`whitespace-nowrap !w-fit flex px-2 justify-center items-center !h-[20px] !rounded-[5px] !font-semibold !text-xs tracking-[-0.12px]
                                bg-white text-[#2B303B] hover:bg-[#5149F2] hover:text-[#FFF] pb-[1px]`}
                        >
                            {sessionState?.ctaLoading ? <LoaderWithThreeDots color='#000'/> : sessionState?.sessionData ? 'Continue Learning' : 'Start Learning'}
                        </Button>
                    </div >
                    {/* <span
                        className="cursor-pointer absolute top-[10px] right-[10px]"
                        onClick={handleClose}
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 20 20" fill="none">
                            <g opacity="0.72">
                                <path d="M10.0001 8.93949L13.7126 5.22699L14.7731 6.28749L11.0606 9.99999L14.7731 13.7125L13.7126 14.773L10.0001 11.0605L6.28755 14.773L5.22705 13.7125L8.93955 9.99999L5.22705 6.28749L6.28755 5.22699L10.0001 8.93949Z" fill="white" />
                            </g>
                        </svg>
                    </span> */}
                </motion.div >
            )}
        </AnimatePresence>
    )
}

export default BlogSessionCard