import React from 'react';
import LoadingSpinner from "../../../assets/gif/loading.gif";
import type { AnalysisStatus } from '../types';
import { STYLES } from '../constants';

export const getStepStatus = (stepId: number, currentStep: number): AnalysisStatus => {
  if (currentStep > stepId) return "completed";
  if (currentStep === stepId) return "in-progress";
  return "yet-to-start";
};

export const getStepIcon = (status: AnalysisStatus) => {
  switch (status) {
    case "completed":
      return (
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 20 20" fill="none">
          <rect x="2" y="2" width="16" height="16" rx="8" fill="#5149F2" />
          <path fillRule="evenodd" clipRule="evenodd" d="M14.5294 8.03039L8.99908 13.5607L5.46875 10.0304L6.52941 8.96973L8.99908 11.4394L13.4688 6.96973L14.5294 8.03039Z" fill="#F2F2F2" />
        </svg>
      );
    case "in-progress":
      return <img src={LoadingSpinner} className="w-[16px] h-[16px]" alt="loading" />;
    case "yet-to-start":
      return <div className="w-[16px] h-[16px] rounded-full border border-mentorai-stroke-strong shadow-[0_2px_8px_0px_rgba(255,255,255,0.04)]" />;
  }
};

export const getStepTextStyle = (status: AnalysisStatus): string => {
  switch (status) {
    case "completed":
      return STYLES.COMPLETED_TEXT;
    case "in-progress":
      return STYLES.IN_PROGRESS_TEXT;
    case "yet-to-start":
      return STYLES.YET_TO_START_TEXT;
  }
}; 