import '../utils/chatgpt-capture';
import '../utils/gemini-capture';
import '../utils/perplexity-capture';
import * as React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import { checkUrlListingStatus } from '../utils/helper';

const createFloatingButton = () => {
  // Create a container for the React component
  const container = document.createElement('main');
  container.id = 'mentorai-extension';
  container.className = 'preplaced-extension';
  document.body.appendChild(container);
  const currentUrl = window.location.href;
  let mentorai = "pro-pilot";
  chrome.storage.local.get(["mentorai"], (result) => {
    if (result.mentorai) {
      mentorai = result.mentorai;
    }
  });
  const listingStatus = checkUrlListingStatus(currentUrl, mentorai);

  if (listingStatus === "blacklisted") {
    return;
  }

  const root = createRoot(container);
  root.render(
    React.createElement(App)
  );
};

// Initialize when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', createFloatingButton);
} else {
  window.addEventListener("message", (event) => {
    if (event.source !== window) return;
    if (event.data.action === "openSidePanel") {
      chrome.runtime.sendMessage({ action: "openSidePanel" }, (response) => {
        setTimeout(() => {
          window.postMessage({ action: "sidePanelOpened" }, "*");
        }, 500)
      });
    } else if (event.data.action === "setResourceView") {
      chrome.runtime.sendMessage({ action: "activateResourceView" }, (response) => {
        window.postMessage({ action: "resourceViewActivated" }, "*");
      });
    } else {
      return;
    }
  });
  createFloatingButton();
} 