import React from 'react'
import { useCustomUI } from '../../../../contexts/custom-ui-context/custom-ui-context';

const SectionDetailsWithCTA = ({ sectionTitle, sectionDescription, sectionCTAs, sectionCTADescription, sectionDurationAndDetails, followupQuestions }: { sectionTitle: any, sectionDescription?: any, sectionCTAs?: any, sectionDurationAndDetails?: any, sectionCTADescription?: any, followupQuestions?: any }) => {
    const { playerMode } = useCustomUI();
    const isPlayerModeDefault = playerMode === "DEFAULT";
    return (
        <div className="flex flex-col w-full h-fit" style={{}}>
            <p style={{
                fontSize: isPlayerModeDefault ? 24 : 36,
                fontWeight: 700,
                color: "#DDDDDF",
                lineHeight: isPlayerModeDefault ? "34px" : "46px",
                marginTop: isPlayerModeDefault ? '0px' : "16px"
            }}>{sectionTitle || ""}</p>

            {sectionCTADescription &&
                <p style={{ fontSize: isPlayerModeDefault ? 16 : 20, fontWeight: 500, color: "#DDDDDF", lineHeight: isPlayerModeDefault ? '24px' : '28px', marginTop: "20px" }}>{sectionCTADescription}</p>
            }

            {sectionDurationAndDetails &&
                <div className="w-full" style={{ marginTop: "16px" }}>
                    {sectionDurationAndDetails}
                </div>
            }

            {followupQuestions &&
                <div className="w-full" style={{ marginTop: "16px" }}>
                    {followupQuestions}
                </div>
            }


            {sectionDescription &&
                <p style={{ fontSize: isPlayerModeDefault ? 14 : 16, fontWeight: 500, color: "#DDDDDF", lineHeight: isPlayerModeDefault ? '22px' : '24px', marginTop: "16px", letterSpacing: isPlayerModeDefault ? '0.084px' : '0.096px' }}>{sectionDescription}</p>
            }

            {sectionCTAs &&
                <>
                    {sectionCTAs}
                </>
            }
        </div>
    )
}

export default SectionDetailsWithCTA