import { useCallback } from 'react';

// ───────── helpers ────────────────────────────────────────────────── //

function ytContext() {
  const cfg = (window as any).ytcfg || { get: () => null };
  const context = {
    // key: cfg.get('INNERTUBE_API_KEY'),
    clientVersion: '1.20241009.01.00',
    clientName: cfg.get('INNERTUBE_CONTEXT_CLIENT_NAME') || 'WEB_EMBEDDED_PLAYER',
  };
  // console.log("ytContext:", context);
  return context;
}


/** build Map<lang → track> like Sider */
function buildTrackMap(tracks:any) {
    // console.log("Building track map from tracks:", tracks);
    const map:any = new Map();
    for (const t of tracks) {
      const full = t.kind === 'asr' ? `${t.languageCode}__asr` : t.languageCode;
      const base = full.split('-')[0];
      if (!map.has(full)) map.set(full, t);
      if (!map.has(base)) map.set(base, t);
    }
    // console.log("Built track map:", Object.fromEntries(map));
    return map;
}

/** try internal player API first */
async function getCaptionMapByAPI(videoId:any) {
    // console.log("Getting captions via API for videoId:", videoId);
    // const { clientVersion, clientName} = ytContext();
    // if (!key) {
    //   console.log("No API key found, returning null");
    //   return null;
    // }
  
    const res = await fetch(
      `https://www.youtube.com/youtubei/v1/player`, {
        method: "post",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            videoId: videoId,
            context: {
                client: {
                    clientName: "WEB_EMBEDDED_PLAYER",
                    clientVersion: "1.20241009.01.00"
                }
            }
        })
      });
  
    if (!res.ok) {
      console.log("API request failed:", res.status, res.statusText);
      return null;
    }
    const j = await res.json();
    // console.log("API response:", j);
    const list = j?.captions?.playerCaptionsTracklistRenderer;
    return list ? buildTrackMap(list.captionTracks) : null;
}

/** fallback: scrape watch-page HTML */
async function getCaptionMapByFetch(videoId:any) {
    // console.log("Getting captions via HTML scraping for videoId:", videoId);
    const r = await fetch(`https://www.youtube.com/watch?v=${videoId}&hl=en`);
    if (!r.ok) {
      console.log("Failed to fetch video page:", r.status, r.statusText);
      return null;
    }
    const html = await r.text();
  
    const m = html.match(/ytInitialPlayerResponse\s*=\s*({.+?});/s);
    if (!m) {
      console.log("Could not find player response in HTML");
      return null;
    }
  
    const pr   = JSON.parse(m[1]);
    // console.log("Parsed player response:", pr);
    const list = pr?.captions?.playerCaptionsTracklistRenderer;
    return list ? buildTrackMap(list.captionTracks) : null;
}

/** download one track as JSON3 and flatten to fine-grained cues */
async function fetchTranscriptCues(track:any, targetLang:any) {
    let url = track.baseUrl + '&fmt=json3';
    if (targetLang && targetLang !== track.languageCode)
      url += `&tlang=${targetLang}`;
  
    const j3 = await fetch(url).then(r => r.json());
  
    const cues = [];
    for (const ev of j3.events || []) {
      if (!ev.segs) continue;
      const text = ev.segs.map((s:any) => s.utf8).join('').trim();
      if (text) cues.push({
        text,
        start:     ev.tStartMs          / 1000,
        duration: (ev.dDurationMs ?? 0) / 1000
      });
    }
    return cues;
}

/** merge adjacent cues until each block ≥ minSec seconds */
function mergeCues(cues:any, minSec:any) {
    const merged:any = [];
    let bufText = '', bufStart = null, bufDur = 0;
  
    for (const c of cues) {
      if (bufStart === null) bufStart = c.start;
      bufText += (bufText ? ' ' : '') + c.text;
      bufDur  += c?.duration;
  
      if (bufDur >= minSec) {           // flush chunk
        merged.push({text: bufText, start: bufStart, duration: bufDur});
        bufText = ''; bufStart = null; bufDur = 0;
      }
    }
    if (bufText)                        // tail < minSec
      merged.push({text: bufText, start: bufStart, duration: bufDur});
  
    return merged;
}

// ───────── main entry ──────────────────────────────────────────────── //

/* ───────── main entry ──────────────────────────────────────────────── */

/**
 * getTranscript(pageUrl, preferredLang = 'en', minBlockSec = 10)
 *   → Promise< [{text,start,duration}, …] >
 */
async function getTranscript(
  pageUrl: string,
  preferredLang = "en",
  minBlockSec = 10
) {
  const idMatch =
    pageUrl.match(/[?&]v=([\w-]{11})/) ||
    pageUrl.match(/\/(?:shorts|embed)\/([\w-]{11})/);
  if (!idMatch) throw new Error("No videoId in URL");
  const videoId = idMatch[1];

  // 1️⃣  Collect ALL available tracks once
  let trackMap = (await getCaptionMapByAPI(videoId)) ??
                 (await getCaptionMapByFetch(videoId));
  if (!trackMap || !trackMap.size) throw new Error("No captions for this video");

  // 2️⃣  Build an ordered list of tracks to try
  const orderedTracks: any[] = [];
  const pushUnique = (t: any) => {
    if (t && !orderedTracks.includes(t)) orderedTracks.push(t);
  };

  pushUnique(trackMap.get(preferredLang));
  pushUnique(trackMap.get(`${preferredLang}__asr`));
  // push the rest (Map iteration order is stable in V8)
  for (const t of trackMap.values()) pushUnique(t);

  // 3️⃣  Try each track until we have ≥ 2 merged blocks
  for (const track of orderedTracks) {
    try {
      const fine   = await fetchTranscriptCues(track, preferredLang);
      const merged = mergeCues(fine, minBlockSec);
      if (merged.length >= 2) return merged;   // ✅  success
    } catch { /* ignore bad tracks and continue */ }
  }

  // 4️⃣  If we get here, every track was unusable
  throw new Error("Transcript too sparse on every available track");
}


// ───────── React Hook ──────────────────────────────────────────────── //

export function useYTTranscript() {
  // useCallback is not strictly necessary here, but included for consistency
  return {getTranscript}
} 