import { getCurrentExtensionUsedDaysCount } from "../../utils/helper";
import { getUserStatus } from "../../utils/subscription-helpers";

export interface CheckoutRedirectOptions {
  chatUsageData?: any;
  location?: string;
  selectedPlan?: "1 month" | "1 year";
  menteeData?: any;
  menteeSubscription?: any;
}

export const redirectToCheckout = async (options: CheckoutRedirectOptions = {}) => {
  const {
    chatUsageData,
    location = "Unknown",
    selectedPlan = "1 year",
    menteeData,
    menteeSubscription
  } = options;

  const getLifetimeMessages = async () => {
    const response = await fetch(
      `${import.meta.env.VITE_PREPLACED_BACKEND_AI_URL}/candidates/extension_messages_count?email=${menteeData?.email
      }&current_date=${new Date().toISOString().split("T")[0]}`,
    );
    const data = await response.json();
    return data?.message_count?.[0] || 0;
  };

  const userStatus = menteeSubscription ? getUserStatus(menteeSubscription) : null;
  
  let expiry_days_left = null;
  if (userStatus && (userStatus.isTrial || userStatus.isPaid)) {
    expiry_days_left = userStatus.daysRemaining;
  }

  let user_plan = null;
  if (userStatus && (userStatus.isTrial || userStatus.isPaid)) {
    const menteeSubscriptionDetails = menteeSubscription?.subscriptions?.find((subscription: any) => subscription.status === "Active") || menteeSubscription?.subscriptions?.[0];
    if (menteeSubscriptionDetails?.packageVersion) {
      user_plan = menteeSubscriptionDetails.packageVersion === "1 year" ? "1 year" : 
                  menteeSubscriptionDetails.packageVersion === "1 month" ? "1 month" : 
                  menteeSubscriptionDetails.packageVersion === "3 months" ? "3 months" : 
                  menteeSubscriptionDetails.packageVersion === "1 week" ? "1 week" : null;
    }
  }

  let user_type = "free";
  if (userStatus) {
    if (userStatus.isExpired) {
      user_type = "expired";
    } else if (userStatus.isTrial) {
      user_type = "trial";
    } else if (userStatus.isPaid) {
      user_type = "paid";
    }
  }

  chrome.runtime.sendMessage({
    action: "sendAnalytics",
    url: window.location.href,
    eventName: "Mentor AI Checkout Started",
    eventProperties: {
      location: location,
      expiry_days_left: expiry_days_left,
      user_plan: user_plan,
      user_type: user_type
    }
  });

  // Get required data
  let extensionUsedDaysCount = 0;
  let daily_message_limit_variant = null;

  try {
    extensionUsedDaysCount = await getCurrentExtensionUsedDaysCount();
    const storageData = await chrome.storage.local.get("daily_message_limit_variant");
    daily_message_limit_variant = storageData.daily_message_limit_variant;
  } catch (error) {
    console.error("Error getting checkout data:", error);
  }

  // Build checkout URL
  const devUrl = import.meta.env.VITE_LEECO_WEB_URL;
  const mentorAiPublicProfileId = (await chrome.storage.local.get("mentorai")).mentorai;
  const msgCount = await getLifetimeMessages();

  let urlWithParams = new URL(`${devUrl}/checkout/extension/${mentorAiPublicProfileId}`);
  urlWithParams.searchParams.set("validity", selectedPlan);
  urlWithParams.searchParams.set("spawnRazorpay", "true");
  urlWithParams.searchParams.set("extensionUsedDaysCount", `${extensionUsedDaysCount}`);
  if (msgCount) {
    urlWithParams.searchParams.set("lifetime_messages", `${msgCount}`);
  }
  if (menteeData?.extensionDailyMessageLimit) {
    urlWithParams.searchParams.set("daily_message_limit", `${menteeData.extensionDailyMessageLimit}`);
  }
  if (daily_message_limit_variant) {
    urlWithParams.searchParams.set("daily_message_limit_variant", `${daily_message_limit_variant}`);
  }
  if (chatUsageData?.dailyMessagesLeft !== undefined) {
    urlWithParams.searchParams.set("daily_messages_left", `${chatUsageData.dailyMessagesLeft}`);
  }
  if (location === "Trial Cancelled Banner") {
    urlWithParams = new URL(`${devUrl}/authenticate-extension`);
  }
  window.open(urlWithParams.toString(), "_blank");
};
