import { motion } from "framer-motion";
import { useThemeDetection } from "../../../../hooks/use-theme-detection";
import MentorAiButton from "../../../../../common/button/mentorai-button";
import getCurrency, { getFormattedPriceWithSymbol } from "../../../../../utils/currency";
import useExtensionPlansContainer from "../../../../../src/components/conversation-container/extension-paywall/plan-sheet-new/components/extension-plans/use-extension-plans-container";
import StarLight from "../../../../assets/icons/star-light.svg?react";
import CodeLight from "../../../../assets/icons/code-light.svg?react";
import UserHeartLight from "../../../../assets/icons/user-heart-light.svg?react";
import HeartLight from "../../../../assets/icons/heart-light.svg?react";
import IdeaLight from "../../../../assets/icons/idea-light.svg?react";
import FocusLight from "../../../../assets/icons/focus-light.svg?react";
import RefreshLight from "../../../../assets/icons/refresh-light.svg?react";

import StarDark from "../../../../assets/icons/star-dark.svg?react";
import CodeDark from "../../../../assets/icons/code-dark.svg?react";
import UserHeartDark from "../../../../assets/icons/user-heart-dark.svg?react";
import HeartDark from "../../../../assets/icons/heart-dark.svg?react";
import IdeaDark from "../../../../assets/icons/idea-dark.svg?react";
import FocusDark from "../../../../assets/icons/focus-dark.svg?react";
import RefreshDark from "../../../../assets/icons/refresh-dark.svg?react";
import { useEffect, useRef } from "react";
import { redirectToCheckout } from "../../../../../src/utils/checkout-redirect";
import { useAuthContext } from "../../../../contexts/auth-context/auth-context";
import { getMostRecentSubscription } from "../../../../../utils/subscription-helpers";


const UpgradeToProInterviewModeCard = () => {
  const { isDark } = useThemeDetection();
  const isComponentMounted = useRef(false);
  const { menteeSubscription } = useAuthContext()
  const latestSubscription = getMostRecentSubscription(menteeSubscription?.subscriptions);
  const isTrialCancelled = latestSubscription?.cancelledOn && menteeSubscription?.pricing_plan?.user_type === "trial";
  const handleUpgradeToProClick = async () => {
    if (isTrialCancelled) {
      redirectToCheckout({
        location: "Trial Cancelled Banner",
        menteeSubscription: menteeSubscription
      });
    } else {
    redirectToCheckout({
      location: "1:1 Session Pop-up",
      menteeSubscription: menteeSubscription
    });
  }
}
  const { extensionPlans } = useExtensionPlansContainer();
  const monthlyPriceString = getFormattedPriceWithSymbol(extensionPlans?.find((plan) => plan?.validity === "1 month")?.totalPrice!);
  const currency = getCurrency();

  useEffect(() => {
    if (isComponentMounted.current) {
      return;
    } else {
      chrome.runtime.sendMessage({
        action: "sendAnalytics", url: window.location.href, eventName: "1:1 Session Paywall Popup Shown", eventProperties: {}
      })
    }
    isComponentMounted.current = true;
  }, []);

  if (isDark === null) return null;
  return (
    <motion.div
      initial={{ opacity: 0, y: 24 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 24 }}
      transition={{ duration: 0.1, ease: 'easeOut' }}
      className={`mt-0.5 w-[543px] absolute border  rounded-[12px] cursor-default z-50 font-bricolage-grotesque ml-[-75%] ${isDark ? 'bg-[#07070C] border-[rgba(255,255,255,0.12)]' : 'bg-[linear-gradient(94deg,_#FFF7F1_6.12%,_#FDF4FE_52.18%,_#F5F2FF_96.4%)] border-[rgba(0,0,0,0.08)] shadow-[0_4px_12px_0_rgba(0,0,0,0.08)]'}`}
    >
      <div className={`flex flex-col w-full h-full pt-6 px-5 pb-5 rounded-[12px] ${isDark ? 'bg-[linear-gradient(181deg,_rgba(255,_155,_83,_0.80)_0.54%,_rgba(236,_110,_255,_0.70)_8.34%,_rgba(127,_98,_255,_0.60)_17.01%,_rgba(7,_7,_12,_0.50)_31.15%)]' : ''}`}>
        <h2 className={`text-[22px]  font-bold font-bricolage-grotesque leading-[30px] tracking-[-0.44px] flex items-start justify-center gap-2.5 ${isDark ? 'text-white' : 'text-[#07070A]'}`}>
          {isDark ? <StarDark className="w-[20px] h-[25px]" /> : <StarLight className="w-[20px] h-[25px]" />}
          <span className="max-w-[390px] text-center"> Unlock 1:1 Sessions for Real Interview <br /> Preparation with the Pro Plan</span>
          {isDark ? <StarDark className="w-[20px] h-[25px]" /> : <StarLight className="w-[20px] h-[25px]" />}
        </h2>

        <div className="grid grid-cols-2 gap-4 mt-6">
          <div className={`w-full flex flex-col`}>
            <p className={`text-[10px] font-bold uppercase font-manrope tracking-[0.4px] w-full flex justify-center items-center ${isDark ? 'text-white' : 'text-[#07070A]'}`}>
              1:1 INTERVIEW SIMULATION SESSIONS
            </p>
            <div className={`rounded-xl mt-2 py-4 pl-[14px] pr-4 flex flex-col gap-5 border ${isDark ? 'bg-[rgba(0,0,0,0.15)] border-[rgba(255,255,255,0.10)]' : 'bg-[rgba(255,255,255,0.80)] border-[rgba(255,255,255,0.10)]'}`}>
              <div className="flex gap-1.5">
                {isDark ? <CodeDark className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" /> : <CodeLight className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" />}
                <div className="flex flex-col gap-1">
                  <h4 className={`text-[12px] font-semibold leading-[18px] tracking-[-0.12px] font-manrope ${isDark ? 'text-white' : 'text-[#07070A]'}`}>Turn Problems Into Interviews</h4>
                  <p className={`text-[12px] font-medium leading-[18px] font-manrope flex justify-center items-center  ${isDark ? 'text-[#94939F]' : 'text-[#00000066]'}`}>Practice your favourite questions in a timed, real interview setting.</p>
                </div>
              </div>
              <div className="flex gap-1.5">
                {isDark ? <HeartDark className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" /> : <HeartLight className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" />}
                <div className="flex flex-col gap-1">
                  <h4 className={`text-[12px] font-semibold leading-[18px] tracking-[-0.12px] font-manrope ${isDark ? 'text-white' : 'text-[#07070A]'}`}>Detailed Feedback Report</h4>
                  <p className={`text-[12px] font-medium leading-[18px] font-manrope  ${isDark ? 'text-[#94939F]' : 'text-[#00000066]'}`}>Receive an in-depth breakdown of your approach, coding, and communication with clear improvement points.</p>
                </div>
              </div>
              <div className="flex gap-1.5">
                {isDark ? <UserHeartDark className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" /> : <UserHeartLight className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" />}
                <div className="flex flex-col gap-1">
                  <h4 className={`text-[12px] font-semibold leading-[18px] tracking-[-0.12px] font-manrope ${isDark ? 'text-white' : 'text-[#07070A]'}`}>Confidence Boost</h4>
                  <p className={`text-[12px] font-medium leading-[18px] font-manrope  ${isDark ? 'text-[#94939F]' : 'text-[#00000066]'}`}>Get used to pressure so you stay calm in real interviews.</p>
                </div>
              </div>
            </div>
          </div>

          <div className={`w-full flex flex-col`}>
            <p className={`text-[10px] font-bold uppercase font-manrope tracking-[0.4px] w-full flex justify-center items-center ${isDark ? 'text-white' : 'text-[#07070A]'}`}>
              1:1 STRUCTURED COACHING SESSIONS
            </p>
            <div className={`rounded-xl mt-2 py-4 pl-[14px] pr-4 flex flex-col gap-5 border ${isDark ? 'bg-[rgba(0,0,0,0.15)] border-[rgba(255,255,255,0.10)]' : 'bg-[rgba(255,255,255,0.80)] border-[rgba(255,255,255,0.10)]'}`}>
              <div className="flex gap-1.5">
                {isDark ? <IdeaDark className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" /> : <IdeaLight className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" />}
                <div className="flex flex-col gap-1">
                  <h4 className={`text-[12px] font-semibold leading-[18px] tracking-[-0.12px] font-manrope ${isDark ? 'text-white' : 'text-[#07070A]'}`}>Learn Interview Best Practices</h4>
                  <p className={`text-[12px] font-medium leading-[18px] font-manrope  ${isDark ? 'text-[#94939F]' : 'text-[#00000066]'}`}>Master structuring answers and communicating your thoughts.</p>
                </div>
              </div>
              <div className="flex gap-1.5">
                {isDark ? <FocusDark className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" /> : <FocusLight className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" />}
                <div className="flex flex-col gap-1">
                  <h4 className={`text-[12px] font-semibold leading-[18px] tracking-[-0.12px] font-manrope ${isDark ? 'text-white' : 'text-[#07070A]'}`}>Targeted Guidance</h4>
                  <p className={`text-[12px] font-medium leading-[18px] font-manrope  ${isDark ? 'text-[#94939F]' : 'text-[#00000066]'}`}>You will be guided through the exact structure and frameworks that are expected from top candidates.</p>
                </div>
              </div>
              <div className="flex gap-1.5">
                {isDark ? <RefreshDark className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" /> : <RefreshLight className="w-[17px] h-[18px] min-w-[17px] min-h-[18px]" />}
                <div className="flex flex-col gap-1">
                  <h4 className={`text-[12px] font-semibold leading-[18px] tracking-[-0.12px] font-manrope ${isDark ? 'text-white' : 'text-[#07070A]'}`}>Best for everyday practice</h4>
                  <p className={`text-[12px] font-medium leading-[18px] font-manrope  ${isDark ? 'text-[#94939F]' : 'text-[#00000066]'}`}>Strengthen your thinking skills until it feels natural.</p>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-3">
          <MentorAiButton
            type="primary"
            size="large"
            onClick={handleUpgradeToProClick}
            classNames="w-full font-bricolage-grotesque mt-6"
          >
            {isTrialCancelled ? `Reactivate at ${currency === "INR" ? "₹1" : "FREE"}` : monthlyPriceString.includes("NaN") ? "Unlock with Pro" : `Unlock with Pro at ${monthlyPriceString}`}
          </MentorAiButton>

          <p className={`text-xs font-medium leading-[20px] text-center font-manrope ${isDark ? 'text-[#94939F]' : 'text-[rgba(0,0,0,0.40)]'}`}>
            Also get unlimited credits, unlimited path creations, and GPT-5 with the Pro Plan.
          </p>
        </div>
      </div>
    </motion.div>
  );
};

export default UpgradeToProInterviewModeCard;
