import fetchMentorai from "../src/utils/background-helper";
import checkValidSubscription from "../utils/check-valid-subscription";
import { getCurrentExtensionUsedDaysCount } from "../utils/helper";
import { handleAnalyticsIdentify, handleAnalyticsIdentifyV2, handleAnalyticsPost } from "./Axios";

export const getBrowserInfo = () => {
  const userAgent = navigator.userAgent;
  const browserInfo = {
    browser_name: '',
    browser_version: '',
    os_family: '',
    os_version: '',
    engine_name: '',
    device: ''
  };

  // Get browser name and version
  if (userAgent.includes('Firefox/')) {
    browserInfo.browser_name = 'Firefox';
    browserInfo.browser_version = userAgent.split('Firefox/')[1].split(' ')[0];
  } else if (userAgent.includes('Chrome/')) {
    browserInfo.browser_name = 'Chrome';
    browserInfo.browser_version = userAgent.split('Chrome/')[1].split(' ')[0];
  } else if (userAgent.includes('Safari/')) {
    browserInfo.browser_name = 'Safari';
    browserInfo.browser_version = userAgent.split('Version/')[1]?.split(' ')[0];
  }

  // Get OS info
  if (userAgent.includes('Windows')) {
    browserInfo.os_family = 'Windows';
    browserInfo.os_version = userAgent.split('Windows ')[1]?.split(';')[0];
  } else if (userAgent.includes('Mac OS X')) {
    browserInfo.os_family = 'Mac OS';
    browserInfo.os_version = userAgent.split('Mac OS X ')[1]?.split(')')[0];
  } else if (userAgent.includes('Linux')) {
    browserInfo.os_family = 'Linux';
  }

  // Get engine name
  if (userAgent.includes('Gecko/')) {
    browserInfo.engine_name = 'Gecko';
  } else if (userAgent.includes('WebKit/')) {
    browserInfo.engine_name = 'WebKit';
  } else if (userAgent.includes('Blink/')) {
    browserInfo.engine_name = 'Blink';
  }

  // Get device info
  browserInfo.device = navigator.platform;

  return browserInfo;
};

export const eventPropertyBuilder = async (
  url: string,
  extra_track_properties: any) => {
  try {
    let extensionUsedDaysCount = await getCurrentExtensionUsedDaysCount();
    let params = Object.fromEntries(new URLSearchParams(url?.split("?")[1] || {}).entries());
    const urlOrigin = new URL(url).origin;
    const browserInfo = getBrowserInfo();
    const mentorAiDataInLocalStorage = await chrome.storage.local.get("mentorai_data")
    const userContext = await chrome.storage.local.get("context")
    const userLeetCodeProfileContext = userContext?.context?.[urlOrigin]?.['profile-data']
    const { interviewModeStatus, interviewCount, practiceModeStatus, practiceCount, coding_prompt_version, speech_to_text, lc_theme, model_version, interview_mode_access_option_variant, daily_message_limit_variant, menteeSubscription, dynamic_easy_action_option_variant, initial_default_tab_variant, show_trial_screen, sample_resources_practice_mode_variant } = await chrome.storage.local.get(["interviewModeStatus", "interviewCount", "practiceModeStatus", "practiceCount", "coding_prompt_version", "speech_to_text", "lc_theme", "model_version", "interview_mode_access_option_variant", "daily_message_limit_variant", "menteeSubscription", "dynamic_easy_action_option_variant", "initial_default_tab_variant", "show_trial_screen", "sample_resources_practice_mode_variant"])
    const utmParams = await chrome.storage.local.get('utmParams');

    const isPaidUser = checkValidSubscription(menteeSubscription)

    let mentoraiData;
    if (mentorAiDataInLocalStorage?.mentorai_data) {
      mentoraiData = mentorAiDataInLocalStorage?.mentorai_data
    } else {
      mentoraiData = await fetchMentorai()
      await chrome.storage.local.set({ mentorai_data: mentoraiData })
    }
    const mentorai = {
      name: mentoraiData?.name,
      record_id: mentoraiData?.recordId,
      public_profile_id: mentoraiData?.['publicProfileId(FromMentors)']?.[0]
    }

    let fieldsToAdd = {}
    if (['PREVIEW', 'ONGOING', 'FEEDBACK_GENERATED', 'FEEDBACK'].includes(interviewModeStatus)) {
      fieldsToAdd = {
        interview_mode_version: 'beta',
        interview_count: interviewCount,
      }
    }
    if (['PM_PREVIEW', 'PM_ONGOING', 'PM_FEEDBACK_GENERATED', 'PM_FEEDBACK'].includes(practiceModeStatus)) {
      const validatedPracticeCount = typeof practiceCount === 'number' ? practiceCount : (practiceCount || 1);
      fieldsToAdd = {
        practice_count: validatedPracticeCount,
      }
    }

    let session_type = "default";
    if (["PM_PREVIEW", "PM_ONGOING", "PM_FEEDBACK_GENERATED", "PM_FEEDBACK"].includes(practiceModeStatus)) {
      session_type = "Practice Mode";
    } else if (["PREVIEW", "ONGOING", "FEEDBACK_GENERATED", "FEEDBACK"].includes(interviewModeStatus)) {
      session_type = "Interview Mode";
    }
    if (show_trial_screen) {
      fieldsToAdd = {
        ...fieldsToAdd,
        show_trial_screen: show_trial_screen
      }
    }

    const subscriptionFields: any = {};
    try {
      const menteeSubscriptionDetails = menteeSubscription?.subscriptions?.find((subscription: any) => subscription.status === "Active") || menteeSubscription?.subscriptions?.[0];
      const isPlanASubscription = !!menteeSubscriptionDetails?.subscriptionId;
      const isPlanActive = menteeSubscriptionDetails?.status === "Active";
      const isPlanCancelled = menteeSubscriptionDetails?.status === "Active" && !!menteeSubscriptionDetails?.cancelledOn;

      const daysBetweenFromNow = (targetDateStr: string) => {
        let target: any = new Date(targetDateStr);
        if (`${target}`.includes("Invalid")) {
          target = new Date(targetDateStr?.split('T')?.[0]);
        }

        const now = new Date();
        const diffMs = target.getTime() - now.getTime();
        const days = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
        return Math.max(0, days);
      };

      if (isPlanASubscription) {
        if (isPlanCancelled && menteeSubscriptionDetails?.actualExpirationDate) {
          subscriptionFields.has_cancelled = true;
          subscriptionFields.days_from_expiry = daysBetweenFromNow(menteeSubscriptionDetails.actualExpirationDate);
        } else if (isPlanActive && menteeSubscriptionDetails?.nextRenewalDate) {
          subscriptionFields.has_cancelled = false;
          subscriptionFields.days_from_renewal = daysBetweenFromNow(menteeSubscriptionDetails.nextRenewalDate);
        }
      }
    } catch (e) {
    }

    return {
      source: "Extension",
      browser_name: browserInfo.browser_name,
      browser_version: browserInfo.browser_version,
      os_family: browserInfo.os_family,
      os_version: browserInfo.os_version,
      engine_name: browserInfo.engine_name,
      device: browserInfo.device,
      product_name: 'MentorAi Extension',
      url: url,
      url_params: params,
      mentorai: mentorai,
      extension_version: chrome.runtime.getManifest().version,
      extensionUsedDaysCount: extensionUsedDaysCount,
      coding_prompt_version,
      model_version,
      leetcode_profile_data: {
        problems_solved: userLeetCodeProfileContext?.analysis?.statistics?.problems_solved,
        submissions: userLeetCodeProfileContext?.analysis?.statistics?.submissions,
        rank: userLeetCodeProfileContext?.analysis?.profile?.rank,
      },
      ...extra_track_properties,
      ...utmParams,
      lc_theme,
      speech_to_text,
      interview_mode_access_option_variant,
      daily_message_limit_variant,
      initial_default_tab_variant,
      sample_resources_practice_mode_variant,
      is_paid_user: isPaidUser,
      ...subscriptionFields,
      ...fieldsToAdd,
      session_type,
      dynamic_easy_action_option_variant,
    }
  } catch (error) {
    console.error('Error in eventPropertyBuilder', error)
  }
}

export const sendAnalyticsWithBackend = async (user_email: string, current_url: string, event: string, properties: any) => {
  try {
    const eventProperties = await eventPropertyBuilder(current_url, properties);
    // console.log('Backend eventName: ', event, '\n properties: ', eventProperties, '\n user_id: ', user_email, '\n current_url: ', current_url);
    const response = await handleAnalyticsPost(
      {
        user_id: user_email,
        event,
        properties: eventProperties
      }
    );
    return response;
  } catch (error) {
    console.error(error);
  }
};

export const identifyUser = async (user_email: string, traits: any) => {
  try {
    const response = await handleAnalyticsIdentify(
      {
        user_id: user_email,
        traits: {
          ...traits
        }
      }
    );
    return response;
  } catch (error) {
    console.error(error);
  }
};


export const identifyUserV2 = async (user_email: string, anonymous_id: string, params?: any) => {
  try {
    const response = await handleAnalyticsIdentifyV2(
      {
        userId: user_email,
        anonymousId: anonymous_id,
        context: {
          traits: params || {}
        }
      }
    );
    return response;
  } catch (error) {
    console.error("[DEBUG] identifyUserV2 error", error)
  }
};

const softTriggerEventsFired = new Set<string>();

export const trackSoftTriggerEvent = (eventKey: string, eventName: string, eventProperties: any) => {
  // Create a unique key for this specific soft trigger event
  const uniqueKey = `${eventKey}_${Date.now()}`;

  // Check if this exact event has already been fired recently (within 5 seconds)
  const recentEvents = Array.from(softTriggerEventsFired).filter(key => {
    const timestamp = parseInt(key.split('_').pop() || '0');
    return Date.now() - timestamp < 5000; // 5 seconds
  });

  if (recentEvents.length > 0) {
    return;
  }

  // Add to tracking set
  softTriggerEventsFired.add(uniqueKey);

  // Clean up old events (older than 1 minute)
  const oneMinuteAgo = Date.now() - 60000;
  Array.from(softTriggerEventsFired).forEach(key => {
    const timestamp = parseInt(key.split('_').pop() || '0');
    if (timestamp < oneMinuteAgo) {
      softTriggerEventsFired.delete(key);
    }
  });

  // Send the analytics event
  chrome.runtime.sendMessage({
    action: "sendAnalytics",
    url: window.location.href,
    eventName: eventName,
    eventProperties: eventProperties
  });
};