import { shuffleArray } from "../../utils/shuffle-array";

export function shuffleQuiz(quiz: any) {
    if (!quiz) return quiz
    const originalOptions = [...quiz.options];
    const correctText = originalOptions[quiz.answer];
    const userAnswer = quiz.userAnswer;

    // Create array of objects with option and original index
    const optionsWithIndexes = originalOptions.map((option, index) => ({
        option,
        originalIndex: index
    }));

    // Shuffle the array with indexes
    const shuffled = shuffleArray([...optionsWithIndexes]);

    // Extract shuffled options and their original indexes
    const shuffledOptions = shuffled.map(item => item.option);
    const originalIndexes = shuffled.map(item => item.originalIndex);

    const newAnswerIndex = shuffledOptions.findIndex(opt => opt === correctText);

    let shuffledQuiz = {
        ...quiz,
        options: shuffledOptions,
        answer: newAnswerIndex,
        originalIndexes: originalIndexes
    };

    if (userAnswer !== undefined) {
        shuffledQuiz.userAnswer = originalIndexes[userAnswer];
    }

    return shuffledQuiz;
}

export const getTotalQuizCountInsideSection = (learningSession: any, currentSection: number | null) => {
    if (!learningSession || !currentSection) return 0
    const section = learningSession?.sections?.[currentSection]
    const quizzes = section?.quizzes || []
    return quizzes.reduce((total: number, quizElement: any) => {
        return total + (quizElement.quizQuestions?.length || 0)
    }, 0)
}


export const pad = (n: number) => n.toString().padStart(2, '0')
export const formatTimeDuration = (timeStr: string) => {
    const [h, m, s] = (timeStr.split(':').length === 2 ? `00:${timeStr}` : timeStr).split(':').map(Number)
    return h > 0 ? `${pad(h)}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`
}

export const formatTimeDurationFromSeconds = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const remainingSeconds = Number((seconds % 60).toString().slice(0, 2));
    return `${hours > 0 ? `${hours}:` : ''}${minutes > 0 ? `${minutes}:` : '00:'}${remainingSeconds > 0 ? `${remainingSeconds}` : '00'}`
}

export const formatTimeDurationFromSecondsAsTttFormat = (seconds: number) => {
    const hours = Math.floor(seconds / 3600).toString().padStart(2, '0');
    const minutes = Math.floor((seconds % 3600) / 60).toString().padStart(2, '0');
    const remainingSeconds = Math.floor(seconds % 60).toString().padStart(2, '0');

    let formattedTime = '';

    if (Number(hours) > 0) {
        formattedTime += `${hours} ${Number(hours) === 1 ? 'hr' : 'hrs'}`;
        if (Number(minutes) > 0) {
            formattedTime += ` ${minutes} ${Number(minutes) === 1 ? 'min' : 'mins'}`;
        }
    } else if (Number(minutes) > 0) {
        formattedTime += `${minutes} ${Number(minutes) === 1 ? 'min' : 'mins'}`;
        if (Number(remainingSeconds) > 0) {
            formattedTime += ` ${remainingSeconds} ${Number(remainingSeconds) === 1 ? 'sec' : 'secs'}`;
        }
    } else {
        formattedTime += `${remainingSeconds} ${Number(remainingSeconds) === 1 ? 'sec' : 'secs'}`;
    }
    return formattedTime;
}

export const getDurationStringFromSeconds = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const remainingSeconds = seconds % 60;
    return `${hours > 0 ? `${hours}:` : ''}${minutes > 0 ? `${minutes}:` : '00:'}${remainingSeconds > 0 ? `${remainingSeconds}` : '00'}`
}
