import React, { FC, useEffect, useState } from "react";
import { useCustomUI } from "../../../contexts/custom-ui-context/custom-ui-context";
import MentorAiButton from "../../../../common/button/mentorai-button";
import EndSectionQuizComponent from "./end-section-quiz-component";
import MentorAiAvatarHeader from "./components/mentorai-avatar-header";
import SectionDetailsWithCTA from "./components/section-details-with-cta";
import SectionDurationAndDetails from "./components/section-duration-and-details";
import SkipIcon from '../../../assets/icons/skip.svg'
import RadioUnselectedIcon from "../../../assets/icons/quiz-option-radio-unselected.svg";

import CheckIcon from '../../../assets/icons/white-check.svg'
import MentorAiActiveAvatar from "../../mentorai-active-avatar/mentorai-active-avatar";
import { useChat } from "../../../contexts/chat-context/chat-context";
import SparklingFillIcon from '../../../../src/assets/sparkling2.svg';

type Props = {
  isSidePanelOpen: boolean;
}

const SectionEndOverlay: FC<Props> = ({ isSidePanelOpen }) => {
  const {
    learningSession,
    currentSection,
    sectionEndScreen,
    selectedSection,
    setSectionEndScreen,
    setSessionOverlayView,
    setSelectedSection,
    setCurrentSection,
    mentoraiData,
    markSectionComplete,
    showSessionEndView,
    playerMode,
    trackCustomUIEvent,
    getCurrentSectionProperties
  } = useCustomUI();

  // const { sendMessage, setSelectedYouTubeSideSectionTab } = useChat();

  if (!learningSession || !learningSession.sections[currentSection]) {
    return null;
  }

  const isPlayerModeDefault = playerMode === "DEFAULT";
  const section = learningSession.sections[currentSection];
  const quizzes = section.quizzes || [];
  const isLastSection = currentSection === learningSession.sections.length - 1;
  const isSectionComplete = section.status === 'completed';
  const isCurrentSectionSelected = currentSection === selectedSection
  const [isMarkingComplete, setIsMarkingComplete] = useState(false);
  const isDefaultMode = playerMode === "DEFAULT";


  // Get followup questions for the current section
  const currentSectionData = learningSession?.sections?.[currentSection || 0];
  const followupQuestions = (currentSectionData as any)?.followUpQuestions || currentSectionData?.followup_questions || [];
  const showFollowupQuestions = isCurrentSectionSelected && followupQuestions && followupQuestions.length > 0;

  const handleFollowupQuestionClick = (question: string) => {
    // setSelectedYouTubeSideSectionTab("Chat")
    // sendMessage(question);

    if (!isSidePanelOpen) {
      chrome.runtime.sendMessage({ action: "openSidePanel" }).then(() => {
        setTimeout(() => {
          chrome.runtime.sendMessage({
            action: "easyActionClicked",
            easy_action: question,
            easy_action_title: "Follow-up Question",
            url: window.location.href,
            is_side_panel_opened: false,
            section_title: "Section End Screen",
            easy_action_message: question,
          });
        }, 3000);
      });
    } else {
      chrome.runtime.sendMessage({
        action: "easyActionClicked",
        easy_action: question,
        easy_action_title: "Follow-up Question",
        url: window.location.href,
        is_side_panel_opened: true,
        section_title: "Section End Screen",
        easy_action_message: question,
      });
    }

    // trackCustomUIEvent("Easy Action Clicked", {
    //   info: {
    //     easy_action: "Follow-up Question",
    //     easy_action_title: "Follow-up Question",
    //     section_title: "Section End Screen",
    //     easy_action_message: question,
    //   },
    // });
  }
  // Calculate total quiz count by flattening the structure
  const totalQuizCount = quizzes.reduce((total, quizElement) => {
    return total + (quizElement.quizQuestions?.length || 0);
  }, 0);

  useEffect(() => {
    if (sectionEndScreen === 'explore_quiz' && totalQuizCount == 0) {
      setSectionEndScreen('completion');
    }
  }, [sectionEndScreen]);


  const handleStartQuiz = () => {
    setSectionEndScreen('quiz');
    trackCustomUIEvent("Button Clicked", {
      button_name: isSectionComplete ? "View Quiz" : "Start Quiz",
      section: getCurrentSectionProperties(),
    })
  };

  const handleSkipQuiz = () => {
    setSectionEndScreen('completion');
    trackCustomUIEvent("Button Clicked", {
      button_name: "Skip Quiz",
      section: getCurrentSectionProperties(),
    })
  };

  const handleMarkComplete = () => {
    const currentSectionIndex = currentSection;
    // Mark section as complete and move to next section
    setIsMarkingComplete(true);
    setTimeout(() => {
      markSectionComplete(currentSectionIndex);
      const isLastSectionIndex = currentSectionIndex === learningSession.sections.length - 1;
      if (!isLastSectionIndex) {
        const nextSectionIndex = currentSectionIndex + 1;
        setCurrentSection(nextSectionIndex);
        setSelectedSection(nextSectionIndex);
        setSessionOverlayView('section_start');
        setSectionEndScreen('explore_quiz');
      } else {
        // Last section completed, end session
        showSessionEndView();
        trackCustomUIEvent("MentorAi Session End Screen Viewed", {
          from: "Section End Screen",
          section: getCurrentSectionProperties(),
        });
      }
      trackCustomUIEvent("MentorAi Section Marked Complete", {
        from: "Section End Screen",
        section: getCurrentSectionProperties(),
      });
    }, 2000);
  };

  const handleJumpToNextSection = () => {
    if (!isLastSection) {
      const nextSectionIndex = currentSection + 1;
      setCurrentSection(nextSectionIndex);
      setSelectedSection(nextSectionIndex);
      setSessionOverlayView('section_start');
    } else {
      // Last section, end session
      showSessionEndView();
    }
    trackCustomUIEvent("Button Clicked", {
      button_name: "Jump to Next Section",
      section: getCurrentSectionProperties(),
    })
  };

  const viewSessionSummary = () => {
    // not calling sessionEndView because we want to purposefully show the session end view even if already shown;
    setSessionOverlayView('session_end');
    setSectionEndScreen('explore_quiz');
    trackCustomUIEvent("Button Clicked", {
      button_name: "View Session Summary",
      section: getCurrentSectionProperties(),
    })
  }

  const renderExploreQuizScreen = () => (
    <div className='flex flex-col '   >
      <MentorAiAvatarHeader mentoraiData={mentoraiData} primaryStatus={<span style={{ color: "#FFE097", fontWeight: "600" }}>🏁 Finished Watching  :</span>} secondaryStatus={<span style={{ color: "#94939F", fontWeight: "500" }}>Section {currentSection + 1} of {learningSession.sections.length}</span>} />

      <SectionDetailsWithCTA
        sectionTitle={section.sectionTitle}
        sectionCTADescription={"Ready for a quiz? 🚀"}
        sectionCTAs={
          <div className="flex flex-row flex-wrap" style={{ gap: isDefaultMode ? '8px' : "12px", marginTop: "28px" }}>
            {totalQuizCount > 0 && (
              <MentorAiButton
                type="primary"
                size="large"
                classNames=' !w-fit whitespace-nowrap '
                style={{ paddingLeft: isPlayerModeDefault ? "12px" : "24px", paddingRight: isPlayerModeDefault ? "8px" : "18px", height: isPlayerModeDefault ? "32px" : "40px" }}
                onClick={handleStartQuiz}
              >
                <span style={{ fontSize: 14, color: "#F2F2F2" }}>
                  {isSectionComplete ? "View Quiz" : "Start Quiz"} &rarr;
                </span>
              </MentorAiButton>
            )}

            <MentorAiButton
              type="secondary"
              size="large"
              classNames=' !w-fit whitespace-nowrap '
              style={{ paddingLeft: isPlayerModeDefault ? "12px" : "24px", paddingRight: isPlayerModeDefault ? "12px" : "24px", height: isPlayerModeDefault ? "32px" : "40px" }}
              onClick={handleSkipQuiz}
            >
              {totalQuizCount > 0 ?
                <span style={{ fontSize: 14, color: "#F2F2F2" }}>
                  Skip Quiz
                </span>
                : <span style={{ fontSize: 14, color: "#F2F2F2" }}>
                  Continue
                </span>
              }
            </MentorAiButton>
          </div>
        }
      />

      {quizzes?.length > 0 ?
        <div className="opacity-25 w-full flex flex-col"
          style={{ marginTop: "32px", gap: '24px' }}>
          <p className="text-mentorai-text-primary text-left font-medium leading-6" style={{ fontSize: 16, lineHeight: '24px', letterSpacing: '0.096px' }}>
            {quizzes[0]?.quizQuestions?.[0]?.question}
          </p>
          <div className="flex flex-col" style={{ gap: '16px' }}>
            {quizzes[0]?.quizQuestions?.[0]?.options?.map((option: any, index: number) => (
              <label
                key={index}
                className={'flex items-start gap-6 justify-between w-full rounded-b-xl rounded-t-xl border border-mentorai-stroke-strong'}
                style={{ padding: "12px" }}
              >
                <div className="flex items-start justify-start" style={{ gap: "8px" }}>
                  <img src={RadioUnselectedIcon} alt="radio" className="w-[16px] h-[20px]" />
                  <input
                    type="radio"
                    name="language"
                    className="hidden"
                  />

                  <span
                    className={`tracking-[0.16px] text-[#94939F]`}
                    style={{ fontSize: "16px", fontWeight: 500 }}
                  >
                    {option}
                  </span>
                </div>
              </label>
            ))}
          </div>
        </div>
        : null}
    </div>
  );

  const renderQuizScreen = () => (
    <EndSectionQuizComponent sectionIndex={currentSection} isSidePanelOpen={isSidePanelOpen} />
  );

  const getPrimaryStatus = () => {
    if (isMarkingComplete || isSectionComplete) {
      return <span style={{ color: "#84EBB4", fontWeight: "600" }}>✅ Completed :</span>
    }
    return <span style={{ color: "#FFE097", fontWeight: "600" }}>🏁 Completing :</span>
  }

  const renderFollowupQuestions = () => {
    return (
      <div className="flex flex-col w-full bg-[rgba(20,22,31,0.24)] rounded-xl" style={{ gap: '12px', padding: "16px" }}>
        <div style={{ fontSize: 16, fontWeight: 500, color: '#DDDDDF', lineHeight: '26px', letterSpacing: '0.6px', fontStyle: 'italic' }}>
          Test yourself with critical thinking
        </div>
        {followupQuestions.map((question: string, index: number) => (
          <div
            key={index}
            onClick={() => handleFollowupQuestionClick(question)}
            className="flex flex-row items-center group justify-between w-full rounded-lg border border-mentorai-stroke-strong bg-[rgba(20,22,31,0.75)] hover:bg-[rgba(33,36,49,0.75)] cursor-pointer transition-colors"
            style={{ padding: '12px', gap: 0 }}
          >
            <div className="flex-1 flex flex-row items-center w-full justify-between">
              <div className="flex flex-row items-center" style={{ gap: 8 }}>
                <img src={SparklingFillIcon} alt="sparkle" style={{ width: 20, height: 20, marginRight: 8 }} />
                <span className="flex-1" style={{ fontSize: 16, fontWeight: 500, color: '#94939F', lineHeight: '26px', letterSpacing: '0.6px', overflow: 'hidden' }}>{question}</span>
              </div>
              <div className="flex flex-row items-center whitespace-nowrap" style={{ gap: 6 }}>
                <MentorAiActiveAvatar
                  mentoraiData={mentoraiData}
                  avatarClassName="h-[16px] w-[16px]"
                />
                <span className="group-hover:text-[#A5A1F7] text-[#DDDDDF] transition-colors" style={{ fontSize: 14, fontWeight: 600, letterSpacing: '0.6px', marginLeft: 4 }}>Ask me →</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    );
  }

  const renderCompletionScreen = () => (
    <div className='flex flex-col  w-full'   >
      <MentorAiAvatarHeader
        mentoraiData={mentoraiData}
        primaryStatus={getPrimaryStatus()}
        secondaryStatus={<span style={{ color: "#94939F", fontWeight: "500" }}>Section {currentSection + 1} of {learningSession.sections.length}</span>}
      />
      <SectionDetailsWithCTA
        sectionTitle={section.sectionTitle}
        sectionDurationAndDetails={<SectionDurationAndDetails />}
        followupQuestions={showFollowupQuestions ? renderFollowupQuestions() : null}
        // sectionDescription={section.sectionDescription}
        sectionCTAs={
          <div className="flex flex-row flex-wrap" style={{ gap: isDefaultMode ? '8px' : "12px", marginTop: isDefaultMode ? '28px' : "44px" }}>
            <>
              {isMarkingComplete ?
                null
                :
                isLastSection ? (
                  <MentorAiButton
                    type="success"
                    size="large"
                    // TODO: Handle already completed section
                    onClick={isSectionComplete ? viewSessionSummary : handleMarkComplete}
                    classNames={`whitespace-nowrap !w-fit`}
                    style={{
                      paddingLeft: isPlayerModeDefault ? "12px" : "24px",
                      paddingRight: isPlayerModeDefault ? (isSectionComplete ? '12px' : "8px") : (isSectionComplete ? '24px' : "18px"),
                      height: isPlayerModeDefault ? "32px" : "40px"
                    }}
                  >
                    <span style={{ fontSize: 14, fontWeight: 500, lineHeight: "22px", letterSpacing: "0.084px", color: "#F2F2F2" }}>
                      {isSectionComplete ?
                        "View Session Summary" :

                        <span className="flex flex-row items-center" style={{ gap: '4px' }}>
                          Complete Session
                          <img src={CheckIcon} alt="check" style={{ width: 18, height: 18 }} />
                        </span>
                      }
                    </span>
                  </MentorAiButton>
                ) :
                  <MentorAiButton
                    type={(isSectionComplete) ? "secondary" : "success"}
                    size="large"
                    onClick={isSectionComplete ? handleJumpToNextSection : handleMarkComplete}
                    classNames={`whitespace-nowrap !w-fit`}
                    style={{
                      paddingRight: isSectionComplete ? (isPlayerModeDefault ? '12px' : "24px") : (isPlayerModeDefault ? '8px' : "18px"),
                      paddingLeft: isSectionComplete ? (isPlayerModeDefault ? '8px' : "18px") : (isPlayerModeDefault ? '12px' : "24px"),
                      height: isPlayerModeDefault ? "32px" : "40px"
                    }}
                  >
                    <span style={{ fontSize: 14, fontWeight: 500, lineHeight: "22px", letterSpacing: "0.084px", color: "#F2F2F2" }}>
                      {isSectionComplete ?
                        <span style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                          <img src={SkipIcon} alt="skip" style={{ width: 18, height: 18 }} />
                          Jump to Next Section
                        </span>
                        :
                        <span className="flex items-center" style={{ gap: '8px' }}>
                          Mark Complete
                          <img src={CheckIcon} alt="check" style={{ width: 18, height: 18 }} />
                        </span>
                      }
                    </span>
                  </MentorAiButton>
              }
            </>
          </div>
        }
      />
    </div>
  );

  const getScreenContent = () => {
    switch (sectionEndScreen) {
      case 'explore_quiz':
        return renderExploreQuizScreen();
      case 'quiz':
        return renderQuizScreen();
      case 'completion':
        return renderCompletionScreen();
      default:
        return renderExploreQuizScreen();
    }
  };

  return (
    <div className="w-full h-full flex" style={{ padding: "44px 0px" }}>
      {getScreenContent()}
    </div>
  );
};

export default SectionEndOverlay; 