import React, { useMemo, useEffect, useState } from "react";
import { motion, useMotionValue, useTransform } from "framer-motion";
import "../../content.css";
import { cn } from "../../../utils/cn";
import BlogLearningIcon from "../../assets/icons/blog-learning-icon.svg";

// Internal imports
import type { WidgetComponentProps } from './types';
import { useContextCollection } from './hooks';
import {
  WidgetAvatar,
  WidgetContent,
  CloseButton,
  ContextCollectionView,
} from './components';
import useWidgetComponent from "./use-widget-component";
import { useCustomUI } from "../../contexts/custom-ui-context/custom-ui-context";
import DisableButton from "./components/disable-button/disable-button";
import BlogLearningCard from "../blog-learning-session/blog-learning-card";

const WidgetComponent: React.FC<WidgetComponentProps> = ({
  mentoraiData,
  menteeData,
  isSidePanelOpen,
  setIsSidePanelOpen,
  isBlogLearningSessionVisible,
  handleLeaningCTAClick,
  sessionState,
}) => {
  const { isContextCollection, currentStep, isAnalyzing } = useContextCollection();
  const { widgetState, widgetControls, isYouTubePage, handleWidgetClick, handleMouseEnter, handleMouseLeave, handleClose, handleStartSession } = useWidgetComponent(isSidePanelOpen, setIsSidePanelOpen, menteeData, mentoraiData);
  const [initialY, setInitialY] = useState<number | null>(null);
  const { playerMode } = useCustomUI();
  const shouldHideWidgetOnYouTube = isYouTubePage && playerMode !== "DEFAULT" && widgetState !== "start_session"
  const [isWidgetHovered, setIsWidgetHovered] = useState(false)
  const [isBlogIconHovered, setIsBlogIconHovered] = useState(false)
  const [isBlogCardHovered, setIsBlogCardHovered] = useState(false)
  const [hideTimeout, setHideTimeout] = useState<NodeJS.Timeout | null>(null)
  const [showBlogCard, setShowBlogCard] = useState(true)

  const handleBlogIconMouseEnter = () => {
    if (hideTimeout) {
      clearTimeout(hideTimeout);
      setHideTimeout(null);
    }
    setIsBlogIconHovered(true);
  };

  const handleBlogIconMouseLeave = () => {
    if (!isBlogCardHovered) {
      const timeout = setTimeout(() => {
        setIsBlogIconHovered(false);
      }, 300);
      setHideTimeout(timeout);
    }
  };

  const handleBlogCardMouseEnter = () => {
    if (hideTimeout) {
      clearTimeout(hideTimeout);
      setHideTimeout(null);
    }
    setIsBlogCardHovered(true);
  };

  const handleBlogCardMouseLeave = () => {
    setIsBlogCardHovered(false);
    if (!isBlogIconHovered) {
      const timeout = setTimeout(() => {
        setIsBlogIconHovered(false);
      }, 200)
      setHideTimeout(timeout);
    }
  };

  useEffect(() => {
    return () => {
      if (hideTimeout) {
        clearTimeout(hideTimeout);
      }
    };
  }, [hideTimeout]);

  // Drag and position persistence
  const y = useMotionValue(0);
  const [isDragging, setIsDragging] = useState(false);

  // Calculate icon position based on widget position
  const iconY = useTransform(y, (value) => {
    return value - 48;
  });

  // Calculate drag constraints to keep widget within viewport
  const dragConstraints = useMemo(() => {
    const windowHeight = window.innerHeight;
    const widgetHeight = 40; // Widget height in normal state
    const bottomOffset = 120; // From className bottom-[120px]

    // Calculate movement ranges
    const maxUpwardMovement = windowHeight - widgetHeight - bottomOffset; // Can go to top
    const maxDownwardMovement = bottomOffset; // Can go to actual bottom (120px down)

    return {
      top: -maxUpwardMovement,     // Negative value to move up to viewport top
      bottom: maxDownwardMovement  // Positive value to move down to viewport bottom
    };
  }, []);

  useEffect(() => {
    // Restore saved Y position on mount
    chrome.storage?.local.get(["widgetPositionY"]).then(({ widgetPositionY }) => {
      if (typeof widgetPositionY === "number") {
        setInitialY(widgetPositionY);
        y.set(widgetPositionY);
      } else {
        setInitialY(10);
        y.set(10);
      }
    });
  }, [y]);

  const handleClick = (e: React.MouseEvent) => {
    // Prevent click during drag
    if (isDragging) {
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    handleWidgetClick();
  };

  const widgetClassName = useMemo(
    () =>
      cn(
        "fixed bottom-[120px] z-[9999999] right-0 h-[40px]",
        "rounded-l-[20px] rounded-r-none bg-[#07070A]",
        isYouTubePage && "ml-[3px] mt-[3px]",
        widgetState === "start_session" ? "moving-border rounded-[20px]" : " !max-w-[120px]",
        isContextCollection && "rounded-[20px]",
        // Dynamic cursor based on state
        {
          "cursor-pointer": !isDragging && widgetState !== "start_session", // Hand pointer on hover
          "cursor-grabbing": isDragging, // Grabbing when dragging
          "cursor-default h-[208px] max-w-[285px]": widgetState === "start_session" // Default for start session
        }
      ),
    [isYouTubePage, widgetState, isDragging, isContextCollection]
  );

  if (isContextCollection) {
    return (
      <ContextCollectionView
        mentoraiData={mentoraiData}
        currentStep={currentStep}
        isAnalyzing={isAnalyzing}
      />
    );
  }

  if (initialY === null) {
    return null;
  }

  if (shouldHideWidgetOnYouTube) {
    return null;
  }

  return (
    <>
      {isBlogLearningSessionVisible && (
        <motion.div className=" fixed right-[6px] z-[9999999]"
          style={{
            bottom: 120, // Base position same as widget
            y: iconY // Transform based on widget's Y position
          }}
          onMouseEnter={handleBlogIconMouseEnter}
          onMouseLeave={handleBlogIconMouseLeave}
        >
          <img
            onClick={() => setShowBlogCard(!showBlogCard)}
            src={BlogLearningIcon}
            alt="Blog Learning Icon"
            className={`w-[32px] h-[32px] cursor-pointer`}
          />

          {isBlogLearningSessionVisible && (isBlogIconHovered || isBlogCardHovered) && (
            <BlogLearningCard
              showCard={showBlogCard}
              handleLeaningCTAClick={handleLeaningCTAClick}
              sessionState={sessionState}
              onMouseEnter={handleBlogCardMouseEnter}
              onMouseLeave={handleBlogCardMouseLeave}
            />
          )}
        </motion.div>

      )}

      <motion.div
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onClick={handleClick}
        drag={widgetState !== "start_session" ? "y" : false}
        dragConstraints={dragConstraints}
        dragMomentum={false}
        dragElastic={0.1}
        style={widgetState !== "start_session" ? { y } : {}}
        onDragStart={() => setIsDragging(true)}
        onDragEnd={() => {
          setIsDragging(false);
          // Save Y position when drag ends
          chrome.storage?.local.set({ widgetPositionY: y.get() });
        }}
        animate={widgetControls}
        layout
        className={widgetClassName}
      >
        {widgetState !== "start_session" ?
          <div
            style={{
              paddingTop: isYouTubePage ? (!isSidePanelOpen ? '7.5px' : '9.5px') : '',
              paddingLeft: isYouTubePage ? (!isSidePanelOpen ? '7.5px' : '9.5px') : '',
            }}
            className={cn(
              "flex items-center relative",
              isSidePanelOpen ? "p-[5px] m-auto h-[40px] flex items-center justify-center" : "justify-between gap-2 py-1 pl-1"
            )}
            onMouseEnter={() => setIsWidgetHovered(true)}
            onMouseLeave={() => setIsWidgetHovered(false)}
          >
            {!isSidePanelOpen ? (
              <div className="flex items-center gap-[5px]">
                <WidgetAvatar
                  photoUrl={mentoraiData?.aiPhotoUrl || mentoraiData?.photoUrl}
                />
                <WidgetContent
                  widgetState={widgetState}
                  isSidePanelOpen={isSidePanelOpen}
                  handleStartSession={handleStartSession}
                  menteeData={menteeData}
                />
              </div>
            ) : (
              <CloseButton onClose={handleClose} />
            )}
            {isWidgetHovered && <DisableButton />}
          </div>
          :
          <div className={cn("flex flex-col", widgetState === "start_session" && "pr-[10px]")}>
            <div
              className={`fixed w-full h-full bg-[rgba(0,0,0,0.50)] backdrop-blur-[2px] inset-0 z-[-10]`}
              onClick={handleClose}
            />
            <div className="px-[16px] py-[16px] flex items-center justify-between">
              <WidgetAvatar
                photoUrl={mentoraiData?.aiPhotoUrl || mentoraiData?.photoUrl}
              />
              <CloseButton onClose={handleClose} />
            </div>
            <WidgetContent
              widgetState={widgetState}
              isSidePanelOpen={isSidePanelOpen}
              handleStartSession={handleStartSession}
              menteeData={menteeData}
            />
          </div>
        }
      </motion.div>
    </>
  );
};

export default WidgetComponent;
