import { useEffect, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import Button from "../../../../src/components/common/common-button";
import { handleAibackendPost } from "../../../../core/Axios";
import { Mentee } from "../../../../src/types/type";
import Tippy from "@tippyjs/react";
import "./custom-learning-session.css";

const CustomLearningSession = ({
  menteeData,
  mentoraiData,
  isInsideInputBox,
}: {
  menteeData: Mentee | undefined;
  mentoraiData: any | undefined;
  isInsideInputBox: boolean;
}) => {
  const [learningIntent, setLearningIntent] = useState<any>({
    isLoading: false,
    hasLearningIntent: false,
    topic: null,
  });
  const [isHovered, setIsHovered] = useState(false);
  const [theme, setTheme] = useState<"dark" | "light">("light");

  const createSession = async (location: string) => {
    const sessionData = {
      candidates: [menteeData?.dlData?.recordId],
      created: "",
      description: document.title || "Blog Learning Session",
      index: 0,
      mentorAi: mentoraiData?.recordId || "",
      modules: [],
      platformType: "blog",
      resources: [],
      status: "Yet To Start",
      thumbnail: "",
      title: learningIntent?.topic || document.title || "Blog Learning Session",
      type: "Custom Learning Session",
      url: window.location.href,
      learningPath: [],
    };
    const response = await handleAibackendPost(
      "/leeco/sessions/create-session",
      {
        sessionData,
        useTitle: true,
      },
      {},
    );
    if (response?.status === 200) {
      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: window.location.href,
        eventName: "Button Clicked",
        eventProperties: {
          button_name: "Start Learning Session",
          location: location,
        },
      });
      const urlWithParams = new URL(
        `${import.meta.env.VITE_LEECO_WEB_URL}/sessions-instant-chat/${response?.data?.recordId}`,
      );
      window.open(urlWithParams.toString(), "_blank");
    }
  };

  useEffect(() => {
    const EVENT_NAME = "mentorai:learning-intent";
    const selector = ".user-message-bubble-color";

    const g: any = window as any;
    g.__MENTORAI_LEARN_INTENT__ = g.__MENTORAI_LEARN_INTENT__ || {
      initialized: false,
      mountCount: 0,
      lastBubbleCount: 0,
      lastRequestKey: undefined,
      result: undefined,
      scanScheduled: false,
      observer: undefined,
      lastAnalyticsKey: undefined,
    };
    const ctrl = g.__MENTORAI_LEARN_INTENT__;
    ctrl.mountCount = (ctrl.mountCount || 0) + 1;

    const detectFromCurrentBubbles = async () => {
      try {
        const nodes = document.querySelectorAll(selector);
        const currentCount = nodes.length;
        if (currentCount <= 0) {
          ctrl.lastBubbleCount = 0;
          return;
        }
        const allTexts = Array.from(nodes).map((el) => (el as HTMLElement).innerText || "");
        const latestText = (nodes[nodes.length - 1] as HTMLElement)?.innerText || "";
        const requestKey = `${allUserMessageTextsLength(allTexts)}|${latestText}`;
        if (ctrl.lastRequestKey === requestKey) {
          ctrl.lastBubbleCount = currentCount;
          return;
        }
        ctrl.lastRequestKey = requestKey;
        const resp = await handleAibackendPost("/extension/detect-learning-intent", { messages: allTexts }, {});
        if (resp?.status === 200) {
          const result = {
            hasLearningIntent: resp?.data?.intent === "LEARN_INTENT",
            topic: resp?.data?.intent === "LEARN_INTENT" ? resp?.data?.topic : null,
          };
          ctrl.result = result;
          window.dispatchEvent(new CustomEvent(EVENT_NAME, { detail: result }));
        }
        ctrl.lastBubbleCount = currentCount;
      } catch (err) {
        const result = { hasLearningIntent: false, topic: null };
        ctrl.result = result;
        window.dispatchEvent(new CustomEvent(EVENT_NAME, { detail: result }));
      }
    };

    const allUserMessageTextsLength = (texts: string[]) => texts.filter(Boolean).length;

    // Initialize local state from global cache if available
    if (ctrl.result) {
      setLearningIntent({
        isLoading: false,
        hasLearningIntent: !!ctrl.result.hasLearningIntent,
        topic: ctrl.result.topic || null,
      });
    }

    const onGlobalIntent = (e: any) => {
      const detail = e?.detail || {};
      if (detail?.hasLearningIntent) {
        const analyticsKey = `${window.location.href}|${detail?.topic || ""}`;
        if (ctrl.lastAnalyticsKey !== analyticsKey) {
          ctrl.lastAnalyticsKey = analyticsKey;
          chrome.runtime.sendMessage({
            action: "sendAnalytics",
            url: window.location.href,
            eventName: "Learning session suggested",
            eventProperties: {
              learning_intent_topic: detail?.topic,
            },
          });
        }
      }
      setLearningIntent({
        isLoading: false,
        hasLearningIntent: !!detail?.hasLearningIntent,
        topic: detail?.topic || null,
      });
    };
    window.addEventListener(EVENT_NAME, onGlobalIntent);

    // Observe title changes to reset cached intent when chat/thread changes
    if (!ctrl.titleObserver) {
      ctrl.lastTitle = document.title || "";
      const headObserver = new MutationObserver(() => {
        const current = document.title || "";
        if (current !== ctrl.lastTitle) {
          ctrl.lastTitle = current;
          // Reset global caches and notify listeners
          ctrl.lastRequestKey = undefined;
          ctrl.result = undefined;
          ctrl.lastAnalyticsKey = undefined;
          ctrl.lastBubbleCount = 0;
          const cleared = { hasLearningIntent: false, topic: null };
          setLearningIntent({ isLoading: false, hasLearningIntent: false, topic: null });
          window.dispatchEvent(new CustomEvent(EVENT_NAME, { detail: cleared }));
          // Immediately attempt detection based on current bubbles
          window.setTimeout(() => {
            detectFromCurrentBubbles();
          }, 0);
        }
      });
      ctrl.titleObserver = headObserver;
      headObserver.observe(document.head || document.documentElement, {
        childList: true,
        subtree: true,
        characterData: true,
      });
    }

    if (!ctrl.initialized) {
      ctrl.initialized = true;
      ctrl.lastBubbleCount = document.querySelectorAll(selector).length;
      ctrl.scanScheduled = false;

      const onUserMessageSent = async (allUserMessageTexts: string[], latestUserMessageText: string) => {
        try {
          const requestKey = `${allUserMessageTexts.length}|${latestUserMessageText}`;
          if (ctrl.lastRequestKey === requestKey) return;
          ctrl.lastRequestKey = requestKey;

          const resp = await handleAibackendPost(
            "/extension/detect-learning-intent",
            { messages: allUserMessageTexts },
            {},
          );

          if (resp?.status === 200) {
            const result = {
              hasLearningIntent: resp?.data?.intent === "LEARN_INTENT",
              topic: resp?.data?.intent === "LEARN_INTENT" ? resp?.data?.topic : null,
            };
            ctrl.result = result;
            window.dispatchEvent(new CustomEvent(EVENT_NAME, { detail: result }));
          }
        } catch (err) {
          const result = { hasLearningIntent: false, topic: null };
          ctrl.result = result;
          window.dispatchEvent(new CustomEvent(EVENT_NAME, { detail: result }));
        }
      };

      const runScan = () => {
        const nodes = document.querySelectorAll(selector);
        const currentCount = nodes.length;
        if (currentCount > ctrl.lastBubbleCount) {
          const allTexts = Array.from(nodes).map((el) => (el as HTMLElement).innerText || "");
          const latestText = (nodes[nodes.length - 1] as HTMLElement)?.innerText || "";
          onUserMessageSent(allTexts, latestText);
        }
        ctrl.lastBubbleCount = currentCount;
      };

      const scheduleScan = () => {
        if (ctrl.scanScheduled) return;
        ctrl.scanScheduled = true;
        window.setTimeout(() => {
          ctrl.scanScheduled = false;
          runScan();
        }, 120);
      };

      const observer = new MutationObserver((mutationList) => {
        for (const m of mutationList) {
          if (m.type !== "childList") continue;
          if (m.addedNodes && m.addedNodes.length) {
            for (const node of Array.from(m.addedNodes)) {
              if (!(node instanceof Element)) continue;
              if ((node as Element).matches?.(selector) || (node as Element).querySelector?.(selector)) {
                scheduleScan();
                return;
              }
            }
          }
        }
      });
      ctrl.observer = observer;
      observer.observe(document.body, { childList: true, subtree: true });

      // Perform an immediate detection pass for existing bubbles
      window.setTimeout(() => {
        detectFromCurrentBubbles();
      }, 0);
    }

    return () => {
      window.removeEventListener(EVENT_NAME, onGlobalIntent);
      ctrl.mountCount -= 1;
      if (ctrl.mountCount <= 0 && ctrl.observer) {
        ctrl.observer.disconnect();
        ctrl.observer = undefined;
        ctrl.initialized = false;
        ctrl.scanScheduled = false;
        ctrl.lastBubbleCount = document.querySelectorAll(selector).length;
      }
      if (ctrl.mountCount <= 0 && ctrl.titleObserver) {
        ctrl.titleObserver.disconnect();
        ctrl.titleObserver = undefined;
      }
    };
  }, []);

  useEffect(() => {
    const root = document.documentElement;
    const updateTheme = () => setTheme(root.classList.contains("dark") ? "dark" : "light");
    updateTheme();
    // Use a single observer and ignore irrelevant attribute changes
    const mo = new MutationObserver((mutations) => {
      for (const m of mutations) {
        if (m.type === "attributes" && m.attributeName === "class") {
          updateTheme();
          break;
        }
      }
    });
    mo.observe(root, { attributes: true, attributeFilter: ["class"] });
    return () => mo.disconnect();
  }, []);

  if (!menteeData) return <></>;

  return (
    <AnimatePresence initial={false}>
      {learningIntent?.hasLearningIntent && !isInsideInputBox && (
        <motion.div
          key="learning-banner"
          initial={{ y: 24, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 24, opacity: 0 }}
          transition={{ type: "spring", stiffness: 500, damping: 40, mass: 0.5 }}
          onClick={() => createSession("Banner")}
        >
          <div
            data-theme={theme}
            className={`w-full cursor-pointer flex justify-between items-center h-full rounded-t-[20px] ${
              theme === "light" ? "bg-[#fff] border border-[#E1E4EA]" : "bg-[#424242]"
            } pt-[10px] pb-[40px] pl-[16px] pr-[12px]`}
          >
            <div className="flex items-center gap-[10px]">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="20"
                height="20"
                viewBox="0 0 20 20"
                fill="none"
                onClick={(e) => {
                  e.stopPropagation();
                  setLearningIntent({ hasLearningIntent: false, topic: null });
                }}
              >
                <path
                  d="M14.2538 4.7558C14.5272 4.48244 14.9707 4.48244 15.2441 4.7558C15.5174 5.02917 15.5174 5.47267 15.2441 5.74604L10.9892 10.0009L15.2441 14.2558L15.3339 14.3661C15.513 14.6378 15.4831 15.0069 15.2441 15.246C15.005 15.4851 14.6358 15.515 14.3642 15.3359L14.2538 15.246L9.99898 10.9911L5.74409 15.246C5.47073 15.5194 5.02723 15.5194 4.75386 15.246C4.48049 14.9727 4.48049 14.5291 4.75386 14.2558L9.00874 10.0009L4.75386 5.74604L4.66402 5.63569C4.48492 5.36402 4.51478 4.99488 4.75386 4.7558C4.99294 4.51673 5.36208 4.48686 5.63374 4.66596L5.74409 4.7558L9.99898 9.01069L14.2538 4.7558Z"
                  fill={theme === "light" ? "#0E121B" : "#F3F3F3"}
                />
              </svg>
              <p
                className={`text-[14px] leading-[20px] -tracking-[0.098px] ${
                  theme === "light" ? "text-[#0E121B]" : "text-[#F3F3F3]"
                }`}
              >
                Start Learning Session With Leeco on{" "}
                <span className={`font-semibold ${theme === "light" ? "text-[#0E121B]" : "text-[#FFF]"}`}>
                  “
                  {learningIntent?.topic && learningIntent.topic.length > 32
                    ? `${learningIntent.topic.slice(0, 32)}...`
                    : learningIntent?.topic}
                  ”
                </span>
              </p>
            </div>
            <Button
              className={`whitespace-nowrap !w-fit flex justify-center items-center !h-[26px] ${
                theme === "light" ? "!text-[#fff] bg-[#000]" : "!text-[#111] bg-[#F3F3F3]"
              } !rounded-full !font-semibold !text-xs/[20px] tracking-[-0.12px] px-[12px] py-[5px]`}
            >
              Start Session
            </Button>
          </div>
        </motion.div>
      )}
      {learningIntent?.hasLearningIntent && isInsideInputBox && (
        <Tippy
          delay={0}
          duration={0}
          visible={isHovered}
          content={<div className="">Start Learning Session</div>}
          arrow={false}
          placement="bottom"
          theme={theme}
          key="learning-session-input-box"
          className={`custom-tooltip flex items-center h-[20px] justify-center font-manrope text-xs px-1.5 rounded-[6px] [box-shadow:0_12px_24px_0_rgba(14,18,27,0.06)] border ${
            theme === "light"
              ? "bg-[#fff] text-[#0E121B] border-[#E1E4EA]"
              : "bg-[#303030] text-mentorai-text-white border-[#000]"
          }`}
        >
          <button
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
            onClick={() => createSession("Input Box")}
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 20 20" fill="none">
              <path
                d="M4.16602 15.8333V3.33333C4.16602 3.11232 4.25381 2.90036 4.41009 2.74408C4.56637 2.5878 4.77834 2.5 4.99935 2.5H14.9993C15.2204 2.5 15.4323 2.5878 15.5886 2.74408C15.7449 2.90036 15.8327 3.11232 15.8327 3.33333V14.1667H5.83268C5.39065 14.1667 4.96673 14.3423 4.65417 14.6548C4.34161 14.9674 4.16602 15.3913 4.16602 15.8333ZM4.16602 15.8333C4.16602 16.2754 4.34161 16.6993 4.65417 17.0118C4.96673 17.3244 5.39065 17.5 5.83268 17.5H15.8327M7.49935 2.5V14.1667M13.3327 14.1667V17.5"
                stroke={theme === "dark" ? "white" : "black"}
                stroke-width="1.4"
                stroke-linecap="round"
                stroke-linejoin="round"
              />
            </svg>
          </button>
        </Tippy>
      )}
    </AnimatePresence>
  );
};

export default CustomLearningSession;
