import React from 'react'
import MentorAiActiveAvatar from '../../../mentorai-active-avatar/mentorai-active-avatar'
import { useCustomUI } from '../../../../contexts/custom-ui-context/custom-ui-context';

const MentorAiAvatarHeader = ({ mentoraiData, primaryStatus, secondaryStatus }: { mentoraiData: any, primaryStatus?: any, secondaryStatus?: any }) => {
    const { playerMode } = useCustomUI();
    const isPlayerModeDefault = playerMode === "DEFAULT";
    return (
        <div className='line-clamp-1 truncate' style={{ display: 'flex', gap: isPlayerModeDefault ? 8 : 12, marginBottom: 16, alignItems: "center", width: "100%" , whiteSpace: 'nowrap'}}>
            <MentorAiActiveAvatar mentoraiData={mentoraiData} avatarClassName="h-[20px] w-[20px]" />
            <p style={{ fontWeight: 500, fontSize: isPlayerModeDefault ? 14 : 16, color: '#DDDDDF', lineHeight: isPlayerModeDefault ? "22px" : "24px", letterSpacing: isPlayerModeDefault ? "0.084px" : "0.096px" }}>{mentoraiData?.name}</p>
            {primaryStatus &&
                <span style={{ fontWeight: 500, fontSize: isPlayerModeDefault ? 14 : 16, lineHeight: isPlayerModeDefault ? "22px" : "24px", letterSpacing: isPlayerModeDefault ? "0.084px" : "0.096px" }}>{primaryStatus}</span>
            }
            {secondaryStatus &&
                <span style={{ fontWeight: 500, fontSize: isPlayerModeDefault ? 14 : 16, lineHeight: isPlayerModeDefault ? "22px" : "24px", letterSpacing: isPlayerModeDefault ? "0.084px" : "0.096px" }}>{secondaryStatus}</span>
            }
        </div>
    )
}

export default MentorAiAvatarHeader