import { useCallback, useEffect, useMemo, useState } from 'react'
import { resetStoredValues, removeActionQueryParamFromUrl } from '../../../utils/helper'
import { WidgetState } from './types'
import { WIDGET_ANIMATION_STATES, WIDGET_CONSTANTS } from './constants'
import { useAnimationControls } from 'framer-motion'
import { useCustomUI } from '../../contexts/custom-ui-context/custom-ui-context'

const useWidgetComponent = (isSidePanelOpen: boolean, setIsSidePanelOpen: (isOpen: boolean) => void, menteeData: any, mentoraiData: any) => {
  const { toggleLearningSession, isUserInteractionDataFetched, learningSession, pauseVideo, setSelectedSection, getSectionAccordindToCurrentDuration } = useCustomUI();
  const [widgetState, setWidgetState] = useState<WidgetState>("default");
  const widgetControls = useAnimationControls();
  

  const isYouTubePage = useMemo(
    () => window.location.href.includes("youtube.com"),
    []
  );

  const [urlVersion, setUrlVersion] = useState(0);
  useEffect(() => {
    const onUrlChange = () => setUrlVersion(v => v + 1);
    window.addEventListener('popstate', onUrlChange);
    window.addEventListener('hashchange', onUrlChange);
    window.addEventListener('mentorai-url-changed', onUrlChange);
    return () => {
      window.removeEventListener('popstate', onUrlChange);
      window.removeEventListener('hashchange', onUrlChange);
      window.removeEventListener('mentorai-url-changed', onUrlChange);
    };
  }, []);

  const isActionStartSession = useMemo(
    () => {
      const search = new URLSearchParams(window.location.search);
      const hash = new URLSearchParams(window.location.hash.slice(1));
      const action = search.get('action') || hash.get('action');
      return action === 'start-session'
    },
    [urlVersion]
  );

  const saveWidgetState = useCallback(async (): Promise<void> => {
    try {
      await chrome.storage.local.set({ widgetState });
    } catch (error) {
      console.error('Error saving widget state:', error);
    }
  }, [widgetState]);

  const animateWidget = useCallback(
    async (state: WidgetState): Promise<void> => {
      setWidgetState(state);
      await widgetControls.start({
        ...WIDGET_ANIMATION_STATES[state],
        transition: WIDGET_CONSTANTS.ANIMATION_TRANSITION,
      });
    },
    [widgetControls]
  );

  const handleWidgetClick = useCallback(async (): Promise<void> => {
    try {
      if (widgetState === "start_session") {
        return;
      }
      const action = isSidePanelOpen ? "closeSidePanel" : "openSidePanel";
      const result = await chrome.storage.local.get(['practiceModeStatus', 'interviewModeStatus']);
      if (isSidePanelOpen && (result.practiceModeStatus === "PM_ONGOING" || result.interviewModeStatus === "ONGOING")) {
        chrome.runtime.sendMessage({ action: "showExitSessionPopup" });
      } else {
        chrome.runtime.sendMessage({ action });
      }
      resetStoredValues("isLiveMessageStreaming", false);
    } catch (error) {
      console.error("Failed to toggle side panel:", error);
    }
  }, [isSidePanelOpen, widgetState]);

  const sessionStartText = {
    "leetcode.com": [
      `Hey ${menteeData?.name?.split(" ")[0]}, let’s solve this together! Use the quick guidance buttons on the LeetCode screen or chat with me for help.`,
      `Alright Let’s start with the problem, Go through the questions first and let me know what you understood about the problem.`
    ],
    "youtube.com": [
      `Hey ${menteeData?.name?.split(" ")[0]}, I’ll turn on “Learning Session” for this video. If it doesn’t work, I’m right here to answer your questions or discuss!`,
      `Alright Let’s start with this video. I’ve created a learning session for you which is divided into different sections and quizzes at the end of each section. 
            \n\n You can look at the section and decide to go through it or skip it. 
            \n\n The quizzes are there to test your understanding and make sure you stay attentive.
             \n\n Also if at any point of the video, you have any questions or doubts, feel free to ask me here and I’ll help you out with it.`
    ],
    "default": [
      `Hey ${menteeData?.name?.split(" ")[0]}, welcome to our learning session! I’m right here to discuss the topic with you or answer your questions.`,
      `Alright let’s start with the session. I’m here if you have any questions or doubts.`
    ]
  }

  const getCurrentHostnameText = (index: number) => {
    const hostname = window.location.hostname;
    const matchingKey = Object.keys(sessionStartText).find(key =>
      key !== 'default' && hostname.includes(key)
    );
    return sessionStartText?.[matchingKey as keyof typeof sessionStartText]?.[index] || sessionStartText?.default?.[index];
  }

  const handleStartSession = useCallback(async (): Promise<void> => {
    try {
      const messages = [
        {
          props: {
            model: {
              id: new Date().getTime().toString(),
              message: getCurrentHostnameText(0),
              sentTime: (new Date().getTime()).toString(),
              sender: "assistant",
              direction: "incoming",
              position: "single",
              senderPhotoUrl: mentoraiData?.aiPhotoUrl,
              senderName: mentoraiData?.name,
            },
            children: <></>,
          },
        },
        {
          props: {
            model: {
              id: new Date().getTime().toString(),
              message: "Start Session",
              sentTime: (new Date().getTime()).toString(),
              sender: "user",
              direction: "outgoing",
              position: "single",
              senderPhotoUrl: menteeData?.photoUrl,
              senderName: menteeData?.name,
            },
            children: <></>,
          },
        },
        {
          props: {
            model: {
              id: new Date().getTime().toString(),
              message: getCurrentHostnameText(1),
              sentTime: (new Date().getTime()).toString(),
              sender: "assistant",
              direction: "incoming",
              position: "single",
              senderPhotoUrl: mentoraiData?.aiPhotoUrl,
              senderName: mentoraiData?.name,
            },
            children: <></>,
          },
        },
      ]
      chrome.runtime.sendMessage({ action: "start-session", is_side_panel_opened: isSidePanelOpen, messages });
      if (isYouTubePage) {
        if (learningSession?.sessionStatus !== "ongoing") {
          toggleLearningSession();
        } else {
          const sectionIndex = getSectionAccordindToCurrentDuration();
          setSelectedSection(sectionIndex);
          let showSectionOverlay = true;
          pauseVideo(showSectionOverlay);
        }
      }
      const action = "openSidePanel";
      chrome.runtime.sendMessage({ action });
      removeActionQueryParamFromUrl();
      setWidgetState("default");
      animateWidget("default");
    } catch (error) {
      console.error("Failed to start session:", error);
    }
  }, [isSidePanelOpen, learningSession, toggleLearningSession, animateWidget, setIsSidePanelOpen, setWidgetState]);

  const handleMouseEnter = useCallback(async (): Promise<void> => {
    if (!isSidePanelOpen && widgetState !== "start_session") {
      await animateWidget("hover");
    }
  }, [animateWidget, isSidePanelOpen, widgetState]);

  const handleMouseLeave = useCallback(async (): Promise<void> => {
    if (widgetState !== "start_session") {
      await animateWidget("default");
    }
  }, [animateWidget, widgetState]);

  const handleClose = useCallback(async (): Promise<void> => {
    const result = await chrome.storage.local.get(['practiceModeStatus', 'interviewModeStatus']);
    if (isSidePanelOpen && (result.practiceModeStatus === "PM_ONGOING" || result.interviewModeStatus === "ONGOING")) {
      return;
    } else {
      animateWidget("default");
      if (isSidePanelOpen) {
        setIsSidePanelOpen(false);
      }
    }
  }, [animateWidget, isSidePanelOpen, setIsSidePanelOpen]);

  // Save widget state to storage
  useEffect(() => {
    saveWidgetState();
  }, [saveWidgetState]);

  // Reset streaming state when side panel closes
  useEffect(() => {
    if (!isSidePanelOpen) {
      resetStoredValues("isLiveMessageStreaming", false);
    }
  }, [isSidePanelOpen]);

  useEffect(() => {
    if (isActionStartSession && menteeData?.recordId && mentoraiData?.recordId) {
      if (isYouTubePage && isUserInteractionDataFetched) {
        setWidgetState("start_session");
        animateWidget("start_session");
      } else if (!isYouTubePage) {
        setWidgetState("start_session");
        animateWidget("start_session");
      }
    }
  }, [isActionStartSession, menteeData?.recordId, mentoraiData?.recordId, isUserInteractionDataFetched, isYouTubePage]);

  return {
    widgetState,
    widgetControls,
    isYouTubePage,
    handleWidgetClick,
    handleMouseEnter,
    handleMouseLeave,
    handleClose,
    isActionStartSession,
    handleStartSession
  }
}

export default useWidgetComponent