import React from "react";
import { LoaderWithThreeDots } from "./loader";

type Props = {
  className?: string;
  loaderColor?: string;
  loading?: boolean;
  children: React.ReactNode;
  onClick?: React.MouseEventHandler<HTMLButtonElement> | undefined;
  disabled?: boolean;
  size?: number;
  buttonId?: string;
  buttonRef?: any;
  onMouseEnter?: any;
  onMouseLeave?: any;
  clickEventName?: string;
  clickEventProperties?: Record<string, any>;
  style?: React.CSSProperties;
  title?: string;
};

const Button = ({
  className,
  children,
  loading,
  loaderColor,
  onClick,
  disabled,
  // size = 8,
  buttonRef,
  buttonId,
  style,
  clickEventName,
  clickEventProperties,
  title,
  onMouseEnter,
  onMouseLeave,
}: Props) => {
  const getTextContent = (children: React.ReactNode): string => {
    if (typeof children === "string") return children;
    if (typeof children === "number") return children.toString();

    if (React.isValidElement(children)) {
      if (children.props.children) {
        return getTextContent(children.props.children);
      }
      return "";
    }

    if (Array.isArray(children)) {
      return children.map((child) => getTextContent(child)).join(" ");
    }

    return "";
  };

  const buttonClickHandler: React.MouseEventHandler<HTMLButtonElement> = (
    e
  ) => {
    if (onClick) {
      onClick(e);
    }

    try {
      if (clickEventName) {
        // const eventProperties = {
        //   buttonText: getTextContent(children),
        //   ...(clickEventProperties || {}),
        // };
      } else if (clickEventProperties) {
        // const eventProperties = {
        //   buttonText: getTextContent(children),
        //   ...(clickEventProperties || {}),
        // };
      }
    } catch (e) {}
  };

  return (
    <button
      id={buttonId}
      ref={buttonRef}
      disabled={disabled || loading}
      className={className}
      type="button"
      onClick={buttonClickHandler}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      style={style}
      title={title}
    >
      {loading ? <LoaderWithThreeDots color={loaderColor} /> : children}
    </button>
  );
};

export default Button;

Button.defaultProps = {
  className: "",
  loaderColor: "#00ffc3",
  loading: false,
  onClick: () => {},
  disabled: false,
  size: 8,
};