import Triangle from '../../../assets/icons/triangle.svg'
import Loading from '../../../assets/gif/loading.gif'
import CheckedGreen from '../../../assets/icons/checked-green.svg'
import ErrorWarning from '../../../assets/icons/error-warning.svg'
// import GrayRing from '../../../assets/icons/gray-ring.svg'
import { ReactNode, memo, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const TippyContent = memo(({ tippyStatus }: { tippyStatus: any }) => {
    const textSm = {
        fontSize: "14px",
        lineHeight: "20px",
        letterSpacing: "0.14px"
    }

    const flexGap1 = {
        display: "flex",
        alignItems: "center",
        justifyContent: "start",
        gap: "4px",
        height: "22px"
    }

    const animationProps = {
        initial: { opacity: 0, y: 10 },
        animate: { opacity: 1, y: 0 },
        exit: { opacity: 0, y: -10 },
        transition: { duration: 0.2 }
    }

    const AnimatedContent = memo(({ children, style = {} }: { children: ReactNode, style?: any }) => (
        <motion.div {...animationProps} style={style}>
            {children}
        </motion.div>
    ))

    const TranscriptStatusPanel = useMemo(() => {
        let content: ReactNode = null;

        switch (tippyStatus) {
            case 'checkingTranscript':
                content = (
                    <AnimatedContent>
                        <div style={flexGap1}>
                            <img src={Loading} alt="" style={{ width: 16, height: 16 }} />
                            <p style={{ ...textSm, fontWeight: 600, color: '#F2F2F2' }}>
                                Checking for transcript
                            </p>
                        </div>
                        <p style={{ ...textSm, color: '#94939F', marginTop: "2px", marginLeft: "22px" }}>
                            This will take a few seconds.
                        </p>
                    </AnimatedContent>
                );
                break;

            case 'sectionGenerating':
                content = (
                    <AnimatedContent>
                        <div style={flexGap1}>
                            <img src={CheckedGreen} alt="" style={{ width: 16, height: 16 }} />
                            <p style={{ ...textSm, fontWeight: 500, color: '#1DAF61' }}>
                                Transcript available
                            </p>
                        </div>
                        <p style={{ ...textSm, color: '#94939F', marginTop: "2px", marginLeft: "22px" }}>
                            This will take a few seconds.
                        </p>
                    </AnimatedContent>
                );
                break;

            case 'quizGenerating':
                content = (
                    <AnimatedContent>
                        <div style={flexGap1}>
                            <img src={CheckedGreen} alt="" style={{ width: 16, height: 16 }} />
                            <p style={{ ...textSm, fontWeight: 500, color: '#1DAF61' }}>
                                Transcript available
                            </p>
                        </div>
                        <p style={{ ...textSm, color: '#94939F', marginTop: "2px", marginLeft: "22px" }}>
                            This will take a few seconds.
                        </p>
                    </AnimatedContent>
                );
                break;

            // case 'quizDone':
            // content = (
            //     <AnimatedContent>
            //         <div style={flexGap1}>
            //             <img src={CheckedGreen} alt="" style={{ width: 16, height: 16 }} />
            //             <p style={{ ...textSm, fontWeight: 500, color: '#1DAF61' }}>
            //                 Transcript available
            //             </p>
            //         </div>
            //         <div style={{ marginTop: "4px" }}>
            //             <img src={CheckedGreen} alt="" style={{ width: 16, height: 16, top: "2px", position: "relative" }} />
            //             <p style={{ ...textSm, fontWeight: 500, color: '#1DAF61', marginLeft: "4px", display: "inline" }}>
            //                 Quiz generated
            //             </p>
            //             <p style={{ ...textSm, color: '#94939F', marginTop: "2px", marginLeft: "22px" }}>
            //                 You'll see them marked on the video now. Don't skip them 😊
            //             </p>
            //         </div>
            //     </AnimatedContent>
            // );
            // break;

            case 'transcriptError':
                content = (
                    <AnimatedContent style={{ flexDirection: 'column' }}>
                        <div style={flexGap1}>
                            <img src={ErrorWarning} alt="" style={{ width: 16, height: 16 }} />
                            <p style={{ ...textSm, fontWeight: 500, color: '#FF6875' }}>
                                Transcript unavailable
                            </p>
                        </div>
                        <p style={{ ...textSm, color: '#94939F', marginTop: "2px", marginLeft: "22px" }}>
                            Sadly, Learning Session cannot be made without a transcript :(
                        </p>
                    </AnimatedContent>
                );
                break;

                // case 'quizError':
                // content = (
                //     <AnimatedContent style={{ flexDirection: 'column' }}>
                //         <div style={{ ...flexGap1 }}>
                //             <img src={ErrorWarning} alt="" style={{ width: 16, height: 16 }} />
                //             <p style={{ ...textSm, fontWeight: 500, color: '#FF6875' }}>
                //                 We could not generate the Quiz
                //             </p>
                //         </div>
                //         <p style={{ ...textSm, color: '#94939F', marginTop: "2px", marginLeft: "22px" }}>
                //             Please retry to resolve this issue!
                //         </p>
                //     </AnimatedContent>
                // );
                // break;
        }

        return (
            <div style={{ position: 'relative' }}>
                <AnimatePresence mode="wait">
                    {content}
                </AnimatePresence>
            </div>
        );
    }, [tippyStatus]);

    const initialContent = useMemo(() => (
        <AnimatedContent>
            <div className='flex flex-col' style={{ zIndex: 2, position: "relative" }}>
                <p style={{ ...textSm, fontWeight: "500", color: "#F2F2F2" }}>Turn this video into a hands-on learning session</p>
                <p style={{ ...textSm, fontWeight: "500", color: "#94939F", marginTop: "8px" }}>I will divide the video into smaller chunks and we will focus on each chunk at a time. Look out for surprise quizzes :) </p>
            </div>
        </AnimatedContent>
    ), []);

    return (
        <div className=''
            style={{
                width: "200px",
                padding: "12px",
                borderRadius: "12px",
                backgroundColor: "#2F3241",
                position: "relative"
            }}>
            {tippyStatus === "stopped" ? (
                initialContent
            ) : (
                <div className='flex flex-col ' style={{ zIndex: 2, position: "relative" }}>
                    {TranscriptStatusPanel}
                </div>
            )}

            <img src={Triangle} alt="triangle"
                style={{
                    position: "absolute",
                    bottom: "-11px",
                    left: "50%",
                    transform: "translateX(-50%)",
                    zIndex: 1
                }}
            />
        </div>
    )
})

export default TippyContent