import { useEffect, useState, useCallback, useRef } from "react";

interface Position {
  x: number;
  y: number;
  width: number;
  height: number;
}

interface EditorInfo {
  container: HTMLElement;
  rect: DOMRect;
  scrollContainer: HTMLElement;
  isCodeEditor: boolean;
}

const EDITOR_CLASSES = [
  'monaco-editor',
  'ace_editor',
  'CodeMirror',
  'view-lines',
  'ace_content'
] as const;

const DEBOUNCE_DELAY = 100;
const MARGIN = {
  LEFT: 5,
  RIGHT: 200,
  TOP: 5,
  BOTTOM: 50,
  VERTICAL_OFFSET: 5,
  WIDGET_HEIGHT: 35
};

const isElementScrollable = (element: HTMLElement): boolean => {
  const style = window.getComputedStyle(element);
  const overflow = style.overflow;
  const overflowY = style.overflowY;
  return (overflow === 'auto' || overflow === 'scroll' || 
          overflowY === 'auto' || overflowY === 'scroll') &&
         (element.scrollHeight > element.clientHeight);
};

const useSelectionSearch = () => {
  const [selection, setSelection] = useState<string>();
  const [widgetPosition, setWidgetPosition] = useState<Position>();
  const [askedInChatSelection, setAskedInChatSelection] = useState<string>();
  const timeoutRef = useRef<NodeJS.Timeout>();
  const scrollContainerRef = useRef<HTMLElement | null>(null);
  const lastSelectionRef = useRef<Selection | null>(null);

  const findScrollableParent = useCallback((element: Element | null): HTMLElement | null => {
    if (!element) return null;
    
    let currentElement = element.parentElement;
    while (currentElement) {
      if (currentElement instanceof HTMLElement && isElementScrollable(currentElement)) {
        return currentElement;
      }
      currentElement = currentElement.parentElement;
    }
    return document.documentElement;
  }, []);

  const findEditorContainer = useCallback((element: Element | null): EditorInfo | null => {
    if (!element) return null;

    let currentElement: Element | null = element;
    while (currentElement !== null) {
      if (currentElement instanceof HTMLElement) {
        const isCodeEditor = EDITOR_CLASSES.some(className => 
          currentElement?.classList.contains(className)) || 
          currentElement.id === 'editor';

        if (isCodeEditor) {
          const scrollContainer = findScrollableParent(currentElement);
          return {
            container: currentElement,
            rect: currentElement.getBoundingClientRect(),
            scrollContainer: scrollContainer || document.documentElement,
            isCodeEditor: true
          };
        }
      }
      currentElement = currentElement.parentElement;
    }
    
    // If no code editor found, return document body as container
    return {
      container: document.body,
      rect: document.body.getBoundingClientRect(),
      scrollContainer: document.documentElement,
      isCodeEditor: false
    };
  }, [findScrollableParent]);

  const isSelectionUpward = useCallback((selection: Selection): boolean => {
    if (!selection.anchorNode || !selection.focusNode) return false;

    // If nodes are different, compare their position in the document
    if (selection.anchorNode !== selection.focusNode) {
      const position = selection.anchorNode.compareDocumentPosition(selection.focusNode);
      // If focus node is before anchor node, selection is upward
      return !!(position & Node.DOCUMENT_POSITION_PRECEDING);
    }

    // If nodes are the same, compare offsets
    return selection.anchorOffset > selection.focusOffset;
  }, []);

  const calculatePosition = useCallback((
    focusRect: DOMRect,
    editorInfo: EditorInfo,
    isUpward: boolean
  ): Position => {
    let x = focusRect.right;
    let y = isUpward 
      ? focusRect.top - MARGIN.WIDGET_HEIGHT - MARGIN.VERTICAL_OFFSET
      : focusRect.bottom + MARGIN.VERTICAL_OFFSET;

    const { rect: containerRect, scrollContainer, isCodeEditor } = editorInfo;
    
    if (isCodeEditor) {
      // Special handling for code editors
      const scrollRect = scrollContainer.getBoundingClientRect();
      
      // Adjust x position to stay within editor bounds with proper margins
      x = Math.min(
        Math.max(containerRect.left + MARGIN.LEFT, x),
        containerRect.right - MARGIN.RIGHT
      );

      // For code editors, we want to be more precise with vertical positioning
      if (isUpward) {
        // If going upward and not enough space, flip to bottom
        if (y < scrollRect.top + MARGIN.TOP) {
          y = focusRect.bottom + MARGIN.VERTICAL_OFFSET;
        }
      } else {
        // If going downward and not enough space, flip to top
        if (y + MARGIN.WIDGET_HEIGHT > scrollRect.bottom - MARGIN.BOTTOM) {
          y = focusRect.top - MARGIN.WIDGET_HEIGHT - MARGIN.VERTICAL_OFFSET;
        }
      }

      // Ensure final position is within the visible editor area
      y = 78
    } else {
      // Regular document positioning
      const viewportHeight = window.innerHeight;
      const viewportWidth = window.innerWidth;

      // Keep widget within viewport bounds
      x = Math.min(Math.max(MARGIN.LEFT, x), viewportWidth - MARGIN.RIGHT);

      // Flip position if too close to viewport edges
      if (isUpward && y < MARGIN.TOP) {
        y = focusRect.bottom + MARGIN.VERTICAL_OFFSET;
      } else if (!isUpward && y + MARGIN.WIDGET_HEIGHT > viewportHeight - MARGIN.BOTTOM) {
        y = focusRect.top - MARGIN.WIDGET_HEIGHT - MARGIN.VERTICAL_OFFSET;
      }

      y = Math.max(MARGIN.TOP, Math.min(y, viewportHeight - MARGIN.BOTTOM));
    }

    // Store the scroll container reference for scroll event handling
    scrollContainerRef.current = scrollContainer;

    return {
      x,
      y,
      width: 0,
      height: 0
    };
  }, []);

  const updatePosition = useCallback(() => {
    const selection = window.getSelection();
    if (!selection?.toString()) {
      setWidgetPosition(undefined);
      return;
    }

    try {
      // Store the selection for later use
      lastSelectionRef.current = selection;

      // Get the focus node (where selection ends) and its parent element
      const focusNode = selection.focusNode;
      if (!focusNode) return;

      // Create a range from the focus point
      const range = document.createRange();
      range.setStart(focusNode, selection.focusOffset);
      range.setEnd(focusNode, selection.focusOffset);
      
      const focusRect = range.getBoundingClientRect();
      
      // Find the editor container from the focus node's parent element
      const parentElement = focusNode.nodeType === Node.TEXT_NODE 
        ? focusNode.parentElement 
        : focusNode as Element;
        
      const editorInfo = findEditorContainer(parentElement) || {
        container: document.body,
        rect: document.body.getBoundingClientRect(),
        scrollContainer: document.documentElement,
        isCodeEditor: false
      };
      const isUpward = isSelectionUpward(selection);
      const position = calculatePosition(focusRect, editorInfo, isUpward);
      
      // Immediately set the position without debouncing for the initial selection
      setWidgetPosition(position);
    } catch (error) {
      console.error('[updatePosition] Error:', error);
      setWidgetPosition(undefined);
    }
  }, [findEditorContainer, calculatePosition, isSelectionUpward]);

  const debouncedPositionUpdate = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    timeoutRef.current = setTimeout(updatePosition, DEBOUNCE_DELAY);
  }, [updatePosition]);

  const handleSelectionChange = useCallback((isStart: boolean) => {
    const text = window.getSelection()?.toString().trim();

    if (isStart || !text) {
      setSelection(undefined);
      setWidgetPosition(undefined);
      lastSelectionRef.current = null;
      chrome.storage.local.remove("selectedText");
      chrome.runtime.sendMessage({ action: 'textSelected', text: undefined });
      return;
    }

    setSelection(text);
    chrome.runtime.sendMessage({ action: 'textSelected', text });
    // Call updatePosition immediately for the initial selection
    updatePosition();
  }, [updatePosition]);

  useEffect(() => {
    const handleSelectionStart = () => handleSelectionChange(true);
    const handleSelectionEnd = () => handleSelectionChange(false);
    const handleScroll = () => {
      // Only update position if we have a stored selection
      if (lastSelectionRef.current) {
        debouncedPositionUpdate();
      }
    };

    document.addEventListener("selectstart", handleSelectionStart);
    document.addEventListener("mouseup", handleSelectionEnd);
    document.addEventListener("keyup", handleSelectionEnd);
    window.addEventListener("scroll", handleScroll, true);
    window.addEventListener("resize", debouncedPositionUpdate);

    if (scrollContainerRef.current) {
      scrollContainerRef.current.addEventListener("scroll", handleScroll);
    }

    return () => {
      document.removeEventListener("selectstart", handleSelectionStart);
      document.removeEventListener("mouseup", handleSelectionEnd);
      document.removeEventListener("keyup", handleSelectionEnd);
      window.removeEventListener("scroll", handleScroll, true);
      window.removeEventListener("resize", debouncedPositionUpdate);
      if (scrollContainerRef.current) {
        scrollContainerRef.current.removeEventListener("scroll", handleScroll);
      }
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [handleSelectionChange, debouncedPositionUpdate]);

  return {
    selection,
    setSelection,
    widgetPosition,
    askedInChatSelection,
    setAskedInChatSelection,
  };
};

export default useSelectionSearch;