import MentoraiButton from '../../../../../common/button/mentorai-button';
import { useState } from 'react';
import { cn } from '../../../../../utils/cn';
import { motion } from 'framer-motion';
import Tippy from '@tippyjs/react';
import { useThemeDetection } from '../../../../hooks/use-theme-detection';


const Sparkle = ({ isDark }: { isDark: boolean | null }) => {
    return (
        <svg xmlns="http://www.w3.org/2000/svg" width="9" height="8" viewBox="0 0 9 8" fill="none">
            <path d="M4.26562 8C4.17969 7.54861 3.95312 7.0625 3.58593 6.54167C3.21875 6.01388 2.69531 5.5243 2.01562 5.07292C1.34375 4.62153 0.671875 4.33333 0 4.20833V3.77084C0.664063 3.63194 1.30078 3.375 1.91015 3C2.52734 2.61805 3.04297 2.15972 3.45702 1.625C3.8789 1.07639 4.14843 0.534721 4.26562 0H4.7578C4.82812 0.347221 4.96874 0.704861 5.17968 1.07292C5.39062 1.43403 5.66015 1.78125 5.98827 2.11459C6.32422 2.44097 6.69922 2.73611 7.11327 3C7.73047 3.38888 8.35937 3.64584 9 3.77084V4.20833C8.57031 4.28472 8.12499 4.44097 7.66405 4.67708C7.21093 4.91319 6.78906 5.19444 6.39843 5.52083C6.00781 5.84027 5.6875 6.17708 5.43749 6.53125C5.07031 7.05208 4.84375 7.54167 4.7578 8H4.26562Z" fill={`${isDark ? '#A5A1F7' : '#736DF2'}`} />
        </svg>
    )
}

type Props = {
    handleStartThinkingAloud: () => void,
    handleStartInterviewMode: () => void,
    practiceModeOn: boolean,
    interviewModeOn: boolean
}

const PracticeWithMeOptionCard = ({ handleStartThinkingAloud, handleStartInterviewMode, practiceModeOn, interviewModeOn }: Props) => {
    const [tippyHoverCard, setTippyHoverCard] = useState('');
    const { isDark } = useThemeDetection();

    const handleOpenSidePanel = () => {
        chrome.runtime.sendMessage({ action: "openSidePanel" });
    };

    if (isDark === null) return null;
    return (
        <motion.div
            initial={{ opacity: 0, y: 24 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 24 }}
            transition={{ duration: 0.1, ease: 'easeOut' }}
            className={`mt-0.5 w-[354px] absolute border  rounded-[12px] p-2 flex flex-col cursor-default z-50 font-bricolage-grotesque ${isDark ? 'bg-mentorai-bg-base border-mentorai-stroke-strong' : 'bg-white border-[#00000014]'}`}
        >
            <Tippy
                delay={0}
                duration={0}
                visible={tippyHoverCard === 'thinking-aloud'}
                interactive={true}
                placement='bottom-end'
                content={
                    <motion.div
                        initial={{ opacity: 0, y: 5 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 5 }}
                        transition={{ duration: 0.3 }}
                        className='max-w-[200px] h-[28px] bg-[#4B4E63] flex items-center justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md   relative bottom-[50px]'>
                        {practiceModeOn ? 'This session is ongoing' : 'Another session is ongoing'}
                    </motion.div>
                }
            >
                <div className={`flex flex-col gap-5 flex-1 rounded-[8px] p-3 justify-center 
            ${(interviewModeOn) ? `` : `cursor-pointer ${isDark ? 'hover:bg-mentorai-bg-strong' : 'hover:bg-[#0000000D]'}`}
            `}
                    onMouseEnter={() => {
                        if (practiceModeOn || interviewModeOn) {
                            setTippyHoverCard('thinking-aloud');
                        }
                    }}
                    onMouseLeave={() => {
                        if (practiceModeOn || interviewModeOn) {
                            setTippyHoverCard('');
                        }
                    }}
                    onClick={() => {
                        if (practiceModeOn) {
                            handleOpenSidePanel();
                        } else {
                            handleStartThinkingAloud();
                        }
                    }}
                >
                    <div className="flex flex-col gap-1.5"
                    >
                        <div className="flex flex-row items-center gap-1">
                            <span className={`font-medium text-[14px] leading-normal font-bricolage-grotesque ${isDark ? 'text-mentorai-text-white' : 'text-[#07070A]'}`}>
                                1:1 Structured Coaching Session
                            </span>
                        </div>
                        <span className="text-[#94939F] text-[12px] font-normal font-manrope flex flex-col gap-1">
                            <div className="flex gap-2 font-manrope">
                                <span className='w-[9px] flex justify-center items-center'><Sparkle isDark={isDark} /></span>
                                We’ll follow a structured, step by step approach.
                            </div>
                            <div className="flex gap-2 font-manrope">
                                <span className='w-[9px] flex justify-center items-center'><Sparkle isDark={isDark} /></span>
                                This will prepare you to always approach a problem in a structured way which is expected at interviews.
                            </div>
                            <div className="flex gap-2 font-manrope">
                                <span className='w-[9px] flex justify-center items-center'><Sparkle isDark={isDark} /></span>
                                <span
                                    style={{
                                        textUnderlineOffset: '32.5%',
                                        textDecorationSkipInk: 'none',
                                        textUnderlinePosition: 'from-font',
                                        textDecorationThickness: '12.5%',
                                        textDecorationLine: 'underline',
                                        textDecorationStyle: 'dotted',
                                    }}
                                    className={`font-manrope ${isDark ? 'text-mentorai-text-soft' : ' text-[#07070A] border-b-[#07070A]'}`}>Best for everyday practice.</span>
                            </div>
                        </span>
                    </div>
                    <div className="flex flex-row justify-start w-full">
                        {(practiceModeOn) ?
                            <div className={`flex items-center gap-1 py-1 h-7 rounded-lg px-3 w-[80px] ${isDark ? 'bg-[rgba(31,_193,_107,_0.24)]' : 'bg-[rgba(31,_193,_107,_0.12)]'}`}>
                                <div className={`text-[12px] font-medium leading-normal flex items-center justify-center ${isDark ? 'text-[#3EE089]' : 'text-[#1DAF61]'}`}>ONGOING</div>
                            </div>
                            :
                            <MentoraiButton
                                onClick={() => { }}
                                type='primary'
                                size='small'
                                classNames='w-fit !font-normal h-[28px] w-[114px] !font-bricolage-grotesque'
                                disabled={practiceModeOn || interviewModeOn}
                            >
                                Start Session →
                            </MentoraiButton>
                        }
                    </div>
                </div>
            </Tippy>


            <div className={`w-full h-px my-4 ${isDark ? 'bg-[#45475F]' : 'bg-[#0000001A]'}`}>
                <span className='invisible'>.</span>
            </div>

            <Tippy
                delay={0}
                duration={0}
                visible={tippyHoverCard === 'interview-mode'}
                interactive={true}
                placement='bottom-end'
                content={
                    <motion.div
                        initial={{ opacity: 0, y: 5 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 5 }}
                        transition={{ duration: 0.3 }}
                        className='max-w-[200px] h-[28px]    bg-[#4B4E63] flex items-center justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md   relative bottom-[50px]'>
                        {interviewModeOn ? 'This session is ongoing' : 'Another session is ongoing'}
                    </motion.div>
                }
            >
                <div className={cn("flex flex-col gap-5 flex-1 rounded-[8px] p-3 justify-center ",
                    `${practiceModeOn ? '' : ` cursor-pointer ${isDark ? 'hover:bg-mentorai-bg-strong' : 'hover:bg-[#0000000D]'}`}`
                )}
                    onMouseEnter={() => {
                        if (practiceModeOn || interviewModeOn) {
                            setTippyHoverCard('interview-mode');
                        }
                    }}
                    onMouseLeave={() => {
                        if (practiceModeOn || interviewModeOn) {
                            setTippyHoverCard('');
                        }
                    }}
                    onClick={() => {
                        if (interviewModeOn) {
                            handleOpenSidePanel();
                        } else {
                            handleStartInterviewMode();
                        }
                    }}
                >
                    <div className="flex flex-col gap-1.5"
                    >
                        <div className="flex flex-row items-center gap-2">
                            <span className={`font-medium text-[14px] leading-normal font-bricolage-grotesque ${isDark ? 'text-mentorai-text-white' : 'text-[#07070A]'}`}>
                                1:1 Interview Simulation Session
                            </span>
                        </div>
                        <span className="text-[#94939F] text-[12px] font-normal font-manrope flex flex-col gap-1">
                            <div className="flex gap-2 font-manrope">
                                <span className='w-[9px] flex justify-center items-center'><Sparkle isDark={isDark} /></span>
                                The session will be timed.
                            </div>
                            <div className="flex gap-2 font-manrope">
                                <span className='w-[9px] flex justify-center items-center'><Sparkle isDark={isDark} /></span>
                                Like in a real interview, you’ll solve the question while speaking your thought process.                            </div>
                            <div className="flex gap-2 font-manrope">
                                <span className='w-[9px] flex justify-center items-center'><Sparkle isDark={isDark} /></span>
                                <span
                                    style={{
                                        textUnderlineOffset: '32.5%',
                                        textDecorationSkipInk: 'none',
                                        textUnderlinePosition: 'from-font',
                                        textDecorationThickness: '12.5%',
                                        textDecorationLine: 'underline',
                                        textDecorationStyle: 'dotted',
                                    }}
                                    className={` font-manrope ${isDark ? 'text-mentorai-text-soft' : ' text-[#07070A] border-b-[#07070A]'}`}>Best for evaluating yourself</span>
                            </div>
                        </span>
                    </div>
                    <div className="flex flex-row justify-start w-full">
                        {(interviewModeOn) ?
                            <div className={`flex items-center gap-1 py-1 h-7 rounded-lg px-3 w-[80px] ${isDark ? 'bg-[rgba(31,_193,_107,_0.24)]' : 'bg-[rgba(31,_193,_107,_0.12)]'}`}>
                                <div className={`text-[12px] font-medium leading-normal flex items-center justify-center ${isDark ? 'text-[#3EE089]' : 'text-[#1DAF61]'}`}>ONGOING</div>
                            </div>
                            :
                            <MentoraiButton
                                onClick={() => { }}
                                type='primary'
                                size='small'
                                classNames='w-fit !font-normal h-[28px] w-[114px] !font-bricolage-grotesque'
                                disabled={practiceModeOn || interviewModeOn}
                            >
                                Start Session →
                            </MentoraiButton>
                        }
                    </div>
                </div>
            </Tippy>
        </motion.div >
    );
};

export default PracticeWithMeOptionCard;
