import { timeToSeconds } from "../../../../../src/utils/str-time-to-seconds";
import { getYoutubeVideoLength } from "../../../../utils/get-youtube-video-length";
import { useCustomUI } from "../../../../contexts/custom-ui-context/custom-ui-context";
import BrainFill2 from "../../../../assets/icons/brain-fill2.svg";
import BrainFill2Hover from "../../../../assets/icons/brain-fill2-hover.svg";
import { useState } from "react";
import Tippy from "@tippyjs/react";

const ProgressCheckpoint: React.FC = () => {
    const { learningSession, setSessionOverlayView, setSelectedSection, setCurrentSection, pauseVideo, markSectionEndScreenShown } = useCustomUI();
    const [isQuizHovered, setIsQuizHovered] = useState<number | null>(null);
    const [isSectionHover, setIsSectionHover] = useState<number | null>(null);
    if (!learningSession?.sections?.length) {
        return null;
    }

    const videoDuration = getYoutubeVideoLength();
    if (!videoDuration) return null;

    const handleSectionClick = (sectionIndex: number, section: any, event: React.MouseEvent) => {
        // const videoElement = document.querySelector("video");
        // if (videoElement) {
        //     // Calculate the exact position clicked within the section
        //     const rect = (event.currentTarget as HTMLElement).getBoundingClientRect();
        //     const clickX = event.clientX - rect.left;
        //     const sectionWidth = rect.width;
        //     const clickRatio = clickX / sectionWidth;
        //     // Calculate the exact timestamp within the section
        //     const sectionStartSeconds = timeToSeconds(section.startTime);
        //     const sectionEndSeconds = timeToSeconds(section.endTime);
        //     const sectionDuration = sectionEndSeconds - sectionStartSeconds;
        //     const exactTimestamp = sectionStartSeconds + (clickRatio * sectionDuration);

        //     videoElement.currentTime = exactTimestamp;
        // }
        setSelectedSection(sectionIndex);
        let showSectionOverlay = true;
        pauseVideo(showSectionOverlay);
    };

    const handleQuizPinClick = (sectionIndex: number, section: any, event: React.MouseEvent) => {
        event.stopPropagation(); // Prevent section click

        const videoElement = document.querySelector("video");
        if (videoElement) {
            videoElement.currentTime = timeToSeconds(section.endTime);
            pauseVideo();
        }

        setSelectedSection(sectionIndex);
        setCurrentSection(sectionIndex);
        setSessionOverlayView('section_end');
        markSectionEndScreenShown(sectionIndex);

        // chrome.runtime.sendMessage({
        //     action: "sendAnalytics",
        //     url: window.location.href,
        //     eventName: "MentorAi Learning Session Quiz Pin Clicked",
        //     eventProperties: {
        //         section_index: sectionIndex,
        //         section_title: section.sectionTitle,
        //         end_time: section.endTime,
        //         quiz_count: section.quizzes?.length || 0,
        //         current_duration: getYoutubeVideoPlayHead(),
        //         video_duration: videoDuration
        //     },
        // });
    };

    return (
        <div
            className="w-full absolute pointer-events-auto"
            style={{
                height: '32px',
                bottom: '100%', // Position above the chrome-bottom container content
                left: '0',
                right: '0',
                marginBottom: '0px', // Small gap above progress bar container
                zIndex: 1000,
                pointerEvents: 'auto'
            }}
        >
            {/* Section Bars Layer */}
            {learningSession.sections.map((section: any, index: number) => {
                const startPosition = (timeToSeconds(section.startTime) / videoDuration) * 100;
                const endPosition = (timeToSeconds(section.endTime) / videoDuration) * 100;
                const width = endPosition - startPosition;

                // Check if section has quizzes
                const hasQuizzes = section.quizzes && section.quizzes.length > 0;

                return (
                    <Tippy
                        visible={isSectionHover === index && (isQuizHovered !== index)}
                        content={
                            <div className="flex flex-wrap items-start"
                                style={{
                                    padding: '4px 8px',
                                    maxWidth: '200px',
                                    textAlign: 'left',
                                    backgroundColor: "#4B4E63",
                                    color: "#f2f2f2",
                                    fontSize: "12px",
                                    fontFamily: "Manrope, sans-serif",
                                    alignItems: "center",
                                    borderRadius: '6px',
                                    letterSpacing: "-0.12px",
                                }}
                            >
                                Section {index + 1}: {section.sectionTitle}
                            </div>
                        }
                        placement="top"
                        interactive={true}
                        delay={[0, 0]}
                        duration={0}
                        hideOnClick={true}
                        interactiveBorder={10}
                    >
                        <div
                            onMouseEnter={() => setIsSectionHover(index)}
                            onMouseLeave={() => setIsSectionHover(null)}
                            key={`section-${index}`}
                            className={`absolute cursor-pointer group border-l border-r ${isSectionHover === index ? 'hover:bg-[rgba(242,242,242,0.50)] hover:border-l-[#DDDDDF] hover:border-r-[#DDDDDF]' : 'bg-[rgba(81,73,242,0.20)] border-l-[#A5A1F7] border-r-[#A5A1F7]'}`}
                            style={{
                                left: `${startPosition}%`,
                                width: `${width}%`,
                                height: '32px',
                                top: '-1px', // Center within the 32px container
                                zIndex: `${1000 - index}`, // this is done so that the quiz icon of the first section should be on top of the second section start 
                                cursor: 'pointer',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                minWidth: '20px', // Ensure very small sections are still visible
                            } as any}
                            onClick={(e) => handleSectionClick(index, section, e)}
                        >
                            {/* Section Number - only show if section is wide enough */}
                            {width > 3 && (
                                <span
                                    style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        width: '16px',
                                        height: '16px',
                                        borderRadius: '40px',
                                        fontWeight: 800,
                                        fontSize: '10px',
                                        lineHeight: '10px',
                                        letterSpacing: '0.4px',
                                        userSelect: 'none',
                                        paddingTop: '0.8px',
                                        textAlign: 'center'
                                    } as any}
                                    className={`${isSectionHover === index ? 'group-hover:bg-[#5149F2] group-hover:text-[#F2F2F2]' : ' bg-[rgba(81,73,242,0.32)] text-[#A5A1F7]'}`}
                                >
                                    {index + 1}
                                </span>
                            )}

                            {/* Quiz Pin inside section for sections with quizzes */}
                            {hasQuizzes && (
                                <Tippy
                                    visible={isQuizHovered === index}
                                    content={
                                        <div className="flex flex-wrap items-start z-[10002]"
                                            style={{
                                                padding: '4px 8px',
                                                maxWidth: '200px',
                                                textAlign: 'left',
                                                backgroundColor: "#4B4E63",
                                                color: "#f2f2f2",
                                                fontSize: "12px",
                                                fontFamily: "Manrope, sans-serif",
                                                alignItems: "center",
                                                borderRadius: '6px',
                                                letterSpacing: "-0.12px",
                                            }}
                                        >
                                            Quiz - Section {index + 1}
                                        </div>
                                    }
                                    placement="top"
                                    interactive={true}
                                    delay={[0, 0]}
                                    duration={0}
                                    hideOnClick={true}
                                    interactiveBorder={10}

                                >
                                    <div
                                        className="absolute cursor-pointer hover:scale-110 transition-transform"
                                        onMouseEnter={() => setIsQuizHovered(index)}
                                        onMouseLeave={() => setIsQuizHovered(null)}
                                        style={{
                                            right: '-11px',
                                            top: '6px',
                                            width: '20px',
                                            height: '20px',
                                            zIndex: 10001,
                                        }}
                                        onClick={(e) => handleQuizPinClick(index, section, e)}
                                    >
                                        <div
                                            className="relative rounded-full"
                                            style={{
                                                width: '20px',
                                                height: '20px',
                                                background: '#5149F2',
                                                border: '1px solid #A5A1F7',
                                                display: 'flex',
                                                alignItems: 'center',
                                                justifyContent: 'center',
                                                boxShadow: '0 2px 4px rgba(0, 0, 0, 0.2)'
                                            }}
                                        >
                                            <img
                                                src={isQuizHovered === index ? BrainFill2Hover : BrainFill2}
                                                alt="Quiz Available"
                                            />
                                        </div>
                                    </div>
                                </Tippy>
                            )}
                        </div>
                    </Tippy>
                );
            })}
        </div>
    );
};

export default ProgressCheckpoint;