import React from 'react';
import { useCustomUI } from '../../../contexts/custom-ui-context/custom-ui-context';
import { timeToSeconds } from '../../../../src/utils/str-time-to-seconds';
import MentorAiAvatarHeader from './components/mentorai-avatar-header';
import SectionDetailsWithCTA from './components/section-details-with-cta';
import SectionDurationAndDetails from './components/section-duration-and-details';
import MentorAiButton from '../../../../common/button/mentorai-button';
import SkipIcon from '../../../assets/icons/skip.svg'
import PlayIcon from '../../../assets/icons/white-play.svg'


const SectionStartOverlay: React.FC = () => {
  const {
    learningSession,
    selectedSection,
    currentSection,
    setCurrentSection,
    setSelectedSection,
    setSessionOverlayView,
    videoRef,
    mentoraiData,
    playVideo,
    playerMode,
    trackCustomUIEvent,
    getSectionProperties
  } = useCustomUI();

  if (!learningSession || selectedSection === null) return null;

  const isPlayerModeDefault = playerMode === "DEFAULT";
  const sectionData = learningSession.sections[selectedSection];
  const section = learningSession.sections[selectedSection];
  const canJumpToNext = (selectedSection || selectedSection === 0) && selectedSection < (learningSession?.sections?.length || 0) - 1;

  const handleStartWatching = () => {
    if (videoRef.current && sectionData) {
      videoRef.current.currentTime = timeToSeconds(sectionData.startTime);
      setCurrentSection(selectedSection);
      playVideo();
    }
  };

  const handleJumpToNext = () => {
    setSelectedSection(selectedSection + 1);
    trackCustomUIEvent("Button Clicked", {
      button_name: "Jump to Next Section",
      section: getSectionProperties(currentSection),
    })
    // Stay on overlay to show next section info
  };


  return (
    <div className='flex flex-col  w-full'   >
      <MentorAiAvatarHeader mentoraiData={mentoraiData}
        primaryStatus={<span style={{ color: "#94939F" }}>Now Watching : </span>}
        secondaryStatus={<span style={{ color: "#94939F", fontWeight: "500" }}>Section {currentSection + 1} of {learningSession.sections.length}</span>}
      />

      <SectionDetailsWithCTA
        sectionTitle={section.sectionTitle}
        sectionDurationAndDetails={<SectionDurationAndDetails />}
        sectionDescription={section.sectionDescription}
        sectionCTAs={
          <div className="flex flex-row flex-wrap" style={{ gap: isPlayerModeDefault ? '8px' : "12px", marginTop: isPlayerModeDefault ? '28px' : "44px" }}>
            <MentorAiButton
              type="primary"
              size="large"
              onClick={handleStartWatching}
              classNames=' !w-fit whitespace-nowrap'
              style={{ paddingLeft: isPlayerModeDefault ? "8px" : "18px", paddingRight: isPlayerModeDefault ? "12px" : "24px", height: isPlayerModeDefault ? '32px' : '40px' }}
            >
              <div className="flex items-center" style={{ gap: 8 }}>
                <img src={PlayIcon} alt="play" style={{ width: 18, height: 18 }} />
                <span style={{ fontWeight: 500, fontSize: 14, color: "#F2F2F2" }}>Start Watching</span>
              </div>
            </MentorAiButton>

            {canJumpToNext ? (
              <MentorAiButton
                type="secondary"
                size="large"
                onClick={handleJumpToNext}
                classNames=' !w-fit whitespace-nowrap'
                style={{ paddingLeft: isPlayerModeDefault ? "8px" : "18px", paddingRight: isPlayerModeDefault ? "12px" : "24px", height: isPlayerModeDefault ? '32px' : '40px' }}
              >
                <span style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 14, fontWeight: 500, lineHeight: "22px", letterSpacing: "0.084px", color: "#F2F2F2" }}>
                  <img src={SkipIcon} alt="skip" style={{ width: 18, height: 18 }} />
                  Jump to Next Section
                </span>
              </MentorAiButton>
            ) : null}
          </div>
        }
      />
    </div>
  );
};

export default SectionStartOverlay; 