import React from "react";
import MentorAiButton from "../../../common/button/mentorai-button";
import useDeleteInteractionsCta from "./use-delete-interactions";

const DeleteInteractionsCta = () => {
  const {handleDeleteInteractions, handleDeleteResourcesData}=useDeleteInteractionsCta()
  return <div className="flex items-center fixed bottom-0 right-0 p-4 gap-4">
    <MentorAiButton type="primary" classNames="h-[44px] w-[160px]" onClick={handleDeleteInteractions}>
        Delete Interactions
    </MentorAiButton>
    <MentorAiButton type="outlined" classNames="h-[44px] w-[160px]" onClick={handleDeleteResourcesData}>
        Delete Resources Data
    </MentorAiButton>
  </div>
};

export default DeleteInteractionsCta;