import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback, useRef } from 'react';


interface AuthContextType {
    menteeData: any;
    setMenteeData: Function;
    mentoraiData: any;
    setMentoraiData: Function;
    menteeSubscription: any;
    setMenteeSubscription: Function;
}

export const AuthContext = createContext<AuthContextType | undefined>(undefined);
export const AuthContextProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [menteeData, setMenteeData] = useState(null);
    const [mentoraiData, setMentoraiData] = useState(null);
    const [menteeSubscription, setMenteeSubscription] = useState(null);


    const fetchMenteeSubscription = async (mentee_id: string, mentorai_id: string) => {
        const menteeSubscription = await chrome.runtime.sendMessage({
            action: "fetch_calls",
            fetch_call: "fetch_mentee_subscription",
            mentee_id: mentee_id,
            mentorai_id: mentorai_id,
        });

        setMenteeSubscription(menteeSubscription.mentee_subscription);
    };


    const fetchMentoraiData = async () => {
        const mentoraiData = await chrome.runtime.sendMessage({
            action: "fetch_calls",
            fetch_call: "fetch_mentorai",
        });

        setMentoraiData(mentoraiData.mentorai_data);
        return mentoraiData.mentorai_data;
    };

    const fetchMenteeData = async () => {
        const menteeDataResponse = await chrome.runtime.sendMessage({
            action: "fetch_calls",
            fetch_call: "fetch_mentee",
        });

        const menteeProfileData = menteeDataResponse.mentee_data;

        setMenteeData(menteeProfileData);
        return menteeProfileData;
    };

    const fetchData = async () => {
        const menteeaiDataProcess = fetchMentoraiData();
        const menteeDataProcess = fetchMenteeData();

        const menteeData = await menteeDataProcess;
        const mentoraiData = await menteeaiDataProcess;
        if (menteeData?.recordId && mentoraiData?.recordId) {
            await fetchMenteeSubscription(menteeData?.recordId || "", mentoraiData?.recordId || "");
        }
    };

    const messageListener = async (event: any) => {
        if (event.source !== window) return;
        switch (event.data.action) {
            case "refetch_mentee_data":
                const menteeData = await chrome.runtime.sendMessage({
                    action: "fetch_calls",
                    fetch_call: "fetch_mentee",
                    refetch: true,
                });
                setMenteeData(menteeData.mentee_data);
                chrome.storage.local.set({ menteeData: menteeData.mentee_data });
                break;
            default:
                break;
        }
    };

    useEffect(() => {
        fetchData();

        const localStorageListener = (changes: any) => {
            if (changes.menteeSubscription) {
                setMenteeSubscription(changes.menteeSubscription.newValue);
            }
        };
        chrome.storage.local.onChanged.addListener(localStorageListener);
        window.addEventListener("message", messageListener);
        return () => {
            chrome.storage.local.onChanged.removeListener(localStorageListener);
            window.removeEventListener("message", messageListener);
        };
    }, []);


    return (
        <AuthContext.Provider
            value={{
                menteeData,
                setMenteeData,
                mentoraiData,
                setMentoraiData,
                menteeSubscription,
                setMenteeSubscription,
            }}
        >
            {children}
        </AuthContext.Provider>
    );
};

export const useAuthContext = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuthContext must be used within a AuthContextProvider');
    }
    return context;
}; 