export const randomDelay = (min: number, max: number): Promise<void> => {
    return new Promise(resolve => setTimeout(resolve, Math.random() * (max - min) + min));
};

/**
 * Checks if Easy Apply filter is currently active via URL parameter
 */
export const isEasyApplyFilterActive = (): boolean => {
    const url = new URL(window.location.href);
    return url.searchParams.get('f_AL') === 'true';
};

/**
 * Enables the Easy Apply filter by clicking the Easy Apply button in the LinkedIn jobs toolbar.
 * This filters the job list to only show jobs with Easy Apply option.
 * @returns Promise<boolean> - true if filter was enabled successfully, false otherwise
 */
export const enableEasyApplyFilter = async (): Promise<boolean> => {
    try {
        // First check if filter is already active via URL
        if (isEasyApplyFilterActive()) {
            console.log('[AutoApply] Easy Apply filter is already active (detected via URL)');
            return true;
        }

        // Target the jobs search toolbar container
        const toolbarContainer = document.querySelector(
            'body > div.application-outlet > div.authentication-outlet > div.scaffold-layout.scaffold-layout--breakpoint-xl.scaffold-layout--list-detail.scaffold-layout--reflow.scaffold-layout--has-list-detail.jobs-search-two-pane__layout > section'
        );

        console.log('[AutoApply] Toolbar container found:', !!toolbarContainer);

        // Find the Easy Apply filter button in the toolbar
        const searchContainer = toolbarContainer || document;
        let easyApplyFilterBtn: HTMLElement | null = null;

        // Method 1: Look for buttons with "Easy Apply" text that are filter buttons (not the apply button)
        const allButtons = searchContainer.querySelectorAll('button');
        
        for (const button of allButtons) {
            const buttonText = button.textContent?.trim().toLowerCase() || '';
            const ariaLabel = button.getAttribute('aria-label')?.toLowerCase() || '';
            
            // Must contain "easy apply" but NOT be the job detail's Easy Apply button
            // The filter button is typically smaller and in the filter bar area
            const isEasyApplyText = buttonText.includes('easy apply') || ariaLabel.includes('easy apply');
            const isNotJobApplyButton = !button.closest('.jobs-details, .jobs-unified-top-card, .job-details-jobs-unified-top-card');
            const isFilterArea = button.closest('.jobs-search-box, .search-reusables, .jobs-search-results-list') !== null;
            
            if (isEasyApplyText && isNotJobApplyButton && isFilterArea) {
                easyApplyFilterBtn = button as HTMLElement;
                console.log('[AutoApply] Found Easy Apply filter button via Method 1');
                break;
            }
        }

        // Method 2: Look for filter pill/chip buttons
        if (!easyApplyFilterBtn) {
            const filterSelectors = [
                'button.search-reusables__filter-pill-button',
                'button.artdeco-pill',
                'button[aria-label*="Easy Apply"]',
                '.jobs-search-box__filters button',
                '.search-reusables__filters-bar button'
            ];
            
            for (const selector of filterSelectors) {
                const buttons = document.querySelectorAll(selector);
                for (const btn of buttons) {
                    const text = btn.textContent?.toLowerCase() || '';
                    if (text.includes('easy apply')) {
                        easyApplyFilterBtn = btn as HTMLElement;
                        console.log('[AutoApply] Found Easy Apply filter button via Method 2:', selector);
                        break;
                    }
                }
                if (easyApplyFilterBtn) break;
            }
        }

        // Method 3: Direct search in the section container
        if (!easyApplyFilterBtn && toolbarContainer) {
            const sectionButtons = toolbarContainer.querySelectorAll('button');
            for (const btn of sectionButtons) {
                const text = btn.textContent?.trim() || '';
                // Match "Easy Apply" exactly or with slight variations
                if (/easy\s*apply/i.test(text) && text.length < 50) { // Filter buttons have short text
                    easyApplyFilterBtn = btn as HTMLElement;
                    console.log('[AutoApply] Found Easy Apply filter button via Method 3');
                    break;
                }
            }
        }

        if (easyApplyFilterBtn) {
            // Check if already selected/active
            const isAlreadyActive = 
                easyApplyFilterBtn.getAttribute('aria-pressed') === 'true' ||
                easyApplyFilterBtn.classList.contains('artdeco-pill--selected') ||
                easyApplyFilterBtn.classList.contains('active') ||
                easyApplyFilterBtn.getAttribute('aria-checked') === 'true';

            if (isAlreadyActive) {
                console.log('[AutoApply] Easy Apply filter button already appears active');
                return true;
            }

            console.log('[AutoApply] Clicking Easy Apply filter button...');
            easyApplyFilterBtn.click();
            
            // Wait for the filter to be applied and jobs to reload (optimized from 2500-3500ms)
            await randomDelay(1500, 2000);
            
            // Verify filter was applied via URL
            if (isEasyApplyFilterActive()) {
                console.log('[AutoApply] Easy Apply filter enabled successfully (verified via URL)');
                return true;
            } else {
                console.log('[AutoApply] Filter clicked but URL not updated. Filter may still be active.');
                return true; // Assume it worked since we clicked the button
            }
        }

        console.warn('[AutoApply] Easy Apply filter button not found in toolbar');
        
        // Fallback: Try to set filter via URL
        console.log('[AutoApply] Attempting to enable filter via URL...');
        const url = new URL(window.location.href);
        url.searchParams.set('f_AL', 'true');
        window.location.href = url.toString();
        
        // This will cause a page reload, so we return true
        // The page will reload with the filter applied
        return true;
        
    } catch (error) {
        console.error('[AutoApply] Error enabling Easy Apply filter:', error);
        return false;
    }
};

export const logToStorage = async (message: string) => {
    const data = await chrome.storage.local.get(['autoApplyLogs']);
    const logs = data.autoApplyLogs || [];
    logs.push({ timestamp: new Date().toISOString(), message });
    // Keep only last 1000 logs
    if (logs.length > 1000) logs.shift();
    await chrome.storage.local.set({ autoApplyLogs: logs });
};
