import React from 'react';
import CrossIcon from '../../../assets/icons/cross.svg';
import type { CloseButtonProps } from '../types';

export const CloseButton: React.FC<CloseButtonProps> = ({ onClose }) => (
  <div
    onClick={onClose}
    className="h-[20px] w-[20px] min-h-[20px] min-w-[20px] p-[4px] border border-[#45475F] rounded-full flex items-center justify-center cursor-pointer"
  >
    <img src={CrossIcon} className="w-[12px] h-[12px]" alt="close" />
  </div>
); 