import { useState, useEffect, useMemo } from 'react';
import { WIDGET_CONSTANTS } from '../constants';
import { handlePost } from '../../../../core/Axios';

export const useContextCollection = () => {
  const [currentStep, setCurrentStep] = useState(1);
  const [isAnalyzing, setIsAnalyzing] = useState(true);
  
  const urlParams = useMemo(() => new URLSearchParams(window.location.search), []);
  
  const isContextCollection = useMemo(
    () => urlParams.get('action') === 'context-collection',
    [urlParams]
  );
  
  // Listen for context collection completion
  useEffect(() => {
    if (!isContextCollection) return;

    const storageListener = (changes: { [key: string]: chrome.storage.StorageChange }) => {
      if (changes.context_collection?.newValue === 'completed') {
        setIsAnalyzing(false);
      }
    };

    chrome.storage.onChanged.addListener(storageListener);
    return () => {
      chrome.storage.onChanged.removeListener(storageListener);
    };
  }, [isContextCollection]);
  
  useEffect(() => {
    const storageListener = async (changes: { [key: string]: chrome.storage.StorageChange }) => {
      if (changes.extensionUsedDaysCount?.newValue) {
        const menteeData = (await chrome.storage.local.get("menteeData")).menteeData;
        const payload = {
          body: {
            recordId: menteeData.recordId,
            extensionUsedDaysCount: changes.extensionUsedDaysCount.newValue,
          },
          params: {
            airtable_update: false,
          },
        };
        if (menteeData.recordId) {
          await handlePost("/candidates/profile", payload.body, payload.params);
        }
      }
    };

    chrome.storage.onChanged.addListener(storageListener);
    return () => {
      chrome.storage.onChanged.removeListener(storageListener);
    };
  }, []);

  // Handle step progression
  useEffect(() => {
    if (!isContextCollection || currentStep > WIDGET_CONSTANTS.TOTAL_STEPS) {
      return;
    }

    if (currentStep === 4 && isAnalyzing) {
      return;
    }

    const timer = setTimeout(() => {
      setCurrentStep(prev => prev + 1);

      if (currentStep === WIDGET_CONSTANTS.TOTAL_STEPS) {
        const currentUrl = window.location.href;
        const referrer = new URL(currentUrl).searchParams.get('referrer');
        
        chrome.runtime.sendMessage(
          {
            action: "switchToReferrerTab",
            referrer,
          },
          (response) => {
            if (chrome.runtime.lastError) {
              console.error("Error switching tabs:", chrome.runtime.lastError);
            }
          }
        );
      }
    }, WIDGET_CONSTANTS.STEP_DURATION);

    return () => clearTimeout(timer);
  }, [currentStep, isAnalyzing, isContextCollection]);

  return {
    isContextCollection,
    currentStep,
    isAnalyzing,
  };
}; 