import { mentoraiConfig } from "../configs/mentorai-listings";
import { sessionTypeConfig } from "../configs/session-type";
import { cleanYoutubeUrl } from "../content/utils/clean-youtube-url";
import { getYoutubeVideoLength, getYoutubeVideoPlayHead } from "../content/utils/get-youtube-video-length";

export const checkUrlListingStatus = (url: string, mentor_ai: string) => {
  const mentoraiConfigListing = mentoraiConfig[mentor_ai as keyof typeof mentoraiConfig];
  const blacklistedUrls = mentoraiConfigListing?.["blacklisted-urls"] || [];
  const whitelistedUrls = mentoraiConfigListing?.["whitelisted-urls"] || [];

  // Check if the URL is in the whitelisted or blacklisted URLs
  const isBlacklisted = blacklistedUrls.some((urlPattern) => {
    const regexPattern = new RegExp(
      "^https?:\\/\\/(www\\.)?" +
      urlPattern.replace(/https?:\/\//, "").replace(/\*/g, ".*") +
      "$"
    );
    return regexPattern.test(url);
  });

  const isWhitelisted = whitelistedUrls.some((urlPattern) => {
    const regexPattern = new RegExp(
      "^https?:\\/\\/(www\\.)?" +
      urlPattern.replace(/https?:\/\//, "").replace(/\*/g, ".*") +
      "$"
    );
    return regexPattern.test(url);
  });

  // Determine the status based on the checks
  if (isBlacklisted) {
    return 'blacklisted';
  } else if (isWhitelisted) {
    return 'whitelisted';
  } else {
    return 'normal'; // Not in either list
  }
};

export const extractSessionType = (url: string) => {
  const searchParams = new URLSearchParams(url);
  // Check if type=Session exists in search
  let sessionType = searchParams.get("session_type");

  // If not found, check for the query parameter in the hash (fragment)
  if (!sessionType && window.location.hash) {
    const hashParams = new URLSearchParams(window.location.hash.slice(1)); // Remove the leading #
    sessionType = hashParams.get("session_type");
  }

  // Check if URL matches any patterns in sessionTypeConfig
  for (const [type, urlPatterns] of Object.entries(sessionTypeConfig)) {
    if (urlPatterns.some(pattern => url.includes(pattern))) {
      sessionType = type;
      break;
    }
  }

  return sessionType;
};

export const detectAndFixStructure = (jsonString: string): string => {
  try {
    // Stack to keep track of open braces, brackets, and string status
    const stack: string[] = [];
    // Dictionary to map opening symbols to their corresponding closing symbols
    const symbolPairs: { [key: string]: string } = { "{": "}", "[": "]" };
    // Variable to track whether we are inside a string
    let inString: boolean = false;
    // Variable to track escaping within strings
    let escaping: boolean = false;

    for (const char of jsonString) {
      if (char === '"' && !escaping) {
        // Toggle inString status on unescaped quotes
        inString = !inString;
      } else if (char === "\\" && inString) {
        // Handle escaping status if inside a string
        escaping = true; // Mark as escaping
      } else if (escaping) {
        // If previously marked as escaping, unmark it (handles consecutive backslashes)
        escaping = false;
      }

      if (!inString) {
        // Process braces and brackets only if not inside a string
        if (Object.keys(symbolPairs).includes(char)) {
          // If it's an opening symbol, push to stack
          stack.push(char);
        } else if (Object.values(symbolPairs).includes(char)) {
          // If it's a closing symbol
          if (
            stack.length > 0 &&
            symbolPairs[stack[stack.length - 1]] === char
          ) {
            // If last open symbol matches the closing symbol
            stack.pop(); // Pop it as it's a valid pair
          }
        }
      }
    }

    // Close the unclosed string if any
    if (inString) {
      jsonString += '"';
    }

    // After processing all characters, add missing closing symbols for any unclosed structures
    while (stack.length > 0) {
      const closingSymbol =
        symbolPairs[stack.pop() as keyof typeof symbolPairs]; // Pop the last open symbol and append its closing symbol
      jsonString += closingSymbol;
    }

    return jsonString;
  } catch (e) {
    throw new Error(
      `An error occurred while trying to fix the JSON structure: ${e}`
    );
  }
};

export const allowSessionBanner = () => {
  const searchParams = new URLSearchParams(window.location.search);
  // Check if type=Session exists in search
  let isMentorAiSession = !!searchParams.get("session_id");

  // If not found, check for the query parameter in the hash (fragment)
  if (!isMentorAiSession && window.location.hash) {
    const hashParams = new URLSearchParams(window.location.hash.slice(1)); // Remove the leading #
    isMentorAiSession = !!hashParams.get("session_id");
  }

  return isMentorAiSession;
};

export const getChatMessagesFromStorage = async () => {
  try {
    const result = await chrome.storage.local.get(['chatMessages']);
    return result.chatMessages || [];
  } catch (error) {
    console.error('Error getting chat messages from storage:', error);
    return [];
  }
};


export const getTodaysMessageCount = async (): Promise<number> => {
  try {
    const messages = await getChatMessagesFromStorage();

    const today = new Date();
    const todayString = today.toDateString();

    const todayMessagesCount = messages.filter((message: any) => {
      if (message.sent_by === "user") {
        const sentTime = new Date(parseInt(message.createdAt || message.created_at));
        return sentTime.toDateString() === todayString;
      }
      return false;
    }).length;

    return todayMessagesCount;
  } catch (error) {
    console.error('Error getting today\'s message count:', error);
    return 0;
  }
};

export const calculateDailyMessagesLeft = async (dailyMessageLimit: number = 20) => {
  try {
    const messages = await getChatMessagesFromStorage();

    const todayOutgoingChatMessagesCount = messages.filter((message: any) => {
      if (message.sent_by === "user") {
        const sentTime = new Date(parseInt(message.createdAt || message.created_at));
        const today = new Date();

        if (sentTime.toDateString() === today.toDateString()) {
          return true;
        }
      }
      return false;
    }).length;

    return Math.max(dailyMessageLimit - todayOutgoingChatMessagesCount, 0);
  } catch (error) {
    console.error('Error calculating daily messages left:', error);
    return dailyMessageLimit;
  }
};

export const getTodaysDate = () => {
  return new Date().toISOString().split('T')[0];
};

export const getDateFromTimestamp = (timestamp: number) => {
  return new Date(timestamp).toISOString().split('T')[0];
};

export function getTitleSlug(url: string) {
  // Create a URL object to easily parse the URL
  try {
    const urlObj = new URL(url);
    // Split the pathname and filter the empty strings
    const parts = urlObj.pathname.split("/").filter(Boolean);

    // Find and return the title slug (second part after "/problems/")
    if (parts[0] === "problems" && parts[1]) {
      return parts[1];
    }
    return null; // Return null if not found
  } catch (error) {
    console.error("Invalid URL:", error);
    return null;
  }
}

export const resetStoredValues = (key: string, value: any) => {
  chrome.storage.local.set({
    [key]: value
  });
};

export const getNumberOfKeyTerms = (glossary: any) => {
  if (!glossary) {
    return 0;
  }
  // Count terms by finding all lines that match the pattern "### NUMBER. Term"
  const termRegex = /^###\s+\d+\.\s+.+$/gm;
  const matches = glossary?.match(termRegex) || [];
  return matches.length;
};

export const safelyIncrementExtensionUsedDaysCount = async (): Promise<number> => {
  try {
    const todaysDate = getTodaysDate();

    const result = await chrome.storage.local.get([
      "extensionUsedDaysCount",
      "lastMessageSentDate"
    ]);

    const currentCount = parseInt(result.extensionUsedDaysCount || "0");
    const lastMessageSentDate = result.lastMessageSentDate;

    if (isNaN(currentCount) || currentCount < 0) {
      console.warn(`Invalid extensionUsedDaysCount found: ${result.extensionUsedDaysCount}, resetting to 0`);
      await chrome.storage.local.set({
        extensionUsedDaysCount: "0",
        lastMessageSentDate: todaysDate
      });
      return 0;
    }

    if (lastMessageSentDate !== todaysDate) {
      const newCount = currentCount + 1;

      await chrome.storage.local.set({
        extensionUsedDaysCount: newCount.toString(),
        lastMessageSentDate: todaysDate
      });

      return newCount;
    } else {
      return currentCount;
    }
  } catch (error) {
    console.error('Error incrementing extensionUsedDaysCount:', error);
    const result = await chrome.storage.local.get("extensionUsedDaysCount");
    return parseInt(result.extensionUsedDaysCount || "0");
  }
};

export const getCurrentExtensionUsedDaysCount = async (): Promise<number> => {
  try {
    const result = await chrome.storage.local.get("extensionUsedDaysCount");
    const count = parseInt(result.extensionUsedDaysCount || "0");
    return isNaN(count) ? 0 : count;
  } catch (error) {
    console.error('Error getting extensionUsedDaysCount:', error);
    return 0;
  }
};

const getChannelPhotoUrl = () => {
  const channelElement: any = document.querySelector("#avatar");
  const channelPhotoUrl = channelElement?.children[0]?.src;
  return channelPhotoUrl || '';
}


export const getYoutubeChannelName = () => {
  const channelElement: any = document.querySelector("#channel-name");
  const channelName = channelElement?.innerText || '';
  return channelName || '';
}


export const getVideoProperties = () => {
  return {
    url: cleanYoutubeUrl(window.location.href),
    title: document.title,
    duration: Math.floor(getYoutubeVideoLength()),
    current_duration: Math.floor(getYoutubeVideoPlayHead()),
    channel: getYoutubeChannelName(),
    channelPhotoUrl: getChannelPhotoUrl(),
  }
}

export function safeParse(data: any) {
  try {
    return JSON.parse(data);
  } catch (e) {
    return data;
  }
}

export const removeActionQueryParamFromUrl = () => {
  try {
    const currentUrl = new URL(window.location.href);
    if (currentUrl.searchParams.has("action")) {
      currentUrl.searchParams.delete("action");
    }
    if (currentUrl.hash) {
      const hashParams = new URLSearchParams(currentUrl.hash.slice(1));
      if (hashParams.has("action")) {
        hashParams.delete("action");
        const newHash = hashParams.toString();
        currentUrl.hash = newHash ? `#${newHash}` : "";
      }
    }
    history.replaceState(null, "", currentUrl.toString());
    window.dispatchEvent(new Event("mentorai-url-changed"));
  } catch (e) { }
};