const parseMultipleJsonChunks = (chunk: string): any[] => {
  const jsonObjects: any[] = [];
  
  // Split by "}{"  pattern to handle concatenated JSON objects
  const parts = chunk.split(/(?<=})\s*(?={)/);
  
  for (const part of parts) {
    try {
      const parsedObject = JSON.parse(part);
      jsonObjects.push(parsedObject);
    } catch (parseError) {
      // If parsing fails, try to clean up the part and parse again
      let cleanedPart = part.trim();
      
      // Add missing opening brace if needed
      if (!cleanedPart.startsWith('{') && cleanedPart.includes('"sections"')) {
        cleanedPart = '{' + cleanedPart;
      }
      
      // Add missing closing brace if needed
      if (!cleanedPart.endsWith('}') && cleanedPart.includes('"sections"')) {
        cleanedPart = cleanedPart + '}';
      }
      
      try {
        const parsedObject = JSON.parse(cleanedPart);
        jsonObjects.push(parsedObject);
      } catch (secondParseError) {
        console.warn("Failed to parse JSON part:", cleanedPart, secondParseError);
      }
    }
  }
  
  return jsonObjects;
};

export const fetchSectionsStreaming = async (url: string, onSectionUpdate: (sections: any[]) => Promise<void>) => {
  try {
    const response = await handleAibackendStreamingPost(
      '/resources/generate_sections',
      { url, stream: true },
      false
    );

    if (!response.body) {
      throw new Error("No response body received for sections generation");
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let entireChunk = "";

    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        // console.log("Custom-ui-context: entireChunk", entireChunk);

        const jsonObjects = parseMultipleJsonChunks(entireChunk);
        // console.log("Custom-ui-context: jsonObjects", jsonObjects);
        // Find the latest sections data from all parsed objects
        let latestSections: any[] | null = null;
        
        for (const parsedChunk of jsonObjects) {
          if (parsedChunk.sections && Array.isArray(parsedChunk.sections)) {    
            latestSections = parsedChunk.sections;
          }
        }
        // If we found valid sections, call the callback with the latest data
        if (latestSections) {   
          // console.log("Custom-ui-context: latestSections", latestSections);
          await onSectionUpdate(latestSections);
        } else {
          console.log("Custom-ui-context: condition failed - sections not found or not array");
        }
        break;
      };

      const chunk = decoder.decode(value, { stream: true });
      entireChunk += chunk;
      try {
        // console.log("Custom-ui-context: chunk", chunk);
        // Handle multiple JSON objects in a single chunk
        const jsonObjects = parseMultipleJsonChunks(chunk);
        // console.log("Custom-ui-context: jsonObjects", jsonObjects);
        // Find the latest sections data from all parsed objects
        let latestSections: any[] | null = null;
        
        for (const parsedChunk of jsonObjects) {
          if (parsedChunk.sections && Array.isArray(parsedChunk.sections)) {
            latestSections = parsedChunk.sections;
          }
        }
        
        // If we found valid sections, call the callback with the latest data
        if (latestSections) {
          // console.log("Custom-ui-context: latestSections", latestSections);
          await onSectionUpdate(latestSections);
        } else {
          console.log("Custom-ui-context: condition failed - sections not found or not array");
        }
        
      } catch (parseError) {
        console.warn("Failed to parse chunk:", chunk, parseError);
        // Continue processing other chunks even if one fails to parse
      }
    }
  } catch (error) {
    console.error("Error in fetchSectionsStreaming:", error);
    throw error;
  }
};


export const fetchStreamingSectionsMetadata = async (body: any, onSectionUpdate: (sections: any[]) => Promise<void>) => {
    try {
        const response = await handleAibackendStreamingPost(
          '/resources/generate_sections_metadata',
          { ...body, stream: true },
          false
        );
    
        if (!response.body) {
          throw new Error("No response body received for sections generation");
        }
    
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
    
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
    
          const chunk = decoder.decode(value, { stream: true });
          
          try {
            // Handle multiple JSON objects in a single chunk
            const jsonObjects = parseMultipleJsonChunks(chunk);
            
            // Find the latest sections data from all parsed objects
            let latestSections: any[] | null = null;
            
            for (const parsedChunk of jsonObjects) {
              if (parsedChunk.sections && Array.isArray(parsedChunk.sections)) {
                latestSections = parsedChunk.sections;
              }
            }
            
            // If we found valid sections, call the callback with the latest data
            if (latestSections) {
              await onSectionUpdate(latestSections);
            } else {
              console.log("Custom-ui-context: metadata condition failed - sections not found or not array");
            }
          } catch (parseError) {
            console.warn("Failed to parse chunk:", chunk, parseError);
            // Continue processing other chunks even if one fails to parse
          }
        }
    } catch (error) {
    console.error("Error in fetchSectionsStreaming:", error);
    throw error;
    }
};

