export function mergeSectionsAndQuizzes(sections: any, quizzes: any) {
    const secs = sections.map((sec: any) => ({
        ...sec,
        _start: timeToSeconds(sec.startTime),
        _end: timeToSeconds(sec.endTime),
        quizzes: []
    }));

    quizzes.forEach((quizBlock: any) => {
        const t = timeToSeconds(quizBlock.timestamp);
        const target = secs.find((sec: any) => t >= sec._start && t < sec._end);
        if (target) {
            target.quizzes.push(quizBlock);
        }
    });

    let result = secs.map(({ _start, _end, ...rest }: any) => rest);
    // console.log("result", result);
    return result;
}