import { useState, useEffect, useRef } from 'react'
import { createPortal } from 'react-dom'
import { motion, AnimatePresence } from 'framer-motion'
import { hasValidArticleContent } from '../../../utils/article-content-validator'
import Button from '../../../src/components/common/common-button'
import LeecoAvatar from '../../../src/assets/leeco_profile.webp'
import { LoaderWithThreeDots } from '../../../common/loader/loader'

const BlogLearningHeader = ({ isVisible, handleLeaningCTAClick, sessionState }: {
    isVisible: boolean,
    handleLeaningCTAClick: () => void,
    sessionState: any
}) => {
    const [showBanner, setShowBanner] = useState(false)
    const hasValidArticle = hasValidArticleContent()
    const containerRef = useRef<HTMLDivElement | null>(null)

    useEffect(() => {
        if (isVisible && hasValidArticle) {
            const container = document.createElement('div')
            container.id = 'blog-learning-header-container'
            container.className = 'preplaced-extension'
            container.style.position = 'sticky'
            container.style.top = '12px'
            container.style.marginBottom = '12px'
            container.style.zIndex = '9999'
            container.style.pointerEvents = 'none'

            const style = document.createElement('style')
            container.appendChild(style)

            document.body.insertBefore(container, document.body.firstChild)
            containerRef.current = container

            return () => {
                if (containerRef.current && containerRef.current.parentNode) {
                    containerRef.current.parentNode.removeChild(containerRef.current)
                }
            }
        }
    }, [isVisible, hasValidArticle])

    useEffect(() => {
        if (isVisible) {
            setShowBanner(false)

            const bannerTimer = setTimeout(() => setShowBanner(true), 1000)

            return () => {
                clearTimeout(bannerTimer)
            }
        } else {
            setShowBanner(false)
        }
    }, [isVisible])

    useEffect(() => {
        return () => {
            setShowBanner(false)
        }
    }, [])

    const handleHideBanner = () => {
        setShowBanner(false)
        chrome.runtime.sendMessage({
            action: "sendAnalytics",
            url: window.location.href,
            eventName: "Button Clicked",
            eventProperties: {
                button_name: "Banner Dismissed",
            }
        });
    }

    if (!isVisible || !hasValidArticle || !containerRef.current) {
        return null
    }


    const bannerContent = (
        <AnimatePresence>
            {showBanner && (
                <motion.div
                    className="mx-7 w-[calc(100%-56px)] flex justify-between items-center py-2.5 px-3 rounded-[62px]"
                    style={{
                        pointerEvents: 'auto',
                        margin: '0px 28px',
                        zIndex: 9999,
                        width: 'calc(100% - 56px)',
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        padding: '10px 12px',
                        backgroundColor: 'rgba(81,73,242,1)',
                        borderRadius: '62px'
                    }}
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    transition={{
                        duration: 0.4,
                        ease: "easeOut",
                        type: "tween"
                    }}
                >

                    <Button className='h-[22px] w-[22px]' onClick={handleHideBanner}>
                        <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 22 22" fill="none">
                            <path d="M11 9.83345L15.0837 5.74969L16.2503 6.91624L12.1665 11L16.2503 15.0837L15.0837 16.2503L11 12.1665L6.91624 16.2503L5.74969 15.0837L9.83345 11L5.74969 6.91624L6.91624 5.74969L11 9.83345Z" fill="white" />
                        </svg>
                    </Button>
                    <div
                        className="flex items-center gap-3 whitespace-nowrap"
                        style={{ display: 'flex', alignItems: 'center', gap: '12px', whiteSpace: 'nowrap' }}
                    >
                        <img
                            src={LeecoAvatar}
                            className='w-[24px] h-[24px] rounded-full max-w-[24px] max-h-[24px]'
                            style={{ width: '24px', height: '24px', borderRadius: '50%', maxWidth: '24px', maxHeight: '24px' }}
                        />
                        <span
                            className='text-xs font-medium leading-4 tracking-[-0.06px] text-white'
                            style={{
                                fontSize: '12px',
                                fontWeight: '500',
                                lineHeight: '16px',
                                letterSpacing: '-0.06px',
                                color: 'white'
                            }}
                        >
                            {sessionState?.sessionData ?
                                'Great learning so far! Continue learning faster & smarter with Leeco.'
                                : 'Read smarter with Leeco for interactive highlights, quizzes, and active recall — so you retain this blog forever.'}
                        </span>
                    </div>

                    <Button
                        onClick={() => {
                            chrome.runtime.sendMessage({
                                action: "sendAnalytics",
                                url: window.location.href,
                                eventName: "Button Clicked",
                                eventProperties: {
                                    button_name: sessionState?.sessionData ? 'Continue Learning' : 'Start Learning',
                                    location: "Banner"
                                }
                            });
                            handleLeaningCTAClick();
                        }}
                        disabled={sessionState?.isLoading || sessionState?.ctaLoading}
                        className={`whitespace-nowrap w-fit h-[20px] py-[3px] px-[8px] rounded-[100px] font-semibold text-xs tracking-[-0.12px] flex items-center disabled:opacity-50 text-[#181B25] bg-[#FFF] hover:bg-[#0E121B] hover:text-[#FFF]`}
                    >
                        {sessionState?.ctaLoading ? <LoaderWithThreeDots color='#000'/> : sessionState?.sessionData ? 'Continue Learning' : 'Start Learning'}
                    </Button>
                </motion.div>
            )}
        </AnimatePresence>
    )

    return createPortal(bannerContent, containerRef.current)
}

export default BlogLearningHeader