import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback, useRef } from 'react';
import { getBrowserInfo } from '../../../core/Analytics';

export type MicrophonePermissionStatus = 'granted' | 'denied' | 'prompt' | 'not-supported';

interface ContentSyncContextType {
  permissionStatus: MicrophonePermissionStatus;
  checkPermission: () => Promise<void>;
  requestPermission: () => Promise<void>;
  isAudioLive: boolean;
  setIsAudioLive: (isAudioLive: boolean) => void;
  handleAudioLive: ({ isLive }: { isLive: boolean }) => void;
  transcription: string;
  setTranscription: (transcription: string) => void;
  widgetState: WidgetState;
  setWidgetState: (widgetState: WidgetState) => void;
  audioStream: MediaStream | null;
  volume: number;
  initializeAudioStream: () => Promise<void>;
  cleanupAudioStream: () => void;
}

const ContentSyncContext = createContext<ContentSyncContextType | undefined>(undefined);

type WidgetState = "HIDE" | "MICROPHONE_PREMISSION" | "MICROPHONE_PREMISSION_ERROR" | "SHOW" | "LISTENING";

export const ContentSyncProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [permissionStatus, setPermissionStatus] = useState<MicrophonePermissionStatus>('prompt');
  const [isAudioLive, setIsAudioLive] = useState(false);
  const [transcription, setTranscription] = useState<string>('');
  const [widgetState, setWidgetState] = useState<WidgetState>("HIDE");
  const [audioStream, setAudioStream] = useState<MediaStream | null>(null);
  const [browserInfo, setBrowserInfo] = useState<any>(null);
  const [volume, setVolume] = useState(0);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const dataArrayRef = useRef<Uint8Array | null>(null);
  const animationFrameRef = useRef<number>();
  const volumeArrayRef = useRef<number[]>([]);
  const lastNotifyTimeRef = useRef<number>(0);

  // Function to notify sidepanel of state changes with throttling
  const notifySidepanel = useCallback(() => {
    const now = Date.now();
    const throttleDelay = 100; // 100ms throttle

    if (now - lastNotifyTimeRef.current >= throttleDelay) {
      chrome.runtime.sendMessage({
        type: 'syncStatesToSidepanel',
        permissionStatus,
        isAudioLive,
        transcription,
        widgetState,
        volume,
        browserInfo
      });
      lastNotifyTimeRef.current = now;
    }
  }, [permissionStatus, isAudioLive, transcription, widgetState, volume, browserInfo]);

  const checkPermission = async () => {
    try {
      // Check if the browser supports the MediaDevices API
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        setPermissionStatus('not-supported');
        return;
      }

      // Check if we already have permission
      const result = await navigator.permissions.query({ name: 'microphone' as PermissionName });
      setPermissionStatus(result.state as MicrophonePermissionStatus);
    } catch (error) {
      console.error('Error checking microphone permission:', error);
      setPermissionStatus('prompt');
    }
  };

  const initializeAudioStream = async () => {
    try {
      cleanupAudioStream();
      
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      
      // Create audio context and analyzer
      const audioContext = new AudioContext();
      const source = audioContext.createMediaStreamSource(stream);
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 256;
      source.connect(analyser);
      
      // Initialize analyzer refs
      analyserRef.current = analyser;
      dataArrayRef.current = new Uint8Array(analyser.frequencyBinCount);
      
      setAudioStream(stream);
      setPermissionStatus('granted');
      
      // Start volume monitoring
      startVolumeMonitoring();
    } catch (error) {
      console.error('Error initializing audio stream:', error);
      setPermissionStatus('denied');
      setAudioStream(null);
    }
  };

  const startVolumeMonitoring = () => {
    if (!analyserRef.current || !dataArrayRef.current) return;

    const updateVolume = () => {
      analyserRef.current!.getByteFrequencyData(dataArrayRef.current!);
      
      // Calculate average level like the reference implementation
      const level = dataArrayRef.current!.reduce((acc, val) => acc + val, 0) / 
                   dataArrayRef.current!.length;
      
      setVolume(level / 256); // Normalize to 0-1
      
      animationFrameRef.current = requestAnimationFrame(updateVolume);
    };

    updateVolume();
  };

  const cleanupAudioStream = () => {
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
    if (audioStream) {
      audioStream.getTracks().forEach(track => track.stop());
      setAudioStream(null);
    }
    analyserRef.current = null;
    dataArrayRef.current = null;
    volumeArrayRef.current = []; // Clear the volume array
    setVolume(0);
  };

  const requestPermission = async () => {
    try {
      await initializeAudioStream();
    } catch (error) {
      console.error('Error requesting microphone permission:', error);
      setPermissionStatus('denied');
    }
  };

  const handleAudioLive = ({ isLive }: { isLive: boolean }) => {
    setIsAudioLive(isLive);
  }

  // Listen for state requests from sidepanel
  useEffect(() => {
    const handleMessage = (message: any) => {
      if (message.type === 'getMicrophoneState') {
        notifySidepanel();
      }
      if (message.type === 'syncStatesToContext') {
        // setIsAudioLive(message.isAudioLive);
        // setTranscription(message.transcription);
        // setWidgetState(message.widgetState);
      }
      // Add handler for initial state request
      if (message.type === 'getInitialStates') {
        chrome.runtime.sendMessage({
          type: 'initialStates',
          permissionStatus,
          isAudioLive,
          transcription,
          widgetState,
          browserInfo,
          volume
        });
      }
    };

    chrome.runtime.onMessage.addListener(handleMessage);

    return () => {
      chrome.runtime.onMessage.removeListener(handleMessage);
    };
  }, [permissionStatus, isAudioLive, transcription, widgetState, browserInfo]);

  // Notify sidepanel whenever state changes
  // useEffect(() => {
  //   notifySidepanel();
  // }, [permissionStatus, isAudioLive, transcription, widgetState, browserInfo]);

  // // Add permission change listener in a separate effect
  // useEffect(() => {
  //   let permissionObserver: PermissionStatus | null = null;

  //   const setupPermissionListener = async () => {
  //     try {
  //       const result = await navigator.permissions.query({ name: 'microphone' as PermissionName });
  //       permissionObserver = result;
        
  //       const handlePermissionChange = () => {
  //         setPermissionStatus(result.state as MicrophonePermissionStatus);
  //       };

  //       result.addEventListener('change', handlePermissionChange);
  //       return () => {
  //         result.removeEventListener('change', handlePermissionChange);
  //       };
  //     } catch (error) {
  //       console.error('Error setting up permission listener:', error);
  //     }
  //   };

  //   setupPermissionListener();

  //   return () => {
  //     if (permissionObserver) {
  //       // Cleanup will be handled by the inner function's return
  //       permissionObserver = null;
  //     }
  //   };
  // }, []);

  // useEffect(() => {
  //   checkPermission();
  //   setBrowserInfo(getBrowserInfo());
  // }, []);
  

  // useEffect(() => {
  //   if (isAudioLive) {
  //     initializeAudioStream();
  //   }else{
  //     cleanupAudioStream();
  //   }
  // }, [isAudioLive]);

  // Cleanup on unmount
  // useEffect(() => {
  //   return () => {
  //     cleanupAudioStream();
  //   };
  // }, []);

  // const handleStorageChange = useCallback((changes: { [key: string]: chrome.storage.StorageChange }) => {
  //   if (changes.is_side_panel_opened) {
  //       const newValue = changes.is_side_panel_opened.newValue;
  //       if (!newValue && widgetState !== "SHOW") {
  //         cleanupAudioStream();
  //         setTranscription('');
  //       }
  //   }
  // }, [widgetState]);

  // useEffect(() => {
  //   chrome.storage.onChanged.addListener(handleStorageChange);
  //   return () => {
  //     chrome.storage.onChanged.removeListener(handleStorageChange);
  //   };
  // }, [handleStorageChange]);


  return (
    <ContentSyncContext.Provider
      value={{
        permissionStatus,
        checkPermission,
        requestPermission,
        isAudioLive,
        setIsAudioLive,
        handleAudioLive,
        transcription,
        setTranscription,
        widgetState,
        setWidgetState,
        audioStream,
        volume,
        initializeAudioStream,
        cleanupAudioStream,
      }}
    >
      {children}
    </ContentSyncContext.Provider>
  );
};

export const useContentSyncContext = () => {
  const context = useContext(ContentSyncContext);
  if (context === undefined) {
    throw new Error('useContentSyncContext must be used within a ContentSyncContextProvider');
  }
  return context;
}; 