import { useState, useEffect } from "react"
import Modal from "../../../common/modal/modal"
import rehypeRaw from "rehype-raw"
import remarkGfm from "remark-gfm"
import ReactMarkdown from "react-markdown"
import CloseIcon from "../../assets/icons/close-icon.svg"
import CloseIconHovered from "../../assets/icons/close-icon-hovered.svg"
import Button from "../../../src/components/common/common-button"

type Props = {
  show: boolean
  handleClose: () => void
  generatedFeedback: string
}

const InterviewFeedbackModal = ({ show, handleClose, generatedFeedback }: Props) => {

  if(generatedFeedback === ""){
    return null
  }

  return (
  <Modal
    open={show}
    handleCloseOutside={handleClose}
    className={{
      container: "rounded-xl",
      overlay:
        "!bg-[rgba(20,22,31,0.60)] !rounded-tl-[6px] !rounded-bl-[6px]",
    }}
  >
    <div className="shadow-[inset_0px_0px_48px_0px_rgba(115,109,249,0.20)] flex items-center justify-center flex-col p-[16px] max-h-[80vh] max-w-[80vw] rounded-xl relative border border-[#363645] bg-mentorai-bg-base overflow-hidden">
        <Button className="!cursor-pointer absolute transition-all duration-100 group"
          style={{
              top: "4px",
              right: "4px"
          }}
          onClick={() => handleClose()}>
          <img src={CloseIcon} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] flex group-hover:hidden" />
          <img src={CloseIconHovered} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] hidden group-hover:flex" />
        </Button>
        <div className="flex items-center justify-center flex-col p-[16px] h-full w-full gap-8 overflow-y-auto">
          <h1 className="text-mentorai-primary-lighter text-[24px] leading-[32px] tracking-[0.12px] font-semibold text-center">Interview Report</h1>
          <ReactMarkdown
            rehypePlugins={[rehypeRaw]}
            remarkPlugins={[remarkGfm]}
            className={
              `prose markdown-prose !text-[14px]/[22px] !tracking-[0.14px] max-w-full overflow-auto`
            }
          >
            {generatedFeedback}
          </ReactMarkdown>
        </div>
    </div>
    </Modal>
  )
}

export default InterviewFeedbackModal