import { FC, useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useCustomUI } from "../../../contexts/custom-ui-context/custom-ui-context";
import MentorAiButton from "../../../../common/button/mentorai-button";
import VerifiedIcon from "../../../assets/icons/verified-icon.svg";
import HourglassIcon from "../../../assets/icons/hourglass-icon.svg";
import WhiteCheckIcon from "../../../assets/icons/white-check.svg";
import { SectionTimelineCard } from "../sections-timeline/sections-timeline";
import { timeToSeconds } from "../../../../src/utils/str-time-to-seconds";

const SessionEndOverlay: FC = () => {
  const {
    learningSession,
    mentoraiData,
    menteeData,
    setSessionOverlayView,
    markSectionComplete,
    setIsSessionCompleted,
    sessionOverlayView,
    sectionEndScreen,
    selectSection,
    playerMode,
    trackCustomUIEvent,
    getSectionProperties,
  } = useCustomUI();
  const [feedbackGiven, setFeedbackGiven] = useState(false);

  if (!learningSession) {
    return null;
  }

  const isPlayerModeDefault = playerMode === "DEFAULT";
  // Calculate session statistics
  const totalSections = learningSession.sections.length;
  const completedSections = learningSession.sections.filter(section => section.status === 'completed').length;
  const sectionCompletionPercentage = Math.round((completedSections / totalSections) * 100);
  const incompleteSections = learningSession.sections.filter(section => section.status !== 'completed');
  const remainingSectionsCount = incompleteSections.length;

  // Check if all sections are complete
  const allSectionsComplete = completedSections === totalSections;

  // Calculate quiz statistics
  const totalQuizzes = learningSession.sections.reduce((total, section) => {
    return total + (section.quizzes?.length || 0);
  }, 0);

  // Calculate quiz accuracy
  let completedQuizzes = 0;
  let correctQuizzes = 0;
  learningSession.sections.forEach(section => {
    // Each section has a quizzes array, and each quiz has quizQuestions array
    section.quizzes?.forEach(quiz => {
      quiz.quizQuestions?.forEach(question => {
        if (question.userAnswer !== undefined && question.userAnswer !== null) {
          completedQuizzes++;
          if (question.userAnswer === question.answer) {
            correctQuizzes++;
          }
        }
      });
    });
  });

  const quizAccuracy = completedQuizzes === 0 ? 0 : Math.round((correctQuizzes / completedQuizzes) * 100);

  const userName = menteeData?.name?.split(" ")[0] || "there";


  useEffect(() => {
    if (allSectionsComplete) {
      setIsSessionCompleted(true);
    }
  }, [allSectionsComplete]);



  const isClickable = (learningSession?.sessionStatus === 'ongoing' || learningSession?.sessionStatus === 'completed') && !(sessionOverlayView === 'section_end' && (sectionEndScreen === 'explore_quiz' || sectionEndScreen === 'quiz'))
  const handleSectionClick = (index: number) => {
    if (isClickable) {
      selectSection(index);
      trackCustomUIEvent("MentorAi Section Clicked", {
        from:"Session End Screen",
        section: getSectionProperties(index),
      });
      if (sessionOverlayView === 'created' || sessionOverlayView === 'session_end' || sessionOverlayView === 'section_end') {
        setSessionOverlayView('section_start');
      }
    }
  }


  const handleMarkSectionComplete = (sectionIndex: number) => {
    // Use the context function to mark the section as complete
    markSectionComplete(sectionIndex);
    trackCustomUIEvent("MentorAi Section Marked Complete", {
      from:"Session End Screen",
      section: getSectionProperties(sectionIndex),
    });
  };



  const handleHelpfulClick = () => {
    trackCustomUIEvent("MentorAi Session Feedback Submitted", {
      feedback : {
        helpfulness : "Helpful"
      }
    });
    setFeedbackGiven(true);
  }

  const handleNotHelpfulClick = () => {
    trackCustomUIEvent("MentorAi Session Feedback Submitted", {
      feedback : {
        helpfulness : "Not Helpful"
      }
    });
    setFeedbackGiven(true);
  }
  

  // Render complete session view
  const renderCompleteSessionView = () => (
    <div className="flex flex-col items-center justify-center w-full" style={{ padding: "16px 0px", gap: "12px" }}>
      <div className="flex flex-col items-center justify-center w-full" style={{ gap: "8px" }}>
        <div style={{ width: "100px", height: "100px" }}>
          <img src={VerifiedIcon} alt="Session Complete" className="w-full h-full" />
        </div>

        {/* Title and Progress */}
        <div className="flex flex-col items-center justify-center w-full" style={{ gap: "12px" }}>
          <h1 className="text-center"
            style={{
              fontWeight: 700,
              fontSize: "36px",
              lineHeight: "46px",
              color: "#DDDDDF"
            }}
          >
            We've finished this session
          </h1>

          <p
            className="text-center"
            style={{
              fontWeight: 600,
              fontSize: "20px",
              lineHeight: "30px",
              letterSpacing: "-2%",
              color: "#94939F",
              marginTop: "-4px"
            }}
          >
            Good job, {userName}!
          </p>
        </div>
      </div>

      <StatisticsCard
        totalSections={totalSections}
        sectionCompletionPercentage={sectionCompletionPercentage}
        totalQuizzes={totalQuizzes}
        totalQuizzesCompleted={completedQuizzes}
        quizAccuracy={quizAccuracy}
      />


      <div className="flex flex-col items-center" style={{ marginTop: "64px", gap: "12px" }}>
        <p className="self-stretch text-[#94939f] text-center" style={{ fontSize: "16px", lineHeight: "26px", letterSpacing: "0.6%" }}>{!feedbackGiven ? "Was this session helpful?" : "Thank you for your feedback!"}</p>
        {!feedbackGiven && <div className="flex items-center self-stretch" style={{ gap: "8px" }}>

          <MentorAiButton
            type="secondary"
            size="medium"
            onClick={handleHelpfulClick}
            style={{ paddingRight: "12px", paddingLeft: "12px", height: "32px", gap: "4px" }}
            classNames=" !w-fit whitespace-nowrap"
          >
            <svg width={16} height={16} viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M2.00039 6.20007H3.80039V13.4001H2.00039C1.84126 13.4001 1.68865 13.3369 1.57613 13.2243C1.4636 13.1118 1.40039 12.9592 1.40039 12.8001V6.80007C1.40039 6.64094 1.4636 6.48833 1.57613 6.3758C1.68865 6.26328 1.84126 6.20007 2.00039 6.20007ZM5.17619 5.42427L9.01619 1.58427C9.06723 1.53308 9.13503 1.50205 9.20712 1.49687C9.27922 1.49168 9.35076 1.51271 9.40859 1.55607L9.92039 1.94007C10.0625 2.04677 10.1699 2.19318 10.2289 2.36082C10.288 2.52846 10.2961 2.70983 10.2522 2.88207L9.56039 5.60007H13.4004C13.7187 5.60007 14.0239 5.7265 14.2489 5.95154C14.474 6.17658 14.6004 6.48181 14.6004 6.80007V8.06247C14.6006 8.21928 14.57 8.37461 14.5104 8.51967L12.6534 13.0287C12.6081 13.1386 12.5312 13.2326 12.4323 13.2987C12.3335 13.3648 12.2173 13.4001 12.0984 13.4001H5.60039C5.44126 13.4001 5.28865 13.3369 5.17613 13.2243C5.06361 13.1118 5.00039 12.9592 5.00039 12.8001V5.84847C5.00043 5.68935 5.06366 5.53676 5.17619 5.42427Z" fill="#DDDDDF" />
            </svg>
            <p className="text-[#dddddf]" style={{ fontSize: "14px", lineHeight: "22px", letterSpacing: "0.084px" }}>It was Helpful</p>
          </MentorAiButton>

          <MentorAiButton
            type="secondary"
            size="medium"
            onClick={handleNotHelpfulClick}
            style={{ paddingRight: "12px", paddingLeft: "12px", height: "32px", gap: '4px' }}
            classNames=" !w-fit whitespace-nowrap"
          >
            <svg width={16} height={16} viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M1.99961 9.79961L3.79961 9.79961L3.79961 2.59961L1.99961 2.59961C1.84048 2.59961 1.68787 2.66282 1.57534 2.77534C1.46282 2.88787 1.39961 3.04048 1.39961 3.19961L1.39961 9.19961C1.39961 9.35874 1.46282 9.51135 1.57534 9.62387C1.68786 9.73639 1.84048 9.79961 1.99961 9.79961ZM5.17541 10.5754L9.01541 14.4154C9.06644 14.4666 9.13424 14.4976 9.20634 14.5028C9.27843 14.508 9.34998 14.487 9.40781 14.4436L9.91961 14.0596C10.0617 13.9529 10.1691 13.8065 10.2282 13.6389C10.2872 13.4712 10.2953 13.2898 10.2514 13.1176L9.55961 10.3996L13.3996 10.3996C13.7179 10.3996 14.0231 10.2732 14.2481 10.0481C14.4732 9.82309 14.5996 9.51787 14.5996 9.19961L14.5996 7.93721C14.5998 7.78039 14.5692 7.62506 14.5096 7.48001L12.652 2.97161C12.6068 2.86166 12.53 2.76761 12.4313 2.70138C12.3326 2.63515 12.2165 2.59973 12.0976 2.59961L5.59961 2.59961C5.44048 2.59961 5.28787 2.66282 5.17534 2.77534C5.06282 2.88787 4.99961 3.04048 4.99961 3.19961L4.99961 10.1512C4.99964 10.3103 5.06288 10.4629 5.17541 10.5754Z" fill="#DDDDDF" />
            </svg>
            <p className="text-[#dddddf]" style={{ fontSize: "14px", lineHeight: "22px", letterSpacing: "0.084px" }}>It was not Helpful</p>
          </MentorAiButton>

        </div>}
      </div>

    </div>
  );

  // Render incomplete session view
  const renderIncompleteSessionView = () => (
    <div className="flex flex-col items-center justify-center w-full" style={{ padding: "16px 0px", gap: "12px" }}>
      <div className="flex flex-col items-center justify-center w-full" style={{ gap: "8px" }}>
        <div style={{ width: "100px", height: "100px" }}>
          <img src={HourglassIcon} alt="Session Incomplete" className="w-full h-full" />
        </div>

        {/* Title and Progress */}
        <div className="flex flex-col items-center justify-center w-full" style={{ gap: "12px" }}>
          <h1 className="text-center"
            style={{
              fontWeight: 700,
              fontSize: "36px",
              lineHeight: "46px",
              color: "#DDDDDF"
            }}
          >
            You've reached the end
          </h1>

          {/* Progress Bar Section */}
          <div className="flex flex-col items-center justify-center" style={{ gap: "12px" }}>
            {/* Progress Bar */}
            <div className="w-full flex flex-col" style={{ gap: "-8px", width: "390px", maxWidth: "90%" }}>
              {/* Background Bar */}
              <div
                className="w-full rounded-full"
                style={{
                  height: "8px",
                  backgroundColor: "rgba(29, 175, 97, 0.3)"
                }}
              />
              {/* Progress Bar */}
              <div
                className="rounded-[100px]"
                style={{
                  height: "8px",
                  width: `${sectionCompletionPercentage}%`,
                  backgroundColor: "#3EE089",
                  marginTop: "-8px"
                }}
              />
            </div>

            {/* Progress Text */}
            <p
              className="text-center"
              style={{
                fontWeight: 600,
                fontSize: "16px",
                lineHeight: "26px",
                letterSpacing: "0.6%",
                color: "#3EE089"
              }}
            >
              Our session is {sectionCompletionPercentage}% complete
            </p>
          </div>

          <p
            className="text-center"
            style={{
              fontWeight: 500,
              marginTop: "32px",
              fontSize: "16px",
              lineHeight: "1.625em",
              letterSpacing: "0.6%",
              color: "#DDDDDF"
            }}
          >
            {remainingSectionsCount} more sections to go
          </p>
        </div>
      </div>


      {/* Remaining Sections */}
      <div
        className="flex overflow-x-auto w-full scrollbar-hide max-w-[calc(100vw-700px)]"
        style={{ gap: "12px" }}
      >
        <AnimatePresence mode="popLayout">
        {learningSession?.sections.map((section, index) => {
          if(section.status === 'completed') return null;
          return (
            <motion.div 
              key={`section-${index}-${section?.sectionTitle}`}
              className="flex flex-col justify-center" 
              style={{ gap: "12px" }}
              initial={{ opacity: 1, y: 0 }}
              exit={{ 
                opacity: 0, 
                y: -40,
                transition: { 
                  duration: 0.4, 
                  ease: "easeOut"
                }
              }}
              layout
            >
              <SectionTimelineCard
                item={section}
                index={index}
                isSelected={false}
                isNewlyStreamed={false}
                isCompleted={false}
                isClickable={true}
                isRenderedInSessionEnd={true}
                handleSectionClick={handleSectionClick}
              />
              <MentorAiButton
                type="secondary"
                size="medium"
                onClick={() => handleMarkSectionComplete(index)}
                style={{ paddingRight: "12px", paddingLeft: "8px", height: "28px",  }}
                classNames=" w-full"
              >
                <span className="flex flex-row items-center" style={{ gap: '4px', fontSize: "14px", fontWeight: 500, lineHeight: "22px", letterSpacing: "0.084px", color: "#DDDDDF" }}>
                  <img src={WhiteCheckIcon} alt="check" style={{ width: 18, height: 18 }} />
                  Mark Complete
                </span>
              </MentorAiButton>
            </motion.div>
          );
        })}
        </AnimatePresence>
      </div>
    </div>
  );

  // Return the appropriate view based on completion status
  return allSectionsComplete ? renderCompleteSessionView() : renderIncompleteSessionView();
};

export default SessionEndOverlay;


const StatisticsCard: FC<{
  totalSections: number,
  sectionCompletionPercentage: number,
  totalQuizzes: number,
  totalQuizzesCompleted: number,
  quizAccuracy: number
}> = ({ totalSections, sectionCompletionPercentage, totalQuizzes, totalQuizzesCompleted, quizAccuracy }) => {
  return (
    <div className="flex w-full justify-center" style={{ gap: "16px", padding: "16px 0px" }}>
      <div
        className="flex-1 flex flex-col bg-yt-session-statistics-card-bg border border-[rgba(255,255,255,0.10)] max-w-[314px] min-w-[200px]"
        style={{
          gap: "16px",
          padding: "16px",
          borderRadius: "8px"
        }}
      >

        <div className="flex flex-col">
          <p
            className="text-center"
            style={{
              fontFamily: "Fredoka",
              fontWeight: 500,
              fontSize: "20px",
              lineHeight: "1.2em",
              letterSpacing: "-1%",
              color: "#94939F"
            }}
          >
            We watched
          </p>
          <p
            className="text-center"
            style={{
              fontFamily: "Fredoka",
              fontWeight: 500,
              fontSize: "20px",
              lineHeight: "1.2em",
              letterSpacing: "-1%",
              color: "#DDDDDF"
            }}
          >
            {totalSections} sections
          </p>
        </div>


        <div className="flex flex-col items-center" style={{ gap: "8px" }}>
          <div className="w-full flex flex-col">
            <div
              className="w-full rounded-full"
              style={{
                height: "8px",
                backgroundColor: "rgba(29, 175, 97, 0.3)"
              }}
            />
            <div
              className="rounded-full"
              style={{
                height: "8px",
                width: `${sectionCompletionPercentage}%`,
                backgroundColor: "#3EE089",
                marginTop: "-8px"
              }}
            />
          </div>

          <p
            style={{
              fontWeight: 600,
              fontSize: "14px",
              lineHeight: "1.57em",
              letterSpacing: "0.6%",
              color: "#3EE089",
              fontFamily: "Fredoka"
            }}
          >
            {sectionCompletionPercentage}% complete
          </p>
        </div>
      </div>

     {quizAccuracy > 0 && <div
        className="flex-1 flex flex-col bg-yt-session-statistics-card-bg border border-[rgba(255,255,255,0.10)] max-w-[314px] min-w-[200px]"
        style={{
          gap: "16px",
          padding: "16px",
          borderRadius: "8px"
        }}
      >

        <div className="flex flex-col">
          <p
            className="text-center"
            style={{
              fontFamily: "Fredoka",
              fontWeight: 500,
              fontSize: "20px",
              lineHeight: "1.2em",
              letterSpacing: "-1%",
              color: "#94939F"
            }}
          >
            We also took
          </p>
          <p
            className="text-center"
            style={{
              fontFamily: "Fredoka",
              fontWeight: 500,
              fontSize: "20px",
              lineHeight: "1.2em",
              letterSpacing: "-1%",
              color: "#DDDDDF",
            }}
          >
            {totalQuizzesCompleted} quizzes
          </p>
        </div>


        <div className="flex flex-col items-center" style={{ gap: "8px" }}>
          <div className="w-full flex flex-col">
            <div
              className="w-full rounded-full"
              style={{
                height: "8px",
                backgroundColor: "rgba(29, 175, 97, 0.3)"
              }}
            />
            <div
              className="rounded-full"
              style={{
                height: "8px",
                width: `${quizAccuracy}%`,
                backgroundColor: "#3EE089",
                marginTop: "-8px",
                fontFamily: "Fredoka"
              }}
            />
          </div>

          <p
            style={{
              fontWeight: 600,
              fontSize: "14px",
              lineHeight: "1.57em",
              letterSpacing: "0.6%",
              color: "#3EE089",
              fontFamily: "Fredoka"
            }}
          >
            {quizAccuracy}% accuracy
          </p>
        </div>
      </div>}
    </div>
  )
}