// Context collection flows for handling avatar and menu interactions

/**
 * Triggers a click on the avatar element and then clicks a specific menu item,
 * opening it in a new tab
 */
export function triggerProfileDataCollection() {
    
    // Find the avatar element
    const avatarImg = document.querySelector('#navbar_user_avatar') as HTMLElement;

    if (!avatarImg) {
        return false;
    }

    // Click the avatar to open the menu
    avatarImg.click();

    // Try to find the menu item multiple times
    let attempts = 0;
    const maxAttempts = 5;
    const checkInterval = 200; // Check every 200ms

    const findAndClickMenuItem = () => {
        const menuItem = document.querySelector('#web-user-menu > div > div > div.z-base-1.relative.flex.h-full.w-full.flex-col.items-end.p-4 > div > div.flex.shrink-0.items-center.px-4.pb-4.pt-1.md\\:px-\\[1px\\] > div > a') as HTMLAnchorElement;

        if (menuItem && menuItem.href) {
            avatarImg.click();
            window.open(`${menuItem.href}?action=context-collection&referrer=${window.location.href}`, '_blank');
            return true;
        }

        attempts++;
        if (attempts >= maxAttempts) {
            if (!menuItem) {
                console.warn('Menu item element not found');
            }
            if (menuItem && !menuItem.href) {
                console.warn('Menu item found but href is missing');
            }
            return true;
        }

        // Try again after delay
        setTimeout(findAndClickMenuItem, checkInterval);
        return false;
    };

    // Start checking for menu item
    setTimeout(findAndClickMenuItem, checkInterval);

    return true;
}
