import { createContext, useContext } from "react";
import useChatConversations, { ChatUsageData, NPS_STATUS } from "./use-chat-conversations";
import { SCREEN } from "../../types/type";

export type ChatContextType = ReturnType<typeof useChatConversations>;

const defaultFn = () => {
  console.warn("ChatContext: default function called before provider is initialised");
};

const defaultContextValues: ChatContextType = {
  chatMessages: [],
  setChatMessages: defaultFn,
  loading: false,
  setLoading: defaultFn,
  liveMessages: [],
  setLiveMessages: defaultFn,
  userLiveMessage: [],
  setUserLiveMessage: defaultFn,
  isLiveMessageStreaming: false,
  setisLiveMessageStreaming: defaultFn,
  fetchMessages: async () => {},
  sendMessage: async () => {},
  conversationFeedbackStatus: "not_shown_today",
  setConversationFeedbackStatusToCancel: defaultFn,
  setConversationFeedbackStatusToSubmitted: defaultFn,
  npsStatus: NPS_STATUS.HIDE,
  setNpsStatus: defaultFn,
  chatUsageData: {
    isPaidUser: false,
    dailyMessageLimit: 0,
    dailyMessagesLeft: 0,
    todayOutgoingChatMessagesCount: 0,
    menteeDataLoading: false,
  } as ChatUsageData,
  isPlansSheetOpen: false,
  setIsPlansSheetOpen: defaultFn,
  menteeSubscription: null,
  handleUpgradeToProClick: async () => {},
};

export const ChatContext = createContext<ChatContextType>(defaultContextValues);

interface ChatProviderProps {
  menteeData: any;
  mentoraiData: any;
  menteeSubscription: any;
  menteeDataLoading: boolean;
  children: React.ReactNode;
  setScreen: (screen: SCREEN) => void;
}

export const ChatProvider = ({
  children,
  menteeData,
  mentoraiData,
  menteeSubscription,
  menteeDataLoading,
  setScreen,
}: ChatProviderProps) => {
  const chatContextValue = useChatConversations({
    menteeData,
    mentoraiData,
    menteeSubscription,
    menteeDataLoading,
    setScreen,
  });

  return <ChatContext.Provider value={chatContextValue}>{children}</ChatContext.Provider>;
};

export const useChatContext = () => useContext(ChatContext); 