import { useState, useEffect, useRef, useCallback } from "react"
import { usePageContext } from "../../../../contexts/page-context/page-context"
import { useCustomUI } from "../../../../contexts/custom-ui-context/custom-ui-context"


const defaultEasyActionOptions = [
  {
    timestamp: "",
    category: "default category",
    follow_up: "Have a doubt here"
  },
  {
    timestamp: "",
    category: "default category",
    follow_up: "Dive deeper into this"
  },
  {
    timestamp: "",
    category: "default category",
    follow_up: "Assess on the video"
  }
]


const useLeecoHelp = () => {
  const { isSidePanelOpen } = usePageContext()
  const { getVideoProperties, getSessionProperties, showCurrentDynamicEasyAction, currentDynamicEasyAction, hideCurrentDynamicEasyAction, cleanedYoutubeUrl } = useCustomUI()
  const [isHovered, setIsHovered] = useState(false)
  const [showEasyActions, setShowEasyActions] = useState(true)
  const [isDoubleArrowHovered, setIsDoubleArrowHovered] = useState(false)
  const [isLeecoIconHovered, setIsLeecoIconHovered] = useState(false);
  const [isHidden, setIsHidden] = useState(true)
  const [isVideoFirstLoad, setIsVideoFirstLoad] = useState(false)
  const [showConfirmationModal, setShowConfirmationModal] = useState(false)
  const [showHideEye, setShowHideEye] = useState(false)
  const timeoutRef = useRef<NodeJS.Timeout | null>(null)
  const videoStartTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const hideEyeTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const lastVideoIdRef = useRef<string>('')
  const getVideoId = () => {
    const url = window?.location?.href || ''
    const patterns = [
      /[?&]v=([^&]+)/,
      /youtube\.com\/watch\?.*v=([^&]+)/,
      /youtu\.be\/([^?]+)/,
      /embed\/([^?]+)/
    ]

    for (const pattern of patterns) {
      const match = url.match(pattern)
      if (match) {
        return match[1]
      }
    }

    return null
  }

  const locationHref = window?.location?.href

  useEffect(() => {
    const currentVideoId = getVideoId()
    // Check if this is a new video
    if (currentVideoId && currentVideoId !== lastVideoIdRef.current) {
      lastVideoIdRef.current = currentVideoId

      // Show easy actions after 2 seconds
      if (videoStartTimeoutRef.current) {
        clearTimeout(videoStartTimeoutRef.current)
      }
      if (hideEyeTimeoutRef.current) {
        clearTimeout(hideEyeTimeoutRef.current)
      }
      videoStartTimeoutRef.current = setTimeout(() => {
        setIsVideoFirstLoad(true)
        setShowEasyActions(true)
        setShowHideEye(false)
        chrome.runtime.sendMessage({
          action: "sendAnalytics",
          url: window.location.href,
          eventName: "Followup Questions Shown",
          eventProperties: {
            type: "Static Follow-up",
            trigger: "Video Start",
            category: "default category",
            video: getVideoProperties()
          }
        });

        // Show HideEye after easy action animation completes (0.45 seconds)
        hideEyeTimeoutRef.current = setTimeout(() => {
          setShowHideEye(true)
        }, 450)

        // Hide easy actions after 3 seconds from when they appear
        setTimeout(() => {
          setShowEasyActions(false)
          setIsVideoFirstLoad(false)
          setShowConfirmationModal(false)
          setShowHideEye(false)
        }, 3000)
      }, 3000)
    }

    setIsHidden(false)
  }, [locationHref])

  const handleMouseEnter = () => {
    if (timeoutRef?.current) {
      clearTimeout(timeoutRef?.current)
    }
    if (hideEyeTimeoutRef?.current) {
      clearTimeout(hideEyeTimeoutRef?.current)
    }
    setIsHovered(true)
    setShowEasyActions(true)
    setShowHideEye(false)
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: window.location.href,
      eventName: "Followup Questions Shown",
      eventProperties: {
        type: currentDynamicEasyAction.follow_up ? "All" : "Static Follow-up",
        trigger: "Hover",
        category: currentDynamicEasyAction.follow_up ? currentDynamicEasyAction.category : "default category",
        video: getVideoProperties()
      }
    });

    // Show HideEye after easy action animation completes (0.45 seconds)
    hideEyeTimeoutRef.current = setTimeout(() => {
      setShowHideEye(true)
    }, 450)
  }

  const handleMouseLeave = () => {
    if (timeoutRef?.current) {
      clearTimeout(timeoutRef?.current)
    }
    if (hideEyeTimeoutRef?.current) {
      clearTimeout(hideEyeTimeoutRef?.current)
    }
    timeoutRef.current = setTimeout(() => {
      setIsHovered(false)
      setShowEasyActions(false)
      setShowConfirmationModal(false)
      setShowHideEye(false)
    }, 300) // 300ms delay before closing
  }


  const handleEasyActionClick = useCallback((message: string, category?: string) => {
    const video = document.querySelector('video') as HTMLVideoElement
    if (video) {
      video.pause()
    }
    const isDynamicFollowUp = defaultEasyActionOptions.find(option => option.follow_up === message)?.category !== "default category";
    const actionType = isDynamicFollowUp ? "Dynamic Follow-up" : "Static Follow-up";
    const currentTime = video ? video.currentTime : 0
    chrome.runtime.sendMessage({
      action: "easyActionClicked",
      easy_action: message,
      easy_action_title: message,
      url: window.location.href,
      is_side_panel_opened: isSidePanelOpen,
      section_title: "Leeco Help",
      easy_action_message: message,
      event_properties: {
        category: category || 'default category',
        type: actionType,
        total_duration: `${Math.floor(video.duration / 60)}:${Math.floor(video.duration % 60).toString().padStart(2, '0')}`,
        current_time: `${Math.floor(currentTime / 60)}:${Math.floor(currentTime % 60).toString().padStart(2, '0')}`,
        video: getVideoProperties(),
        session: getSessionProperties()
      },
    })
  }, [isSidePanelOpen, getVideoProperties, getSessionProperties])

  const brandingContainer = document.querySelector(".branding-img-container");

  const appendLocations = document.querySelector("div.ytp-timely-actions-overlay");
  const customUiElementAtAppendLocation: any = appendLocations?.querySelector(".customUI-added");

  // useEffect(() => {
  //   if (customUiElementAtAppendLocation && !!brandingContainer) {
  //     console.log("[YouTube Debug] brandingContainer", brandingContainer);
  //     (brandingContainer as HTMLElement).style.position = "relative";
  //     const brandingHeight = brandingContainer.getBoundingClientRect().height;
  //     const brandingWidth = brandingContainer.getBoundingClientRect().width;

  //     customUiElementAtAppendLocation.style.top = `-${brandingHeight + 4}px`;
  //     customUiElementAtAppendLocation.style.right = `-${brandingWidth + 14}px`;
  //   }
  // }, [brandingContainer]);

  // Cleanup timeouts on unmount
  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
      if (videoStartTimeoutRef.current) {
        clearTimeout(videoStartTimeoutRef.current);
      }
      if (hideEyeTimeoutRef.current) {
        clearTimeout(hideEyeTimeoutRef.current);
      }
    };
  }, []);

  return {
    isHovered,
    setIsHovered,
    showEasyActions,
    isDoubleArrowHovered,
    isHidden,
    setIsHidden,
    isVideoFirstLoad,
    showConfirmationModal,
    setShowConfirmationModal,
    showHideEye,
    timeoutRef,
    videoStartTimeoutRef,
    defaultEasyActionOptions,
    showCurrentDynamicEasyAction,
    currentDynamicEasyAction,
    hideCurrentDynamicEasyAction,
    handleMouseEnter,
    handleMouseLeave,
    handleEasyActionClick,
    setIsDoubleArrowHovered,
    isLeecoIconHovered,
    setIsLeecoIconHovered,
    setShowEasyActions,
    setShowHideEye

  }
}

export default useLeecoHelp