import { useState, useMemo, useEffect } from 'react';
import { useCustomUI } from '../../../contexts/custom-ui-context/custom-ui-context';
import { shuffleQuiz } from '../../../utils/learning-session-helper';

export type QuizSubmissionStatus = 'default' | 'correct' | 'incorrect';

export interface UseEndSectionQuizComponentProps {
  quizzes: any[]; // Array of quiz objects with timestamp and quizQuestions
  currentQuizIndex: number;
  onSubmitAnswer: (answerIdx: number) => void;
  onNextQuiz: (sectionIdx: number) => void;
  sectionIndex: number;
}

export default function useEndSectionQuizComponent({
  quizzes,
  currentQuizIndex,
  onSubmitAnswer,
  onNextQuiz,
  sectionIndex,
}: UseEndSectionQuizComponentProps) {
  const { trackCustomUIEvent, getSectionProperties } = useCustomUI();
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [quizSubmissionStatus, setQuizSubmissionStatus] = useState<QuizSubmissionStatus>('default');
  const [submitted, setSubmitted] = useState(false);

  // Flatten the quiz structure to get all individual questions
  const flattenedQuizzes = useMemo(() => {
    const flattened: any[] = [];
    quizzes.forEach((quizElement) => {
      if (quizElement.quizQuestions && Array.isArray(quizElement.quizQuestions)) {
        quizElement.quizQuestions.forEach((question: any) => {
          flattened.push({
            ...question,
            timestamp: quizElement.timestamp, // Include timestamp for context
          });
        });
      }
    });
    return flattened;
  }, [quizzes]);

  const tempQuiz = flattenedQuizzes[currentQuizIndex];
  const currentQuiz = useMemo(() => shuffleQuiz(tempQuiz), [tempQuiz?.question])
  const totalQuizzes = flattenedQuizzes.length;

  const handleOptionSelect = (idx: number) => {
    if (quizSubmissionStatus === 'default') {
      setSelectedOption(idx);
    }
  };

  const handleSubmit = () => {
    if (selectedOption === null || quizSubmissionStatus !== 'default') return;
    setSubmitted(true);
    const isCorrect = currentQuiz.answer === selectedOption;
    setQuizSubmissionStatus(isCorrect ? 'correct' : 'incorrect');
    trackCustomUIEvent("MentorAi Quiz Submitted", {
      section: getSectionProperties(sectionIndex),
      question: {
        quiz_number: currentQuizIndex + 1,
        question: currentQuiz?.question,
        user_answer: isCorrect ? "correct" : "incorrect",
        type: currentQuiz?.questionType,
      }
    });
    // Doing this because the answer is shuffled and we need to store the original index
    onSubmitAnswer(currentQuiz.originalIndexes[selectedOption]);
  };

  const handleNext = () => {
    setSelectedOption(null);
    setQuizSubmissionStatus('default');
    setSubmitted(false);
    onNextQuiz(sectionIndex);
  };


  useEffect(() => {
    
    if (currentQuiz?.userAnswer !== undefined) {
      const isCorrect = currentQuiz.answer === currentQuiz.userAnswer;
      setQuizSubmissionStatus(isCorrect ? 'correct' : 'incorrect');
      setSelectedOption(currentQuiz.userAnswer);
      setSubmitted(true);
    } else {
      setQuizSubmissionStatus('default');
      setSelectedOption(null);
      setSubmitted(false);
    }
  }, [currentQuiz]);
  

  useEffect(() => {
    if(currentQuiz)
    {
      trackCustomUIEvent("MentorAi Quiz Viewed", {
        section: getSectionProperties(sectionIndex),
        question: {
          quiz_number: currentQuizIndex + 1,
          question: currentQuiz?.question,
          user_answer: currentQuiz?.userAnswer && (currentQuiz?.userAnswer === currentQuiz?.answer ? "correct" : "incorrect"),
          type: currentQuiz?.questionType,
        }
      });
    }
  }, [currentQuizIndex]);
  

  return {
    currentQuiz,
    selectedOption,
    setSelectedOption: handleOptionSelect,
    quizSubmissionStatus,
    handleSubmit,
    handleNext,
    submitted,
    totalQuizzes,
    flattenedQuizzes,
  };
} 