import React from 'react'
import { useCustomUI } from '../../../../contexts/custom-ui-context/custom-ui-context'
import hourglassIcon from '../../../../assets/icons/hourglass.svg'
import brainLineIcon from '../../../../assets/icons/brain-line.svg'
import clockIcon from '../../../../assets/icons/timeline.svg'
import { formatTimeDuration, formatTimeDurationFromSecondsAsTttFormat } from '../../../../utils/learning-session-helper'
import { timeToSeconds } from '../../../../../src/utils/str-time-to-seconds'

const SectionDurationAndDetails = () => {
    const { learningSession, selectedSection , playerMode } = useCustomUI()
    const isPlayerModeDefault = playerMode === "DEFAULT";
    const section = learningSession?.sections?.[selectedSection || 0]
    const quizzes = section?.quizzes || [];
    const totalQuizCount = quizzes.reduce((total, quizElement) => {
        return total + (quizElement.quizQuestions?.length || 0);
    }, 0);

    const timeRange = `${formatTimeDuration(section?.startTime || '')} - ${formatTimeDuration(section?.endTime || '')}`
    const rangeDuration = `${formatTimeDurationFromSecondsAsTttFormat(timeToSeconds(section?.endTime || '') - timeToSeconds(section?.startTime || ''))}`
    const quizLabel = totalQuizCount === 1 ? '1 quiz' : `${totalQuizCount} quizzes`

    return (
        <div className="flex items-center whitespace-nowrap truncate" style={{ gap: 16 }}>
            <div className="flex items-center" style={{ gap: 4 }}>
                <img src={hourglassIcon} alt="hourglass" style={{marginTop:'-2px', width: isPlayerModeDefault ? 16 : 20, height: isPlayerModeDefault ? 16 : 20 }} />
                <div style={{ color: '  #94939F', fontWeight: 500, fontSize: isPlayerModeDefault ? 14 : 16, lineHeight: isPlayerModeDefault ? '22px' : '24px', textAlign: 'center' }}>{rangeDuration}</div>
            </div>
            <div className="flex items-center" style={{ gap: 4 }}>
                <img src={clockIcon} alt="clock" style={{marginTop:'-2px', width: isPlayerModeDefault ? 16 : 20, height: isPlayerModeDefault ? 16 : 20 }} />
                <div style={{ color: '#94939F', fontWeight: 500, fontSize: isPlayerModeDefault ? 14 : 16, lineHeight: isPlayerModeDefault ? '22px' : '24px', textAlign: 'center' }}>{timeRange}</div>
            </div>
            {totalQuizCount > 0 &&
                <div className="flex items-center" style={{ gap: 4 }}>
                    <img src={brainLineIcon} alt="brain" style={{marginTop:'-2px', width: isPlayerModeDefault ? 16 : 20, height: isPlayerModeDefault ? 16 : 20 }} />
                    <div style={{ color: '#94939F', fontWeight: 500, fontSize: isPlayerModeDefault ? 14 : 16, lineHeight: isPlayerModeDefault ? '22px' : '24px', textAlign: 'center' }}>{quizLabel}</div>
                </div>
            }
        </div>
    )
}

export default SectionDurationAndDetails