import { useState, useEffect } from "react"
import rehypeRaw from "rehype-raw"
import remarkGfm from "remark-gfm"
import ReactMarkdown from "react-markdown"
import CloseIcon from "../../../../assets/icons/close-icon.svg"
import CloseIconHovered from "../../../../assets/icons/close-icon-hovered.svg"
import Modal from "../../../../../common/modal/modal"
import Button from "../../../../../src/components/common/common-button"

type Props = {
    show: boolean
    handleClose: () => void
    generatedPracticeFeedback: string
}

const PracticeFeedbackModal = ({ show, handleClose, generatedPracticeFeedback }: Props) => {
    if (generatedPracticeFeedback === "") {
        return null
    }
    if (generatedPracticeFeedback.length < 50) {
        chrome.runtime.sendMessage({
            action: "generatedPracticeFeedbackIsNotValid",
            practiceFeedback: "Feedback not generated. Not enough Data"
        })
        return null
    }

    return (
        <Modal
            open={show}
            handleCloseOutside={handleClose}
            className={{
                container: "rounded-xl",
                overlay:
                    "!bg-[rgba(20,22,31,0.60)] !rounded-tl-[6px] !rounded-bl-[6px]",
            }}
        >
            <div className="shadow-[inset_0px_0px_48px_0px_rgba(115,109,249,0.20)] flex items-center justify-center flex-col p-[16px] max-h-[80vh] max-w-[80vw] rounded-xl relative border border-[#363645] bg-mentorai-bg-base overflow-hidden font-bricolage-grotesque">
                <Button className="!cursor-pointer sticky transition-all duration-100 group"
                    style={{
                        top: "12px",
                        left: "100%"
                    }}
                    onClick={() => handleClose()}>
                    <img src={CloseIcon} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] flex group-hover:hidden" />
                    <img src={CloseIconHovered} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] hidden group-hover:flex" />
                </Button>
                <div className="flex items-center justify-center flex-col p-[16px] h-full w-full gap-8 overflow-y-auto">
                    <h1 className="text-mentorai-primary-lighter text-[24px] leading-[32px] tracking-[0.12px] font-semibold text-center">Practice Report</h1>
                    <ReactMarkdown
                        rehypePlugins={[rehypeRaw]}
                        remarkPlugins={[remarkGfm]}
                        className={
                            `prose markdown-prose !text-[14px]/[22px] !-tracking-[0.084px] max-w-full overflow-auto`
                        }
                    >
                        {generatedPracticeFeedback}
                    </ReactMarkdown>
                </div>
            </div>
        </Modal>
    )
}

export default PracticeFeedbackModal