interface QuestionData {
    questionId: string;
}

interface CodeEntry {
    key: string;
    timestamp: number;
}

export const scrapeLeetcodeUserCode = async (): Promise<string | null> => {
    try {
        // Get and validate question data
        const questionData = await getQuestionData();
        if (!questionData) return null;

        // Try IndexedDB first, then localStorage, finally Monaco editor HTML
        const userCode = await getUserCodeFromIndexedDB(questionData.questionId) || 
                         await getUserCodeFromLocalStorage(questionData.questionId) ||
                         extractMonacoFromHtml();

        return userCode;

    } catch (error) {
        console.error("Error in scrapeLeetcodeUserCode:", error);
        return null;
    }
};

// Helper function to get and validate question data
async function getQuestionData(): Promise<QuestionData | null> {
    try {
        const questionData = await chrome.storage.local.get("question_data");
        if (!questionData?.question_data) return null;

        const parsedData = questionData.question_data;
        const questionId = parsedData?.questionId || "";
        
        if (!questionId) return null;

        return { questionId };
    } catch (error) {
        console.error("Failed to parse question_data:", error);
        return null;
    }
}

// Get user code from IndexedDB
async function getUserCodeFromIndexedDB(questionId: string): Promise<string | null> {
    return new Promise((resolve) => {
        const request = indexedDB.open("LeetCode-problems");
        
        request.onsuccess = function(event: any) {
            try {
                const db = event.target.result;
                const txn = db.transaction("problem_code", "readonly");
                const store = txn.objectStore("problem_code");
                
                findMostRecentCodeEntry(store, questionId, resolve);
            } catch (error) {
                console.error("IndexedDB transaction error:", error);
                resolve(null);
            }
        };
        
        request.onerror = function() {
            console.error("IndexedDB connection error");
            resolve(null);
        };
    });
}

// Find most recent code entry using cursor
function findMostRecentCodeEntry(
    store: IDBObjectStore, 
    questionId: string, 
    resolve: (value: string | null) => void
): void {
    const questionRegex = new RegExp(`^${questionId}`);
    const timestampSuffix = '-updated-time';
    
    let mostRecentEntry: CodeEntry | null = null;
    
    const cursorRequest = store.openCursor();
    
    cursorRequest.onsuccess = function(event: any) {
        const cursor = event.target.result;
        
        if (cursor) {
            mostRecentEntry = processCurrentCursorEntry(cursor, questionRegex, timestampSuffix, mostRecentEntry);
            cursor.continue();
        } else {
            // Cursor finished - retrieve the actual code
            retrieveCodeByKey(store, mostRecentEntry?.key || null, resolve);
        }
    };
    
    cursorRequest.onerror = function() {
        console.error("Cursor error in IndexedDB");
        resolve(null);
    };
}

// Process current cursor entry
function processCurrentCursorEntry(
    cursor: IDBCursorWithValue,
    questionRegex: RegExp,
    timestampSuffix: string,
    mostRecentEntry: CodeEntry | null
): CodeEntry | null {
    const key = cursor.key as string;
    const value = cursor.value;
    
    // Check if this is a timestamp key for current question
    if (typeof key === 'string' && 
        key.endsWith(timestampSuffix) && 
        questionRegex.test(key)) {
        
        const timestamp = Number(value);
        if (!isNaN(timestamp) && 
            (!mostRecentEntry || timestamp > mostRecentEntry.timestamp)) {
            
            const codeKey = key.replace(timestampSuffix, '');
            mostRecentEntry = { key: codeKey, timestamp };
        }
    }
    
    return mostRecentEntry;
}

// Retrieve code by key from store
function retrieveCodeByKey(
    store: IDBObjectStore, 
    codeKey: string | null, 
    resolve: (value: string | null) => void
): void {
    if (!codeKey) {
        resolve(null);
        return;
    }
    
    const getCodeRequest = store.get(codeKey);
    
    getCodeRequest.onsuccess = function() {
        const result = getCodeRequest.result;
        resolve(typeof result === 'string' ? result : null);
    };
    
    getCodeRequest.onerror = function() {
        console.error("Error retrieving code from IndexedDB");
        resolve(null);
    };
}

// Get user code from localStorage as fallback
async function getUserCodeFromLocalStorage(questionId: string): Promise<string | null> {
    try {
        const timestampSuffix = '-updated-time';
        const localStorageRegex = new RegExp(`^${questionId}.*${timestampSuffix}$`);
        
        const mostRecentEntry = findMostRecentLocalStorageEntry(localStorageRegex, timestampSuffix);
        
        if (!mostRecentEntry) return null;
        
        const codeKey = mostRecentEntry.replace(timestampSuffix, '');
        return codeKey ? localStorage.getItem(codeKey) : null;
        
    } catch (error) {
        console.error("Error in localStorage fallback:", error);
        return null;
    }
}

// Find most recent entry in localStorage
function findMostRecentLocalStorageEntry(regex: RegExp, timestampSuffix: string): string | null {
    let mostRecentKey = "";
    let mostRecentTimestamp = -Infinity;
    
    const localStorageKeys = Object.keys(localStorage);
    
    for (const key of localStorageKeys) {
        if (regex.test(key)) {
            const timestamp = Number(localStorage[key]);
            if (!isNaN(timestamp) && timestamp > mostRecentTimestamp) {
                mostRecentTimestamp = timestamp;
                mostRecentKey = key;
            }
        }
    }
    
    return mostRecentKey || null;
}

// Extract code from Monaco editor HTML as final fallback
function extractMonacoFromHtml(): string | null {
    try {
        // Find Monaco editor view-lines
        const codeLines = [...document.querySelectorAll('.view-line')]
            .map(el => ({
                top: parseFloat((el as HTMLElement).style.top) || 0,
                text: el.textContent?.replace(/\u00A0/g, ' ') || '' // Replace non-breaking spaces
            }))
            .sort((a, b) => a.top - b.top)  // Sort by vertical position
            .map(l => l.text)
            .join('\n');                    // Join lines

        const trimmedCode = codeLines.trimEnd();
        return trimmedCode || null;

    } catch (error) {
        console.error("Error extracting Monaco editor content:", error);
        return null;
    }
}
