export const scrapeNeetcodeUserCode = async () => {
  // Get problem key from URL
  const url = window.location.href;
  const problemKey = url.split('/problems/')[1];
  
  if (!problemKey) return null;

  // First try to get saved language preference
  const savedLanguage = localStorage.getItem('saved-coding-language');

  if (savedLanguage) {
    // If language preference exists, look for exact key match
    const storageKey = `${problemKey}_${savedLanguage}`;
    const code = localStorage.getItem(storageKey);
    if (code) return code;
  }

  // If no language preference or code not found, look for any matching key
  const regex = new RegExp(`^${problemKey}_.*`);
  
  for (const key of Object.keys(localStorage)) {
    if (regex.test(key)) {
      return localStorage.getItem(key);
    }
  }

  return null;
};
