export function getYoutubeVideoLength() {
    const video = document.getElementsByTagName("video");
    return video?.[0]?.duration ?? 0;
}

export function getYoutubeVideoPlayHead(): number {
    const videoEl = document.querySelector('video');
    return videoEl?.currentTime ?? 0;
}

export function formatTime(seconds: number): string {
    const hours = Math.floor(seconds / 3600);
    const remainingSeconds = Math.floor(seconds % 60);
    const minutes = Math.floor((seconds % 3600) / 60) + (remainingSeconds > 0 ? 1 : 0);
    let formattedTime = ''
    if (hours > 0) {
        formattedTime = `${formattedTime} ${hours}${hours === 1 ? ' hr' : ' hrs'}`
    }
    if (minutes > 0) {
        formattedTime = `${formattedTime} ${minutes}${minutes === 1 ? ' min' : ' mins'}`
    }
    // if (remainingSeconds > 0) {
    //     formattedTime = `${formattedTime} ${remainingSeconds}${remainingSeconds === 1 ? ' sec' : ' secs'}`
    // }
    return formattedTime
}