import { useEffect, useRef, useState } from 'react'
import { SessionOverlayView } from '../../../types/youtube-session'
import TextSkeleton from '../../../../common/loader/text-skeleton'
import { useCustomUI } from '../../../contexts/custom-ui-context/custom-ui-context'
import IncompleteIconDefault from '../../../assets/icons/incomplete.svg'
import IncompleteIconHover from '../../../assets/icons/incomplete-hover.svg'
import CompletedIconDefault from '../../../assets/icons/completed.svg'
import CompletedIconHover from '../../../assets/icons/completed-hover.svg'
import { formatTimeDuration } from '../../../utils/learning-session-helper';
import BrainIcon from '../../../assets/icons/brain-line.svg'
import BrainIconActive from '../../../assets/icons/brain-line-active.svg'
import Confetti from '../../../assets/icons/confetti.svg'

// Add keyframes for fade-in animation
const styles = `
  @keyframes sectionFadeIn {
    from {
      opacity: 0;
      transform: translateY(10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
`;

// Inject styles into document head
if (typeof document !== 'undefined') {
  const styleSheet = document.createElement('style');
  styleSheet.type = 'text/css';
  styleSheet.innerText = styles;
  document.head.appendChild(styleSheet);
}



const SectionCreating = ({ index, isDefaultMode }: { index: number, isDefaultMode: boolean }) => {
  return (
    <div className='max-h-[175px] flex flex-col' style={{
      paddingTop: "16px", paddingRight: "16px", paddingBottom: "16px", borderRadius: "4px",
      width: isDefaultMode ? '158px' : '198px',
    }}>
      <div className="flex relative w-full" style={{
        gap: "2px", borderRadius: "4px",
        maxWidth: isDefaultMode ? '158px' : '198px',
      }}>
        <p className="text-mentorai-text-sub line-clamp-3 h-full flex justify-center items-center tracking-[0.084px]" style={{ fontWeight: 500, width: "24px", fontSize: "14px", lineHeight: "22px" }}>
          {index === 0 ? "1" : index + 1}
        </p>
        <TextSkeleton height='95px' width='100%' containerStyle={{
          marginLeft: "8px",
          maxWidth: isDefaultMode ? '120px' : '170px',
          width: "100%", marginTop: "10px"
        }} />
        <TextSkeleton height='20px' width='20px' containerStyle={{ borderRadius: "100%", position: "absolute", top: "16px", right: "8px" }} />
        <TextSkeleton height='20px' width='46px' containerStyle={{ position: "absolute", bottom: "8px", right: "8px", borderRadius: "4px" }} />
      </div>
      <TextSkeleton height='16px' width='100%' containerStyle={{ marginLeft: "30px", marginTop: "10px" }} />
      <TextSkeleton height='16px' width='100%' containerStyle={{
        marginLeft: "30px",
        maxWidth: isDefaultMode ? "60px" : "80px",
        width: "50%", marginTop: "6px"
      }} />
    </div>
  )
}


export const SectionTimelineCard = ({ item, index, isSelected, isCompleted, handleSectionClick, isNewlyStreamed, isClickable, isRenderedInSessionEnd }: { item: any, index: number, isSelected: boolean, isCompleted: boolean, handleSectionClick: (index: number) => void, isNewlyStreamed: boolean, isClickable: boolean, isRenderedInSessionEnd?: boolean }) => {
  const { sessionOverlayView, sectionEndScreen, playerMode, markSectionComplete, markSectionOngoing, currentSection, currentQuizIndex, trackCustomUIEvent, getSectionProperties } = useCustomUI()
  const isSelectedAndNotCreatedOverlay = isSelected && sessionOverlayView !== 'created'
  const [isHoveredIndex, setIsHoveredIndex] = useState<number | null>(null)
  const isPlayerModeDefault = playerMode === "DEFAULT";

  useEffect(() => {
    if (isSelectedAndNotCreatedOverlay) {
      const element = document.getElementById(`${index}-${item.sectionTitle}`);
      if (element) {
        element.scrollIntoView({ behavior: 'smooth', block: 'end' });
      }
    }
  }, [])

  // const rangeDuration = `${formatTimeDurationFromSeconds(timeToSeconds(item?.endTime || '') - timeToSeconds(item?.startTime || ''))}`
  // console.log('isRenderedInSessionEnd', isRenderedInSessionEnd, item, rangeDuration)
  const formatedStartTime = formatTimeDuration(item?.startTime || '')

  const handleMarkSection = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    if (isClickable) {
      if (isCompleted) {
        markSectionOngoing(index)
      } else {
        markSectionComplete(index)
        trackCustomUIEvent("MentorAi Section Marked Complete", {
          from: "Session Timeline",
          section: getSectionProperties(index),
        });
      }
    }
  }

  return (
    <div
      key={`${index}-${item.sectionTitle}`}
      id={`${index}-${item.sectionTitle}`}
      className={` mentorai-section-timeline-item group 
              ${isSelectedAndNotCreatedOverlay ? ' selected' : ''}
              ${(isClickable && !isSelectedAndNotCreatedOverlay) ? 'hover:border-l-4 hover:border-l-[#84848C] cursor-pointer hover:text-[#DDDDDF] hover:bg-[rgba(132,132,140,0.12)]' : 'cursor-default'}
              ${isNewlyStreamed ? 'animate-fade-in' : ''}
              `}
      style={{
        borderTopRightRadius: "4px",
        borderBottomRightRadius: "4px",
        padding: isPlayerModeDefault ? '8px 8px 8px 0px' : '16px 16px 16px 0px',
        gap: "4px",
      }}
      onClick={() => handleSectionClick(index)}
    >
      <div className="flex items-center self-stretch" style={{ gap: isPlayerModeDefault ? '4px' : '2px' }}>
        <p className={`mentorai-section-timeline-number${isSelectedAndNotCreatedOverlay ? ' selected' : ''}`}
          style={{
            fontSize: isPlayerModeDefault ? '12px' : '14px',
            lineHeight: isPlayerModeDefault ? '18px' : '22px',
            letterSpacing: isPlayerModeDefault ? '0.072px' : '0.084px',
            width: isPlayerModeDefault ? '22px' : '24px',
          }}
        >{index + 1}</p>
        <div className={`mentorai-section-timeline-thumb${isSelectedAndNotCreatedOverlay ? ' selected' : ''}`}
          style={{
            width: isPlayerModeDefault ? '120px' : '170px',
            height: isPlayerModeDefault ? '76px' : '95px',
            minWidth: isPlayerModeDefault ? '120px' : '170px',
            minHeight: isPlayerModeDefault ? '76px' : '95px',
          }}
        >
          {item?.thumbnail ? (
            <img
              src={item.thumbnail}
              alt={`${index}`}
              className="w-full h-full object-cover"
              style={{ borderRadius: "8px" }}
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center" style={{ background: '#06060B', borderRadius: '8px' }} />
          )}
          <button className="mentorai-section-timeline-check"
            onClick={handleMarkSection}
            onMouseEnter={() => {
              if (isClickable) {
                setIsHoveredIndex(index)
              }
            }}
            onMouseLeave={() => {
              if (isClickable) {
                setIsHoveredIndex(null)
              }
            }}
          >
            <img src={isCompleted ? (isHoveredIndex === index ? CompletedIconHover : CompletedIconDefault) : (isHoveredIndex === index ? IncompleteIconHover : IncompleteIconDefault)} alt="completed" style={{
              width: isPlayerModeDefault ? 16 : 20,
              height: isPlayerModeDefault ? 16 : 20,
              zIndex: 10
            }} />
          </button>

          <div className="mentorai-section-timeline-time">
            {formatedStartTime}
          </div>
        </div>
      </div>

      <p className={`mentorai-section-timeline-title
        ${isSelectedAndNotCreatedOverlay ? ' selected' : ''}
        ${(isClickable && !isSelectedAndNotCreatedOverlay) ? 'group-hover:text-[#DDDDDF]' : ''}
        `}
        style={{
          height: isRenderedInSessionEnd ? '66px' : 'auto',
          fontSize: isPlayerModeDefault ? '12px' : '14px',
          lineHeight: isPlayerModeDefault ? '18px' : '22px',
          letterSpacing: isPlayerModeDefault ? '0.072px' : '0.084px',
        }}
      >
        {item?.sectionTitle}
      </p>

      {isRenderedInSessionEnd ? (
        null
      ) :
        item?.quizzes?.length > 0 &&
        <div style={{ marginTop: isPlayerModeDefault ? '4px' : '8px', paddingLeft: "20px", width: '100%', display: "flex", flexDirection: "column", gap: "4px" }}>
          {item?.quizzes?.map((quiz: any, idx: number) => {
            const isQuizBeingAttempted = index === currentSection && idx === currentQuizIndex && sectionEndScreen === 'quiz'
            const isQuizCompleted = quiz?.quizQuestions?.[0]?.userAnswer !== undefined
            return (
              <div key={`quiz-${idx}`} className="flex flex-row items-center w-full" style={{ gap: "4px" }}>
                <div style={{ display: "flex", flexDirection: "row", alignItems: "center", gap: "4px", width: '100%' }}>
                  <img src={isQuizBeingAttempted ? BrainIconActive : BrainIcon} alt="brain" style={{
                    width: isPlayerModeDefault ? '16px' : '20px',
                    height: isPlayerModeDefault ? '16px' : '20px',
                  }} />
                  <span style={{
                    width: "100%",
                    fontSize: isPlayerModeDefault ? '12px' : '14px',
                    lineHeight: isPlayerModeDefault ? '18px' : '22px',
                    letterSpacing: isPlayerModeDefault ? '0.072px' : '0.084px',
                    fontWeight: 500,
                    color: isQuizBeingAttempted ? "#A5A1F7" : "#94939F"
                  }}> Quiz {idx + 1}</span>
                </div>
                {isQuizCompleted ?
                  <img src={CompletedIconDefault} alt="check" style={{ width: 16, height: 16 }} />
                  : null
                }
              </div>
            )
          })}
        </div>}
    </div>
  )
}

type SessionProgressCardProps = {
  learningSession: any;
  sessionOverlayView: SessionOverlayView;
  setSessionOverlayView: (view: SessionOverlayView) => void;
  setSelectedSection: (idx: number | null) => void;
  isPlayerModeDefault: boolean;
  trackCustomUIEvent: (eventName: string, eventProperties: any) => void;
}

const SessionProgressCard = ({ learningSession, sessionOverlayView, isPlayerModeDefault, setSessionOverlayView, setSelectedSection, trackCustomUIEvent }: SessionProgressCardProps) => {
  const totalSections = learningSession.sections.length;
  const completedSections = learningSession.sections.filter((section: any) => section.status === 'completed').length;
  const sectionCompletionPercentage = Math.round((completedSections / totalSections) * 100);
  const isSelected = sessionOverlayView === 'session_end';
  const isClickable = sessionOverlayView !== 'session_end';
  const handleProgressCardClick = () => {
    if (isClickable) {
      setSessionOverlayView('session_end');
      trackCustomUIEvent("MentorAi Session End Screen Viewed", {
        from: "Session Timeline",
      });
    }
  };

  return (
    <div
      className={`mentorai-section-timeline-item group flex-row gap-[2px] justify-normal w-full
              ${isSelected ? ' selected' : ''}
              ${(isClickable && !isSelected) ? 'hover:border-l-4 hover:border-l-[#84848C] cursor-pointer hover:text-[#DDDDDF] hover:bg-[rgba(132,132,140,0.12)]' : 'cursor-default'}
              `}
      style={{
        borderTopRightRadius: "4px",
        borderBottomRightRadius: "4px",
        padding: isPlayerModeDefault ? '8px 8px 8px 0px' : '16px 16px 16px 0px',
        gap: "4px",
      }}
      onClick={handleProgressCardClick}
    >
      <div className='flex items-center justify-center shrink-0 h-[calc(100%-26px)]' style={{ width: isPlayerModeDefault ? '22px' : '24px', fontSize: isPlayerModeDefault ? '14px' : '16px' }}>
        🎉
      </div>
      <div className='flex flex-col gap-[4px] w-full'>
        <div className='flex flex-col p-[12px] pb-[8px] w-full border-[1px] border-mentorai-stroke-strong rounded-[8px] bg-[#14161F]'>
          <div className="flex flex-col gap-2">
            <div className="w-full bg-[rgba(29,175,97,0.30)] rounded-full h-[8px]">
              <div
                className="bg-mentorai-green-400 h-[8px] rounded-full transition-all duration-300 ease-out"
                style={{ width: `${sectionCompletionPercentage}%` }}
              ></div>
            </div>
            <span className="text-mentorai-green-400" style={{ fontSize: isPlayerModeDefault ? '10px' : '12px', lineHeight: isPlayerModeDefault ? '18px' : '22px', letterSpacing: isPlayerModeDefault ? '0.072px' : '0.084px', fontWeight: 500 }} >{sectionCompletionPercentage}% Complete</span>
          </div>
        </div>
        <p className='text-mentorai-text-sub' style={{ fontSize: isPlayerModeDefault ? '12px' : '14px', lineHeight: isPlayerModeDefault ? '22px' : '24px', letterSpacing: isPlayerModeDefault ? '0.084px' : '0.096px', fontWeight: 500 }} >End of Session</p>
      </div>
    </div>
  )
}

const SectionsTimeline = ({
  setTransitionDirection
}: {
  setTransitionDirection: (dir: 'up' | 'down') => void
}) => {
  const { learningSession, sessionCreationStatus, selectedSection, setSelectedSection, selectSection, streamingSections, setSessionOverlayView, sectionEndScreen, sessionOverlayView, playerMode, trackCustomUIEvent, getSectionProperties } = useCustomUI()
  const isPlayerModeDefault = playerMode === "DEFAULT";
  const isClickable = (learningSession?.sessionStatus === 'ongoing' || learningSession?.sessionStatus === 'completed') &&
    !(sessionOverlayView === 'section_end' && (sectionEndScreen === 'explore_quiz' || sectionEndScreen === 'quiz'))
  const sectionsToDisplay = learningSession?.sections || streamingSections || []
  const isStreaming = sessionCreationStatus === 'generating_section' && streamingSections.length > 0

  const handleSectionClick = (index: number) => {
    if (isClickable) {
      if (typeof selectedSection === 'number' && index !== selectedSection) {
        setTransitionDirection(index < selectedSection ? 'down' : 'up');
      }
      selectSection(index);
      trackCustomUIEvent("MentorAi Section Clicked", {
        from: "Session Timeline",
        section: getSectionProperties(index),
      });
      if (sessionOverlayView === 'created' || sessionOverlayView === 'session_end' || sessionOverlayView === 'section_end') {
        setSessionOverlayView('section_start');
      }
    }
  }

  const timelineContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (selectedSection !== null && selectedSection !== undefined) {
      const el = document.getElementById(`${selectedSection}-${sectionsToDisplay[selectedSection]?.sectionTitle}`);
      if (el && timelineContainerRef.current) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }
  }, [selectedSection, sectionsToDisplay]);

  return (
    <div
      ref={timelineContainerRef}
     className='flex flex-col max-h-[calc(100%-0px)] overflow-y-auto scrollbar-hide' style={{ gap: "8px", width: isPlayerModeDefault ? '158px' : '214px', minWidth: isPlayerModeDefault ? '158px' : '214px', }}>
      {sectionsToDisplay.map((item: any, index: number) => {
        const isSelected = selectedSection === index
        const isNewlyStreamed = isStreaming && index === sectionsToDisplay.length - 1
        const isCompleted = item.status === 'completed'
        return (
          <SectionTimelineCard
            item={item}
            index={index}
            isSelected={isSelected}
            isNewlyStreamed={isNewlyStreamed}
            isCompleted={isCompleted}
            isRenderedInSessionEnd={false}
            handleSectionClick={handleSectionClick}
            isClickable={isClickable}
          />
        )
      })}
      {Boolean(sessionCreationStatus) && ['checking_transcription', 'generating_section', 'generating_quiz'].includes(sessionCreationStatus as string) ?
        <SectionCreating index={sectionsToDisplay.length} isDefaultMode={isPlayerModeDefault} />
        : <SessionProgressCard learningSession={learningSession} sessionOverlayView={sessionOverlayView} isPlayerModeDefault={isPlayerModeDefault} setSessionOverlayView={setSessionOverlayView} setSelectedSection={setSelectedSection} trackCustomUIEvent={trackCustomUIEvent} />}
    </div >
  )
}


export default SectionsTimeline;  