interface ChatMessage {
    props: {
      model: {
        id: string;
        message: string;
        sentTime: string;
        sender: string;
        direction: string;
        position: string;
        senderPhotoUrl?: string;
        senderName?: string;
      };
      children?: JSX.Element;
      error?: boolean;
      theme?: "red" | "yellow";
    };
  }

export const convertChatMessagesToBackendFormat = (chatMessages: ChatMessage[], activeTabUrl: string) =>
    chatMessages?.map((chatMessage: ChatMessage) => ({
      id: chatMessage.props.model.id,
      text: chatMessage.props.model.message,
      createdAt: parseInt(chatMessage.props.model.sentTime),
      sent_by: chatMessage.props.model.sender,
      content: [
        {
          type: "text",
          children: [chatMessage.props.model.message],
        },
      ],
      custom: {
        interview_mode: "false",
        url: activeTabUrl,
      },
    }));