import { cleanYoutubeUrl } from "../../content/utils/clean-youtube-url"
import { handleAibackendGet } from "../../core/Axios"

export const LEARNING_CATEGORIES = new Set([
    'Education',            // 27
    'Howto & Style',        // 26
    'Science & Technology',  // 28
    'People & Blogs'
]);

// Cache to prevent duplicate API calls for the same URL
const userInteractionCache = new Map<string, { data: any; timestamp: number; tabId: number }>();
// Track ongoing API calls to prevent concurrent requests
const ongoingRequests = new Map<string, Promise<any>>();
const CACHE_DURATION = 5000; // 5 seconds cache

export const fetchUserInteractionData = async (youtubeURL: string, tabId: number) => {
  const cacheKey = `${youtubeURL}-${tabId}`;
  const cached = userInteractionCache.get(cacheKey);
  const now = Date.now();

  // Check if we have valid cached data for the same tab
  if (cached && (now - cached.timestamp) < CACHE_DURATION && cached.tabId === tabId) {
    // console.log("Using cached user interaction data for:", youtubeURL);
    // Still send the message even with cached data
    // chrome.tabs.sendMessage(tabId, {
    //   action: "sendUserInteractionData",
    //   tabId: tabId,
    //   url: youtubeURL,
    //   userInteractionData: cached.data
    // });
    return cached.data;
  }

  // Check if there's already an ongoing request for this URL+tabId
  const requestKey = cacheKey;
  if (ongoingRequests.has(requestKey)) {
    // console.log("Waiting for ongoing request for:", youtubeURL);
    const response = await ongoingRequests.get(requestKey);
    // Send message for the waiting request too
    // chrome.tabs.sendMessage(tabId, {
    //   action: "sendUserInteractionData",
    //   tabId: tabId,
    //   url: youtubeURL,
    //   userInteractionData: response
    // });
    return response;
  }

  // console.log("Fetching fresh user interaction data for:", youtubeURL);
  
  // Create and store the promise for this request
  const requestPromise = (async () => {
    try {
      const { menteeData } = await chrome.storage.local.get("menteeData");
      
      const response = await handleAibackendGet(`/user-interactions/get`, {
        candidates: menteeData?.dlData?.recordId,
        url: youtubeURL
      }, false);

      // Cache the response
      userInteractionCache.set(cacheKey, {
        data: response,
        timestamp: now,
        tabId: tabId
      });

      return response;
    } finally {
      // Remove the ongoing request when done
      ongoingRequests.delete(requestKey);
    }
  })();

  // Store the ongoing request
  ongoingRequests.set(requestKey, requestPromise);

  const response = await requestPromise;

  // // send user interaction data to content script
  // chrome.tabs.sendMessage(tabId, {
  //   action: "sendUserInteractionData",
  //   tabId: tabId,
  //   url: youtubeURL,
  //   userInteractionData: response
  // });

  return response;
};

export const handleWebNavigationCompleted = async (details: any) => {
   // check if youtube video is playing 
    if (details.url?.includes("youtube.com") && details.transitionType === "link") {
      const youtubeURL = cleanYoutubeUrl(details.url)
      if (youtubeURL) {
        const activeTab = await chrome.tabs.query({ active: true, currentWindow: true })
        const tabId = activeTab?.[0]?.id;
        const tabUrl = activeTab?.[0]?.url;

        // Only proceed if the tab's current URL matches the event URL (i.e., we have arrived)
        if (tabUrl !== details.url) {
            // Not the current page, skip
            return;
        }

        // get user interaction data+
        const categoryResult = await checkYoutubeVideoCategory(youtubeURL)
        const videoCategory = categoryResult?.category
        if (tabId) {
          chrome.tabs.sendMessage(tabId, {
            action: "sendYoutubeVideoCategory",
            tabId: tabId,
            url: youtubeURL,
            videoCategory: videoCategory
          })
        }
        if(tabId){
          if(!LEARNING_CATEGORIES.has(videoCategory) ) return;
          await fetchUserInteractionData(youtubeURL, tabId);
        }
      }
    }
}

