export const checkYoutubeVideoCategory = async (url: string) => {
  const urlObj = new URL(url)
  const videoId = urlObj.searchParams.get("v")
  if (videoId) {
    const r = await fetch(`https://www.youtube.com/watch?v=${videoId}&hl=en`);
    const html = await r.text();
    const pr = extractJSON(html)
    const category = pr?.microformat?.playerMicroformatRenderer?.category
    ?? pr?.videoDetails?.category;
    const videoInfo={
      // "shortDescription": pr?.videoDetails?.shortDescription,
      "title": pr?.videoDetails?.title,
      "channelTitle": pr?.videoDetails?.author,
      "keywords":pr?.videoDetails?.keywords ? [
          ...pr?.videoDetails?.keywords,
      ]:[]
    }
    return {category, videoInfo} // or return { category, chapters: formattedChapters } if you want both
  }
}

function extractJSON(html: string, varName = "ytInitialPlayerResponse") {
  const start = html.indexOf(varName + " = ");
  if (start === -1) return null;

  // find first "{" then walk until the matching "}"
  let brace = 0, i = html.indexOf("{", start);
  for (; i < html.length; i++) {
    if (html[i] === "{") brace++;
    if (html[i] === "}") brace--;
    if (brace === 0) break;
  }
  const jsonText = html.slice(html.indexOf("{", start), i + 1);
  return JSON.parse(jsonText);
}