type PlayerMode = 'DEFAULT' | 'THEATRE' | 'FULLSCREEN'

const detectPlayerMode = (): PlayerMode => {
  if (document.fullscreenElement) return 'FULLSCREEN'

  // "theater" attribute is present on <ytd-watch-flexy> in cinema mode
  const flexy = document.querySelector('ytd-watch-flexy')
  if (flexy && (flexy as HTMLElement).hasAttribute('theater')) return 'THEATRE'

  return 'DEFAULT'
}

const detectYoutubeTheme = (): boolean => {
  return document.documentElement.getAttribute("dark") === '';
}
type FollowUp = {
  timestamp: string,
  category: string,
  follow_up: string
}


interface CustomUIContextType {
  mentoraiData: MentorAi | null;
  menteeData: Mentee | null;
  isDisabled: boolean;
  interviewModeOn: boolean;
  practiceModeOn: boolean;
  userInteractionData: any;
  isUserInteractionDataFetched: boolean;
  showQuiz: boolean;
  currentIndex: number;
  totalVideoDurationInHMSFormat: string;
  showSectionEndNotification: boolean;
  quizGenerationProcessing: {
    isCheckingForTranscript: boolean;
    isTranscriptAvailable: boolean;
    errorFetchingTranscript: boolean;
    isGeneratingQuiz: boolean;
    isQuizGenerated: boolean;
    errorGeneratingQuiz: boolean;
  };
  revisionNotesGenerationProcessing: {
    isCheckingForTranscript: boolean;
    isTranscriptAvailable: boolean;
    isGeneratingRevisionNotes: boolean;
    isRevisionNotesGenerated: boolean;
  };
  videoRef: React.RefObject<HTMLVideoElement | null>;
  setUserInteractionData: (userInteractionData: any) => void;
  handleHelperOptionClick: (
    option: any,
    type: string,
    message?: string
  ) => void;
  handleBoostLearningToggle: (toggle_location?: string) => Promise<void>;
  handleToggleRevisionNotes: (action_location?: string) => Promise<void>;
  handleBoostLearningSwitchOff: (toggle_location?: string) => Promise<void>;
  setCurrentIndex: (currentIndex: number) => void;
  handleResumeVideo: () => void;

  // Learning Session States
  learningSession: LearningSession | null;
  streamingSections: any[];
  sessionOverlayView: SessionOverlayView;
  selectedSection: number | null;
  currentSection: number;
  sessionCreationStatus: SessionCreationStatus;
  sectionEndScreen: SectionEndScreen;
  extractingThumbnails: boolean;
  isSessionCompleted: boolean;
  currentQuizIndex: number;
  playerMode: PlayerMode;
  isYouTubeThemeDark: boolean;
  cleanedYoutubeUrl: string;
  dynamicEasyActionsForThisVideo: FollowUp[],
  dynamicEasyActionOptionVariant: 'v1' | 'v2' | 'v3' | '',
  showCurrentDynamicEasyAction: boolean;
  currentDynamicEasyAction: FollowUp;
  hideCurrentDynamicEasyAction: () => void;

  // Learning Session Actions
  setSessionOverlayView: (view: SessionOverlayView) => void;
  setSelectedSection: (idx: number | null) => void;
  setCurrentSection: (idx: number) => void;
  setSessionCreationStatus: (status: SessionCreationStatus) => void;
  setSectionEndScreen: (screen: SectionEndScreen) => void;
  toggleLearningSession: () => Promise<void>;
  stopLearningSession: () => void;
  selectSection: (idx: number) => void;
  startSelectedSection: (currentVideoTime?: number) => void;
  answerQuiz: (sectionIdx: number, quizIdx: number, answer: any) => void;
  nextQuiz: (sectionIdx: number) => void;
  showSessionEndView: () => void;
  markSectionComplete: (sectionIndex: number) => void;
  checkForTranscriptAvailability: (cleanedYoutubeUrl: string) => Promise<boolean>;
  playVideo: () => void;
  pauseVideo: (showSectionOverlay?: boolean) => void;
  setShowQuiz: (showQuiz: boolean) => void;
  setExtractingThumbnails: (extractingThumbnails: boolean) => void;
  handleJumpToNextSection: () => void;
  setIsSessionCompleted: (isSessionCompleted: boolean) => void;
  markSectionOngoing: (sectionIndex: number) => void;
  setPlayerMode: (playerMode: PlayerMode) => void;
  setShowSectionEndNotification: (showSectionEndNotification: boolean) => void;
  markSectionEndScreenShown: (sectionIndex: number) => void;
  // Analytics
  trackCustomUIEvent: (eventName: string, eventProperties: any) => void;
  getCurrentSectionProperties: () => any;
  getSectionProperties: (sectionIndex: number) => any;
  hideOverlay: () => void;
  getSectionAccordindToCurrentDuration: () => number;
  getVideoProperties: () => any;
  getSessionProperties: () => any;
}

const CustomUIContext = createSelectorContext<CustomUIContextType | undefined>(
  undefined
);

export const CustomUIProvider: React.FC<{
  children: ReactNode;
  isSidePanelOpen: boolean;
}> = ({ children, isSidePanelOpen }) => {
  const { isYouTubeSite, setIsYoutubeLearningVideo, setLlmClassificationResponse } = usePageContext();
  const { getTranscript } = useYTTranscript();
  const [mentoraiData, setMentoraiData] = useState<MentorAi | null>(null);
  const [menteeData, setMenteeData] = useState<Mentee | null>(null);
  const [isDisabled, setIsDisabled] = useState(false);
  const [showQuiz, setShowQuiz] = useState<boolean>(false);
  const [interviewModeOn, setInterviewModeOn] = useState(false);
  const [practiceModeOn, setPracticeModeOn] = useState(false);
  const [userInteractionData, setUserInteractionData] = useState<any>(null);
  const [isUserInteractionDataFetched, setIsUserInteractionDataFetched] =
    useState(false);
  const [quizGenerationProcessing, setQuizGenerationProcessing] = useState({
    isCheckingForTranscript: false,
    isTranscriptAvailable: false,
    errorFetchingTranscript: false,
    isGeneratingQuiz: false,
    isQuizGenerated: false,
    errorGeneratingQuiz: false,
  });
  const [
    revisionNotesGenerationProcessing,
    setRevisionNotesGenerationProcessing,
  ] = useState({
    isCheckingForTranscript: false,
    isTranscriptAvailable: false,
    errorFetchingTranscript: false,
    isGeneratingRevisionNotes: false,
    isRevisionNotesGenerated: false,
    errorGeneratingRevisionNotes: false,
  });
  const [cleanedYoutubeUrl, setCleanedYoutubeUrl] = useState<string>('');
  const [currentIndex, setCurrentIndex] = useState<number>(-1);
  const [currentQuizIndex, setCurrentQuizIndex] = useState<number>(0);
  const [videoCategory, setVideoCategory] = useState<string>('');
  const timeoutRef = React.useRef<NodeJS.Timeout | null>(null);

  // Core Learning Session Data (persisted)
  const [learningSession, setLearningSession] = useState<LearningSession | null>(null);

  // Add throttling ref for handleTimeUpdate
  const lastTimeUpdateRef = useRef<number>(0);
  const TIME_UPDATE_THROTTLE_MS = 500;

  // Temporary state for streaming sections during creation
  const [streamingSections, setStreamingSections] = useState<any[]>([]);

  // Ephemeral UI states for Learning Session
  const [sessionOverlayView, setSessionOverlayView] = useState<SessionOverlayView>('hidden');
  const [selectedSection, setSelectedSection] = useState<number | null>(null);
  const [currentSection, setCurrentSection] = useState<number>(0);
  const [sessionCreationStatus, setSessionCreationStatus] = useState<SessionCreationStatus>(null);
  const [sectionEndScreen, setSectionEndScreen] = useState<SectionEndScreen>('explore_quiz');
  const [extractingThumbnails, setExtractingThumbnails] = useState<boolean>(false);
  const [isSessionCompleted, setIsSessionCompleted] = useState<boolean>(false);
  const totalVideoDurationInHMSFormat = formatTime(getYoutubeVideoLength());
  const [showSectionEndNotification, setShowSectionEndNotification] = useState<boolean>(false);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(() => detectPlayerMode());
  const [isYouTubeThemeDark, setIsYouTubeThemeDark] = useState<boolean>(false);
  const { shouldFetchTranscription } = useTranscriptionQueue();
  const [dynamicEasyActionOptionVariant, setDynamicEasyActionOptionVariant] = useState<'v1' | 'v2' | 'v3' | ''>('')
  const [dynamicEasyActionsForThisVideo, setDynamicEasyActionsForThisVideo] = useState<FollowUp[]>([])
  const [showCurrentDynamicEasyAction, setShowCurrentDynamicEasyAction] = useState<boolean>(false)
  const [currentDynamicEasyAction, setCurrentDynamicEasyAction] = useState<FollowUp>({
    timestamp: '',
    category: '',
    follow_up: '',
  })

  const isSessionEndViewShown = useRef<boolean>(false);

  const videoRef = useRef<HTMLVideoElement | null>(null);

  const userInteractionDataRef = useRef<any>(null);

  const firedAnalyticsActions = useRef<Set<string>>(new Set());
  useEffect(() => {
    userInteractionDataRef.current = userInteractionData;
  }, [userInteractionData]);

  const setQuizGeneratingProcessStateToDefault = () => {
    setQuizGenerationProcessing({
      isCheckingForTranscript: false,
      isTranscriptAvailable: false,
      errorFetchingTranscript: false,
      isGeneratingQuiz: false,
      isQuizGenerated: false,
      errorGeneratingQuiz: false,
    });
  }



  const hideCurrentDynamicEasyAction = () => {
    setShowCurrentDynamicEasyAction(false);
  };

  const resetDynamicEasyActionStates = () => {
    setShowCurrentDynamicEasyAction(false);
    setDynamicEasyActionsForThisVideo([])
    setCurrentDynamicEasyAction({ timestamp: '', category: '', follow_up: '' });
    firedAnalyticsActions.current.clear();
  };

  const getDynamicEasyAction = async (currentTime: any) => {
    const now = Date.now();
    if (now - lastTimeUpdateRef.current < TIME_UPDATE_THROTTLE_MS) {
      return;
    }
    if (!Array.isArray(dynamicEasyActionsForThisVideo) || dynamicEasyActionsForThisVideo.length === 0) {
      return;
    }

    const currentUrl = cleanYoutubeUrl(window.location.href);

    if (currentUrl !== cleanedYoutubeUrl) {
      return;
    }

    const currentTimeInSeconds = Math.floor(currentTime);
    let selectedAction = null;

    let filteredActions = [...dynamicEasyActionsForThisVideo];
    // if (dynamicEasyActionOptionVariant === 'v2') {
    //   filteredActions = dynamicEasyActionsForThisVideo.filter((_, index) => index % 2 === 0);
    // }

    for (const action of filteredActions) {
      const actionTimeInSeconds = timeToSeconds(action.timestamp);
      if (Math.abs(currentTimeInSeconds - actionTimeInSeconds) <= 4) {
        selectedAction = action;
        break;
      }
    }

    if (selectedAction) {
      const actionKey = `${selectedAction.timestamp}-${selectedAction.category}`;
      if (firedAnalyticsActions.current.has(actionKey)) {
        return;
      }

      // Update local state to show the dynamic action immediately
      setCurrentDynamicEasyAction(selectedAction);
      setShowCurrentDynamicEasyAction(true);
      firedAnalyticsActions.current.add(actionKey);
      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: window.location.href,
        eventName: "Followup Questions Shown",
        eventProperties: {
          type: "Dynamic Follow-up",
          trigger: "Auto",
          category: selectedAction.category,
          video: getVideoProperties()
        }
      });

      // Auto-hide after 7 seconds
      setTimeout(() => {
        setShowCurrentDynamicEasyAction(false);
      }, 7000);
    }
  }


  const fetchDynamicEasyActionOptionsForThisVideo = async (url: string, variant: "v1" | "v2") => {
    try {
      const response = await handleAibackendStreamingPost('/resources/generate_follow_up_questions', {
        url: url,
        stream: true,
        variant: variant
      }, false)
      if (!response.body) {
        throw new Error("No response body received followup generation");
      }
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let fullRes = "";
      while (true) {
        const { done, value } = await reader.read();
        if (done) {
          const parsedData = safeParse(fullRes);
          if (Array.isArray(parsedData)) {
            setDynamicEasyActionsForThisVideo(parsedData);
            // Reset analytics tracking when new actions are fetched
            firedAnalyticsActions.current.clear();
          }
          break;
        };

        const chunk = decoder.decode(value, { stream: true });
        fullRes = chunk;
        const parsedChunk = safeParse(fullRes);
        setDynamicEasyActionsForThisVideo(parsedChunk);
        // Reset analytics tracking when streaming updates
        firedAnalyticsActions.current.clear();
        await new Promise(r => setTimeout(r, 0));
      }

      const parsedData = safeParse(fullRes);
      if (Array.isArray(parsedData)) {
        // Reset analytics tracking when final data is parsed
        firedAnalyticsActions.current.clear();
        // Return the data immediately since it's already in local state
        // Update storage in the background for persistence
        chrome.storage.local.get(['dynamic_easy_action_options']).then(({ dynamic_easy_action_options = {} }) => {
          const updatedOptions = {
            ...dynamic_easy_action_options,
            [url]: {
              data: parsedData,
              time_stamp: new Date().getTime()
            }
          };

          // Check if we have more than 40 records and remove the oldest ones
          const urlKeys = Object.keys(updatedOptions);
          if (urlKeys.length > 40) {
            // Sort URLs by timestamp to find the oldest ones
            const sortedUrls = urlKeys
              .map(key => ({
                url: key,
                timestamp: updatedOptions[key].time_stamp || 0
              }))
              .sort((a, b) => a.timestamp - b.timestamp);

            // Remove the oldest records (keep only the latest 40)
            const urlsToRemove = sortedUrls.slice(0, sortedUrls.length - 40);
            urlsToRemove.forEach(({ url: urlToRemove }) => {
              delete updatedOptions[urlToRemove];
            });
          }

          chrome.storage.local.set({
            dynamic_easy_action_options: updatedOptions
          });
        }).catch(error => {
          console.error('Error updating dynamic easy action options in storage:', error);
        });

        return parsedData;
      } else {
        // Fallback to storage if parsing failed
        const { dynamic_easy_action_options = {} } = await chrome.storage.local.get(['dynamic_easy_action_options']);
        return dynamic_easy_action_options[url]?.data || [];
      }
    } catch (error) {
      console.error('Error fetching dynamic easy action options:', error);
      const { dynamic_easy_action_options = {} } = await chrome.storage.local.get(['dynamic_easy_action_options']);
      return dynamic_easy_action_options[url]?.data || [];
    }
  }

  const isLastSection = learningSession && (currentSection === learningSession?.sections?.length - 1);
  const handleJumpToNextSection = () => {
    if (!isLastSection) {
      const nextSectionIndex = currentSection + 1;
      setCurrentSection(nextSectionIndex);
      setSelectedSection(nextSectionIndex);
      setSessionOverlayView('section_start');
    } else {
      showSessionEndView();
    }
    trackCustomUIEvent("Button Clicked", {
      button_name: "Jump to Next Section",
      section: getSectionProperties(currentSection),
    })
  };


  const handleHelperOptionClick = (
    option: any,
    type: string,
    message?: string
  ) => {
    if (isDisabled || interviewModeOn) return;
    setIsDisabled(true);
    const currentUrl = window.location.href;
    chrome.runtime.sendMessage({
      action: "easyActionClicked",
      easy_action: option.message || message || option || type,
      easy_action_title: option.message || message || option || type,
      url: currentUrl,
      is_side_panel_opened: isSidePanelOpen,
      section_title: type,
      easy_action_message: option.message || message || option || type,
    });
  };

  const handleUpdateUserInteractionDataToBackendAndState = async (newUserInteractionData: any) => {
    // This function now correctly merges with existing userInteractionData
    setUserInteractionData((prev: any) => {
      const updatedData = { ...prev, ...newUserInteractionData };
      return updatedData;
    });
    const { menteeData } = await chrome.storage.local.get('menteeData');
    try {
      const payload = {
        ...newUserInteractionData,
        candidates: [menteeData?.recordId],
        url: cleanYoutubeUrl(window.location.href),
        recordId: userInteractionDataRef.current?.recordId,
      };

      const response = await handleAibackendPost(`/user-interactions/create`, payload, false);
      if (response?.status === 200 && response?.data?.recordId && !userInteractionData?.recordId) {
        setUserInteractionData((prev: any) => ({ ...prev, recordId: response?.data?.recordId }));
        await updateDlDataIfNotExists();
      }
    } catch (error) {
      console.error("Error updating user interaction data", error);
    }
  };

  const updateTranscriptionQueue = async (
    transcript: string,
    cleanedYoutubeUrl: string
  ) => {
    const { youtube_transcription_queue } = await chrome.storage.local.get(
      "youtube_transcription_queue"
    );

    let updatedQueue = { ...youtube_transcription_queue };

    // If the queue already has 10 records, remove the oldest one
    const keys = Object.keys(updatedQueue);
    if (keys.length >= 10) {
      // Remove the first (oldest) key
      delete updatedQueue[keys[0]];
    }

    updatedQueue[cleanedYoutubeUrl] = transcript;

    await chrome.storage.local.set({
      youtube_transcription_queue: updatedQueue,
    });
  };

  const handleUpdateTranscription = async (cleanedYoutubeUrl: string) => {
    const transcript = await getTranscript(cleanedYoutubeUrl);

    if (!transcript || transcript.length === 0) {
      return false;
    }

    const requestBody = {
      url: cleanedYoutubeUrl,
      transcript: transcript,
    };

    const response = await chrome.runtime.sendMessage({
      action: "updateTranscription",
      url: cleanedYoutubeUrl,
      requestBody: requestBody,
    });

    await updateTranscriptionQueue(transcript, cleanedYoutubeUrl);

    if (response?.status === "ok") {
      return true;
    }

    return false;
  };

  const checkForTranscriptAvailability = async (cleanedYoutubeUrl: string) => {
    const isTranscriptAvailableResponse = await handleAibackendGet(
      `/resources/check-transcription-availability`,
      {
        url: cleanedYoutubeUrl,
        return_transcript: true,
      },
      false
    );

    let isTranscriptAvailable =
      isTranscriptAvailableResponse?.data?.is_transcription_available;

    if (!isTranscriptAvailable) {
      isTranscriptAvailable = await handleUpdateTranscription(
        cleanedYoutubeUrl
      );
      if (!isTranscriptAvailable) {
        return false;
      }
    } else {
      await updateTranscriptionQueue(
        isTranscriptAvailableResponse?.data?.transcription,
        cleanedYoutubeUrl
      );
    }

    return isTranscriptAvailable;
  };

  const handleBoostLearningSwitchOff = async (toggle_location?: string) => {
    try {
      await handleUpdateUserInteractionDataToBackendAndState({
        practiceMode: false,
      });

      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: window.location.href,
        eventName: "MentorAi Boost Learning Toggled",
        eventProperties: {
          toggle_location: toggle_location || "Outside Quiz",
          toggled: "Off",
          current_duration: getYoutubeVideoPlayHead(),
          video_duration: getYoutubeVideoLength(),
        },
      });
    } catch (error) {
      console.error("Error creating user interaction", error);
    }
  };

  const handleBoostLearningSwitchOn = async () => {
    try {
      // setQuizGenerationProcessing({
      //   ...quizGenerationProcessing,
      //   isGeneratingQuiz: true,
      // });
      await handleUpdateUserInteractionDataToBackendAndState({
        practiceMode: true,
      });
      // setQuizGenerationProcessing({
      //   ...quizGenerationProcessing,
      //   isGeneratingQuiz: false,
      //   isQuizGenerated: true,
      // });
    } catch (error) {
      console.error("Error creating user interaction", error);
    }
  };

  const handleBoostLearningToggle = async (toggle_location?: string) => {
    try {
      if (!menteeData?.recordId) {
        if (!isSidePanelOpen) {
          chrome.runtime.sendMessage({ action: "openSidePanel" });
        }
        return;
      }

      if (userInteractionData?.practiceMode) {
        await handleBoostLearningSwitchOff(toggle_location);
        return;
      }

      if (!userInteractionData?.practiceMode) {
        chrome.runtime.sendMessage({
          action: "sendAnalytics",
          url: window.location.href,
          eventName: "MentorAi Boost Learning Toggled",
          eventProperties: {
            toggled: "On",
            current_duration: getYoutubeVideoPlayHead(),
            video_duration: getYoutubeVideoLength(),
          },
        });
        if (userInteractionData?.quizzes) {
          await handleBoostLearningSwitchOn();
          return;
        }
      }

      // First check for transcript availability
      let isTranscriptAvailable;
      try {
        setQuizGenerationProcessing({
          ...quizGenerationProcessing,
          isCheckingForTranscript: true,
        });
        isTranscriptAvailable = await checkForTranscriptAvailability(
          cleanedYoutubeUrl
        );
        // If transcript is not available, early return
        if (!isTranscriptAvailable) {
          setQuizGenerationProcessing({
            ...quizGenerationProcessing,
            isCheckingForTranscript: false,
            errorFetchingTranscript: true,
          });
          return;
        }
      } catch (error) {
        console.error("Error fetching transcript available status", error);
        setQuizGenerationProcessing({
          ...quizGenerationProcessing,
          isCheckingForTranscript: false,
          errorFetchingTranscript: true,
        });
        chrome.runtime.sendMessage({
          action: "sendAnalytics",
          url: window.location.href,
          eventName: "MentorAi Boost Learning Generation Stopped",
          eventProperties: {
            reason: "Transcript Unavailable",
            detailed_reason: JSON.stringify(error),
            current_duration: getYoutubeVideoPlayHead(),
            video_duration: getYoutubeVideoLength(),
          },
        });
        return;
      }

      // If transcript is available, start generating quizzes
      if (isTranscriptAvailable) {
        setQuizGenerationProcessing({
          ...quizGenerationProcessing,
          isCheckingForTranscript: false,
          isTranscriptAvailable: true,
          isGeneratingQuiz: true,
        });

        let generatedQuizzes: any;
        try {
          generatedQuizzes = await handleAibackendPost(
            `/resources/generate_quizzes`,
            {
              url: cleanYoutubeUrl(window.location.href),
            },
            false
          );
          chrome.runtime.sendMessage({
            action: "sendAnalytics",
            url: window.location.href,
            eventName: "MentorAi Boost Learning Generated",
            eventProperties: {
              current_duration: getYoutubeVideoPlayHead(),
              video_duration: getYoutubeVideoLength(),
            },
          });
        } catch (error) {
          console.error("Error generating quizzes", error);
          setQuizGenerationProcessing({
            ...quizGenerationProcessing,
            isGeneratingQuiz: false,
            isQuizGenerated: false,
            errorGeneratingQuiz: true,
          });
          chrome.runtime.sendMessage({
            action: "sendAnalytics",
            url: window.location.href,
            eventName: "MentorAi Boost Learning Generation Stopped",
            eventProperties: {
              reason: "Other",
              detailed_reason: JSON.stringify(error),
              current_duration: getYoutubeVideoPlayHead(),
              video_duration: getYoutubeVideoLength(),
            },
          });
          return;
        }

        // If quizzes are generated, create a user interaction
        if (generatedQuizzes?.data) {
          const payload = {
            quizzes: generatedQuizzes?.data?.quizzes,
            practiceMode: true,
          };
          try {
            await handleUpdateUserInteractionDataToBackendAndState(payload);
            chrome.runtime.sendMessage({
              action: "sendAnalytics",
              url: window.location.href,
              eventName: "MentorAi Boost Learning Generated",
              eventProperties: {
                current_duration: getYoutubeVideoPlayHead(),
                video_duration: getYoutubeVideoLength(),
                total_questions: generatedQuizzes?.data?.quizzes?.length,
              },
            });
          } catch (error) {
            console.error("Error creating user interaction", error);
          }
          setQuizGenerationProcessing({
            ...quizGenerationProcessing,
            isGeneratingQuiz: false,
            isQuizGenerated: true,
          });
          setTimeout(() => {
            setQuizGeneratingProcessStateToDefault();
          }, 5000);
        }
      }
    } catch (error) {
      setQuizGenerationProcessing({
        ...quizGenerationProcessing,
        isGeneratingQuiz: false,
        isQuizGenerated: false,
        errorGeneratingQuiz: true,
      });
      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: window.location.href,
        eventName: "MentorAi Boost Learning Generation Stopped",
        eventProperties: {
          reason: "Other",
          detailed_reason: JSON.stringify(error),
          current_duration: getYoutubeVideoPlayHead(),
          video_duration: getYoutubeVideoLength(),
        },
      });
    }
  };

  const handleToggleRevisionNotes = async (action_location?: string) => {
    try {
      if (!menteeData?.recordId) {
        if (!isSidePanelOpen) {
          chrome.runtime.sendMessage({ action: "openSidePanel" });
        }
        chrome.runtime.sendMessage({ action: "showSignupModalInSidePanel" });
        return;
      }

      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: window.location.href,
        eventName: "MentorAi Revision Notes Requested",
        eventProperties: {
          current_duration: getYoutubeVideoPlayHead(),
          video_duration: getYoutubeVideoLength(),
          action_location: action_location || 'Video Player',
          video: getVideoProperties(),
          session: getSessionProperties(),
        },
      });

      // First check for transcript availability
      setRevisionNotesGenerationProcessing({
        ...revisionNotesGenerationProcessing,
        isCheckingForTranscript: true,
      });

      let isTranscriptAvailable;
      try {
        isTranscriptAvailable = await checkForTranscriptAvailability(
          cleanedYoutubeUrl
        );
      } catch (error) {
        console.error("Error fetching transcript available status", error);
        chrome.runtime.sendMessage({
          action: "sendAnalytics",
          url: window.location.href,
          eventName: "MentorAi Revision Notes Generation Stopped",
          eventProperties: {
            reason: "Transcript Unavailable",
            detailed_reason: JSON.stringify(error),
            current_duration: getYoutubeVideoPlayHead(),
            video_duration: getYoutubeVideoLength(),
            video: getVideoProperties(),
            session: getSessionProperties(),
          },
        });
      }

      // If transcript is not available, early return
      if (!isTranscriptAvailable) {
        setRevisionNotesGenerationProcessing({
          ...revisionNotesGenerationProcessing,
          isCheckingForTranscript: false,
          errorFetchingTranscript: true,
        });
        chrome.runtime.sendMessage({
          action: "sendAnalytics",
          url: window.location.href,
          eventName: "MentorAi Revision Notes Generation Stopped",
          eventProperties: {
            reason: "Transcript Unavailable",
            detailed_reason: "Transcript not available",
            current_duration: getYoutubeVideoPlayHead(),
            video_duration: getYoutubeVideoLength(),
            video: getVideoProperties(),
            session: getSessionProperties(),
          },
        });
        return;
      }

      // If transcript is available, start generating
      if (isTranscriptAvailable) {
        setRevisionNotesGenerationProcessing({
          ...revisionNotesGenerationProcessing,
          isCheckingForTranscript: false,
          isTranscriptAvailable: true,
          isGeneratingRevisionNotes: true,
        });

        // Initialize the detailed summary
        setUserInteractionData((prev: any) => ({
          ...prev,
          detailedSummary: "",
        }));

        // Create a reader for the detailed summary stream
        try {
          // Start all three operations in parallel
          // 1. Start the detailed summary stream
          const summaryPromise = handleAibackendStreamingPost(
            `/resources/generate_detailed_summary`,
            {
              url: cleanYoutubeUrl(window.location.href),
              stream: true,
            },
            false
          );

          // 2 & 3. Start glossary and cheatsheet requests in parallel with the stream
          const glossaryPromise = handleAibackendPost(
            `/resources/generate_glossary`,
            {
              url: cleanYoutubeUrl(window.location.href),
            },
            false
          );

          const cheatsheetPromise = handleAibackendPost(
            `/resources/generate_cheatsheet`,
            {
              url: cleanYoutubeUrl(window.location.href),
            },
            false
          );

          // Process the streaming response for detailed summary
          const response = await summaryPromise;

          if (!response.body) {
            throw new Error("No response body received for summary generation");
          }

          // Read the stream
          const reader = response.body.getReader();
          const decoder = new TextDecoder();
          let fullSummary = "";

          // Handle the stream while glossary and cheatsheet continue processing
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;

            const chunk = decoder.decode(value, { stream: true });
            fullSummary += chunk;

            // Update UI with current progress
            setUserInteractionData((prev: any) => ({
              ...prev,
              detailedSummary: fullSummary,
            }));
            await new Promise(r => setTimeout(r, 0));
          }

          // By this point, the stream is complete, now wait for glossary and cheatsheet to complete
          const [generatedGlossary, generatedCheatsheet] = await Promise.all([
            glossaryPromise,
            cheatsheetPromise,
          ]);

          // Stream is complete, now finalize by setting state for all components
          if (generatedGlossary?.data && generatedCheatsheet?.data) {
            setUserInteractionData((prev: any) => ({
              ...prev,
              detailedSummary: fullSummary,
              glossary: generatedGlossary?.data,
              cheatsheet: generatedCheatsheet?.data,
            }));

            await handleUpdateUserInteractionDataToBackendAndState({
              glossaryGenerated: true,
              detailedSummaryGenerated: true,
              cheatsheetGenerated: true,
            });

            setRevisionNotesGenerationProcessing({
              ...revisionNotesGenerationProcessing,
              isGeneratingRevisionNotes: false,
              isRevisionNotesGenerated: true,
              errorGeneratingRevisionNotes: false,
            });

            chrome.runtime.sendMessage({
              action: "sendAnalytics",
              url: window.location.href,
              eventName: "MentorAi Revision Notes Generated",
              eventProperties: {
                current_duration: getYoutubeVideoPlayHead(),
                video_duration: getYoutubeVideoLength(),
                video: getVideoProperties(),
                session: getSessionProperties(),
              },
            });
          }
        } catch (error) {
          console.error("Error processing summary stream", error);
          setRevisionNotesGenerationProcessing({
            ...revisionNotesGenerationProcessing,
            isGeneratingRevisionNotes: false,
            isRevisionNotesGenerated: false,
            errorGeneratingRevisionNotes: true,
          });
          chrome.runtime.sendMessage({
            action: "sendAnalytics",
            url: window.location.href,
            eventName: "MentorAi Revision Notes Generation Stopped",
            eventProperties: {
              reason: "Stream Processing Error",
              detailed_reason: JSON.stringify(error),
              current_duration: getYoutubeVideoPlayHead(),
              video_duration: getYoutubeVideoLength(),
              video: getVideoProperties(),
              session: getSessionProperties(),
            },
          });
        }
      }
    } catch (error) {
      console.log("Custom-ui-context: error", error);
      setRevisionNotesGenerationProcessing({
        ...revisionNotesGenerationProcessing,
        isGeneratingRevisionNotes: false,
        isRevisionNotesGenerated: false,
        errorGeneratingRevisionNotes: true,
      });
      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: window.location.href,
        eventName: "MentorAi Revision Notes Generation Stopped",
        eventProperties: {
          reason: "Other",
          detailed_reason: JSON.stringify(error),
          current_duration: getYoutubeVideoPlayHead(),
          video_duration: getYoutubeVideoLength(),
          video: getVideoProperties(),
          session: getSessionProperties(),
        },
      });
    }
  };

  const checkIfDlDataExists = () => {
    if (menteeData?.dlData?.recordId) {
      return true;
    }
    return false;
  };

  const updateDlDataIfNotExists = async () => {
    if (!checkIfDlDataExists()) {
      const menteeData = await chrome.runtime.sendMessage({
        action: "fetch_calls",
        fetch_call: "fetch_mentee",
        refetch: true,
      });
      chrome.storage.local.set({ menteeData: menteeData.mentee_data });
      setMenteeData(menteeData.mentee_data);
    }
  };

  // only add this when session status is ongoing
  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      if (sessionOverlayView !== 'hidden') {
        // TODO: this was not working in full screen mode, so we need to find a better way to detect full screen mode
        // detectPlayerMode() === 'FULLSCREEN' && event.preventDefault();
        hideOverlay();
        trackCustomUIEvent("MentorAi Session Overlay Closed", {
          from: "Escape Key",
        });
      }
    }
  }, [sessionOverlayView, playerMode]);

  const handleKeyUp = useCallback((event: KeyboardEvent) => {
    if (event.key === 'Space' && sessionOverlayView === 'hidden') {
      setSessionOverlayView("hidden");
      trackCustomUIEvent("MentorAi Session Overlay Opened", {
        from: "Space Key",
      });
    }
  }, [sessionOverlayView]);

  // Separate useEffect for keyboard event listeners to avoid re-running other setup code
  useEffect(() => {
    document.addEventListener('keydown', handleKeyDown);
    document.addEventListener('keyup', handleKeyUp);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.removeEventListener('keyup', handleKeyUp);
    };
  }, [handleKeyDown, handleKeyUp, playerMode]);

  useEffect(() => {
    const fetchMentoraiData = async () => {
      const mentoraiData = await chrome.runtime.sendMessage({
        action: "fetch_calls",
        fetch_call: "fetch_mentorai",
      });
      setMentoraiData(mentoraiData.mentorai_data);
    };

    const fetchMenteeData = async () => {
      const menteeData = await chrome.runtime.sendMessage({
        action: "fetch_calls",
        fetch_call: "fetch_mentee",
      });
      setMenteeData(menteeData.mentee_data);
    };

    fetchMentoraiData();
    fetchMenteeData();

    // Listen for userInteractionData updates
    chrome.runtime.onMessage.addListener(async (message, sender, sendResponse) => {
      if (message.action === "sendUserInteractionData") {
        if (message.userInteractionData?.status === 200) {
          setUserInteractionData(message.userInteractionData?.data);
          const cleanedUrl = cleanYoutubeUrl(window.location.href);
          setCleanedYoutubeUrl(cleanedUrl);
          // Reset analytics tracking when URL changes
          firedAnalyticsActions.current.clear();
          setIsUserInteractionDataFetched(true);
          setLearningSession(message.userInteractionData?.data?.learningSession);
          const sessionStatus = message.userInteractionData?.data?.learningSession?.sessionStatus;

          if (sessionStatus === "created") {
            setSessionCreationStatus("completed");
          }

          if (sessionStatus === "ongoing") {
            // pauseVideo() // removing this now as we don't want to pause the video when the page loads
            const sectionIndex = getSectionAccordindToCurrentDuration();
            setSessionCreationStatus("completed");
            // setSessionOverlayView('section_ongoing'); // removing this now as we don't want to show the section ongoing view when the page loads
            setSelectedSection(sectionIndex);
            setCurrentSection(sectionIndex);
            setSectionEndScreen('explore_quiz');
          }
        } else {
          console.log("Custom-ui-context: UserInteractionData status not 200:", message.userInteractionData?.status);
        }
      }
      if (message.action === "getTranscript") {
        const cleanedYoutubeUrl = cleanYoutubeUrl(window.location.href)
        const isTranscriptAvailable = await checkForTranscriptAvailability(cleanedYoutubeUrl)
        sendResponse({
          isTranscriptAvailable: isTranscriptAvailable,
        })
      }
      // if (message.action === "sendYoutubeVideoCategory") {
      //   setVideoCategory(message.videoCategory);
      // }
    });

    // Fetch data from storage
    const fetchStorageData = async () => {
      const result = await chrome.storage.local.get([
        "mentorai_data",
        "interviewModeStatus",
        "menteeData",
        "practiceModeStatus",
        "dynamic_easy_action_option_variant"
      ]);

      if (result.mentorai_data) {
        setMentoraiData(result.mentorai_data);
      }
      if (result.interviewModeStatus) {
        setInterviewModeOn(result.interviewModeStatus === "ONGOING");
      }
      if (result.practiceModeStatus) {
        setPracticeModeOn(result.practiceModeStatus === "PM_ONGOING");
      }
      if (result?.menteeData) {
        setMenteeData(result?.menteeData);
      }
    };
    fetchStorageData();

    // Check initial streaming status
    const checkStreamingStatus = async () => {
      const result = await chrome.storage.local.get("isLiveMessageStreaming");
      setIsDisabled(!!result.isLiveMessageStreaming);
    };
    checkStreamingStatus();

    // Listen for changes in storage
    chrome.storage.onChanged.addListener((changes) => {
      if (changes.isLiveMessageStreaming) {
        setIsDisabled(!!changes.isLiveMessageStreaming.newValue);
      }
      if (changes.interviewModeStatus) {
        if (changes.interviewModeStatus.newValue === "ONGOING") {
          setInterviewModeOn(true);
          setIsDisabled(true);
        } else {
          setInterviewModeOn(false);
          setIsDisabled(false);
        }
      }
      if (changes.practiceModeStatus) {
        if (changes.practiceModeStatus.newValue === "PM_ONGOING") {
          setPracticeModeOn(true);
        } else {
          setPracticeModeOn(false);
        }
      }
    });

    // For YouTube sites, store the theme
    const isLeetCodeSite = window.location.hostname === "leetcode.com";
    if (isLeetCodeSite) {
      const lc_theme = localStorage.getItem("lc-theme");
      if (lc_theme) {
        chrome.storage.local.set({ lc_theme: lc_theme });
      }
    }

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
      if (videoRef.current) {
        stopLearningSession(); // ensures listeners are removed
      }
    };
  }, []);


  // --- Learning Session Logic (Refactored) ---

  const persistCoreLearningSession = async (sessionData: LearningSession | null) => {
    setLearningSession(sessionData); // Update local core session state
    if (sessionData) {
      await handleUpdateUserInteractionDataToBackendAndState({ learningSession: sessionData });
    }
  };

  const stopLearningSession = () => {
    if (videoRef.current) {
      videoRef.current.removeEventListener('timeupdate', handleTimeUpdate);
      // videoRef.current.removeEventListener('pause', handlePause);
      videoRef.current.removeEventListener('play', handlePlay);
      videoRef.current.removeEventListener('seeked', handleSeeked);
      videoRef.current.removeEventListener('ended', handleEnded);
      videoRef.current = null;
    }
    if (learningSession) {
      persistCoreLearningSession({ ...learningSession, sessionStatus: 'stopped' });
    }
    setSessionOverlayView('hidden');
    setSessionCreationStatus(null);
    setSelectedSection(null);
    setStreamingSections([]);
  };

  const selectSection = (idx: number) => {
    setSelectedSection(idx);
  };

  const startSelectedSection = (currentVideoTime?: number) => {
    if (!learningSession || selectedSection === null) return;
    const idx = selectedSection;
    const sectionToStart = learningSession.sections[idx];

    setCurrentSection(idx); // Set current section first

    if (videoRef.current && sectionToStart) {
      if (currentVideoTime) {
        videoRef.current.currentTime = currentVideoTime;
      } else {
        videoRef.current.currentTime = timeToSeconds(sectionToStart.startTime);
      }
      playVideo(); // Use our wrapper to play and ensure 'section_ongoing' is cleared if it was active
      // setSessionOverlayView('hidden'); // Explicitly hide overlay BEFORE playing
    }

    if (learningSession.sessionStatus === 'created') {
      persistCoreLearningSession({ ...learningSession, sessionStatus: 'ongoing' });
    }
  };

  const answerQuiz = (sectionIdx: number, quizIdx: number, answer: any) => {
    if (!learningSession) return;

    // Calculate total flattened quiz count for this section
    const section = learningSession.sections[sectionIdx];

    // Find which quiz element and question index this flattened index corresponds to
    let flattenedIndex = 0;
    let targetQuizElementIdx = -1;
    let targetQuestionIdx = -1;

    for (let i = 0; i < section.quizzes.length; i++) {
      const quizElement = section.quizzes[i];
      const questionsInThisElement = quizElement.quizQuestions?.length || 0;

      if (flattenedIndex + questionsInThisElement > quizIdx) {
        targetQuizElementIdx = i;
        targetQuestionIdx = quizIdx - flattenedIndex;
        break;
      }
      flattenedIndex += questionsInThisElement;
    }

    const updatedSections = learningSession.sections.map((sec, sIdx) => {
      if (sIdx === sectionIdx) {
        const updatedQuizzes = sec.quizzes.map((quizElement, qElementIdx) => {
          if (qElementIdx === targetQuizElementIdx) {
            const updatedQuestions = quizElement.quizQuestions.map((question, qIdx) => {
              if (qIdx === targetQuestionIdx) {
                return {
                  ...question,
                  userAnswer: answer // Store the user's answer
                };
              }
              return question;
            });
            return {
              ...quizElement,
              quizQuestions: updatedQuestions
            };
          }
          return quizElement;
        });
        return { ...sec, quizzes: updatedQuizzes };
      }
      return sec;
    });

    // Only store the answer, don't increment quiz index or change screen state
    persistCoreLearningSession({
      ...learningSession,
      sections: updatedSections
    });
  };

  const nextQuiz = (sectionIdx: number) => {
    if (!learningSession) return;

    // Calculate total flattened quiz count for this section
    const section = learningSession.sections[sectionIdx];
    const totalFlattenedQuizzes = section.quizzes.reduce((total, quizElement) => {
      return total + (quizElement.quizQuestions?.length || 0);
    }, 0);

    let nextQuizIndex = currentQuizIndex + 1;
    if (nextQuizIndex >= totalFlattenedQuizzes) {
      setSectionEndScreen('completion');
      // Don't increment beyond the last quiz
      nextQuizIndex = currentQuizIndex;
    } else {
      setSectionEndScreen('quiz'); // Stay in quiz screen for next question
    }
    setCurrentQuizIndex(nextQuizIndex);
  };

  const showSessionEndView = () => {
    if (!isSessionEndViewShown.current && sessionOverlayView !== 'session_end') {
      pauseVideo();

      setTimeout(() => {
        setSessionOverlayView('session_end');
        setSectionEndScreen('explore_quiz');
        isSessionEndViewShown.current = true;
      }, 100);
    }
  }

  const markSectionComplete = (sectionIndex: number) => {
    if (!learningSession) return;

    const updatedSections = [...learningSession.sections];
    updatedSections[sectionIndex] = {
      ...updatedSections[sectionIndex],
      status: 'completed' as const
    };

    persistCoreLearningSession({
      ...learningSession,
      sections: updatedSections
    });
  };

  const markSessionCompleted = () => {
    if (!learningSession || learningSession.sessionStatus === 'completed') return;

    persistCoreLearningSession({
      ...learningSession,
      sessionStatus: 'completed'
    });

    trackCustomUIEvent("MentorAi Session Completed", {});
  };

  // Check if all sections have been completed
  const areAllSectionsCompleted = () => {
    if (!learningSession?.sections || learningSession.sections.length === 0) {
      return false;
    }

    return learningSession.sections.every(section => section.status === 'completed');
  };

  const markSectionOngoing = (sectionIndex: number) => {
    if (!learningSession) return;

    const updatedSections = [...learningSession.sections];
    updatedSections[sectionIndex] = {
      ...updatedSections[sectionIndex],
      status: 'ongoing' as const
    };

    persistCoreLearningSession({
      ...learningSession,
      sections: updatedSections
    });
  };

  const markSectionEndScreenShown = (sectionIndex: number) => {
    if (!learningSession) return;

    const updatedSections = [...learningSession.sections];
    updatedSections[sectionIndex] = {
      ...updatedSections[sectionIndex],
      endScreenShown: true
    };

    persistCoreLearningSession({
      ...learningSession,
      sections: updatedSections
    });
  };

  const hideOverlay = () => {
    if (extractingThumbnails) return;
    setSessionOverlayView('hidden');
    setSelectedSection(currentSection);
    setSectionEndScreen('explore_quiz');
  }

  const playVideo = () => {
    if (videoRef.current) {
      if (videoRef.current.paused) {
        videoRef.current.play();
      }
      hideOverlay();
    }
  };

  const pauseVideo = useCallback((showSectionOverlay: boolean = false) => {
    if (videoRef.current) {
      videoRef.current.pause();
      // Note: We don't automatically set to 'section_ongoing' here.
      // handlePause event handler will determine if 'section_ongoing' is appropriate.
      if (showSectionOverlay) {
        setSessionOverlayView('section_ongoing');
      }
    }
  }, [sessionOverlayView, selectedSection]);


  const handleTimeUpdate = useCallback((e: Event) => {
    // Throttling mechanism - only execute once every 500ms
    const now = Date.now();
    if (now - lastTimeUpdateRef.current < TIME_UPDATE_THROTTLE_MS) {
      return;
    }
    lastTimeUpdateRef.current = now;
    if (!learningSession || learningSession.sessionStatus !== 'ongoing') return;
    const videoElement = e.target as HTMLVideoElement;
    const currentTime = videoElement.currentTime;
    const currentSectionData = learningSession.sections[currentSection];

    if (!currentSectionData) return;

    // First: Check if current time is within the current section's range
    const isTimeInCurrentSection =
      currentTime >= timeToSeconds(currentSectionData.startTime) &&
      currentTime <= timeToSeconds(currentSectionData.endTime) + 1;

    const isFiveSecondsLeftForCurrentSectionEnd = (timeToSeconds(currentSectionData.endTime) - currentTime) < 5;
    if (!showSectionEndNotification && isFiveSecondsLeftForCurrentSectionEnd) {
      setShowSectionEndNotification(true);
    }

    if (!isFiveSecondsLeftForCurrentSectionEnd) {
      if (showSectionEndNotification) {
        pauseVideo();
        setSectionEndScreen('explore_quiz');
        setSessionOverlayView('section_end');
        markSectionEndScreenShown(currentSection);
      }
      setShowSectionEndNotification(false);
    }

    if (isTimeInCurrentSection) {
      // Time is within current section - check if we're at the end
      if (currentTime >= timeToSeconds(currentSectionData.endTime)) {
        // Only trigger if we are not already in 'section_end' or 'session_end'
        if (sessionOverlayView !== 'section_end' && sessionOverlayView !== 'session_end' && !currentSectionData.endScreenShown && currentSectionData.status !== 'completed') {
          // console.log(
          //   `Custom-ui-context: End of current section ${currentSection} detected. Name: "${currentSectionData.sectionTitle}", EndTime: ${currentSectionData.endTime}, CurrentTime: ${currentTime}`
          // );

          pauseVideo();

          setTimeout(() => {
            if (currentSectionData.status !== 'completed') {
              setSectionEndScreen('explore_quiz');
              setSessionOverlayView('section_end');
              markSectionEndScreenShown(currentSection);
              trackCustomUIEvent("MentorAi Section Finished", {
                section: getCurrentSectionProperties()
              });
            }
          }, 100);
        }
        return;
      }
      // Time is within section but not at end - continue normal playback
      return;
    }

    // Time is NOT within current section - find which section it belongs to
    const correctSectionIndex = learningSession.sections.findIndex(
      (s, index) => currentTime >= timeToSeconds(s.startTime) &&
        currentTime < timeToSeconds(s.endTime)
    );

    if (correctSectionIndex !== -1 && correctSectionIndex !== currentSection) {
      // Silently update section indices when user seeks - no overlay interruption
      setCurrentSection(correctSectionIndex);
      setSelectedSection(correctSectionIndex);
      return;
    }

    // Check if we're past all sections (session end)
    const lastSection = learningSession.sections[learningSession.sections.length - 1];
    if (lastSection && currentTime > timeToSeconds(lastSection.endTime)) {
      showSessionEndView();
      trackCustomUIEvent("MentorAi Session End Screen Viewed", {
        from: "Jumped Beyond Session End",
        section: getSectionProperties(currentSection),
      });
    }
  }, [learningSession, currentSection, sessionOverlayView, selectedSection, pauseVideo, setSessionOverlayView, setSectionEndScreen, setCurrentSection, setSelectedSection, persistCoreLearningSession]);

  const handlePause = useCallback(() => {
    if (learningSession?.sessionStatus === 'ongoing') {
      // If an overlay that implies video should be paused is already active, 
      // or is about to be set by another function (e.g. handleTimeUpdate setting section_start/section_end),
      // do not override it with 'section_ongoing'.
      if (
        sessionOverlayView === 'section_start' ||
        sessionOverlayView === 'section_end' ||
        sessionOverlayView === 'session_end' ||
        sessionOverlayView === 'section_ongoing' ||
        sessionOverlayView === 'creating' ||
        sessionOverlayView === 'created' ||
        sessionOverlayView === 'first_time_learning_session'
      ) {
        return; // The active/intended overlay implies video is paused.
      }
      // If no other specific overlay is active, then this pause is likely a user action
      // or a generic programmatic pause, so show the 'section_ongoing' (paused) overlay.
      setTimeout(() => {
        if (videoRef.current && videoRef.current.paused) {
          setSessionOverlayView((prev) => {
            if (prev === 'hidden') {
              return 'section_ongoing';
            }
            return prev;
          });
        }
      }, 100);
    }
  }, [learningSession?.sessionStatus, sessionOverlayView, setSessionOverlayView]);

  const handlePlay = useCallback(() => {
    hideOverlay();
    // Do not hide other overlays like 'section_start', 'section_end' here.
    // Those manage their own dismissal via user interaction or other logic.
  }, [playVideo]);

  const handleSeeked = useCallback((e: Event) => {
    // Re-evaluate current section and overlay after seek
    handleTimeUpdate(e);
  }, [handleTimeUpdate]);

  const handleEnded = useCallback(() => {
    if (learningSession && learningSession?.sessionStatus === 'ongoing') {
      showSessionEndView();
    }
  }, [learningSession, setSessionOverlayView, persistCoreLearningSession]);

  useEffect(() => {
    const vid = document.querySelector<HTMLVideoElement>('video');
    if (!vid) {
      console.warn("Video element not found for attaching listeners.");
      return;
    }

    // Remove existing listeners first (if any)
    if (videoRef.current) {
      videoRef.current.removeEventListener('timeupdate', handleTimeUpdate);
      videoRef.current.removeEventListener('timeupdate', getDynamicEasyAction);
      // videoRef.current.removeEventListener('pause', handlePause);
      videoRef.current.removeEventListener('play', handlePlay);
      videoRef.current.removeEventListener('seeked', handleSeeked);
      videoRef.current.removeEventListener('ended', handleEnded);
    }

    videoRef.current = vid;
    vid.addEventListener('timeupdate', (event) => {
      const videoElement = event.target as HTMLVideoElement;
      getDynamicEasyAction(videoElement.currentTime);
    });

    if (learningSession?.sessionStatus === 'ongoing') {
      vid.addEventListener('timeupdate', handleTimeUpdate);
      // vid.addEventListener('pause', handlePause);
      vid.addEventListener('play', handlePlay);
      // vid.addEventListener('seeked', handleSeeked);
      vid.addEventListener('ended', handleEnded);
    }

    return () => {
      if (videoRef.current) {
        videoRef.current.removeEventListener('timeupdate', handleTimeUpdate);
        videoRef.current.removeEventListener('timeupdate', getDynamicEasyAction);
        // videoRef.current.removeEventListener('pause', handlePause);
        videoRef.current.removeEventListener('play', handlePlay);
        videoRef.current.removeEventListener('seeked', handleSeeked);
        videoRef.current.removeEventListener('ended', handleEnded);
      }
    };
  }, [learningSession?.sessionStatus, handleTimeUpdate, handlePause, handlePlay, handleSeeked, handleEnded, getDynamicEasyAction]);

  const getSectionAccordindToCurrentDuration = () => {
    if (!learningSession) return 0;
    const currentTime = videoRef.current?.currentTime || 0;
    const sections = learningSession.sections;
    for (let i = 0; i < sections.length; i++) {
      const section = sections[i];
      if (currentTime >= timeToSeconds(section.startTime) && currentTime <= timeToSeconds(section.endTime)) {
        return i;
      }
    }
    return 0;
  }

  // Helper function to merge existing sections with new streamed sections
  const mergeStreamedSections = (newStreamedSections: any[], existingSections: any[]): any[] => {
    const merged: any[] = [];

    // Process each new section and try to find a matching existing section
    for (const newSection of newStreamedSections) {
      // Try to find an existing section with the same startTime
      const existingSection = existingSections.find(
        existing => existing.startTime === newSection.startTime
      );

      if (existingSection && (existingSection.thumbnailBlob || existingSection.thumbnail)) {
        // Keep existing section with thumbnail data, but update other properties from new section
        merged.push({
          ...newSection, // Use new section data as base
          thumbnailBlob: existingSection.thumbnailBlob, // Preserve thumbnail data
          fileName: existingSection.fileName,
          thumbnail: existingSection.thumbnail
        });
      } else {
        // Use new section (no matching existing section with thumbnails)
        merged.push(newSection);
      }
    }

    return merged;
  };

  // Helper function to merge metadata with existing sections
  const mergeStreamedMetadata = (newStreamedSections: any[], existingSections: any[]): any[] => {
    const merged: any[] = [];

    // Process each existing section and try to find matching new metadata
    for (const existingSection of existingSections) {
      // Try to find a new section with the same startTime
      const newSection = newStreamedSections.find(
        newSec => newSec.startTime === existingSection.startTime
      );

      if (newSection) {
        // Merge new metadata fields (sectionDescription, followUpQuestions) with existing section
        merged.push({
          ...existingSection,
          sectionDescription: newSection.sectionDescription || existingSection.sectionDescription,
          followUpQuestions: newSection.followUpQuestions || newSection.followup_questions || existingSection.followUpQuestions || existingSection.followup_questions || [],
        });
      } else {
        // Keep existing section if no new metadata available
        merged.push(existingSection);
      }
    }

    return merged;
  };

  const getYoutubeChannelName = () => {
    const channelElement: any = document.querySelector("#channel-name");
    const channelName = channelElement?.innerText || '';
    return channelName || '';
  }


  const getVideoProperties = useCallback(() => {
    return {
      url: cleanYoutubeUrl(window.location.href),
      title: document.title,
      duration: Math.floor(getYoutubeVideoLength()),
      current_duration: Math.floor(getYoutubeVideoPlayHead()),
      category: videoCategory,
      channel: getYoutubeChannelName(),
      view: detectPlayerMode()
    }
  }, [videoCategory]);

  const getSessionProperties = () => {
    if (!learningSession?.sections) {
      return {
        total_sections: 0,
        completed_sections: 0,
        status: null,
        total_quizzes: 0,
        completed_quizzes: 0,
        progress: 0
      };
    }

    const sections = learningSession.sections;
    const completedSections = sections.filter(section => section.status === 'completed').length;

    let totalQuizzes = 0;
    let completedQuizzes = 0;
    let correctQuizzes = 0;

    sections.forEach(section => {
      // Each section has a quizzes array, and each quiz has quizQuestions array
      section.quizzes?.forEach(quiz => {
        quiz.quizQuestions?.forEach(question => {
          totalQuizzes++;
          if (question.userAnswer !== undefined && question.userAnswer !== null) {
            completedQuizzes++;
            if (question.userAnswer === question.answer) {
              correctQuizzes++;
            }
          }
        });
      });
    });

    const progress = sections.length ? (completedSections / sections.length) * 100 : 0;
    const accuracy = totalQuizzes ? (correctQuizzes / totalQuizzes) * 100 : 0;

    return {
      total_sections: sections.length,
      completed_sections: completedSections,
      section_status: learningSession.sessionStatus,
      total_quizzes: totalQuizzes,
      completed_quizzes: completedQuizzes,
      progress: Math.floor(progress),
      quiz_accuracy: Math.floor(accuracy),
    };
  }

  const getCurrentSectionProperties = () => {
    return getSectionProperties(currentSection);
  }


  const getSectionProperties = (sectionIndex: number) => {
    const section = learningSession?.sections[sectionIndex];
    return {
      section_number: sectionIndex + 1,
      title: section?.sectionTitle,
      duration: timeToSeconds(section?.endTime) - timeToSeconds(section?.startTime),
      status: section?.status,
      total_quizzes: section?.quizzes?.length,
    }
  }

  const trackCustomUIEvent = (eventName: string, eventProperties: any) => {
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: window.location.href,
      eventName,
      eventProperties: {
        video: getVideoProperties(),
        session: getSessionProperties(),
        ...eventProperties
      }
    });
  }

  const toggleLearningSession = async () => {
    const { menteeData } = await chrome.storage.local.get('menteeData');
    if (!menteeData?.recordId) {
      if (!isSidePanelOpen) {
        chrome.runtime.sendMessage({ action: "openSidePanel" });
      }
      chrome.runtime.sendMessage({ action: "showSignupModalInSidePanel" });
      return;
    }
    const hasSeenLearningSession = await chrome.storage.local.get('hasSeenLearningSession');

    if (!hasSeenLearningSession.hasSeenLearningSession) {
      setSessionOverlayView('first_time_learning_session');
      await chrome.storage.local.set({ hasSeenLearningSession: true });
      return;
    }

    if (learningSession && ['ongoing', 'creating', 'created'].includes(learningSession.sessionStatus || '')) {
      stopLearningSession();
      trackCustomUIEvent("MentorAi Session Toggled", {
        toggled: "off",
      });
      return;
    }

    trackCustomUIEvent("MentorAi Session Toggled", {
      toggled: "on",
    });

    if (["created", "stopped"].includes(userInteractionData?.learningSession?.sessionStatus || "")) {
      const sectionIndex = getSectionAccordindToCurrentDuration();
      setSessionCreationStatus('completed');
      setSessionOverlayView('section_ongoing');
      setSelectedSection(sectionIndex);
      setCurrentSection(sectionIndex);
      setSectionEndScreen('explore_quiz');
      const finalSessionData: LearningSession = {
        ...userInteractionData?.learningSession,
        sessionStatus: 'ongoing',
      };
      pauseVideo()
      await persistCoreLearningSession(finalSessionData);
      return;
    }

    // Start creation
    setSessionCreationStatus('checking_transcription');
    const url = cleanYoutubeUrl(window.location.href);
    setCleanedYoutubeUrl(url);
    // Reset analytics tracking when URL changes
    firedAnalyticsActions.current.clear();

    let isTranscriptAvailable
    try {
      isTranscriptAvailable = await checkForTranscriptAvailability(url);
      if (!isTranscriptAvailable) {
        setSessionCreationStatus('transcription_failed');
        return;
      }
    } catch (error) {
      setSessionCreationStatus('transcription_failed');
      trackCustomUIEvent("MentorAi Session Creation Failed", {
        error: error,
        reason: "Transcription Failed",
      });
      return;
    }

    let wasMutedInitially = true;
    let mutedByUs = false;
    if (videoRef.current) {
      wasMutedInitially = videoRef.current.muted;
      if (!wasMutedInitially) {
        videoRef.current.muted = true;
        mutedByUs = true;
      }
    }

    pauseVideo()
    setSessionOverlayView('creating');
    setStreamingSections([]);
    setExtractingThumbnails(true);
    const coreSessionStub: Omit<LearningSession, 'sections'> = {
      sessionStatus: 'creating',
    };

    setSessionCreationStatus('generating_section');

    // Start both sections and quizzes generation in parallel
    let finalSections: any[] = [];
    let quizzesRes: any = null;

    try {
      // Start both operations in parallel
      const [sectionsResult, quizzesResult] = await Promise.all([
        // Sections streaming promise with thumbnail capture

        fetchSectionsStreaming(url, async (streamedSections) => {
          // Merge new streamed sections with existing sections (preserving thumbnails)
          const mergedSections = mergeStreamedSections(streamedSections, finalSections);

          // Capture thumbnails for sections that don't have them yet
          if (videoRef.current) {
            const sectionsWithThumbnails = await captureThumbnailsForStreamingSections(
              mergedSections,
              videoRef.current,
              url
            );
            setStreamingSections(sectionsWithThumbnails);
            finalSections = sectionsWithThumbnails;
          } else {
            setStreamingSections(mergedSections);
            finalSections = mergedSections;
          }
        }).catch(err => {
          console.error("Failed to fetch sections", err);
          setSessionCreationStatus('section_creation_failed');
          trackCustomUIEvent("MentorAi Session Creation Failed", {
            error: err,
            reason: "Section Generation Failed",
          });
          throw err;
        }),
        // Quizzes generation promise
        fetchQuizzes(url)
          .then(res => {
            const quizzes = res?.data?.quizzes || [];
            return quizzes;
          })
          .catch(err => {
            console.error("Failed to fetch quizzes", err);
            setSessionCreationStatus('quiz_creation_failed');
            trackCustomUIEvent("MentorAi Session Creation Failed", {
              error: err,
              reason: "Quiz Generation Failed",
            });
            throw err;
          })
      ]);

      // sectionsResult is void (streaming updates finalSections via callback)
      quizzesRes = quizzesResult;

    } catch (err) {
      console.error("Failed to fetch sections or quizzes", err);
      trackCustomUIEvent("MentorAi Session Creation Failed", {
        error: err,
        reason: "Others",
      });
      return;
    }

    // Both operations completed successfully
    const sections = mergeSectionsAndQuizzes(finalSections, quizzesRes);
    const finalSessionData: LearningSession = {
      ...coreSessionStub,
      sections,
      sessionStatus: 'ongoing',
    };

    setSessionCreationStatus('completed');
    setSessionOverlayView('created');
    setSelectedSection(0);
    setCurrentSection(0);
    setSectionEndScreen('explore_quiz');
    setStreamingSections([]); // Clear streaming sections as they're now in the final session

    // Update local state without persisting to backend yet
    setLearningSession(finalSessionData);

    setExtractingThumbnails(false);
    if (videoRef.current && mutedByUs) {
      videoRef.current.muted = false;
    }
    // Upload thumbnails and update session with URLs
    let finalSectionsWithThumbnails: any[] = [];
    if (videoRef.current && sections.length > 0) {


      try {
        const sectionsWithThumbnailUrls = await uploadThumbnailsAndGetUrls(sections, url);

        const finalSessionWithThumbnails: LearningSession = {
          ...finalSessionData,
          sections: sectionsWithThumbnailUrls,
        };

        // Now persist to backend with thumbnail URLs
        await persistCoreLearningSession(finalSessionWithThumbnails);
        finalSectionsWithThumbnails = sectionsWithThumbnailUrls;
        // Add metadata generation here
      } catch (error) {
        console.error('Error uploading thumbnails:', error);
        trackCustomUIEvent("MentorAi Session Creation Failed", {
          error: error,
          reason: "Thumbnail Upload Failed",
        });
        // Persist without thumbnails if upload fails
        await persistCoreLearningSession(finalSessionData);
      } finally {

      }
    } else {
      // No video element or sections, persist without thumbnails
      // await persistCoreLearningSession(finalSessionData);
    }


    // Start streaming metadata generation


    try {
      // Check if any section is missing followUpQuestions or sectionDescription
      const needsMetadataGeneration = finalSectionsWithThumbnails.some(section =>
        !section?.followUpQuestions ||
        !section?.sectionDescription ||
        (Array.isArray(section?.followUpQuestions) && section?.followUpQuestions.length === 0)
      );

      if (needsMetadataGeneration) {
        const body = {
          url,
          sections: finalSectionsWithThumbnails,
        }
        await fetchStreamingSectionsMetadata(body, async (streamedSections) => {
          // Update streamingSections state with new metadata during streaming
          if (streamedSections.length > 0) {
            const updatedSections = mergeStreamedMetadata(streamedSections, finalSectionsWithThumbnails);
            setStreamingSections(updatedSections);
            // Update finalSectionsWithThumbnails for the final persistence
            finalSectionsWithThumbnails = updatedSections;
          }
        });

        // Stream is complete, now persist the final learning session with all metadata
        const finalSessionWithMetadata: LearningSession = {
          ...finalSessionData,
          sections: finalSectionsWithThumbnails,
        };

        // Persist to backend only once with complete data
        await persistCoreLearningSession(finalSessionWithMetadata);
      }
      trackCustomUIEvent("MentorAi Session Generated", {
        session: {
          total_sections: finalSectionsWithThumbnails.length,
          completed_sections: 0,
          status: 'pending',
          total_quizzes: finalSectionsWithThumbnails.reduce((acc, section) => acc + (section.quizzes?.length || 0), 0),
          completed_quizzes: 0,
          progress: 0,
          quiz_accuracy: 0,
        }
      });
    } catch (error) {
      console.error('Error generating metadata:', error);
      trackCustomUIEvent("MentorAi Session Generation Failed", {
        error: error,
        reason: "Metadata Generation Failed",
      });
      // If metadata generation fails, persist without metadata
      await persistCoreLearningSession(finalSessionData);
    }
  };

  const handleResumeVideo = () => {
    const isCurrentAndSelectedSectionSame = currentSection === selectedSection
    if (videoRef?.current) {
      if (!isCurrentAndSelectedSectionSame && selectedSection) {
        const selectedSectionStartTime = learningSession?.sections?.[selectedSection]?.startTime
        if (videoRef.current) {
          videoRef.current.currentTime = timeToSeconds(selectedSectionStartTime || '00:00:00')
        }
      }
      videoRef.current.play();
      setSessionOverlayView('hidden');
    }
  }

  useEffect(() => {
    // Reset current quiz when section changes
    setCurrentQuizIndex(0);
  }, [currentSection]);


  // ---------------- Player-mode state ----------------
  useEffect(() => {
    let flexyObserver: MutationObserver | null = null;
    let attrObserver: MutationObserver | null = null;
    let currentFlexy: Element | null = null;

    const updateMode = () => setPlayerMode(detectPlayerMode());

    // Helper to observe the 'theater' attribute on the current flexy
    const observeFlexyAttr = (flexy: Element | null) => {
      if (attrObserver) attrObserver.disconnect();
      if (flexy) {
        attrObserver = new MutationObserver(updateMode);
        attrObserver.observe(flexy, { attributes: true, attributeFilter: ['theater'] });
      }
    };

    // Watch for flexy element changes
    const observeFlexy = () => {
      if (flexyObserver) flexyObserver.disconnect();
      flexyObserver = new MutationObserver(() => {
        const newFlexy = document.querySelector('ytd-watch-flexy');
        if (newFlexy !== currentFlexy) {
          currentFlexy = newFlexy;
          observeFlexyAttr(currentFlexy);
          updateMode();
        }
      });
      flexyObserver.observe(document.body, { childList: true, subtree: true });
    };

    // Initial setup
    currentFlexy = document.querySelector('ytd-watch-flexy');
    observeFlexyAttr(currentFlexy);
    observeFlexy();

    // Listen for fullscreen changes
    document.addEventListener('fullscreenchange', updateMode);
    // Listen for YouTube navigation events (for SPA navigation)
    window.addEventListener('yt-navigate-finish', updateMode);

    // Extra: After a short delay, re-check mode in case YouTube sets the attribute late
    const timeoutId = setTimeout(updateMode, 500);

    return () => {
      document.removeEventListener('fullscreenchange', updateMode);
      window.removeEventListener('yt-navigate-finish', updateMode);
      flexyObserver?.disconnect();
      attrObserver?.disconnect();
      clearTimeout(timeoutId);
    };
  }, []);

  useEffect(() => {
    const updateTheme = () => setIsYouTubeThemeDark(detectYoutubeTheme());
    updateTheme();

    // Observe changes to the dark attribute on documentElement
    const observer = new MutationObserver(updateTheme);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['dark']
    });

    // Listen for YouTube navigation events (for SPA navigation)
    window.addEventListener('yt-navigate-finish', updateTheme);

    return () => {
      observer.disconnect();
      window.removeEventListener('yt-navigate-finish', updateTheme);
    };
  }, []);

  useEffect(() => {
    // Only mark session as completed if all sections are completed and session is not already completed
    if (learningSession?.sessionStatus !== 'completed' && areAllSectionsCompleted()) {
      markSessionCompleted();
    }
  }, [learningSession]);

  const currentUrlRef = useRef<string>(window.location.href);
  const initializedUrlsRef = useRef<Set<string>>(new Set()); // Track which URLs have been initialized
  const urlParams = useMemo(() => new URLSearchParams(window.location.search), []);
  const urlHashParams = useMemo(() => new URLSearchParams(window.location.hash.slice(1)), []);

  const isActionStartSession = useMemo(
    () => {
      const action = urlParams.get('action') || urlHashParams.get('action');
      return action === 'start-session'
    },
    [urlParams]
  );

  const handleLLMCategoryCheck = async (videoInfo: any, url: string) => {
    try {
      const response = await handleAibackendPost("/resources/video-classifier", {
        video_info: videoInfo,
        video_url: url
      }, false)
      setLlmClassificationResponse({
        done: true,
        learningVideo: response?.data?.learningVideo,
      });
      return response?.data;
    } catch (error) {
      setLlmClassificationResponse({
        done: true,
        learningVideo: false,
      });
      return null;
    }
  }

  // Extract the logic into a reusable function with debug logs
  const handleYouTubeVideoInitialization = async (url: string) => {
    // Check if this URL has already been initialized
    if (initializedUrlsRef.current.has(url)) {
      return;
    }

    // Mark this URL as being initialized
    initializedUrlsRef.current.add(url);
    resetDynamicEasyActionStates()

    let videoCategory;
    let videoInfo;
    try {
      const response = await chrome.runtime.sendMessage({
        action: "checkYoutubeVideoCategory",
        url: url
      });
      videoCategory = response.videoCategory;
      videoInfo = response.videoInfo;

    } catch (err) {
      videoCategory = undefined;
    }

    // const llmClassificationResponse = await handleLLMCategoryCheck(videoInfo, url);
    setVideoCategory(videoCategory);
    // if ((!LEARNING_CATEGORIES.has(videoCategory) && !isActionStartSession) || !llmClassificationResponse?.learningVideo) {
      if ((!LEARNING_CATEGORIES.has(videoCategory) && !isActionStartSession)) {
      setIsYoutubeLearningVideo(false);
      return;
    }

    setIsYoutubeLearningVideo(true);
    const activeTabId = Math.floor(Math.random() * 1000000);

    if (activeTabId) {
      const cleanedUrl = cleanYoutubeUrl(url);

      let userInteractionData;
      try {
        userInteractionData = await fetchUserInteractionData(cleanedUrl, activeTabId);
      } catch (err) {
      }

      try {
        if (await shouldFetchTranscription(cleanedUrl)) {
          const isTranscriptAvailable = await checkForTranscriptAvailability(cleanedUrl);
          if (!isTranscriptAvailable) {
            setQuizGenerationProcessing((prev) => ({
              ...prev,
              isTranscriptAvailable: false,
            }));
          }
        } else {
        }
      } catch (err) {
      }

      // Check for cached dynamic easy actions in storage (non-blocking)
      const videoDurationInSeconds = getYoutubeVideoLength();
      let variant: "v1" | "v2" = "v1"
      if (videoDurationInSeconds <= 1200) {
        variant = "v1"
        await chrome.storage.local.set({
          dynamic_easy_action_option_variant: "v1"
        });
      } else {
        variant = "v2"
        await chrome.storage.local.set({
          dynamic_easy_action_option_variant: "v2"
        });
      }
      setDynamicEasyActionOptionVariant(variant)
      chrome.storage.local.get(['dynamic_easy_action_options']).then(async ({ dynamic_easy_action_options = {} }) => {
        if (!!dynamic_easy_action_options?.[url]?.data) {
          const storedData = dynamic_easy_action_options[url];
          if (storedData.data && Array.isArray(storedData.data)) {
            setDynamicEasyActionsForThisVideo(storedData.data);
            // Reset analytics tracking when using cached data
            firedAnalyticsActions.current.clear();
            return; // Exit early if we have cached data
          }
        }
        // If no cached data, fetch new data
        if (videoDurationInSeconds <= 3600) {
          fetchDynamicEasyActionOptionsForThisVideo(url, variant);
        }
      }).catch(err => {
        console.error('Error checking cached dynamic easy actions:', err);
      });
      setUserInteractionData(userInteractionData?.data || null);
      setCleanedYoutubeUrl(cleanedUrl);
      // Reset analytics tracking when URL changes
      firedAnalyticsActions.current.clear();
      setIsUserInteractionDataFetched(true);
      setLearningSession(userInteractionData?.data?.learningSession);

      const sessionStatus = userInteractionData?.data?.learningSession?.sessionStatus;

      if (sessionStatus === "created") {
        setSessionCreationStatus("completed");
      }

      if (sessionStatus === "ongoing") {
        // pauseVideo() // removing this now as we don't want to pause the video when the page loads
        const sectionIndex = getSectionAccordindToCurrentDuration();
        setSessionCreationStatus("completed");
        // setSessionOverlayView('section_ongoing'); // removing this now as we don't want to show the section ongoing view when the page loads
        setSelectedSection(sectionIndex);
        setCurrentSection(sectionIndex);
        setSectionEndScreen('explore_quiz');
      }
    } else {
      // console.warn("[YouTube Debug] activeTabId is falsy, skipping further initialization.");
    }
  };

  // useEffect for initial mount and URL changes - combined into one
  useEffect(() => {
    if (!isYouTubeSite) {
      return;
    }

    const currentUrl = cleanYoutubeUrl(window.location.href);

    // Run on initial mount if not already initialized
    handleYouTubeVideoInitialization(currentUrl);

    const observer = new MutationObserver(async () => {
      const newUrl = cleanYoutubeUrl(window.location.href);
      if (currentUrlRef.current !== newUrl) {
        // Clear the previous URL from the initialized set when navigating away
        if (currentUrlRef.current) {
          initializedUrlsRef.current.delete(currentUrlRef.current);
        }

        currentUrlRef.current = newUrl;
        await handleYouTubeVideoInitialization(newUrl);
      }
    });

    // Watch for title changes (YouTube updates title on navigation)
    const titleElement = document.querySelector('title');
    if (titleElement) {
      observer.observe(titleElement, { childList: true });
    } else {
    }

    return () => {
      observer.disconnect();
    };
  }, [isYouTubeSite]);

  useEffect(() => {
    const messageListener = (message: any, sender: chrome.runtime.MessageSender, sendResponse: (response?: any) => void) => {
      if (message.action === "getYoutubeVideoProperties") {
        // Access current state directly instead of relying on closure
        sendResponse({
          video: {
            url: cleanYoutubeUrl(window.location.href),
            title: document.title,
            duration: Math.floor(getYoutubeVideoLength()),
            current_duration: Math.floor(getYoutubeVideoPlayHead()),
            category: videoCategory, // This will always get the current value
            channel: getYoutubeChannelName(),
            view: detectPlayerMode()
          },
          session: getSessionProperties(),
        });
      }
    };

    chrome.runtime.onMessage.addListener(messageListener);

    return () => {
      chrome.runtime.onMessage.removeListener(messageListener);
    };
  }, [videoCategory]); // Re-register when videoCategory changes

  const contextValue: CustomUIContextType = {
    mentoraiData,
    menteeData,
    isDisabled,
    interviewModeOn,
    practiceModeOn,
    userInteractionData,
    isUserInteractionDataFetched,
    showQuiz,
    currentIndex,
    quizGenerationProcessing,
    revisionNotesGenerationProcessing,
    totalVideoDurationInHMSFormat,
    extractingThumbnails,
    videoRef,
    isSessionCompleted,
    playerMode,
    isYouTubeThemeDark,
    cleanedYoutubeUrl,
    showSectionEndNotification,
    dynamicEasyActionsForThisVideo,
    dynamicEasyActionOptionVariant,
    showCurrentDynamicEasyAction,
    currentDynamicEasyAction,
    hideCurrentDynamicEasyAction,

    setUserInteractionData,
    handleHelperOptionClick,
    handleBoostLearningToggle,
    handleToggleRevisionNotes,
    handleBoostLearningSwitchOff,
    setCurrentIndex,
    setExtractingThumbnails,
    setShowQuiz,
    setIsSessionCompleted,
    setShowSectionEndNotification,

    // Learning Session States & Actions
    learningSession,
    streamingSections,
    sessionOverlayView,
    selectedSection,
    currentSection,
    sessionCreationStatus,
    sectionEndScreen,
    currentQuizIndex,
    setSessionOverlayView,
    setSelectedSection,
    setCurrentSection,
    setSessionCreationStatus,
    setSectionEndScreen,
    toggleLearningSession,
    stopLearningSession,
    selectSection,
    startSelectedSection,
    answerQuiz,
    nextQuiz,
    showSessionEndView,
    markSectionComplete,
    playVideo,
    pauseVideo,
    handleResumeVideo,
    checkForTranscriptAvailability,
    handleJumpToNextSection,
    setPlayerMode,
    markSectionOngoing,
    markSectionEndScreenShown,
    trackCustomUIEvent,
    getCurrentSectionProperties,
    getSectionProperties,
    hideOverlay,
    getSectionAccordindToCurrentDuration,
    getVideoProperties,
    getSessionProperties,
  };

  return (
    <CustomUIContext.Provider value={contextValue}>
      {children}
    </CustomUIContext.Provider>
  );
};

export const useCustomUI = () => {
  const context = useContext(CustomUIContext);
  if (context === undefined) {
    throw new Error("useCustomUI must be used within a CustomUIProvider");
  }
  return context;
};

export default CustomUIContext;
