// Add this function at the top level of the component
const waitForYouTubeVideoCategory = (): Promise<string | null> => {
  return new Promise((resolve) => {
    // First, try to get it immediately
    const getCategory = () => {
      const scripts = [...document.querySelectorAll('script[type="application/ld+json"]')]
        .filter(s => s.textContent?.includes('"@type"') && s.textContent?.includes('VideoObject'));
      const last = scripts[scripts.length - 1];
      return last ? JSON.parse(last.textContent || "{}").genre : null;
    };

    const category = getCategory();
    if (category) {
      resolve(category);
      return;
    }

    // If not available, set up a MutationObserver to watch for it
    const observer = new MutationObserver(() => {
      const category = getCategory();
      if (category) {
        observer.disconnect();
        resolve(category);
      }
    });

    // Watch for script tags being added to the document
    observer.observe(document.head, {
      childList: true,
      subtree: true
    });

    // Fallback timeout after 10 seconds
    setTimeout(() => {
      observer.disconnect();
      resolve(null);
    }, 10000);
  });
};

type YouTubeVideoMeta = {
  title: string | null;
  category: string | null;
  url: string | null;
};

let lastYouTubeVideoMeta: YouTubeVideoMeta = {
  title: null,
  category: null,
  url: null,
};

const extractCurrentYouTubeVideoMeta = (): YouTubeVideoMeta => {
  const currentUrl = window.location.href;
  const urlObj = new URL(currentUrl);
  const currentVideoId = urlObj.searchParams.get("v");

  const scripts = [...document.querySelectorAll('script[type="application/ld+json"]')]
    .filter(s => s.textContent?.includes('"@type"') && s.textContent?.includes('VideoObject'));

  let title: string | null = null;
  let category: string | null = null;

  if (scripts.length > 0) {
    // Prefer the script whose url/embedUrl contains current video id; fallback to the last script
    let chosen: HTMLScriptElement | null = null;
    for (let i = scripts.length - 1; i >= 0; i--) {
      const cand = scripts[i];
      try {
        const json = JSON.parse(cand.textContent || "{}");
        const jsonUrl: string | undefined = json.url || json.embedUrl || json.contentUrl;
        if (currentVideoId && jsonUrl && jsonUrl.includes(currentVideoId)) {
          chosen = cand as HTMLScriptElement;
          break;
        }
      } catch { }
    }
    const last = chosen || scripts[scripts.length - 1];
    try {
      const json = JSON.parse(last.textContent || "{}");
      title = json.name || null;
      category = json.genre || null;
    } catch { }
  }

  if (!title) {
    title = document.title || null;
  }

  return { title, category, url: currentUrl };
};

const waitForYouTubeLdForCurrentVideo = (timeoutMs: number = 10000): Promise<void> => {
  return new Promise((resolve) => {
    const urlObj = new URL(window.location.href);
    const currentVideoId = urlObj.searchParams.get("v");
    const hasMatch = () => {
      const scripts = [...document.querySelectorAll('script[type="application/ld+json"]')]
        .filter(s => s.textContent?.includes('"@type"') && s.textContent?.includes('VideoObject')) as HTMLScriptElement[];
      for (let i = scripts.length - 1; i >= 0; i--) {
        try {
          const json = JSON.parse(scripts[i].textContent || "{}");
          const jsonUrl: string | undefined = json.url || json.embedUrl || json.contentUrl;
          if (currentVideoId && jsonUrl && jsonUrl.includes(currentVideoId)) {
            return true;
          }
        } catch { }
      }
      return false;
    };

    if (hasMatch()) {
      resolve();
      return;
    }

    const observer = new MutationObserver(() => {
      if (hasMatch()) {
        observer.disconnect();
        resolve();
      }
    });
    observer.observe(document.head, { childList: true, subtree: true });

    setTimeout(() => {
      observer.disconnect();
      resolve();
    }, timeoutMs);
  });
};

const getFreshYouTubeVideoMeta = async (): Promise<{ videoTitle: string | null; videoCategory: string | null; changed: boolean }> => {
  // First extraction
  let meta = extractCurrentYouTubeVideoMeta();

  // If category is missing, wait for it to appear via ld+json observer
  if (!meta.category) {
    const awaitedCategory = await waitForYouTubeVideoCategory();
    if (awaitedCategory) {
      meta = extractCurrentYouTubeVideoMeta();
    }
  }

  // Ensure we use ld+json belonging to the current video id; if not found yet, wait briefly and re-extract
  try {
    const urlObj = new URL(window.location.href);
    const currentVideoId = urlObj.searchParams.get("v");
    if (currentVideoId) {
      const scripts = [...document.querySelectorAll('script[type="application/ld+json"]')]
        .filter(s => s.textContent?.includes('"@type"') && s.textContent?.includes('VideoObject')) as HTMLScriptElement[];
      let matched = false;
      for (let i = scripts.length - 1; i >= 0; i--) {
        try {
          const json = JSON.parse(scripts[i].textContent || "{}");
          const jsonUrl: string | undefined = json.url || json.embedUrl || json.contentUrl;
          if (jsonUrl && jsonUrl.includes(currentVideoId)) { matched = true; break; }
        } catch { }
      }
      if (!matched) {
        await waitForYouTubeLdForCurrentVideo();
        meta = extractCurrentYouTubeVideoMeta();
      }
    }
  } catch { }

  const changed =
    meta.title !== lastYouTubeVideoMeta.title ||
    meta.category !== lastYouTubeVideoMeta.category ||
    meta.url !== lastYouTubeVideoMeta.url;

  if (changed) {
    lastYouTubeVideoMeta = meta;
    return { videoTitle: meta.title, videoCategory: meta.category, changed: true };
  }

  return { videoTitle: null, videoCategory: null, changed: false };
};

