import React, { useEffect, useState, useRef } from "react";
import { useCustomUI } from "../../contexts/custom-ui-context/custom-ui-context";
import CreatingOverlay from "./overlays/createing-overlay";
import CreatedOverlay from "./overlays/created-overlay";
import CrossWhiteIcon from "../../assets/icons/cross-white.svg";
import SectionsTimeline from "./sections-timeline/sections-timeline";
// Import other overlay components as they are created
import SectionStartOverlay from "./overlays/SectionStartOverlay";
import SectionOngoingOverlay from "./overlays/SectionOngoingOverlay";
import SectionEndOverlay from "./overlays/SectionEndOverlay";
import SessionEndOverlay from "./overlays/SessionEndOverlay";
import MentorAiButton from "../../../common/button/mentorai-button";
// import { useChat } from "../../contexts/chat-context/chat-context";
// import ChatContainer from "../custom-actions/youtube/youtube-sidesection/chat-container/chat-container";
import Tippy from "@tippyjs/react";
import { AnimatePresence, motion } from "framer-motion";
import FirstTimeLearningSessionOverlay from "./overlays/first-time-learning-session-overlay";

type Props = {
  isSidePanelOpen: boolean;
}

const VideoOverlayContent: React.FC<Props> = ({ isSidePanelOpen }) => {
  const {
    sessionOverlayView,
    extractingThumbnails,
    isSessionCompleted,
    playerMode,
    selectedSection,
    hideOverlay
  } = useCustomUI();
  const appendLocations = document.querySelector("#movie_player");
  const customUiElementAtAppendLocation: any =
    appendLocations?.querySelector(".customUI-added");
  const [showContentInsideOverlay, setShowContentInsideOverlay] = useState({
    mainContent: false,
  });
  // const {
  //   mentoraiData: chatMentorAiData,
  //   menteeData,
  //   activeTabUrl,
  //   chatMessages,
  //   isLiveMessageStreaming,
  //   loading,
  //   lastAssistantMessage,
  //   sendMessage,
  //   userQuery,
  //   liveMessages,
  //   setLiveMessages,
  //   userLiveMessage,
  //   chatUsageData,
  // } = useChat();

  const isPlayerModeDefault = playerMode === "DEFAULT";
  const isPlayerModeTheatre = playerMode === "THEATRE";
  const [transitionDirection, setTransitionDirection] = useState<'up' | 'down'>('up');

  if (customUiElementAtAppendLocation) {
    if (sessionOverlayView === "hidden") {
      customUiElementAtAppendLocation.style.height = "0px";
    } else {
      customUiElementAtAppendLocation.style.height = "100%";
    }
  }

  let content: any = null;
  useEffect(() => {
    if (sessionOverlayView) {
      if (sessionOverlayView !== "hidden") {
        setTimeout(() => {
          setShowContentInsideOverlay((prev) => ({
            ...prev,
            mainContent: true
          }));
        }, 300)
      } else {
        setShowContentInsideOverlay((prev) => ({
          ...prev,
          mainContent: false,
        }));
      }
    }
  }, [sessionOverlayView]);

  switch (sessionOverlayView) {
    case "first_time_learning_session":
      content = <FirstTimeLearningSessionOverlay />;
      break;
    case "creating":
      content = <CreatingOverlay />;
      break;
    case "created":
      content = <CreatedOverlay />;
      // content = <CreatingOverlay />;

      break;
    case "section_start":
      content = <SectionStartOverlay />;
      // content = <div>Section Starting... (Placeholder)</div>;
      break;
    case "section_ongoing":
      content = <SectionOngoingOverlay isSidePanelOpen={isSidePanelOpen} />;
      // content = <SessionEndOverlay />;

      break;
    case "section_end":
      content = <SectionEndOverlay isSidePanelOpen={isSidePanelOpen} />;
      // content = <div>Section Ended - Quizzes incoming! (Placeholder)</div>;
      break;
    case "session_end":
      content = <SessionEndOverlay />;
      break;
    default:
      return null;
  }



  // console.log("showContentInsideOverlay", showContentInsideOverlay);
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.3, ease: "easeInOut" }}
      className={`w-full h-full video-overlay-container
      ${isSessionCompleted
          ? "bg-yt-session-completed-bg"
          : "bg-yt-session-default-bg"
        }
    `}
      style={{
        borderRadius: "12px",
        paddingLeft: isPlayerModeDefault ? "16px" : isPlayerModeTheatre ? "32px" : "48px",
        paddingRight: isPlayerModeDefault ? "52px" : isPlayerModeTheatre ? "0px" : "0px"
      }}
    >
      <div
        className="flex h-full w-full"
        style={{
          gap: isPlayerModeDefault ? "32px" : isPlayerModeTheatre ? "40px" : "48px"
        }}
      >
        {showContentInsideOverlay?.mainContent ?
          <motion.div
            initial={{ x: '-10px', opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            transition={{ duration: 0.3, ease: "easeInOut" }}
            className="flex h-full w-full"
            style={{
              gap: isPlayerModeDefault ? "32px" : isPlayerModeTheatre ? "40px" : "48px"
            }}
          >
            {sessionOverlayView !== 'first_time_learning_session' && (
              <SectionsTimeline setTransitionDirection={setTransitionDirection} />
            )}
            <div
              className={`flex-1 flex h-full relative ${sessionOverlayView === 'first_time_learning_session'
                ? 'max-w-full'
                : (isPlayerModeDefault
                  ? 'max-w-[calc(100%-190px)]'
                  : isPlayerModeTheatre
                    ? 'max-w-[calc(100%-272px)]'
                    : 'max-w-[calc(100%-320px)]')
                }`}
            >
              <Tippy
                placement="left"
                content={
                  extractingThumbnails ? null :
                    <div style={{ padding: "2px 8px", backgroundColor: "#4B4E63", fontSize: "12px", color: "#f2f2f2", borderRadius: "6px", height: "22px", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "Manrope, sans-serif" }}>
                      Press <span style={{ padding: "0px 4px", borderRadius: "2px", fontWeight: "600" }}>Esc</span> to close
                    </div>
                }
              >
                <div onClick={() => {
                  if (!extractingThumbnails) {
                    hideOverlay();
                  }
                }}
                  className={`absolute flex items-center`}
                  style={{
                    height: "28px",
                    width: "28px",
                    zIndex: 1000,
                    right: playerMode === 'DEFAULT' ? '-40px' : '-24px',
                    top: "16px",
                  }}
                >
                  <MentorAiButton
                    type="secondary"
                    rounded={true}
                    size="small"
                    onClick={() => { }}
                    disabled={extractingThumbnails}
                    aria-label="CloseOverlay"
                    style={{
                      height: isPlayerModeDefault ? "24px" : "28px",
                      width: isPlayerModeDefault ? "24px" : "28px",
                    }}
                  >
                    <img
                      src={CrossWhiteIcon}
                      alt="close"
                      style={{ width: 24, height: 24 }}
                    />
                  </MentorAiButton>
                </div>
              </Tippy>


              <AnimatePresence mode="wait">
                <motion.div
                  key={sessionOverlayView + '-' + selectedSection}
                  initial={{
                    opacity: 0,
                    y: transitionDirection === 'down' ? -60 : 60,
                    position: "absolute",
                    width: "100%",
                  }}
                  animate={{
                    opacity: 1,
                    y: 0,
                    position: "relative",
                    width: "100%",
                  }}
                  exit={{
                    opacity: 0,
                    y: transitionDirection === 'down' ? 60 : -60,
                    position: "absolute",
                    width: "100%",
                  }}
                  transition={{ duration: 0.3, ease: "easeInOut" }}
                  className="relative flex-1 my-auto overflow-y-auto scrollbar-hide max-h-[calc(100%-0px)]"
                  style={{ padding: "24px 24px 24px 0px" }}
                >
                  {content}
                </motion.div>
              </AnimatePresence>
            </div>
          </motion.div>
          :
          null
        }

        {/*{(playerMode !== "DEFAULT" && sessionOverlayView !== "creating" && sessionOverlayView !== "created" && sessionOverlayView !== "first_time_learning_session" && showContentInsideOverlay.mainContent) && (
          <ChatContainer
            classNames={{
              chatContainerClassName: "!bg-[#14161F80] max-w-[350px]  min-w-[300px]",
              mainChatContainerClassName: "px-[24px] !bg-[#14161F80]",
              messagesContainerWrapperClassName: "max-h-[calc(100%-70px)]",
              messagesInputContainerWrapperClassName: "p-6 !bg-[#14161F80]",
              messagesContainerClassName: "!bg-[rgba(20,22,31,0.50)]",
              userMessageWrapperClassName: "!bg-[rgba(33,36,49,0.75)]",
              aiMessageWrapperClassName: "!bg-transparent",
            }}
            mentoraiData={chatMentorAiData}
            menteeData={menteeData}
            activeTabUrl={activeTabUrl}
            chatMessages={chatMessages}
            isLiveMessageStreaming={isLiveMessageStreaming}
            loading={loading}
            lastAssistantMessage={lastAssistantMessage}
            sendMessage={sendMessage}
            userQuery={userQuery}
            liveMessages={liveMessages}
            setLiveMessages={setLiveMessages}
            userLiveMessage={userLiveMessage}
            chatUsageData={chatUsageData}
            playerMode={"NOT_DEFAULT"}
          />
        )}
        */}
      </div>
    </motion.div>
  );
};

export default VideoOverlayContent;
