import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { autoApplyManager } from '../../features/linkedin-auto-apply/AutoApplyManager';
import AutoApplyOverlay from '../../features/linkedin-auto-apply/AutoApplyOverlay';
import AutoApplyIcon from '../../assets/icons/auto-apply-icon.svg';

interface AutoApplyWidgetProps {
    menteeData?: any;
}

const AutoApplyWidget: React.FC<AutoApplyWidgetProps> = ({ menteeData }) => {
    const [isRunning, setIsRunning] = useState(false);
    const [logs, setLogs] = useState<string[]>([]);
    const [keywords, setKeywords] = useState('');
    const [location, setLocation] = useState('');
    const logsEndRef = useRef<HTMLDivElement>(null);
    const [isAutoApplyHovered, setIsAutoApplyHovered] = useState(false);
    const [isAutoApplyCardHovered, setIsAutoApplyCardHovered] = useState(false);
    const [autoApplyHideTimeout, setAutoApplyHideTimeout] = useState<NodeJS.Timeout | null>(null);

    const handleAutoApplyIconMouseEnter = () => {
        if (autoApplyHideTimeout) {
            clearTimeout(autoApplyHideTimeout);
            setAutoApplyHideTimeout(null);
        }
        setIsAutoApplyHovered(true);
    };

    const handleAutoApplyIconMouseLeave = () => {
        if (!isAutoApplyCardHovered) {
            const timeout = setTimeout(() => {
                setIsAutoApplyHovered(false);
            }, 300);
            setAutoApplyHideTimeout(timeout);
        }
    };

    const handleAutoApplyCardMouseEnter = () => {
        if (autoApplyHideTimeout) {
            clearTimeout(autoApplyHideTimeout);
            setAutoApplyHideTimeout(null);
        }
        setIsAutoApplyCardHovered(true);
    };

    const handleAutoApplyCardMouseLeave = () => {
        setIsAutoApplyCardHovered(false);
        const timeout = setTimeout(() => {
            setIsAutoApplyHovered(false);
        }, 200);
        setAutoApplyHideTimeout(timeout);
    };

    const handleAutoApplyClick = async () => {
        // Send activateJobAgent - background will open side panel and relay message
        chrome.runtime.sendMessage({ action: 'activateJobAgent', force: true });

        try {
            const candidateId = menteeData?.recordId || menteeData?.dlData?.recordId;
            if (!candidateId) {
                console.log('[AutoApply] Waiting for authentication/candidate ID...');
                return;
            }

            console.log('[AutoApply] Fetching career profile...');

            // Use background script to fetch to avoid CSP blocks
            const result = await chrome.runtime.sendMessage({
                action: 'fetch_calls',
                fetch_call: 'fetch_career_profile',
                candidate_id: candidateId
            });

            if (result.success && result.data) {
                const profile = result.data;
                console.log('[AutoApply] Career profile fetched successfully');

                const roles = Array.isArray(profile.preferredRole)
                    ? profile.preferredRole.map((r: string) => `"${r}"`).join(' OR ')
                    : `"${profile.preferredRole}"`;

                const locations = Array.isArray(profile.preferredJobLocations)
                    ? profile.preferredJobLocations.join(', ')
                    : profile.preferredJobLocations;

                if (!roles || roles === '""') {
                    console.log('[AutoApply] Error: No preferred roles found in profile');
                    return;
                }

                // Save resume URL for AutoApplyManager
                if (profile.resume) {
                    await chrome.storage.local.set({ resumeUrl: profile.resume });
                }

                console.log(`[AutoApply] Keywords: ${roles}, Location: ${locations || 'Global'}`);

                // Construct search URL with Easy Apply filter (f_AL=true)
                const targetUrl = `https://www.linkedin.com/jobs/search/?keywords=${encodeURIComponent(roles)}&location=${encodeURIComponent(locations || '')}&f_AL=true`;
                const currentUrl = window.location.href;

                const hasCorrectKeywords = currentUrl.includes(encodeURIComponent(roles).replace(/%20/g, '+')) || currentUrl.includes(encodeURIComponent(roles));
                const hasCorrectLocation = !locations || currentUrl.includes(encodeURIComponent(locations).replace(/%20/g, '+')) || currentUrl.includes(encodeURIComponent(locations));

                if (!currentUrl.includes('/jobs/search/') || !hasCorrectKeywords || !hasCorrectLocation) {
                    console.log('[AutoApply] Navigating to LinkedIn jobs search with preferences...');
                    await chrome.storage.local.set({
                        autoApplyState: { running: true },
                        autoApplyConfig: { keywords: roles, location: locations || '' }
                    });
                    window.location.href = targetUrl;
                    return;
                }

                // Start manager if already on correct page - use singleton
                console.log('[AutoApply] Starting Auto Apply Agent on current page...');
                await chrome.storage.local.set({
                    autoApplyState: { running: true },
                    autoApplyConfig: { keywords: roles, location: locations || '' }
                });
                setIsRunning(true);
                autoApplyManager.start();
            } else {
                console.log(`[AutoApply] Error: Failed to fetch career profile. ${result.error || ''}`);
            }
        } catch (error) {
            console.log(`[AutoApply] Error in handleAutoApplyClick: ${error}`);
        }
    };

    const handleStop = async () => {
        console.log('[AutoApplyWidget] handleStop called, stopping autoApplyManager');
        autoApplyManager.stop();
        setIsRunning(false);
        await chrome.storage.local.set({
            autoApplyState: { running: false }
        });
    };

    // Setup log callback and message listeners
    useEffect(() => {
        // Use singleton manager
        autoApplyManager.setLogCallback((message) => {
            setLogs(prev => [...prev, message]);
        });

        const fetchAndStart = async () => {
            try {
                const candidateId = menteeData?.recordId || menteeData?.dlData?.recordId;
                if (!candidateId) {
                    setLogs(prev => [...prev, 'Waiting for authentication/candidate ID...']);
                    return;
                }

                setLogs(prev => [...prev, `Fetching your career profile...`]);
                
                // Use background script to fetch to avoid CSP blocks
                const result = await chrome.runtime.sendMessage({
                    action: 'fetch_calls',
                    fetch_call: 'fetch_career_profile',
                    candidate_id: candidateId
                });

                if (result.success && result.data) {
                    const profile = result.data;
                    setLogs(prev => [...prev, 'Career profile fetched successfully']);
                    
                    const roles = Array.isArray(profile.preferredRole) 
                        ? profile.preferredRole.map((r: string) => `"${r}"`).join(' OR ') 
                        : `"${profile.preferredRole}"`;
                    
                    const locations = Array.isArray(profile.preferredJobLocations) 
                        ? profile.preferredJobLocations.join(', ')
                        : profile.preferredJobLocations;

                    if (!roles || roles === '""') {
                        setLogs(prev => [...prev, 'Error: No preferred roles found in profile']);
                        return;
                    }

                    setKeywords(roles);
                    setLocation(locations || '');
                    
                    // Save resume URL for AutoApplyManager
                    if (profile.resume) {
                        await chrome.storage.local.set({ resumeUrl: profile.resume });
                    }

                    setLogs(prev => [...prev, `Selected search keywords: ${roles}`]);
                    setLogs(prev => [...prev, `Selected search location: ${locations || 'Global'}`]);
                    
                    // Construct search URL with Easy Apply filter (f_AL=true)
                    const targetUrl = `https://www.linkedin.com/jobs/search/?keywords=${encodeURIComponent(roles)}&location=${encodeURIComponent(locations || '')}&f_AL=true`;
                    const currentUrl = window.location.href;

                    const hasCorrectKeywords = currentUrl.includes(encodeURIComponent(roles).replace(/%20/g, '+')) || currentUrl.includes(encodeURIComponent(roles));
                    const hasCorrectLocation = !locations || currentUrl.includes(encodeURIComponent(locations).replace(/%20/g, '+')) || currentUrl.includes(encodeURIComponent(locations));

                    if (!currentUrl.includes('/jobs/search/') || !hasCorrectKeywords || !hasCorrectLocation) {
                        setLogs(prev => [...prev, 'Navigating to LinkedIn jobs search with your preferences...']);
                        await chrome.storage.local.set({ 
                            autoApplyState: { running: true },
                            autoApplyConfig: { keywords: roles, location: locations || '' }
                        });
                        window.location.href = targetUrl;
                        return;
                    }

                    // Start manager if already on page - use singleton
                    setIsRunning(true);
                    setLogs(prev => [...prev, 'Starting Auto Apply Agent on current page...']);
                    await autoApplyManager.start();
                    setIsRunning(false);
                } else {
                    setLogs(prev => [...prev, `Error: Failed to fetch career profile. ${result.error || ''}`]);
                }
            } catch (error) {
                setLogs(prev => [...prev, `Error in fetchAndStart: ${error}`]);
            }
        };

        // Listen for start/stop messages
        const messageListener = (message: any) => {
            if (message.action === 'startAutoApply') {
                fetchAndStart();
            } else if (message.action === 'stopAutoApply') {
                handleStop();
            }
        };
        chrome.runtime.onMessage.addListener(messageListener);

        // Check for pending start or auto-resume
        const checkState = async () => {
            const { autoApplyPending, autoApplyState, autoApplyConfig } = await chrome.storage.local.get(['autoApplyPending', 'autoApplyState', 'autoApplyConfig']);
            
            if (autoApplyPending) {
                const candidateId = menteeData?.recordId || menteeData?.dlData?.recordId;
                if (candidateId) {
                    await chrome.storage.local.remove('autoApplyPending');
                    fetchAndStart();
                } else {
                    setLogs(prev => [...prev, 'Auto-apply activation pending (waiting for auth)...']);
                }
            } else if (autoApplyState?.running && autoApplyConfig) {
                setKeywords(autoApplyConfig.keywords || '');
                setLocation(autoApplyConfig.location || '');
                setIsRunning(true);
                await autoApplyManager.start();
                setIsRunning(false);
            }
        };

        checkState();

        return () => {
            chrome.runtime.onMessage.removeListener(messageListener);
            // Always stop on cleanup - use singleton
            autoApplyManager.stop();
        };
    }, [menteeData]);

    // Scroll logs to bottom
    useEffect(() => {
        if (logsEndRef.current) {
            logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [logs]);

    // Cleanup timeout on unmount
    useEffect(() => {
        return () => {
            if (autoApplyHideTimeout) {
                clearTimeout(autoApplyHideTimeout);
            }
        };
    }, [autoApplyHideTimeout]);

    return (
        <>
            {/* Auto Apply Overlay - shows glowing border when running */}
            <AutoApplyOverlay
                isActive={isRunning}
                onStop={handleStop}
                theme="purple"
            />

            {/* Auto Apply Floating Button */}
            <motion.div
                style={{
                    position: 'fixed',
                    right: '6px',
                    zIndex: 9999999,
                    bottom: 160,
                }}
                onMouseEnter={handleAutoApplyIconMouseEnter}
                onMouseLeave={handleAutoApplyIconMouseLeave}
            >
                <img
                    onClick={handleAutoApplyClick}
                    src={AutoApplyIcon}
                    alt="Auto Apply Icon"
                    style={{
                        width: '32px',
                        height: '32px',
                        cursor: 'pointer'
                    }}
                />

                {/* Auto Apply Card - shows on hover */}
                <AnimatePresence>
                    {(isAutoApplyHovered || isAutoApplyCardHovered) && (
                        <motion.div
                            style={{
                                position: 'absolute',
                                bottom: '0px',
                                right: '44px',
                                display: 'flex',
                                alignItems: 'flex-start',
                                gap: '10px',
                                padding: '14px 10px 16px 12px',
                                borderRadius: '16px',
                                backgroundColor: '#0E121B',
                                width: '320px'
                            }}
                            initial={{ opacity: 0, y: -10 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -10 }}
                            transition={{
                                duration: 0.3,
                                ease: "easeOut",
                                type: "tween"
                            }}
                            onMouseEnter={handleAutoApplyCardMouseEnter}
                            onMouseLeave={handleAutoApplyCardMouseLeave}
                        >
                            <img
                                src={AutoApplyIcon}
                                alt="Auto Apply"
                                style={{
                                    width: '24px',
                                    height: '24px',
                                    minWidth: '24px',
                                    minHeight: '24px',
                                    borderRadius: '50%'
                                }}
                            />

                            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: '13px' }}>
                                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: '4px', alignSelf: 'stretch' }}>
                                    <div style={{
                                        alignSelf: 'stretch',
                                        color: 'white',
                                        fontWeight: 600,
                                        lineHeight: '20px',
                                        fontSize: '13px',
                                        letterSpacing: '0.065px'
                                    }}>
                                        Auto Apply to Jobs with Leeco
                                    </div>
                                    <div style={{
                                        alignSelf: 'stretch',
                                        color: 'rgba(255,255,255,0.8)',
                                        fontSize: '13px',
                                        lineHeight: '21px',
                                        letterSpacing: '-0.078px'
                                    }}>
                                        Let Leeco apply to jobs matching your profile — sit back while we do the heavy lifting.
                                    </div>
                                </div>

                                <button
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        if (isRunning) {
                                            handleStop();
                                        } else {
                                            handleAutoApplyClick();
                                        }
                                    }}
                                    style={{
                                        whiteSpace: 'nowrap',
                                        width: 'fit-content',
                                        display: 'flex',
                                        padding: '0 8px',
                                        justifyContent: 'center',
                                        alignItems: 'center',
                                        height: '20px',
                                        borderRadius: '5px',
                                        fontWeight: 600,
                                        fontSize: '12px',
                                        letterSpacing: '-0.12px',
                                        backgroundColor: isRunning ? '#EF4444' : 'white',
                                        color: isRunning ? 'white' : '#2B303B',
                                        border: 'none',
                                        cursor: 'pointer'
                                    }}
                                    onMouseEnter={(e) => {
                                        e.currentTarget.style.backgroundColor = isRunning ? '#DC2626' : '#E5E5E5';
                                    }}
                                    onMouseLeave={(e) => {
                                        e.currentTarget.style.backgroundColor = isRunning ? '#EF4444' : 'white';
                                    }}
                                >
                                    {isRunning ? 'Stop' : 'Start Auto Apply'}
                                </button>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </motion.div>
        </>
    );
};

export default AutoApplyWidget;
