import { SessionCreationStatus } from "../types/youtube-session";

export function getStatus(sessionCreationStatus: SessionCreationStatus) {
    if (sessionCreationStatus === 'checking_transcription') return 'checkingTranscript';
    if (sessionCreationStatus === 'transcription_failed') return 'transcriptError';
    if (sessionCreationStatus === 'generating_section') return 'sectionGenerating';
    if (sessionCreationStatus === 'section_creation_failed') return 'sectionCreationError';
    if (sessionCreationStatus === 'generating_quiz') return 'quizGenerating';
    if (sessionCreationStatus === 'quiz_creation_failed') return 'quizCreationError';
    if (sessionCreationStatus === 'completed') return 'idle';
    if (sessionCreationStatus === null) return 'stopped';
    return 'idle';
}
