import { useState, useEffect, useCallback } from 'react';
import {
    detectGeeksforGeeksTheme,
    detectLeetCodeTheme,
    detectWebsiteTheme,
    createThemeObserver,
    ThemeType
} from '../utils/theme-detection';

/**
 * React hook for detecting and monitoring website themes
 * Only works for GeeksforGeeks and LeetCode websites
 * Returns null/undefined values for other websites
 */
export const useThemeDetection = () => {
    const [theme, setTheme] = useState<ThemeType | null>(null);
    const [website, setWebsite] = useState<string | null>(null);
    const [isDark, setIsDark] = useState<boolean | null>(null);

    // Detect initial theme and website
    const detectInitialTheme = useCallback(() => {
        const websiteTheme = detectWebsiteTheme();
        if (websiteTheme) {
            setTheme(websiteTheme.theme);
            setWebsite(websiteTheme.website);
            setIsDark(websiteTheme.theme === 'dark');
        } else {
            // For non-supported websites, set everything to null
            setTheme(null);
            setWebsite(null);
            setIsDark(null);
        }
    }, []);

    // Update theme state
    const updateTheme = useCallback((newTheme: ThemeType) => {
        setTheme(newTheme);
        setIsDark(newTheme === 'dark');
    }, []);

    useEffect(() => {
        // Detect initial theme
        detectInitialTheme();

        // Only set up theme observer for supported websites
        let observer: MutationObserver | null = null;

        if (website === 'leetcode') {
            observer = createThemeObserver('leetcode', updateTheme);
        } else if (website === 'geeksforgeeks') {
            observer = createThemeObserver('geeksforgeeks', updateTheme);   
        }

        // Cleanup observer on unmount
        return () => {
            if (observer) {
                observer.disconnect();
            }
        };
    }, [website, detectInitialTheme, updateTheme]);

    // Manual theme detection functions for specific websites
    const getLeetCodeTheme = useCallback(() => {
        if (website !== 'leetcode') return null;
        const leetcodeTheme = detectLeetCodeTheme();
        updateTheme(leetcodeTheme);
        return leetcodeTheme;
    }, [website, updateTheme]);

    const getGeeksforGeeksTheme = useCallback(() => {
        if (website !== 'geeksforgeeks') return null;
        const gfgTheme = detectGeeksforGeeksTheme();
        updateTheme(gfgTheme);
        return gfgTheme;
    }, [website, updateTheme]);


    // Only return values if we're on a supported website
    if (!website || !theme || isDark === null) {
        return {
            theme: null,
            website: null,
            isDark: null,
            isLight: null,
            getLeetCodeTheme,
            getGeeksforGeeksTheme,
            updateTheme
        };
    }

    return {
        theme,
        website,
        isDark,
        isLight: isDark === null ? null : !isDark,
        getLeetCodeTheme,
        getGeeksforGeeksTheme,
        updateTheme
    };
};

/**
 * Specific hook for LeetCode theme detection
 * Only works on LeetCode website, returns null values elsewhere
 */
export const useLeetCodeTheme = () => {
    const [theme, setTheme] = useState<ThemeType | null>(null);
    const [isDark, setIsDark] = useState<boolean | null>(null);

    const updateTheme = useCallback((newTheme: ThemeType) => {
        setTheme(newTheme);
        setIsDark(newTheme === 'dark');
    }, []);

    useEffect(() => {
        // Check if we're on LeetCode
        if (window.location.hostname !== 'leetcode.com') {
            setTheme(null);
            setIsDark(null);
            return;
        }

        // Detect initial theme
        const initialTheme = detectLeetCodeTheme();
        updateTheme(initialTheme);

        // Set up observer for LeetCode
        const observer = createThemeObserver('leetcode', updateTheme);

        return () => observer.disconnect();
    }, [updateTheme]);

    return {
        theme,
        isDark,
        isLight: isDark === null ? null : !isDark
    };
};

/**
 * Specific hook for GeeksforGeeks theme detection
 * Only works on GeeksforGeeks website, returns null values elsewhere
 */
export const useGeeksforGeeksTheme = () => {
    const [theme, setTheme] = useState<ThemeType | null>(null);
    const [isDark, setIsDark] = useState<boolean | null>(null);

    const updateTheme = useCallback((newTheme: ThemeType) => {
        setTheme(newTheme);
        setIsDark(newTheme === 'dark');
    }, []);

    useEffect(() => {
        // Check if we're on GeeksforGeeks
        if (window.location.hostname !== 'geeksforgeeks.org' && window.location.hostname !== 'www.geeksforgeeks.org') {
            setTheme(null);
            setIsDark(null);
            return;
        }

        // Detect initial theme
        const initialTheme = detectGeeksforGeeksTheme();
        updateTheme(initialTheme);

        // Set up observer for GeeksforGeeks
        const observer = createThemeObserver('geeksforgeeks', updateTheme);

        return () => observer.disconnect();
    }, [updateTheme]);

    return {
        theme,
        isDark,
        isLight: isDark === null ? null : !isDark
    };
};
