import {
  extractSessionType,
  getChatMessagesFromStorage,
  getTodaysDate,
  calculateDailyMessagesLeft,
  safelyIncrementExtensionUsedDaysCount,
  getCurrentExtensionUsedDaysCount,
} from "../../../utils/helper";
