export const NPS_STATUS = {
  HIDE: "hide",
  SHOW: "show",
  SUBMITTED: "submitted",
  CANCELED: "canceled",
};

interface StartSessionConfig {
  problemText: string;
}
interface useChatConversationsProps {
  menteeData: any;
  mentoraiData: any;
  menteeSubscription: any;
  menteeDataLoading: boolean;
  setScreen: (screen: SCREEN) => void;
}

interface ChatMessage {
  props: {
    model: {
      id: string;
      message: string;
      sentTime: string;
      sender: string;
      direction: string;
      position: string;
      senderPhotoUrl?: string;
      senderName?: string;
    };
    children?: JSX.Element;
    error?: boolean;
    theme?: "red" | "yellow";
  };
}

export interface ChatUsageData {
  isPaidUser: boolean;
  dailyMessageLimit: number;
  dailyMessagesLeft: number;
  todayOutgoingChatMessagesCount: number;
  menteeDataLoading: boolean;
}

const getLocalConversationFeedbackStatus = async (): Promise<string> => {
  const result = await chrome.storage.local.get("conversation_feedback");
  if (result.conversation_feedback) {
    if (result.conversation_feedback.date !== getTodaysDate()) {
      return "not_shown_today"; // if date is not today, then return not_shown
    } else {
      return result.conversation_feedback?.status || "not_shown_today"; // if date is today, then return status
    }
  }
  return "not_shown_today"; // if no conversation_feedback, then return not_shown
};

const useChatConversations = ({
  menteeData,
  mentoraiData,
  menteeSubscription,
  menteeDataLoading,
  setScreen,
}: useChatConversationsProps) => {
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [loading, setLoading] = useState(false);
  const { activeTabUrl, interviewModeStatus, interviewCount, practiceModeStatus, practiceCount, setPracticeCount, setPracticeModeStatus, setShowSignupModal, setSelectedText } =
    useContext(PageContext);

  const { parseChatMessagesForBulkMessagesPayload } = useBulkMessages();

  const [isPlansSheetOpen, setIsPlansSheetOpen] = useState(false);

  const [liveMessages, setLiveMessages] = useState<ChatMessage[]>([]);
  const [userLiveMessage, setUserLiveMessage] = useState<ChatMessage[]>([]);
  const [isLiveMessageStreaming, setisLiveMessageStreaming] = useState(false);
  const [startSessionConfig, setStartSessionConfig] = useState<StartSessionConfig>({ problemText: "" });
  const [conversationFeedbackStatus, setConversationFeedbackStatus] = useState("not_shown_today");
  const [npsStatus, setNpsStatus] = useState(NPS_STATUS.HIDE);
  const [npsData, setNpsData] = useState<any>(null);
  const hasActiveSubscription = checkValidSubscription(menteeSubscription);

  const dailyMessageLimit = menteeData?.extensionDailyMessageLimit || 20;

  const [chatUsageData, setChatUsageData] = useState<ChatUsageData>({
    isPaidUser: hasActiveSubscription,
    dailyMessageLimit: dailyMessageLimit,
    dailyMessagesLeft: dailyMessageLimit,
    todayOutgoingChatMessagesCount: 0,
    menteeDataLoading: menteeDataLoading,
  });

  useEffect(() => {
    const updateChatUsageData = async () => {
      const dailyMessagesLeft = await calculateDailyMessagesLeft(dailyMessageLimit);
      const todayOutgoingChatMessagesCount = dailyMessageLimit - dailyMessagesLeft;

      setChatUsageData({
        isPaidUser: hasActiveSubscription,
        dailyMessageLimit: dailyMessageLimit,
        dailyMessagesLeft: dailyMessagesLeft,
        todayOutgoingChatMessagesCount: todayOutgoingChatMessagesCount,
        menteeDataLoading: menteeDataLoading,
      });
    };

    updateChatUsageData();
  }, [chatMessages.length, menteeData, hasActiveSubscription, dailyMessageLimit, menteeDataLoading]);

  const transformChatMessages = (chatMessages: any) =>
    chatMessages?.map(
      ({
        sent_by: sender,
        text: text,
        createdAt: createdAt,
        id: id,
      }: {
        sent_by: string;
        text: string;
        createdAt: number;
        id: string;
      }) => ({
        props: {
          model: {
            id: id || new Date().getTime().toString(),
            message: text,
            sentTime: (createdAt || 0).toString(),
            sender,
            direction: sender !== "assistant" ? "outgoing" : "incoming",
            position: "single",
            senderPhotoUrl: sender === "user" ? menteeData?.photoUrl :"https://firebasestorage.googleapis.com/v0/b/preplaced-dev.appspot.com/o/leeco_profile.webp?alt=media&token=f25e8955-20ff-48cf-93c7-ef274ad856c2",
            senderName: sender === "user" ? menteeData?.name : mentoraiData?.name,
          },
          children: <></>,
        },
      }),
    );

  const fetchMessages = async (newMenteeData?: any) => {
    try {
      // if (chatMessages.length === 0) {
      //   setLoading(true);
      // }
      const url = `/extension/get_conversation_messages?user_id=${newMenteeData?.recordId || menteeData?.recordId
        }&mentor_ai_id=${mentoraiData?.recordId || "recdIrEzeo6GIXB2C"}&limit=100&create_record_for_empty_conversation=false`;
      const response = await handleAibackendGet(url, {});
      if (response?.data?.refetch) {
        setChatMessages([]);
        const menteeData = await refetchAndUpdateMenteeData();
        fetchMessages(menteeData);
      }
      if (response?.data?.length === 0) {
        const easyActions = activeTabUrl.includes("youtube.com")
          ? `#-#-#[easy action start]
                    {"easy_action":"selector","data": ["I have a doubt!", "What is being discussed now ?", "Simplify this video for me"]}
                    [easy action end]#-#-#`
          : `#-#-#[easy action start]
                    {"easy_action":"selector","data": ["Help me understand the approach", "Help me understand the question", "What is wrong with my code ?"]}
                    [easy action end]#-#-#`;
        response.data.push({
          id: "msg_3yeGEJ7lwnWae6c7kuLDj9",
          text: `Hi! How can help today? ${easyActions}`,
          custom: {},
          content: [
            {
              type: "text",
              children: ["Hi there! How can I assist you today?"],
            },
          ],
          createdAt: new Date().getTime().toString(),
          sent_by: "assistant",
        });
      }

      if (interviewModeStatus === "ONGOING") {
        response.data = response.data.filter((message: any) => {
          const matches = message.custom?.interview_mode === "true" && message.custom?.interview_count === `${interviewCount}`;
          return matches;
        });
      }

      if (practiceModeStatus === "PM_ONGOING") {
        response.data = response.data.filter((message: any) => {
          const matches = message.custom?.practice_mode === "true" && message.custom?.practice_count === `${practiceCount || 1}`;
          return matches;
        });
      }

      const sortedMessages = response.data.sort(
        (a: any, b: any) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
      );

      const transformedMessages = transformChatMessages(sortedMessages).reverse();
      setLoading(false);
      setChatMessages(transformedMessages);
      // Store messages in chrome storage
      try {
        await chrome.storage.local.set({ chatMessages: sortedMessages });
      } catch (error) {
        console.error("Error storing chat messages:", error);
      }
    } catch (error) {
      console.log(error);
      setLoading(false);
    }
  };

  const addLiveMessagesToChatMessages = async () => {
    setChatMessages((prevChatMessages: any) => {
      const newChatMessages = [...prevChatMessages, ...userLiveMessage, ...liveMessages];
      chrome.storage.local.set({
        chatMessages: convertChatMessagesToBackendFormat(newChatMessages, activeTabUrl).reverse(),
      });
      return newChatMessages;
    });
    const activeTab = (await chrome.tabs.query({ active: true, currentWindow: true }))[0];
    if (activeTab?.id) {
      chrome.tabs.sendMessage(activeTab?.id, {
        action: "syncMessagesFromSidePanel",
      });
    }
  };

  useEffect(() => {
    // add liveMessages to chatMessages adter live message streaming is completed
    if (!isLiveMessageStreaming && liveMessages.length > 0) {
      addLiveMessagesToChatMessages();
      setLiveMessages([]);
      setUserLiveMessage([]);
    }
  }, [isLiveMessageStreaming]);

  const setLiveMessageFromAssistant = async (reader: ReadableStreamDefaultReader) => {
    let currentTime = new Date().getTime().toString();
    let accumulatedMessage = "";

    while (true) {
      const { done, value } = await reader.read();

      if (done) {
        try {
          setisLiveMessageStreaming(false);
          chrome.storage.local.set({
            isLiveMessageStreaming: false,
          });
          // bulk message api call when there are more than 10 user messages (call just once)
          setTimeout(async () => {
            const lastestMessageFromLocalStorage = await chrome.storage.local.get("chatMessages");
            if (chatMessages.filter((message: any) => message.props.model.sender === "user").length === 10) {
              const bulkMessages = parseChatMessagesForBulkMessagesPayload(lastestMessageFromLocalStorage.chatMessages);
              const payload = {
                messages: bulkMessages?.messages.reverse() || [],
                user_id: menteeData?.recordId,
                mentor_ai_id: mentoraiData?.recordId || "recdIrEzeo6GIXB2C",
              };
              handleAibackendPost("/extension/add-messages", payload, {}, false);
            }
          }, 500)
        } catch (e) {
          console.log("error after stream completed", e);
        }
        break;
      }

      // Convert Uint8Array to string
      const letter = new TextDecoder().decode(value);
      accumulatedMessage += letter;
      if (accumulatedMessage.trim()) {
        setLiveMessages([
          {
            props: {
              model: {
                id: currentTime,
                message: accumulatedMessage,
                sentTime: currentTime,
                sender: "assistant",
                direction: "incoming",
                position: "single",
                senderPhotoUrl:"https://firebasestorage.googleapis.com/v0/b/preplaced-dev.appspot.com/o/leeco_profile.webp?alt=media&token=f25e8955-20ff-48cf-93c7-ef274ad856c2",
                senderName: mentoraiData?.name,
              },
              children: <></>,
            },
          },
        ]);
      }
      await new Promise(r => setTimeout(r, 50));
    }
  };

  const readStream = async (stream: ReadableStream) => {
    const reader = stream.getReader();
    setLiveMessageFromAssistant(reader);
  };

  const updateNpsFeedbackValues = async () => {
    await safelyIncrementExtensionUsedDaysCount();
  };

  const handleError = (error: any, message: string) => {
    console.error("Error in streaming response:", error);
    chrome.storage.local.set({
      pendingMessage: {
        message,
        timestamp: new Date().getTime(),
        userId: menteeData?.recordId,
        mentorAiId: mentoraiData?.recordId || "recdIrEzeo6GIXB2C",
        url: activeTabUrl,
      },
    });
    if (!chatMessages[chatMessages.length - 1].props.error) {
      setLiveMessages([
        {
          props: {
            model: {
              id: new Date().getTime().toString(),
              message: "An error occurred while sending your message. It should resolve once you retry.",
              sentTime: new Date().getTime().toString(),
              sender: "assistant",
              direction: "incoming",
              position: "single",
              senderPhotoUrl:"https://firebasestorage.googleapis.com/v0/b/preplaced-dev.appspot.com/o/leeco_profile.webp?alt=media&token=f25e8955-20ff-48cf-93c7-ef274ad856c2",
              senderName: mentoraiData?.name,
            },
            children: <></>,
            error: true,
          },
        },
      ]);
    }
    setisLiveMessageStreaming(false);
    chrome.storage.local.set({
      isLiveMessageStreaming: false,
    });
  };

  /**
   * Fetches the transcript text for a 20-second window from the current duration.
   * @param cleanedYoutubeUrl The cleaned YouTube URL key for the queue.
   * @returns The concatenated transcript text for the 20-second window.
   */
  const getTranscriptForCurrentWindow = async (
    cleanedYoutubeUrl: string,
    activeTab?: chrome.tabs.Tab,
    playHead?: string,
  ): Promise<string> => {
    // Get currentDuration and youtube_transcription_queue from chrome.storage.local
    const { youtube_transcription_queue } = await chrome.storage.local.get("youtube_transcription_queue");

    let transcriptionQueue = youtube_transcription_queue;
    if (!transcriptionQueue || !transcriptionQueue[cleanedYoutubeUrl]) {
      const response = await chrome.tabs.sendMessage(activeTab?.id || 0, {
        action: "getTranscript",
        url: cleanedYoutubeUrl,
      });

      if (!response?.isTranscriptAvailable) {
        return "";
      } else {
        const { youtube_transcription_queue } = await chrome.storage.local.get("youtube_transcription_queue");
        transcriptionQueue = youtube_transcription_queue;
      }
    }

    const transcriptArray = transcriptionQueue[cleanedYoutubeUrl];

    if (!transcriptArray) {
      return "";
    }

    // If the transcript is a string, try to parse it as JSON
    let transcriptSegments: any[] = [];
    if (typeof transcriptArray === "string") {
      try {
        transcriptSegments = JSON.parse(transcriptArray);
      } catch (err) {
        return "";
      }
    } else {
      transcriptSegments = transcriptArray;
    }

    // Center the window around playHead: 10 seconds before and 10 seconds after
    const center = Number(playHead) || 0;
    let startWindow = center - 10;
    let endWindow = center + 10;

    if (startWindow < 0) {
      endWindow += Math.abs(startWindow);
      startWindow = 0;
    }

    // Filter segments that overlap with the window
    const relevantSegments = transcriptSegments.filter((segment: any) => {
      const segStart = Number(segment.start);
      const segEnd = segStart + Number(segment?.duration);
      // Overlaps if segment starts before window ends and ends after window starts
      return segStart < endWindow && segEnd > startWindow;
    });

    // Concatenate the text of relevant segments
    const result = relevantSegments.map((seg: any) => seg.text).join(" ");
    return result;
  };


  const refetchAndUpdateMenteeData = async () => {
    let refetchedMenteeData;
    let attempts = 0;
    const maxAttempts = 3;
    const prevRecordId = menteeData?.recordId;

    do {
      refetchedMenteeData = await chrome.runtime.sendMessage({
        action: "fetch_calls",
        fetch_call: "fetch_mentee",
        refetch: true,
      });
      if (refetchedMenteeData.mentee_data?.recordId !== prevRecordId) {
        sendAnalyticsWithBackend(menteeData?.email || "", activeTabUrl, "Mentee Refetch Success", {});
        break;
      }
      attempts++;
      if (attempts < maxAttempts) {
        await new Promise((res) => setTimeout(res, 2000));
      }
    } while (attempts < maxAttempts);

    if (attempts === maxAttempts) {
      sendAnalyticsWithBackend(menteeData?.email || "", activeTabUrl, "Mentee Refetch Failed", {});
    }

    await chrome.storage.local.set({
      menteeData: refetchedMenteeData.mentee_data,
    });
    return refetchedMenteeData.mentee_data;
  };

  const formatCurrentDuration = (currentDuration: string) => {
    const hours = Math.floor(Number(currentDuration) / 3600);
    const minutes = Math.floor((Number(currentDuration) % 3600) / 60);
    const seconds = Number(currentDuration) % 60;
    if (hours > 0) {
      return `${hours}:${minutes}:${seconds}`;
    } else if (minutes > 0) {
      return `${minutes}:${seconds}`;
    } else {
      return `${seconds}`;
    }
  };

  const getEventProperties = async (currentUrl: string, activeTab: chrome.tabs.Tab) => {
    const { menteePreferedLanguage, menteePreferedMentorTone } = await chrome.storage.local.get(["menteePreferedLanguage", "menteePreferedMentorTone"]);
    let eventProperties = {
      ...(await eventPropertyBuilder(currentUrl, {})),
      menteePreferedLanguage: menteePreferedLanguage,
      menteePreferedMentorTone: menteePreferedMentorTone,
      daily_messages_left: chatUsageData.dailyMessagesLeft - 1, // -1 because we want the limit left after the message is sent
      daily_message_limit: chatUsageData.dailyMessageLimit,
      from: "Sidepanel",
    }
    if (currentUrl.includes("youtube.com")) {
      const youtubeProps = await chrome.tabs.sendMessage(activeTab?.id || 0, {
        action: "getYoutubeVideoProperties",
      });
      eventProperties = {
        ...eventProperties,
        ...youtubeProps,
      }
    }
    return eventProperties;
  }

  const handleUpgradeToProClick = async () => {
    const latestSubscription = getMostRecentSubscription(menteeSubscription?.subscriptions);
    const isTrialCancelled = latestSubscription?.cancelledOn && menteeSubscription?.pricing_plan?.user_type === "trial";
    await redirectToCheckout({
      location: isTrialCancelled ? "Trial Cancelled Banner" : "Last Message",
      menteeSubscription: menteeSubscription
    });
  };

  const sendMessage = useCallback(
    async (
      message: string,
      append_user_message: boolean = true,
      additional_message?: string | null,
      treatAsNewConversation?: boolean,
    ) => {
      const isYoutubeUrl = activeTabUrl.includes("youtube.com");
      if (!menteeData) {
        setShowSignupModal(true);
        await chrome.storage.local.set({
          pendingMessage: {
            message,
            timestamp: new Date().getTime(),
            userId: menteeData?.recordId,
            mentorAiId: mentoraiData?.recordId || "recdIrEzeo6GIXB2C",
            url: activeTabUrl,
          },
        });
        return;
      }

      if (!chatUsageData.isPaidUser && chatUsageData.dailyMessagesLeft === 0) {
        setIsPlansSheetOpen(true);
        setLiveMessages([
          {
            props: {
              model: {
                id: new Date().getTime().toString(),
                message: `You've used all free credits today./nUpgrade or wait until tomorrow's credit reset.`,
                sentTime: new Date().getTime().toString(),
                sender: "assistant",
                direction: "incoming",
                position: "single",
                senderPhotoUrl:"https://firebasestorage.googleapis.com/v0/b/preplaced-dev.appspot.com/o/leeco_profile.webp?alt=media&token=f25e8955-20ff-48cf-93c7-ef274ad856c2",
                senderName: mentoraiData?.name,
              },
              children: (
                <div className="relative bg-mentee-profile-pro-bg hover:bg-mentee-profile-pro-bg-hover cursor-pointer p-3 rounded-[12px]"
                  onClick={handleUpgradeToProClick}
                >
                  <div className="flex flex-col gap-5">
                    <div className="flex flex-col gap-0.5">
                      <span className="flex items-center gap-1">
                        <span className="text-mentorai-text-white font-medium text-[14px] leading-[17px] tracking-[-0.14px] font-bricolage-grotesque">
                          Upgrade To Leeco Pro
                        </span>
                        <img src={OpenNewTabIcon} alt="open new tab" className="w-[16px] h-[16px]" />
                      </span>
                      <div className="font-manrope text-[10px] leading-[14px] text-[#94939F] font-medium">Make the best of your learning with Leeco</div>
                    </div>

                    <ul className="text-[12px] text-mentorai-text-soft gap-[8px] tracking-[-0.12px] font-manrope flex flex-col">
                      <li className="flex items-center gap-1 h-[16px] text-[12px] font-manrope leading-normal">
                        <img src={ChatCheckFill2Icon} alt="chat check fill 2" className="w-[12px] h-[12px] max-w-[12px] max-h-[12px]" />
                        Unlimited Daily Credits
                      </li>
                      <li className="flex items-center gap-1 h-[16px] text-[12px] font-manrope leading-normal">
                        <img src={RoadmapFillIcon} alt="roadmap fill" className="w-[12px] h-[12px] max-w-[12px] max-h-[12px]" />
                        Unlimited Path Creation
                      </li>
                      <li className="flex items-center gap-1 h-[16px] text-[12px] font-manrope leading-normal">
                        <img src={SparklingFill2Icon} alt="sparkling fill 2" className="w-[14px] h-[14px] max-w-[14px] max-h-[14px]" />
                        Advanced Learning Model</li>
                    </ul>
                  </div>

                  <div className="absolute bottom-[0px] right-[-10px]">
                    <img src={LeecoMascotIcon} alt="Leeco Mascot" className="h-[151px] w-[101px]" />
                  </div>
                </div>
                // <PurchaseSheetButton
                //   chatUsageData={chatUsageData}
                //   headerType="free-credits-exhausted"
                //   bannerType="daily-limit-left"
                //   buttonId="limit-reached-message"
                //   className="py-1 pl-2 pr-1 bg-[#5149F2] text-white rounded-md w-fit"
                //   actionLocation="Self Triggered"
                // >
                //   Upgrade to Pro →
                // </PurchaseSheetButton>
              ),
              theme: "yellow",
              error: true,
            },
          },
        ]);

        await chrome.storage.local.set({
          pendingMessage: {
            message,
            timestamp: new Date().getTime(),
            userId: menteeData?.recordId,
            mentorAiId: mentoraiData?.recordId || "recdIrEzeo6GIXB2C",
            url: activeTabUrl,
          },
        });

        chrome.runtime.sendMessage({
          action: "sendAnalytics",
          url: activeTabUrl,
          eventName: "MentorAi Limit Exhausted Message Shown",
          eventProperties: {
            daily_messages_left: chatUsageData.dailyMessagesLeft,
            daily_message_limit: chatUsageData.dailyMessageLimit,
          },
        });
        return;
      }

      const activeTab = (await chrome.tabs.query({ active: true, currentWindow: true }))[0];
      const currentUrl: string = activeTab?.url || "";
      let scrapedData = "";
      const { menteePreferedLanguage, menteePreferedMentorTone } = await chrome.storage.local.get(["menteePreferedLanguage", "menteePreferedMentorTone"]);
      try {
        scrapedData = (
          await chrome.tabs.sendMessage(activeTab?.id || 0, {
            action: "scrapeCurrentPageContent",
          })
        )?.scraped_data;
      } catch (error) {
        console.error("Error in scrapedData");
      }
      setisLiveMessageStreaming(true);
      chrome.storage.local.set({
        isLiveMessageStreaming: true,
      });
      const selectedText = (await chrome.storage.local.get("selectedText")).selectedText;
      if (append_user_message) {
        const userMessages = [
          {
            props: {
              model: {
                id: new Date().getTime().toString(),
                message: message,
                sentTime: new Date().getTime().toString(),
                sender: "user",
                direction: "outgoing",
                position: "single",
                senderPhotoUrl: menteeData?.photoUrl,
                senderName: menteeData?.name,
              },
              children: <></>,
            },
          },
        ];
        if (additional_message) {
          userMessages.push({
            props: {
              model: {
                id: new Date().getTime().toString(),
                message: additional_message,
                sentTime: new Date().getTime().toString(),
                sender: "system",
                direction: "outgoing",
                position: "single",
                senderPhotoUrl: menteeData?.photoUrl,
                senderName: menteeData?.name,
              },
              children: <></>,
            },
          });
        }
        if (selectedText) {
          userMessages.push({
            props: {
              model: {
                id: new Date().getTime().toString(),
                message: "SelectedText: " + selectedText,
                sentTime: new Date().getTime().toString(),
                sender: "system",
                direction: "outgoing",
                position: "single",
                senderPhotoUrl: menteeData?.photoUrl,
                senderName: menteeData?.name,
              },
              children: <></>,
            },
          });
        }
        setUserLiveMessage(userMessages);
      }

      if (message === "Start Session") {
        setTimeout(() => {
          setLiveMessages([
            {
              props: {
                model: {
                  id: new Date().getTime().toString(),
                  message: `Welcome to our Practice Session. Let's try to solve ${startSessionConfig?.problemText} problem today.`,
                  sentTime: new Date().getTime().toString(),
                  sender: "assistant",
                  direction: "incoming",
                  position: "single",
                  senderPhotoUrl:"https://firebasestorage.googleapis.com/v0/b/preplaced-dev.appspot.com/o/leeco_profile.webp?alt=media&token=f25e8955-20ff-48cf-93c7-ef274ad856c2",
                  senderName: mentoraiData?.name,
                },
                children: <></>,
              },
            },
          ]);
        }, 0);
      } else {
        setLiveMessages([]);
      }

      // Prepare messages for backend
      const messages = [];

      messages.push({
        role: "user",
        content: message,
      });

      // Add additional message if provided
      if (additional_message) {
        messages.push({
          role: "system",
          content: additional_message,
        });
      } else {
        // Check for selected text from storage if no easy_action_selected_text
        if (selectedText) {
          messages.push({
            role: "system",
            content: "SelectedText: " + selectedText,
          });
        }
      }


      const { model_version, user_context_used, coding_prompt_version, context, currentDuration } =
        await chrome.storage.local.get([
          "model_version",
          "user_context_used",
          "editorial_used",
          "leetcodeSolutions",
          "coding_prompt_version",
          "context",
          "currentDuration",
        ]);
      const currentUrlOrigin = new URL(currentUrl).origin;
      const profile_data = context?.[currentUrlOrigin]?.["profile-data"]?.analysis;

      const messageContainer = document.getElementById("sidebar-chat-conversation-last-message");
      const liveMessageContainer = document.getElementById("sidebar-chat-conversation-live-message");
      messageContainer?.scrollIntoView();
      liveMessageContainer?.scrollIntoView();

      let page_context: {
        url: string;
        content: string;
        profile_data: any;
        transcript_window?: string;
        playhead_timestamp?: string;
      } = {
        url: currentUrl,
        content: scrapedData,
        profile_data: profile_data,
      };
      if (isYoutubeUrl) {
        const { playHead } = await chrome.tabs.sendMessage(activeTab?.id || 0, {
          action: "getYoutubeVideoPlayHead",
        });
        page_context["transcript_window"] = await getTranscriptForCurrentWindow(
          cleanYoutubeUrl(currentUrl),
          activeTab,
          playHead,
        );
        page_context["playhead_timestamp"] = formatCurrentDuration(playHead);
      }


      const body = {
        messages,
        user_id: menteeData?.recordId,
        mentor_ai_id: mentoraiData?.recordId || "recdIrEzeo6GIXB2C",
        page_context: page_context,
        menteePreferedLanguage: menteePreferedLanguage,
        menteePreferedMentorTone: menteePreferedMentorTone,
        process_chunk_on_frontend: true,
        create_record_for_empty_conversation: false,
        previous_messages: treatAsNewConversation
          ? []
          : chatMessages.slice((interviewModeStatus !== "ONGOING" || practiceModeStatus !== "PM_ONGOING") ? chatMessages?.length - 20 : 0).map((msg: any) => ({
            role: msg.props.model.sender,
            content: msg.props.model.message,
          })),
        candidate_data: {
          userCategory: menteeData?.userCategory,
          targetCompanies: menteeData?.targetCompanies,
          recordId: menteeData?.recordId,
          email: menteeData?.email,
          mentorAiRoadmapConfigurations: menteeData?.mentorAiRoadmapConfigurations,
          name: menteeData?.name,
        },
        eventProperties: await getEventProperties(currentUrl, activeTab),
        session_type: ["ONGOING", "PREVIEW"].includes(interviewModeStatus)
          ? "Interview Mode"
          : (["PM_ONGOING", "PM_PREVIEW"].includes(practiceModeStatus) || (message === "Start Structured Coaching Session" && treatAsNewConversation) ? 'Practice Mode' : extractSessionType(currentUrl) || "default"),
        ...((interviewModeStatus === "ONGOING" || interviewModeStatus === "PREVIEW") ? { interview_count: interviewModeStatus === "ONGOING" ? interviewCount : interviewCount + 1 } : {}),
        ...((practiceModeStatus === "PM_ONGOING" || practiceModeStatus === "PM_PREVIEW") ? { practice_count: practiceModeStatus === "PM_ONGOING" ? (practiceCount || 1) : (practiceCount || 1) + 1 } : {}),
        coding_prompt_version: coding_prompt_version,
        user_context_used: user_context_used === "true" ? true : false,
        model_version: model_version,
      };

      // Add timeout check for streaming response
      let hasReceivedResponse = false;
      const timeoutId = setTimeout(() => {
        if (!hasReceivedResponse) {
          console.warn("API call to /extension/send_message has exceeded 10 seconds.");
          chrome.runtime.sendMessage({
            action: "sendAnalytics",
            url: activeTabUrl,
            eventName: "Api Timeout Detected",
            eventProperties: {
              endpoint: `${import.meta.env.VITE_PREPLACED_BACKEND_AI_URL}/extension/send_message`,
              message: "API call to /extension/send_message has exceeded 10 seconds.",
              user_message: message,
            },
          });
        }
      }, 10000);
      chrome.storage.local.remove("selectedText");
      setSelectedText("");
      handleAibackendStreamingPost("/extension/send_message", body, {})
        .then((res) => {
          hasReceivedResponse = true;
          clearTimeout(timeoutId);
          if (res.body) {
            readStream(res.body);
          }
        })
        .catch((error) => {
          handleError(error, message);
        })
        .finally(() => {
          chrome.storage.local.remove("selectedText");
          updateNpsFeedbackValues();
        });
    },
    [chatMessages, chatUsageData, activeTabUrl, menteeSubscription],
  );

  useEffect(() => {
    getChatMessagesFromStorage().then((messages) => {
      const transformedMessages = transformChatMessages(messages).reverse();
      setChatMessages(transformedMessages);
    });
  }, []);

  const setConversationFeedbackStatusToCancel = () => {
    setConversationFeedbackStatus("cancel");
    chrome.storage.local.set({
      conversation_feedback: {
        status: "cancel",
        date: getTodaysDate(),
      },
    });
  };

  const setConversationFeedbackStatusToSubmitted = () => {
    setConversationFeedbackStatus("submitted");
    chrome.storage.local.set({
      conversation_feedback: {
        status: "submitted",
        date: getTodaysDate(),
      },
    });
  };

  const setConversationFeedbackStatusToShow = (localConversationFeedbackStatus: string) => {
    if (localConversationFeedbackStatus !== "show") {
      setConversationFeedbackStatus("show");
      chrome.storage.local.set({
        conversation_feedback: {
          status: "show",
          date: getTodaysDate(),
        },
      });
      sendAnalyticsWithBackend(menteeData?.email || "", activeTabUrl, "Conversation Feedback Shown", {});
    }
  };

  const updateConversationFeedbackStatus = async () => {
    if (chatUsageData.todayOutgoingChatMessagesCount > 7) {
      const localConversationFeedbackStatus = await getLocalConversationFeedbackStatus();
      if (localConversationFeedbackStatus == "not_shown_today" || localConversationFeedbackStatus == "show") {
        setConversationFeedbackStatusToShow(localConversationFeedbackStatus);
      }
    }
  };

  const fetchNpsData = async () => {
    let npsStatusFromLocalStorage = (await chrome.storage.local.get("npsStatusFromLocalStorage"))
      .npsStatusFromLocalStorage;
    if (npsStatusFromLocalStorage !== NPS_STATUS.SUBMITTED && npsStatusFromLocalStorage !== NPS_STATUS.CANCELED) {
      try {
        const response = await handleGet(`nps`, {
          mentee_id: menteeData?.recordId,
        });
        setNpsData(response.data);
      } catch (error) {
        console.log(error);
      }
    }
  };
  useEffect(() => {
    if (menteeData?.recordId) {
      fetchNpsData();
    }
  }, [menteeData?.recordId]);

  const checkNpsRecordForThisMentorMenteeConversation = (npsData: any) => {
    return npsData?.some(
      (record: any) =>
        record.source === "Extension" &&
        record.mentee?.[0] === menteeData?.recordId &&
        record.mentorAi?.[0] === mentoraiData?.recordId,
    );
  };

  const updateNpsStatus = async () => {
    let extensionUsedDaysCount = await getCurrentExtensionUsedDaysCount();
    let npsCanceledOnDay = parseInt((await chrome.storage.local.get("npsCanceledOnDay")).npsCanceledOnDay || "0");
    let npsStatusFromLocalStorage = (await chrome.storage.local.get("npsStatusFromLocalStorage"))
      .npsStatusFromLocalStorage;

    if (npsData && checkNpsRecordForThisMentorMenteeConversation(npsData)) {
      // setNpsStatus(NPS_STATUS.SUBMITTED);
      await chrome.storage.local.set({
        npsStatusFromLocalStorage: NPS_STATUS.SUBMITTED,
      });
    } else if (npsStatusFromLocalStorage !== NPS_STATUS.SUBMITTED) {
      const isExtensionLimitReached = !npsCanceledOnDay && extensionUsedDaysCount > 2;
      const isWeeklyCycle =
        npsCanceledOnDay && Math.floor(extensionUsedDaysCount / 7) > Math.floor(npsCanceledOnDay / 7);

      if (isExtensionLimitReached || isWeeklyCycle) {
        setNpsStatus(NPS_STATUS.SHOW);
        await chrome.storage.local.set({
          npsStatusFromLocalStorage: NPS_STATUS.SHOW,
        });
        if (npsStatusFromLocalStorage !== NPS_STATUS.SHOW) {
          try {
            sendAnalyticsWithBackend(menteeData?.email || "", activeTabUrl, "Mentee NPS Shown", { version: "v2" });
          } catch (error) {
            console.error("Error in sending NPS Shown", error);
          }
        }
      } else {
        setNpsStatus(npsStatusFromLocalStorage);
      }
    } else {
      setNpsStatus(npsStatusFromLocalStorage);
    }
  };

  useEffect(() => {
    updateConversationFeedbackStatus();
  }, [chatMessages.length]);

  useEffect(() => {
    if (!menteeData || !mentoraiData || ["PREVIEW", "FEEDBACK"].includes(interviewModeStatus) || ["PM_PREVIEW", "PM_FEEDBACK"].includes(practiceModeStatus)) return;
    fetchMessages();
  }, [menteeData, mentoraiData, interviewModeStatus, practiceModeStatus]);

  useEffect(() => {
    updateNpsStatus();
  }, [npsData]);

  useEffect(() => {
    chrome.storage.onChanged.addListener((changes) => {
      if (changes.chatMessages) {
        setChatMessages(transformChatMessages(JSON.parse(changes.chatMessages.newValue)));

        const updateChatUsageData = async () => {
          const dailyMessagesLeft = await calculateDailyMessagesLeft(dailyMessageLimit);
          const todayOutgoingChatMessagesCount = dailyMessageLimit - dailyMessagesLeft;

          setChatUsageData(prev => ({
            ...prev,
            dailyMessagesLeft: dailyMessagesLeft,
            todayOutgoingChatMessagesCount: todayOutgoingChatMessagesCount,
          }));
        };

        updateChatUsageData();
      }

      // Sync practice count changes
      if (changes.practiceCount) {
        setPracticeCount(validatePracticeCount(changes.practiceCount.newValue));
      }

      // Sync practice mode status changes
      if (changes.practiceModeStatus) {
        setPracticeModeStatus(changes.practiceModeStatus.newValue || "PM_IDLE");
      }
    });
  }, [activeTabUrl, menteeData, dailyMessageLimit]);

  const [isPending, startTransition] = useTransition();

  // const addMessagesOptimized = useCallback((messages: ChatMessage[]) => {
  //   setisLiveMessageStreaming(true);

  //   startTransition(() => {
  //     // Add all messages at once but mark as non-urgent
  //     setChatMessages(prev => [...prev, ...messages]);
  //     setisLiveMessageStreaming(false);
  //   });
  // }, []);

  // If you still need staggered timing:
  const addMessagesWithStagger = useCallback(async (messages: ChatMessage[], delay: number = 1000) => {
    setisLiveMessageStreaming(true);

    for (const [index, message] of messages.entries()) {
      await new Promise(resolve => setTimeout(resolve, delay));

      startTransition(() => {
        setChatMessages(prev => [...prev, message]);
      });
    }

    setisLiveMessageStreaming(false);
  }, []);

  const updateMessagesInDB = async (messages: any) => {
    const transformedMessages = messages.map((message: any) => ({
      role: message.props.model.sender || 'assistant',
      content: message.props.model.message || '',
      custom: {
        url: new URL(activeTabUrl).origin
      },
      createdAt: message.props.model.sentTime || Date.now(),
    }));
    const payload = {
      messages: transformedMessages,
      user_id: menteeData?.recordId,
      mentor_ai_id: mentoraiData?.recordId || "recdIrEzeo6GIXB2C",
    };
    handleAibackendPost(`/extension/add-messages`, payload, {}, false);
  }

  const handleMessage = useCallback(
    (message: any, sender: any, sendResponse: any) => {
      if (message.action === "sendMessageToAi") {
        setScreen("CHAT");
        sendMessage(message.message, message.message_by, message.additional_message, true);
      }

      if (message.action === "syncMessagesFromContent") {
        getChatMessagesFromStorage().then((messages) => {
          const transformedMessages = transformChatMessages(messages).reverse();
          setChatMessages(transformedMessages);
        });
      }

      if (message.action === "appendMessagesToChat") {
        const { messages: incomingMessages, interval = 1000 } = message;
        updateMessagesInDB(incomingMessages);
        addMessagesWithStagger(incomingMessages, interval);
      }

      return true;
    },
    [chatMessages, sendMessage, addMessagesWithStagger],
  );

  useEffect(() => {
    chrome.runtime.onMessage.addListener(handleMessage);
    return () => {
      chrome.runtime.onMessage.removeListener(handleMessage);
    };
  }, [handleMessage]);

  return {
    chatMessages,
    setChatMessages,
    loading,
    setLoading,
    liveMessages,
    setLiveMessages,
    userLiveMessage,
    setUserLiveMessage,
    isLiveMessageStreaming,
    setisLiveMessageStreaming,
    fetchMessages,
    sendMessage,
    conversationFeedbackStatus,
    setConversationFeedbackStatusToCancel,
    setConversationFeedbackStatusToSubmitted,
    npsStatus,
    setNpsStatus,
    chatUsageData,
    isPlansSheetOpen,
    setIsPlansSheetOpen,
    menteeSubscription,
    handleUpgradeToProClick,
  };
};

export default useChatConversations;
