import React, { useState } from 'react';
import { useCustomUI } from '../../../contexts/custom-ui-context/custom-ui-context';
import Tippy from '@tippyjs/react';
import MentorAiActiveAvatar from '../../mentorai-active-avatar/mentorai-active-avatar';
import { motion } from 'framer-motion';
import TippyContent from './tippy-content';
import SwitchOn from "../../../../src/assets/switch-on.svg"
import SwitchOff from "../../../../src/assets/switch-off.svg"
import Loading from "../../../../src/assets/loading.gif"
import { getStatus } from '../../../utils/get-tippy-status';


const LearningSessionToggle: React.FC = () => {
  const { learningSession, toggleLearningSession, mentoraiData, sessionCreationStatus, userInteractionData } = useCustomUI();
  // const isActive = learningSession && ['ongoing', 'creating', 'created'].includes(learningSession.sessionStatus || '');
  const [showTippy, setShowTippy] = useState(false)
  const tippyStatus = getStatus(sessionCreationStatus)
  const isCreating = (tippyStatus === "checkingTranscript" || tippyStatus === "sectionGenerating" || tippyStatus === "quizGenerating");
  // console.log('tippyStatus', tippyStatus)

  const buttonText = () => {
    let btnContent = {
      text: '',
    }
    if (isCreating) {
      btnContent.text = "Creating Session"
    } else if (!userInteractionData) {
      btnContent.text = "Start Learning Session"
    } else {
      btnContent.text = "Learning Session"
    }
    return btnContent
  }

  return (
    <Tippy
      visible={showTippy && (tippyStatus !== "idle")}
      content={<TippyContent
        tippyStatus={tippyStatus}
      />}
    >
      <div
        onClick={() => {
          if (isCreating || tippyStatus === "transcriptError") {
            return
          } else {
            toggleLearningSession()
          }
        }}
        onMouseEnter={() => {
          setShowTippy(true)
        }}
        onMouseLeave={() => {
          setShowTippy(false)
        }}
        className={`
          h-[34px] w-fit rounded-xl 
          border border-mentorai-stroke-strong 
          backdrop-blur-[12px] 
          shadow-[inset_0px_0px_12px_0px_rgba(0,_0,_0,_0.24)] 
          flex items-center justify-center
          ${isCreating ? "bg-mentorai-bg-sub" : "bg-[#4B4E63]"}
        `}
        style={{
          padding: "6px",
          marginTop: "6px",
          marginRight: "8px",
          gap: "6px",
          cursor: (isCreating || tippyStatus === "transcriptError") ? "not-allowed" : "pointer",
        }}
      >
        <div className="flex items-center h-[22px]" style={{ gap: "8px" }}>
          {(isCreating) ?
            <div className="flex items-center justify-center h-[20px] w-[20px] relative z-10">
              <img src={Loading} alt="" style={{ width: 16, height: 16, position: 'relative', zIndex: 10 }} />
            </div>
            :
            <MentorAiActiveAvatar mentoraiData={mentoraiData} />
          }
          <span
            style={{
              display: 'flex',
              alignItems: 'center',
              fontSize: "14px",
              lineHeight: "22px",
              fontWeight: "500",
              color: tippyStatus === "transcriptError" ? '#94939F' : (isCreating ? '#8E8D99' : '#F2F2F2'),
            }}>
            {buttonText().text}
          </span>
        </div>

        {learningSession &&
          <button
            style={{
              cursor: (isCreating) ? "not-allowed" : "pointer",
            }}
            className='flex items-center justify-center'>
            <motion.img
              transition={{
                duration: 0.3
              }}
              style={{
                scale: "1.3",
                marginTop: "8px"
              }}
              src={(learningSession?.sessionStatus === 'stopped') ? SwitchOff : SwitchOn} alt="MentorAi" className="w-[32px] h-[22px]" />
          </button>
        }
      </div>
    </Tippy>
  )
};

export default LearningSessionToggle; 