/**
 * Theme detection utilities for different websites
 * Provides functions to detect dark/light themes for GeeksforGeeks, LeetCode
 */

export type ThemeType = 'dark' | 'light';

/**
 * Detects the current theme for GeeksforGeeks website
 * GeeksforGeeks uses data-theme attribute on the body tag
 * @returns 'dark' | 'light'
 */
export const detectGeeksforGeeksTheme = (): ThemeType => {
    try {
        const body = document.body;
        if (!body) return 'light'; // fallback

        const themeAttribute = body.getAttribute('data-theme');
        return themeAttribute === 'dark' ? 'dark' : 'light';
    } catch (error) {
        console.warn('Error detecting GeeksforGeeks theme:', error);
        return 'light'; // fallback
    }
};

/**
 * Detects the current theme for LeetCode website
 * LeetCode uses class attribute on the html tag
 * @returns 'dark' | 'light'
 */
export const detectLeetCodeTheme = (): ThemeType => {
    try {
        const htmlElement = document.documentElement;
        if (!htmlElement) return 'light'; // fallback

        const hasDarkClass = htmlElement.classList.contains('dark');
        return hasDarkClass ? 'dark' : 'light';
    } catch (error) {
        console.warn('Error detecting LeetCode theme:', error);
        return 'light'; // fallback
    }
};


/**
 * Generic theme detection function that automatically detects the website and returns appropriate theme
 * @returns { theme: ThemeType, website: string } | null
 */
export const detectWebsiteTheme = (): { theme: ThemeType; website: string } | null => {
    try {
        const hostname = window.location.hostname;

        if (hostname === 'leetcode.com') {
            return {
                theme: detectLeetCodeTheme(),
                website: 'leetcode'
            };
        }

        if (hostname === 'www.geeksforgeeks.org' || hostname === 'geeksforgeeks.org') {
            return {
                theme: detectGeeksforGeeksTheme(),
                website: 'geeksforgeeks'
            };
        }


        return null;
    } catch (error) {
        console.warn('Error detecting website theme:', error);
        return null;
    }
};

/**
 * Creates a MutationObserver to watch for theme changes on a specific website
 * @param website - The website to watch ('leetcode', 'geeksforgeeks')
 * @param callback - Callback function to execute when theme changes
 * @returns MutationObserver instance
 */
export const createThemeObserver = (
    website: string,
    callback: (theme: ThemeType) => void
): MutationObserver => {
    const observer = new MutationObserver(() => {
        let theme: ThemeType = 'light';

        switch (website) {
            case 'leetcode':
                theme = detectLeetCodeTheme();
                break;
            case 'geeksforgeeks':
                theme = detectGeeksforGeeksTheme();
                break;
            default:
                return;
        }

        callback(theme);
    });

    // Observe different elements based on website
    switch (website) {
        case 'leetcode':
            // Watch for class changes on html element
            observer.observe(document.documentElement, {
                attributes: true,
                attributeFilter: ['class']
            });
            break;

        case 'geeksforgeeks':
            // Watch for data-theme attribute changes on body
            observer.observe(document.body, {
                attributes: true,
                attributeFilter: ['data-theme']
            });
            break;
    }

    return observer;
};

/**
 * Hook-like function to get current theme and set up theme change detection
 * @param website - The website to monitor
 * @returns { theme: ThemeType, isDark: boolean }
 */
export const useWebsiteTheme = (website: string): { theme: ThemeType; isDark: boolean } => {
    let theme: ThemeType = 'light';

    switch (website) {
        case 'leetcode':
            theme = detectLeetCodeTheme();
            break;
        case 'geeksforgeeks':
            theme = detectGeeksforGeeksTheme();
            break;
        default:
            theme = 'light';
    }

    return {
        theme,
        isDark: theme === 'dark'
    };
};
