import { handleCommonPost, handlePost } from '../../core/Axios';
import { timeToSeconds } from '../../src/utils/str-time-to-seconds';

// Extract video ID from YouTube URL
export const extractVideoId = (url: string): string | null => {
  const match = url.match(/[?&]v=([\w-]{11})/) || url.match(/\/(?:shorts|embed)\/([\w-]{11})/);
  return match ? match[1] : null;
};

// Create a custom upload function for YouTube thumbnails
export const uploadYoutubeThumbnailToBackend = async (imageFile: File, fileName: string) => {
  if (imageFile) {
    const formData = new FormData();
    formData.append('file', imageFile, fileName);

    try {
      const uploadedFileResponse = await handleCommonPost('upload/file', formData, {
        filepath: 'mentorai/resources/youtube-thumbnails/'
      });
      const imageUrl = `${uploadedFileResponse.data.url}?alt=media&token=${uploadedFileResponse.data.token}`;
      // console.log("imageUrl", imageUrl, uploadedFileResponse);
      return imageUrl;
    } catch (error: any) {
      console.error("error in uploadYoutubeThumbnailToBackend", error);
      if (error?.response?.data) {
        const uploadedFileResponse = error?.response?.data;
        const imageUrl = `${uploadedFileResponse.url}?alt=media&token=${uploadedFileResponse.token}`;
        // console.log("imageUrl in error", imageUrl);
        return imageUrl;
      }
      return '';
    }
  }
  return '';
};

// Capture thumbnail from video at specific time
export const captureVideoThumbnail = async (
  videoElement: HTMLVideoElement,
  timeInSeconds: number,
  width: number = 320,
  height: number = 180
): Promise<Blob | null> => {
  return new Promise((resolve) => {
    // Store original time and paused state
    const originalTime = videoElement.currentTime;
    const wasPaused = videoElement.paused;

    // Create canvas for capture
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    if (!ctx) {
      resolve(null);
      return;
    }

    canvas.width = width;
    canvas.height = height;

    // Function to capture the frame
    const captureFrame = () => {
      try {
        // Draw video frame to canvas
        ctx.drawImage(videoElement, 0, 0, width, height);

        // Convert to blob
        canvas.toBlob((blob) => {
          // Restore original video state
          videoElement.currentTime = originalTime;
          if (!wasPaused) {
            videoElement.play();
          }
          resolve(blob);
        }, 'image/jpeg', 0.8);
      } catch (error) {
        console.error('Error capturing thumbnail:', error);
        // Restore original video state
        videoElement.currentTime = originalTime;
        if (!wasPaused) {
          videoElement.play();
        }
        resolve(null);
      }
    };

    // Seek to the desired time
    const onSeeked = () => {
      videoElement.removeEventListener('seeked', onSeeked);
      // Small delay to ensure frame is ready
      setTimeout(captureFrame, 100);
    };

    videoElement.addEventListener('seeked', onSeeked);
    videoElement.currentTime = timeInSeconds;
  });
};

// NEW: Capture thumbnails for streaming sections (only capture blobs, don't upload)
export const captureThumbnailsForStreamingSections = async (
  streamedSections: any[],
  videoElement: HTMLVideoElement,
  videoUrl: string
): Promise<any[]> => {
  const videoId = extractVideoId(videoUrl);
  if (!videoId) {
    console.error('Could not extract video ID from URL');
    return streamedSections;
  }

  const sectionsWithThumbnails = [];
  
  for (let index = 0; index < streamedSections.length; index++) {
    const section = streamedSections[index];
    
    // Skip if thumbnail already exists (blob URL or permanent URL)
    if (section.thumbnailBlob || section.thumbnail) {
      sectionsWithThumbnails.push(section);
      continue;
    }
    
    try {
      videoElement.muted = true;
      const startTimeInSeconds = timeToSeconds(section.startTime);
      
      // Capture thumbnail blob at section start time
      const thumbnailBlob = await captureVideoThumbnail(videoElement, startTimeInSeconds);
      
      if (thumbnailBlob) {
        // Create file name: videoId-timestampinsec
        const fileName = `${videoId}-${Math.floor(startTimeInSeconds)}.jpg`;
        
        // Create temporary blob URL for immediate display
        const tempUrl = URL.createObjectURL(thumbnailBlob);
        
        // Add thumbnail data to section
        sectionsWithThumbnails.push({
          ...section,
          thumbnailBlob,
          fileName,
          thumbnail: tempUrl
        });
      } else {
        console.warn(`Could not capture thumbnail for section ${index}`);
        sectionsWithThumbnails.push(section);
      }
      
      videoElement.muted = false;
    } catch (error) {
      console.error(`Error capturing thumbnail for section ${index}:`, error);
      sectionsWithThumbnails.push(section);
    }
    
    // Small delay between captures to avoid overwhelming the video element
    await new Promise(resolve => setTimeout(resolve, 100));
  }
  
  return sectionsWithThumbnails;
};

// NEW: Upload thumbnail blobs and return sections with thumbnail URLs
export const uploadThumbnailsAndGetUrls = async (
  sections: any[],
  videoUrl: string
): Promise<any[]> => {
  const videoId = extractVideoId(videoUrl);
  if (!videoId) {
    console.error('Could not extract video ID from URL');
    return sections;
  }

  // Upload all thumbnails in parallel
  const uploadPromises = sections.map(async (section, index) => {
    // Skip if no thumbnail blob or already has URL
    if (!section.thumbnailBlob) {
      return section;
    }

    // Skip if already has permanent URL (not blob URL)
    if (section.thumbnail && !section.thumbnail.startsWith('blob:')) {
      return section;
    }
    
    try {
      const thumbnailFile = new File([section.thumbnailBlob], section.fileName, { type: 'image/jpeg' });
      const thumbnailUrl = await uploadYoutubeThumbnailToBackend(thumbnailFile, section.fileName);
      
      if (thumbnailUrl) {
        // Clean up temporary URL if it exists
        if (section.thumbnail) {
          URL.revokeObjectURL(section.thumbnail);
        }
        
        // Return section with thumbnail URL, remove blob and temp data
        const { thumbnailBlob, thumbnail, fileName, ...sectionWithoutBlob } = section;
        return {
          ...sectionWithoutBlob,
          thumbnail: thumbnailUrl
        };
      } else {
        console.warn(`Failed to upload thumbnail for section ${index}`);
        return section;
      }
    } catch (error) {
      console.error(`Error uploading thumbnail for section ${index}:`, error);
      return section;
    }
  });
  
  // Wait for all uploads to complete
  const sectionsWithUrls = await Promise.all(uploadPromises);
  return sectionsWithUrls;
};

// Generate thumbnails for sections in the background
export const generateThumbnailsInBackground = async (
  sections: any[],
  videoElement: HTMLVideoElement,
  videoUrl: string,
  onSectionUpdate: (sectionIndex: number, thumbnail: string) => void,
  onThumbnailsUploaded: (capturedThumbnails: any[]) => void,
): Promise<void> => {
  const videoId = extractVideoId(videoUrl);
  if (!videoId) {
    console.error('Could not extract video ID from URL');
    return;
  }

  // First pass: Capture all thumbnails
  const capturedThumbnails: Array<{
    index: number;
    blob: Blob;
    fileName: string;
    tempUrl: string;
    thumbnailUrl?: string;
  }> = [];
  for (let index = 0; index < sections.length; index++) {
    const section = sections[index];

    if (section.thumbnail) {
      continue;
    }

    try {
      const startTimeInSeconds = timeToSeconds(section.startTime);

      // Capture thumbnail at section start time
      const thumbnailBlob = await captureVideoThumbnail(videoElement, startTimeInSeconds);

      if (thumbnailBlob) {
        // Create file name: videoId-timestampinsec
        const fileName = `${videoId}-${Math.floor(startTimeInSeconds)}.jpg`;

        // Create temporary blob URL for immediate display
        const tempUrl = URL.createObjectURL(thumbnailBlob);

        // Store captured thumbnail data
        capturedThumbnails.push({
          index,
          blob: thumbnailBlob,
          fileName,
          tempUrl
        });

        // Update UI with temporary URL immediately
        onSectionUpdate(index, tempUrl);
      } else {
        console.warn(`Could not capture thumbnail for section ${index}`);
      }
    } catch (error) {
      console.error(`Error processing thumbnail for section ${index}:`, error);
    }

    // Small delay between captures to avoid overwhelming the video element
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  // Second pass: Upload all thumbnails in parallel
  const uploadPromises = capturedThumbnails.map(async ({ index, blob, fileName, tempUrl }) => {
    try {
      const thumbnailFile = new File([blob], fileName, { type: 'image/jpeg' });

      const thumbnailUrl = await uploadYoutubeThumbnailToBackend(thumbnailFile, fileName);

      if (thumbnailUrl) {

        capturedThumbnails[index].thumbnailUrl = thumbnailUrl;
        // Replace temporary URL with permanent URL
        // onSectionUpdate(index, thumbnailUrl);
        // Clean up temporary URL
        URL.revokeObjectURL(tempUrl);
      }
    } catch (error) {
      console.error(`Error uploading thumbnail for section ${index}:`, error);
      // Keep temporary URL as fallback
    }
  });

  // Wait for all uploads to complete
  await Promise.all(uploadPromises);

  await onThumbnailsUploaded(capturedThumbnails);

};
