import React, { useMemo } from 'react';
import { motion } from 'framer-motion';
import { cn } from '../../../../utils/cn';
import { ANALYSIS_STEPS } from '../constants';
import { getStepStatus, getStepIcon, getStepTextStyle } from '../utils';
import type { ContextCollectionViewProps, AnalysisStep } from '../types';

export const ContextCollectionView: React.FC<ContextCollectionViewProps> = ({
  mentoraiData,
  currentStep,
  isAnalyzing,
}) => {
  const analysisProgress: AnalysisStep[] = useMemo(
    () =>
      ANALYSIS_STEPS.map(step => ({
        ...step,
        status: getStepStatus(step.id, currentStep),
      })),
    [currentStep]
  );

  return (
    <motion.div className="fixed bottom-[120px] z-[9999999] right-0 w-[326px] overflow-hidden cursor-pointer rounded-l-[16px] rounded-r-none bg-[#07070A] moving-border">
      <div className="flex flex-col">
        <div className="flex items-center justify-between px-[16px] py-[8px]">
          <div className="flex items-center gap-2">
            <div className="relative">
              <img
                src={mentoraiData?.aiPhotoUrl || mentoraiData?.photoUrl || ""}
                className="h-[24px] w-[24px] rounded-full"
                alt="avatar"
              />
              <span className="absolute -bottom-[1px] -right-[2px] border-[2px] border-[#000] w-[10px] h-[10px] rounded-full bg-[#1FC16B]" />
            </div>
            <p className="text-[14px] leading-[22px] tracking-[0.084px] text-[#DDDDDF] whitespace-nowrap">
              {mentoraiData?.name}
            </p>
          </div>
        </div>
        
        <div className="flex flex-col px-[12px] pb-[16px]">
          <div className="p-[4px] pb-[8px] border-b border-mentorai-stroke-base">
            <p className="text-[14px] leading-[24px] font-[700] text-mentorai-text-soft whitespace-nowrap">
              Analyzing your profile...
            </p>
          </div>
          
          <div className="pt-[12px]">
            {analysisProgress.map((item) => {
              const isInProgress = item.status === "in-progress";
              const textStyle = getStepTextStyle(item.status);

              return (
                <motion.div
                  key={item.id}
                  className="flex items-center gap-[8px]"
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ duration: 0.3 }}
                >
                  <motion.div
                    animate={{
                      scale: isInProgress ? [1, 1.1, 1] : 1
                    }}
                    transition={{
                      duration: 1,
                      repeat: isInProgress ? Infinity : 0,
                      ease: "easeInOut"
                    }}
                  >
                    {getStepIcon(item.status)}
                  </motion.div>
                  <p
                    className={cn(
                      "text-[14px] leading-[24px] font-normal whitespace-nowrap -tracking-[-0.084px] text-mentorai-text-sub",
                      textStyle
                    )}
                  >
                    {item.title}
                  </p>
                </motion.div>
              );
            })}
          </div>
        </div>
      </div>
    </motion.div>
  );
}; 