import React, { useEffect, useState } from 'react';

interface AutoApplyOverlayProps {
  isActive: boolean;
  onStop: () => void;
  theme?: 'orange' | 'blue' | 'red' | 'purple' | 'cyan' | 'green' | 'pink' | 'gold';
}

const AutoApplyOverlay: React.FC<AutoApplyOverlayProps> = ({ 
  isActive, 
  onStop, 
  theme = 'purple' 
}) => {
  const [state, setState] = useState<'active' | 'idle'>('active');

  useEffect(() => {
    if (isActive) {
      setState('active');
    }
  }, [isActive]);

  if (!isActive) return null;

  const themeColors = {
    // Original themes
    orange: {
      primary: '#f55524',
      secondary: '#f56324',
      tertiary: '#f57124',
      quaternary: '#f55524',
      quinary: '#f33a10',
      borderColor: 'rgba(245, 85, 36, 0.6)',
    },
    blue: {
      primary: '#0066ff',
      secondary: '#0099ff',
      tertiary: '#00ccff',
      quaternary: '#0066ff',
      quinary: '#003399',
      borderColor: 'rgba(0, 102, 255, 0.6)',
    },
    red: {
      primary: '#ff0000',
      secondary: '#ff6b6b',
      tertiary: '#ff0000',
      quaternary: '#cc0000',
      quinary: '#ff0000',
      borderColor: 'rgba(255, 0, 0, 0.6)',
    },
    // New attractive themes
    purple: {
      primary: '#8B5CF6',
      secondary: '#A78BFA',
      tertiary: '#C4B5FD',
      quaternary: '#7C3AED',
      quinary: '#6D28D9',
      borderColor: 'rgba(139, 92, 246, 0.6)',
    },
    cyan: {
      primary: '#06B6D4',
      secondary: '#22D3EE',
      tertiary: '#67E8F9',
      quaternary: '#0891B2',
      quinary: '#0E7490',
      borderColor: 'rgba(6, 182, 212, 0.6)',
    },
    green: {
      primary: '#10B981',
      secondary: '#34D399',
      tertiary: '#6EE7B7',
      quaternary: '#059669',
      quinary: '#047857',
      borderColor: 'rgba(16, 185, 129, 0.6)',
    },
    pink: {
      primary: '#EC4899',
      secondary: '#F472B6',
      tertiary: '#F9A8D4',
      quaternary: '#DB2777',
      quinary: '#BE185D',
      borderColor: 'rgba(236, 72, 153, 0.6)',
    },
    gold: {
      primary: '#F59E0B',
      secondary: '#FBBF24',
      tertiary: '#FCD34D',
      quaternary: '#D97706',
      quinary: '#B45309',
      borderColor: 'rgba(245, 158, 11, 0.6)',
    },
  };

  const colors = themeColors[theme];

  return (
    <>
      <style>{`
        @keyframes auto-apply-border-rotate {
          0% { 
            border-image: conic-gradient(from 0deg, ${colors.primary}, ${colors.secondary}, ${colors.tertiary}, ${colors.quaternary}, ${colors.quinary}) 1;
          }
          25% { 
            border-image: conic-gradient(from 90deg, ${colors.primary}, ${colors.secondary}, ${colors.tertiary}, ${colors.quaternary}, ${colors.quinary}) 1;
          }
          50% { 
            border-image: conic-gradient(from 180deg, ${colors.primary}, ${colors.secondary}, ${colors.tertiary}, ${colors.quaternary}, ${colors.quinary}) 1;
          }
          75% { 
            border-image: conic-gradient(from 270deg, ${colors.primary}, ${colors.secondary}, ${colors.tertiary}, ${colors.quaternary}, ${colors.quinary}) 1;
          }
          100% { 
            border-image: conic-gradient(from 360deg, ${colors.primary}, ${colors.secondary}, ${colors.tertiary}, ${colors.quaternary}, ${colors.quinary}) 1;
          }
        }
      `}</style>
      
      {/* Overlay Border */}
      <div
        style={{
          position: 'fixed',
          inset: '-1.25em',
          border: 'solid',
          borderWidth: '2.5em',
          borderColor: state === 'active' ? colors.primary : `rgba(245, 85, 36, 0.5)`,
          filter: state === 'active' ? 'blur(24px)' : 'blur(8px)',
          zIndex: 2147483646,
          pointerEvents: 'none',
          userSelect: 'none',
          opacity: state === 'active' ? 0.6 : 0.15,
          transition: 'opacity 500ms cubic-bezier(0.4, 0, 0.2, 1), border-width 500ms cubic-bezier(0.4, 0, 0.2, 1), filter 500ms cubic-bezier(0.4, 0, 0.2, 1)',
          animation: state === 'active' ? 'auto-apply-border-rotate 1750ms linear infinite' : 'none',
        }}
      />

      {/* Stop Button */}
      <button
        onClick={onStop}
        style={{
          position: 'fixed',
          bottom: '32px',
          left: '50%',
          transform: 'translateX(-50%)',
          zIndex: 2147483647,
          background: 'rgba(0, 0, 0, 0.3)',
          color: 'rgba(255, 255, 255, 0.9)',
          border: `1.5px solid ${colors.borderColor}`,
          borderRadius: '12px',
          padding: '8px 16px',
          fontSize: '12px',
          fontFamily: 'system-ui, -apple-system, sans-serif',
          display: 'flex',
          alignItems: 'center',
          backdropFilter: 'blur(8px)',
          transition: 'all 0.3s ease',
          opacity: state === 'active' ? 0.85 : 0.5,
          boxShadow: '0 2px 8px rgba(0, 0, 0, 0.3)',
          pointerEvents: 'auto',
          justifyContent: 'center',
          cursor: 'pointer',
          gap: '8px',
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.opacity = '0.95';
          e.currentTarget.style.background = 'rgba(0, 0, 0, 0.8)';
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.opacity = state === 'active' ? '0.85' : '0.5';
          e.currentTarget.style.background = 'rgba(0, 0, 0, 0.3)';
        }}
      >
        {/* Stop icon (square) */}
        <span
          style={{
            width: '8px',
            height: '8px',
            backgroundColor: 'currentColor',
            borderRadius: '2px',
            display: 'inline-block',
            flexShrink: 0,
          }}
        />
        <span>Stop Auto Apply</span>
      </button>
    </>
  );
};

export default AutoApplyOverlay;
