/**
 * Utility functions for validating article content
 */

export interface ArticleValidationResult {
  hasValidArticle: boolean;
  validArticle?: Element;
  contentLength?: number;
}

/**
 * Checks if there are any articles with substantial content
 */
export function hasValidArticleContent(): boolean {
  const result = findValidArticle();
  return result.hasValidArticle;
}

/**
 * Finds the first article with substantial content
 */
export function findValidArticle(): ArticleValidationResult {
  const articleElements = document.querySelectorAll('article');
  
  if (articleElements.length === 0) {
    return { hasValidArticle: false };
  }

  for (let i = 0; i < articleElements.length; i++) {
    const article = articleElements[i];
    const textContent = (article as HTMLElement).innerText || article.textContent || '';
    
    if (textContent.length >= 500) {
      return {
        hasValidArticle: true,
        validArticle: article,
        contentLength: textContent.length
      };
    }
  }

  return { hasValidArticle: false };
}

/**
 * Finds the article with the most substantial content
 */
export function findBestArticle(): ArticleValidationResult {
  const articleElements = document.querySelectorAll('article');
  
  if (articleElements.length === 0) {
    return { hasValidArticle: false };
  }

  let bestArticle = null;
  let maxContentLength = 0;

  for (let i = 0; i < articleElements.length; i++) {
    const article = articleElements[i];
    const textContent = (article as HTMLElement).innerText || article.textContent || '';
    
    if (textContent.length >= 500 && textContent.length > maxContentLength) {
      bestArticle = article;
      maxContentLength = textContent.length;
    }
  }

  if (bestArticle) {
    return {
      hasValidArticle: true,
      validArticle: bestArticle,
      contentLength: maxContentLength
    };
  }

  return { hasValidArticle: false };
}

/**
 * Gets the content length of an article element
 */
export function getArticleContentLength(article: Element): number {
  const textContent = (article as HTMLElement).innerText || article.textContent || '';
  return textContent.length;
}
