// Constants
const ONE_HOURS_MS = 30 * 60 * 1000 // 1 hours in milliseconds
const FOUR_HOURS_MS = 4 * 60 * 60 * 1000 // 4 hours in milliseconds

// Types for better type safety
interface LeetCodeSolution {
  content: string;
  timestamp: number;
  title: string;
  difficulty: string;
  lastUpdated: string;
  authorName: string;
  fetchStatus: 'success' | 'error' | 'pending';
  errorMessage?: string;
}

interface LeetCodeSolutionsCache {
  [titleSlug: string]: LeetCodeSolution;
}

// Cache management functions
const SolutionCache = {
  async get(titleSlug: string): Promise<LeetCodeSolution | null> {
    try {
      const { leetcodeSolutions = {} } = await chrome.storage.local.get('leetcodeSolutions');
      const solution = leetcodeSolutions[titleSlug];
      return solution as LeetCodeSolution || null;
    } catch (error) {
      console.error('Error reading from cache:', error);
      return null;
    }
  },

  async set(titleSlug: string, solution: LeetCodeSolution): Promise<void> {
    try {
      const { leetcodeSolutions = {} } = await chrome.storage.local.get('leetcodeSolutions');
      await chrome.storage.local.set({
        leetcodeSolutions: {
          ...leetcodeSolutions,
          [titleSlug]: solution
        }
      });
    } catch (error) {
      console.error('Error writing to cache:', error);
    }
  },

  async isStale(titleSlug: string): Promise<boolean> {
    const cached = await this.get(titleSlug);
    if (!cached) return true;

    const now = Date.now();
    return (now - cached.timestamp) >= ONE_HOURS_MS;
  },

  async cleanup(): Promise<void> {
    try {
      const { leetcodeSolutions = {} } = await chrome.storage.local.get('leetcodeSolutions');
      const now = Date.now();

      // Remove entries older than 7 days
      const cleanedSolutions = Object.entries(leetcodeSolutions).reduce((acc, [slug, solution]) => {
        if (now - (solution as LeetCodeSolution).timestamp < 7 * ONE_HOURS_MS) {
          acc[slug] = solution as LeetCodeSolution;
        }
        return acc;
      }, {} as LeetCodeSolutionsCache);

      await chrome.storage.local.set({ leetcodeSolutions: cleanedSolutions });
    } catch (error) {
      console.error('Error cleaning up cache:', error);
    }
  }
};

const parseCustomToken = async (
  tabId: number,
  changeInfo: chrome.tabs.TabChangeInfo,
  tab: chrome.tabs.Tab
): Promise<void> => {
  // Proceed only when the tab has finished loading
  if (changeInfo.status === "complete" && tab.url) {
    const url = new URL(tab.url)
    // Check if the tab's URL is the expected one
    if (url.origin === `${import.meta.env.VITE_LEECO_WEB_URL}`) {
      const customToken = url.searchParams.get("custom_token")
      const email = url.searchParams.get("email")
      const originalTabId = url.searchParams.get("originalTabId")
      if (customToken && email) {
        await handleCustomToken(
          tabId,
          customToken,
          email,
          originalTabId ? parseInt(originalTabId) : undefined
        )
      }
    }
  }
}

/**
 * Handles storing the custom token and triggering the login action.
 *
 * @param {number} tabId - The ID of the tab containing the custom token.
 * @param {string} customToken - The custom token retrieved from the URL.
 */
async function handleCustomToken(
  tabId: number,
  customToken: string,
  email: string,
  originalTabId?: number
): Promise<void> {
  try {
    // Store the custom token
    await chrome.storage.sync.set({ [keyAuthCustomToken]: customToken })
    await chrome.storage.sync.set({ [keyAuthEmail]: email })

    await signInWithCustomToken(firebaseAuth, customToken);

    const { model_version, coding_prompt_version, leetcode_profile_collection, editorial_used, user_context_used, speech_to_text, interview_mode_access_option_variant, initial_default_tab_variant, show_trial_screen } = await chrome.storage.local.get(["model_version", "coding_prompt_version", "leetcode_profile_collection", "editorial_used", "user_context_used", "speech_to_text", "interview_mode_access_option_variant", "leeco_anonymous_id", "initial_default_tab_variant", "show_trial_screen"])

    const { leeco_anonymous_id } = await chrome.storage.sync.get('leeco_anonymous_id')
    if (leeco_anonymous_id) {
      await identifyUserV2(email, leeco_anonymous_id)
    }

    if (originalTabId) {
      // Close the new tab
      await chrome.tabs.remove(tabId)
      // Activate the original tab
      await chrome.tabs.update(originalTabId, { active: true })
      // Send message to the original tab to reload
      await chrome.tabs.reload(originalTabId)
    }

    identifyUser(email, {
      leetcode_profile_collection,
      coding_prompt_version,
      editorial_used,
      user_context_used,
      speech_to_text,
      model_version,
      interview_mode_access_option_variant,
      initial_default_tab_variant,
      show_trial_screen
    })

    const { pendingMessage } = await chrome.storage.local.get(["pendingMessage"])
    if (pendingMessage) {
      chrome.runtime.sendMessage({
        action: "sendMessageToAi",
        message: pendingMessage.message,
        message_by: "user",
      })
      await chrome.storage.local.set({ pendingMessage: null })
    }

  } catch (error) {
    console.error("Error handling custom token: ", error)
  }
}

