import React, { useState, useMemo } from "react";
import Markdown from "react-markdown";
import ArrowUp2 from "../../../../assets/icons/arrow-up2.svg";
import ArrowUp2Hover from "../../../../assets/icons/arrow-up2-hover.svg";
import ArrowDown from "../../../../assets/icons/arrow-dow.svg";
import ArrowDownHover from "../../../../assets/icons/arrow-dow-hover.svg";
import { getYoutubeVideoLength, getYoutubeVideoPlayHead } from "../../../../utils/get-youtube-video-length";
import { useCustomUI } from "../../../../contexts/custom-ui-context/custom-ui-context";
import { useChat } from "../../../../contexts/chat-context/chat-context";

const Keyterms = ({ markdown, mentorAiData, isSidePanelOpen, isYouTubeThemeDark }: { markdown: any, mentorAiData: any, isSidePanelOpen: boolean, isYouTubeThemeDark: boolean }) => {

    function parseKeyTermsMarkdown(md: any) {
        const categories = [];
        const lines = md.split("\n");

        let currentCategory: any = null;
        let currentTerm: any = null;

        const flushTerm = () => {
            if (currentCategory && currentTerm) currentCategory.terms.push(currentTerm);
            currentTerm = null;
        };

        for (const raw of lines) {
            const line = raw.trimEnd();

            // Category
            if (line.startsWith("## Category:")) {
                flushTerm();
                currentCategory = {
                    title: line.replace("## Category:", "").trim(),
                    terms: [],
                };
                categories.push(currentCategory);
                continue;
            }

            // Term heading
            if (line.startsWith("### ")) {
                flushTerm();
                const heading = line.replace("### ", ""); // "1. Label"
                const dot = heading.indexOf(".");
                const index = parseInt(heading.slice(0, dot).trim(), 10);
                const label = heading.slice(dot + 1).trim();
                currentTerm = {
                    index,
                    label,
                    definition: "",
                    timestamp: "",
                    followUp: "",
                    state: "collapsed",
                };
                continue;
            }

            // Bullet fields
            if (currentTerm && line.startsWith("- **")) {
                const [, key, value = ""] = line.match(/-\s+\*\*(.+?):\*\*\s*(.*)/);
                switch (key.toLowerCase()) {
                    case "definition":
                        currentTerm.definition = value;
                        break;
                    case "timestamp":
                        currentTerm.timestamp = value;
                        break;
                    case "follow-up":
                        currentTerm.followUp = value;
                        break;
                    case "state":
                        currentTerm.state = value === "expanded" ? "expanded" : "collapsed";
                        break;
                    default:
                        break;
                }
            }
        }
        flushTerm();
        return categories;
    }

    try {
        const categories = useMemo(() => {
            const parsedCategories = parseKeyTermsMarkdown(markdown);
            return parsedCategories;
        }, [markdown]);

        return (
            <div className=""
                style={{
                    fontSize: "14px",
                    fontWeight: "400",
                    color: isYouTubeThemeDark ? "#DDDDDF" : "#0F0F0F",
                }}
            >
                <p className="font-manrope" style={{
                    fontSize: "14px",
                    fontWeight: "400",
                    color: isYouTubeThemeDark ? "#AAAAAA" : "#606060",
                    marginBottom: "24px",
                    lineHeight: "22px"
                }}>
                    These essential terms picked from the video are terms you should be fluent in.
                </p>

                <hr style={{
                    border: "none",
                    height: "1px",
                    backgroundColor: isYouTubeThemeDark ? "#30333c" : "#0000000a",
                    marginBottom: "24px"
                }} />

                {categories.map((cat, index) => (
                    <>
                        <CategoryBlock key={cat.title} category={cat} mentorAiData={mentorAiData} isSidePanelOpen={isSidePanelOpen} markdown={markdown} idx={index} isYouTubeThemeDark={isYouTubeThemeDark} />
                        {index !== categories.length - 1 && (
                            <hr style={{
                                border: "none",
                                height: "1px",
                                backgroundColor: isYouTubeThemeDark ? "#30333c" : "#0000000a",
                                marginTop: "8px",
                                marginBottom: "24px"
                            }} />
                        )}
                    </>
                ))}
            </div>
        )
    } catch (error) {
        console.error("Error parsing key terms markdown", error);
        return <Markdown>{markdown}</Markdown>;
    }
}

export default Keyterms

const TermItem = ({ term, isFirstItemOfFirstCategory, mentorAiData, isSidePanelOpen, markdown, isLastItem, isYouTubeThemeDark }: { term: any, isFirstItemOfFirstCategory?: boolean, mentorAiData: any, isSidePanelOpen: boolean, markdown: any, isLastItem?: boolean, isYouTubeThemeDark: boolean }) => {
    const [open, setOpen] = useState(isFirstItemOfFirstCategory || term.state === "expanded");
    const [isHovering, setIsHovering] = useState(null);
    // const { trackCustomUIEvent } = useCustomUI();
    // const { sendMessage, setSelectedYouTubeSideSectionTab } = useChat();

    const handleTermFollowup = (message: string, selectedText: string) => {
        // sendMessage(message, true, `SelectedText: ${selectedText}`, true)
        // trackCustomUIEvent("Easy Action Clicked", {
        //     info: {
        //         easy_action: message,
        //         easy_action_title: message,
        //         section_title: "Key Terms",
        //         easy_action_message: message,
        //     },
        // });

        // Open side panel and send message there
        if (!isSidePanelOpen) {
            chrome.runtime.sendMessage({ action: "openSidePanel" }).then(() => {
                setTimeout(() => {
                    chrome.runtime.sendMessage({
                        action: "easyActionClicked",
                        easy_action: message,
                        easy_action_title: message,
                        url: window.location.href,
                        is_side_panel_opened: false,
                        section_title: "Key Terms",
                        easy_action_message: message,
                        additional_message: `SelectedText: ${selectedText}`
                    })
                }, 3000);
            });
        } else {    
            chrome.runtime.sendMessage({
                action: "easyActionClicked",
                easy_action: message,
                easy_action_title: message,
                url: window.location.href,
                is_side_panel_opened: true,
                section_title: "Key Terms",
                easy_action_message: message,
                additional_message: `SelectedText: ${selectedText}`
            })
        }
    }

    return (
        <div className="font-manrope" style={{ marginBottom: "16px" }}>
            <div
                style={{ display: "flex", alignItems: "flex-start", cursor: "pointer" }}
                onClick={() => {
                    setOpen(!open)
                    chrome.runtime.sendMessage({
                        action: "sendAnalytics",
                        url: window.location.href,
                        eventName: "MentorAi Revision Notes Section Expanded",
                        eventProperties: {
                            tab_name: "Key Terms",
                            section_name: term.label,
                            current_duration: getYoutubeVideoPlayHead(),
                            video_duration: getYoutubeVideoLength()
                        },
                    })
                }}
            >
                <span
                    style={{
                        background: isYouTubeThemeDark ? "#212431" : "#21243180",
                        color: "#DDDDDF",
                        fontWeight: 600,
                        fontSize: 14,
                        borderRadius: 4,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        cursor: "pointer",
                        lineHeight: "22px",
                        marginRight: 12,
                        width: 20,
                        height: 22,
                    }}
                >
                    {term.index}
                </span>
                <div style={{ flexGrow: 1 }}>
                    <h4 style={{ fontSize: 14, fontWeight: 500, color: isYouTubeThemeDark ? "#DDDDDF" : "#0F0F0F", lineHeight: "22px", letterSpacing: "0.096px" }}>{term.label}</h4>
                    <span onMouseEnter={() => setIsHovering(term.index)} onMouseLeave={() => setIsHovering(null)} style={{ fontSize: 14, lineHeight: "22px", letterSpacing: "0.084px", color: "var(--youtube-primary-color, #A5A1F7)", display: "flex", alignItems: "center", gap: "4px", marginTop: "8px", fontWeight: 500 }} className="transition-all duration-100 hover:!text-[var(--youtube-primary-color)]">
                        {open ? "Collapse" : "Expand"}
                        {open ? <img src={isHovering === term.index ? ArrowUp2Hover : ArrowUp2} alt="Collapse" /> : <img src={isHovering === term.index ? ArrowDownHover : ArrowDown} alt="Expand" />}
                    </span>
                    {open || isLastItem ? null : (
                        <hr style={{
                            border: "none",
                            height: "1px",
                            backgroundColor: isYouTubeThemeDark ? "#30333c" : "#0000000a",
                            marginTop: "24px",
                            marginLeft: "0px"
                        }} />
                    )}
                </div>
            </div>

            {open && (
                <div className="font-manrope" style={{ marginLeft: 32, marginTop: 12, fontSize: "16px", fontWeight: "300", letterSpacing: "0.096px", lineHeight: "24px", color: isYouTubeThemeDark ? "#AAAAAA" : "#606060", }}>
                    <ul style={{
                        fontSize: "14px",
                        fontWeight: "400",
                        color: isYouTubeThemeDark ? "#AAAAAA" : "#606060",
                        marginBottom: "24px",
                        listStyleType: "disc",
                        lineHeight: "22px",
                    }}>
                        <Markdown>{term.definition}</Markdown>
                    </ul>

                    {term.followUp && term.followUp.trim() && (
                        <p style={{ marginTop: 20, gap: "8px", display: "flex" }}>
                            <div className="relative mt-[3px] h-[18px]">
                                {mentorAiData?.photoUrl || mentorAiData?.aiPhotoUrl ? (
                                    <img style={{
                                        minWidth: "16px",
                                        minHeight: "16px",
                                    }}
                                        src={mentorAiData?.photoUrl || mentorAiData?.aiPhotoUrl}
                                        className="h-[16px] w-[16px] rounded-full"
                                        alt="avatar"
                                    />
                                ) : (
                                    <div className="w-[16px] h-[16px] rounded-full bg-[#000]" />
                                )}
                                <span className={`absolute -bottom-[1px] -right-[2px] border-[2px] w-[8px] h-[8px] rounded-full bg-[#1FC16B] ${isYouTubeThemeDark ? ' !border-[#272727]' : ' !border-[#F2F2F2]'}`} />
                            </div>

                            <div onClick={() => handleTermFollowup(term.followUp, JSON.stringify(markdown))} style={{ display: "flex", gap: "8px", fontWeight: 500, color: "var(--youtube-primary-color, #A5A1F7)", cursor: "pointer", fontSize: 14, lineHeight: "22px", letterSpacing: "0.084px" }} className="hover:!text-[var(--youtube-primary-color)] max-w-[92%]">
                                {term.followUp}
                            </div>
                        </p>
                    )}

                    {isLastItem ? null : (
                        <hr style={{
                            border: "none",
                            height: "1px",
                            backgroundColor: isYouTubeThemeDark ? "#30333c" : "#0000000a",
                            marginTop: "24px",
                            marginLeft: "0px"
                        }} />
                    )}
                </div>
            )}
        </div>
    );
};

const CategoryBlock = ({ category, mentorAiData, isSidePanelOpen, markdown, idx, isYouTubeThemeDark }: { category: any, mentorAiData: any, isSidePanelOpen: boolean, markdown: any, idx: number, isYouTubeThemeDark: boolean }) => (
    <section>
        <h3 className="font-manrope" style={{ marginBottom: "24px", fontSize: "16px", fontWeight: "600", color: isYouTubeThemeDark ? "#DDDDDF" : "#0F0F0F", lineHeight: "24px", letterSpacing: "0.096px" }}>{category.title}</h3>
        {category.terms.map((t: any, index: number) => (
            <TermItem key={t.index} term={t} isFirstItemOfFirstCategory={index === 0 && idx === 0} mentorAiData={mentorAiData} isSidePanelOpen={isSidePanelOpen} markdown={markdown} isLastItem={index === category.terms.length - 1} isYouTubeThemeDark={isYouTubeThemeDark} />
        ))}
    </section>
);