import { randomDelay, logToStorage, enableEasyApplyFilter } from './utils';
import { AutoApplyState, LogCallback, FormField } from './types';
import { DELAYS } from './delays.config';

export class AutoApplyManager {
    private state: AutoApplyState;
    private shouldStop: boolean = false;
    private logCallback: LogCallback | null = null;
    private readonly MAX_JOBS_PER_SESSION = 39; // Maximum jobs to apply in a single session

    constructor() {
        this.state = {
            isRunning: false,
            jobsApplied: 0,
            jobsSkipped: 0,
            currentJob: '',
            logs: []
        };
    }

    public setLogCallback(callback: LogCallback) {
        this.logCallback = callback;
    }

    // Check if the async process should stop (more reliable than isRunning)
    public getShouldStop(): boolean {
        return this.shouldStop;
    }

    // Check if session has reached the job limit
    private hasReachedJobLimit(): boolean {
        return this.state.jobsApplied >= this.MAX_JOBS_PER_SESSION;
    }

    // Get remaining jobs that can be applied in this session
    private getRemainingJobsCount(): number {
        return Math.max(0, this.MAX_JOBS_PER_SESSION - this.state.jobsApplied);
    }

    private log(message: string) {
        console.log(`[AutoApply] ${message}`);
        this.state.logs.push(message);
        if (this.state.logs.length > 100) this.state.logs.shift();
        if (this.logCallback) this.logCallback(message);
        logToStorage(message);

        // Send to Side Panel
        chrome.runtime.sendMessage({
            action: 'logAutoApply',
            message
        }).catch(() => {
            // Ignore errors if side panel is closed
        });
    }

    public async start() {
        if (this.state.isRunning) return;
        this.state.isRunning = true;
        this.shouldStop = false;

        // Clear previous logs and reset counters
        this.state.logs = [];
        this.state.jobsApplied = 0;
        this.state.jobsSkipped = 0;
        await chrome.storage.local.set({ autoApplyLogs: [] });

        this.log(`Starting Auto Apply (max ${this.MAX_JOBS_PER_SESSION} jobs per session)...`);

        try {
            chrome.runtime.sendMessage({
                action: 'autoApplyStateUpdate',
                isRunning: true
            }).catch(() => { });

            // Enable Easy Apply filter before starting to process jobs
            this.log('Enabling Easy Apply filter...');
            const filterEnabled = await enableEasyApplyFilter();
            if (filterEnabled) {
                this.log('Easy Apply filter enabled successfully. Waiting for jobs to load...');
                await randomDelay(1500, 2000);
            } else {
                this.log('Warning: Could not enable Easy Apply filter. Proceeding anyway...');
            }

            await this.processJobsWithPagination();
        } catch (error) {
            this.log(`Error in auto apply process: ${error}`);
        } finally {
            this.state.isRunning = false;
            chrome.storage.local.set({
                autoApplyState: { running: false }
            }).catch(() => { });
            chrome.runtime.sendMessage({
                action: 'autoApplyStateUpdate',
                isRunning: false,
                stats: { applied: this.state.jobsApplied, skipped: this.state.jobsSkipped }
            }).catch(() => { });
            this.log('Auto Apply process finished.');
        }
    }

    public stop() {
        this.shouldStop = true;
        this.state.isRunning = false;
        chrome.storage.local.set({
            autoApplyState: { running: false }
        }).catch(() => { });
        chrome.runtime.sendMessage({
            action: 'autoApplyStateUpdate',
            isRunning: false,
            stats: { applied: this.state.jobsApplied, skipped: this.state.jobsSkipped }
        }).catch(() => { });
        this.log('Stopping Auto Apply...');
    }

    public isRunning() {
        return this.state.isRunning;
    }

    /**
     * Main processing loop: Process visible jobs → Scroll for more → Paginate when scroll fails
     */
    private async processJobsWithPagination() {
        const processedJobHrefs = new Set<string>();
        let currentPage = 1;

        while (!this.shouldStop) {
            // Check job limit
            if (this.hasReachedJobLimit()) {
                this.log(`🎯 Session limit reached (${this.MAX_JOBS_PER_SESSION} jobs applied). Stopping Auto Apply...`);
                this.stop();
                return;
            }

            this.log(`--- Page ${currentPage} (${this.getRemainingJobsCount()} jobs remaining) ---`);
            
            let noNewJobsScrollAttempts = 0;
            const maxScrollAttempts = 3;

            // Process all jobs on current page (with scroll-to-load-more)
            while (!this.shouldStop) {
                // Get current visible jobs
                const allJobs = this.getVisibleJobs();
                
                // Filter out already processed jobs
                const unprocessedJobs = allJobs.filter(job => {
                    const href = job.getAttribute('href');
                    return href && !processedJobHrefs.has(href);
                });

                if (unprocessedJobs.length === 0) {
                    // No unprocessed jobs visible, try to scroll for more
                    const loadedMore = await this.scrollToLoadMoreJobs();

                    if (loadedMore) {
                        noNewJobsScrollAttempts = 0;
                        continue; // Check for new jobs
                    } else {
                        noNewJobsScrollAttempts++;
                        if (noNewJobsScrollAttempts >= maxScrollAttempts) {
                            this.log(`No more jobs to load via scroll after ${maxScrollAttempts} attempts.`);
                            break; // Exit to paginate
                        }
                        await randomDelay(800, 1200);
                        continue;
                    }
                }

                // Process the first unprocessed job
                const job = unprocessedJobs[0] as HTMLElement;
                const jobHref = job.getAttribute('href') || '';
                processedJobHrefs.add(jobHref);

                const jobNumber = processedJobHrefs.size;
                this.log(`Processing job ${jobNumber}...`);

                // Scroll job into view and click
                job.scrollIntoView({ behavior: 'smooth', block: 'center' });
                await randomDelay(300, 600);
                job.click();
                await randomDelay(1500, 2500);

                // Try to apply
                const applied = await this.applyToJob();

                if (applied) {
                    this.state.jobsApplied++;
                    this.log(`Job ${jobNumber} applied successfully.`);
                    await randomDelay(1500, 2500);
                } else {
                    this.state.jobsSkipped++;
                    this.log(`Job ${jobNumber} skipped or failed.`);
                    await randomDelay(500, 1000);
                }

                // Update stats
                chrome.runtime.sendMessage({
                    action: 'autoApplyStateUpdate',
                    stats: { applied: this.state.jobsApplied, skipped: this.state.jobsSkipped }
                }).catch(() => { });
            }

            // Try to go to next page
            if (!this.shouldStop) {
                this.log(`Page ${currentPage} complete. Applied: ${this.state.jobsApplied}, Skipped: ${this.state.jobsSkipped}`);
                
                const hasNextPage = await this.goToNextPage();
                if (!hasNextPage) {
                    this.log('No more pages available. Finished.');
                    break;
                }
                
                currentPage++;
                await randomDelay(2000, 3000); // Wait for new page to load
            }
        }

        this.log(`Finished. Total Applied: ${this.state.jobsApplied}, Total Skipped: ${this.state.jobsSkipped}`);
    }

    /**
     * Get currently visible job links (no scrolling)
     */
    private getVisibleJobs(): Element[] {
        const jobLinks = document.querySelectorAll(
            'a.job-card-container__link, ' +
            'a.job-card-list__title, ' +
            '.jobs-search-results__list-item a[href*="/jobs/view/"]'
        );

        // Deduplicate by href
        const uniqueJobs = new Map<string, Element>();
        jobLinks.forEach(link => {
            const href = link.getAttribute('href');
            if (href && !uniqueJobs.has(href)) {
                uniqueJobs.set(href, link);
            }
        });

        return Array.from(uniqueJobs.values());
    }

    /**
     * Scroll to load more jobs via infinite scroll
     * Returns true if new jobs were loaded
     */
    private async scrollToLoadMoreJobs(): Promise<boolean> {
        const beforeCount = this.getVisibleJobs().length;

        // Find the scrollable container
        const jobListContainer = document.querySelector('.jobs-search-results-list') ||
            document.querySelector('.scaffold-layout__list') ||
            document.querySelector('.jobs-search-two-pane__wrapper');

        if (jobListContainer) {
            jobListContainer.scrollTop = jobListContainer.scrollHeight;
        }

        // Also scroll the last job card into view
        const jobCards = document.querySelectorAll('.job-card-container, .jobs-search-results__list-item');
        if (jobCards.length > 0) {
            const lastCard = jobCards[jobCards.length - 1] as HTMLElement;
            lastCard.scrollIntoView({ behavior: 'smooth', block: 'end' });
        }

        // Wait for lazy loading
        await randomDelay(1500, 2000);

        const afterCount = this.getVisibleJobs().length;
        const newJobsLoaded = afterCount > beforeCount;

        if (newJobsLoaded) {
            this.log(`Scrolled: loaded ${afterCount - beforeCount} more jobs (total: ${afterCount})`);
        }

        return newJobsLoaded;
    }

    /**
     * Navigate to the next page of job results
     * Returns true if successfully navigated
     */
    private async goToNextPage(): Promise<boolean> {
        // Find current page number
        const currentPageBtn = document.querySelector(
            '.artdeco-pagination__indicator--number.active button, ' +
            '.artdeco-pagination__indicator--number.selected button'
        );
        const currentPage = currentPageBtn ? parseInt(currentPageBtn.textContent || '1') : 1;

        // Try to find next page button by page number
        const nextPageBtn = document.querySelector(`button[aria-label="Page ${currentPage + 1}"]`) as HTMLElement;
        
        if (nextPageBtn) {
            this.log(`Navigating to page ${currentPage + 1}...`);
            nextPageBtn.click();
            await randomDelay(2500, 3500);
            return true;
        }

        // Try generic next button selectors
        const nextSelectors = [
            'button[aria-label*="Next"]',
            '.artdeco-pagination__button--next:not([disabled])',
            '.jobs-search-pagination__button--next:not([disabled])'
        ];

        for (const selector of nextSelectors) {
            const btn = document.querySelector(selector) as HTMLElement;
            if (btn && !btn.hasAttribute('disabled')) {
                this.log(`Clicking next page button...`);
                btn.click();
                await randomDelay(2500, 3500);
                return true;
            }
        }

        return false;
    }

    private async applyToJob(): Promise<boolean> {
        if (this.shouldStop) return false;

        // Capture job description for AI context
        await this.captureJobDescription();

        // Look for Easy Apply button ONLY in the job details area (not the filter button in toolbar)
        // The filter button is inside: section.scaffold-layout-toolbar
        // The job details panel contains the actual "Easy Apply" button for applying
        const jobDetailsSelectors = [
            '.jobs-details',
            '.jobs-unified-top-card',
            '.job-details-jobs-unified-top-card',
            '.jobs-details-top-card',
            '.jobs-search__job-details',
            '.jobs-details__main-content'
        ];

        // Filter/toolbar selectors to EXCLUDE
        const filterAreaSelectors = [
            '.scaffold-layout-toolbar',
            '.scaffold-layout__list-header',
            '.jobs-search-box',
            '.search-reusables',
            '.jobs-search-results-list__filters',
            '.search-reusables__filters-bar',
            '.jobs-search-box__filters'
        ];

        let easyApplyBtn: HTMLElement | null = null;

        // First, try to find the Easy Apply button within job details containers
        for (const selector of jobDetailsSelectors) {
            const container = document.querySelector(selector);
            if (container) {
                const buttons = Array.from(container.querySelectorAll('button'));
                const found = buttons.find(btn => {
                    const text = btn.innerText?.trim() || '';
                    if (text !== 'Easy Apply') return false;
                    
                    // Make sure it's NOT inside a filter/toolbar area
                    for (const filterSelector of filterAreaSelectors) {
                        if (btn.closest(filterSelector)) {
                            return false;
                        }
                    }
                    return true;
                });
                if (found) {
                    easyApplyBtn = found as HTMLElement;
                    this.log(`Found Easy Apply button in ${selector}`);
                    break;
                }
            }
        }

        // Fallback: Look for Easy Apply button that is NOT in filter areas
        if (!easyApplyBtn) {
            const allButtons = Array.from(document.querySelectorAll('button'));
            easyApplyBtn = allButtons.find(btn => {
                const text = btn.innerText?.trim() || '';
                if (text !== 'Easy Apply') return false;
                
                // Make sure this button is NOT in any filter/toolbar area
                for (const filterSelector of filterAreaSelectors) {
                    if (btn.closest(filterSelector)) {
                        this.log(`Skipping Easy Apply button in filter area: ${filterSelector}`);
                        return false;
                    }
                }
                
                // Prefer buttons that are in job details area
                const isInJobDetails = btn.closest('.jobs-details, .jobs-unified-top-card, .job-details-jobs-unified-top-card, .jobs-search__job-details, .jobs-details-top-card, .jobs-details__main-content');
                return isInJobDetails !== null;
            }) as HTMLElement | null;
            
            if (easyApplyBtn) {
                this.log('Found Easy Apply button via fallback method');
            }
        }

        if (!easyApplyBtn) {
            // Check if job was already applied to
            const jobDetailsArea = document.querySelector('.jobs-details, .jobs-unified-top-card, .job-details-jobs-unified-top-card');
            if (jobDetailsArea) {
                const detailsText = (jobDetailsArea as HTMLElement).innerText?.toLowerCase() || '';
                if (detailsText.includes('applied') || detailsText.includes('application sent') || detailsText.includes('application submitted')) {
                    this.log('Job already applied to. Skipping...');
                    return false;
                }
            }
            this.log('No Easy Apply button found in job details.');
            return false;
        }

        this.log('Clicking Easy Apply...');
        await randomDelay(...DELAYS.EASY_APPLY.PRE_CLICK);
        easyApplyBtn.click();

        // Wait for modal
        await randomDelay(...DELAYS.EASY_APPLY.MODAL_WAIT);

        // Handle Modal Steps
        let maxSteps = 10; // Safety break
        let step = 0;
        let consecutiveErrorRetries = 0;

        while (step < maxSteps) {
            if (this.shouldStop) return false;

            const modal = document.querySelector('.jobs-easy-apply-modal') as HTMLElement;
            if (!modal) {
                this.log('Modal closed unexpectedly.');
                return false;
            }

            // Check for "Submit application" button
            const submitBtn = Array.from(modal.querySelectorAll('button')).find(b => b.innerText.includes('Submit application'));
            if (submitBtn) {
                this.log('Found Submit button. Clicking it!');
                await randomDelay(1000, 1500); // Delay before submit (optimized)
                submitBtn.click();
                await randomDelay(2000, 3000); // Wait for submission (optimized)

                // Close any success modal if it appears (usually "Done" or "Dismiss")
                const closeBtn = (document.querySelector('.artdeco-modal__dismiss') || document.querySelector('button[aria-label="Dismiss"]')) as HTMLElement;
                if (closeBtn) {
                    await randomDelay(500, 1000); // Optimized
                    closeBtn.click();
                }

                return true;
            }

            // Check for "Next" or "Review" button
            const nextBtn = Array.from(modal.querySelectorAll('button')).find(b => b.innerText.includes('Next') || b.innerText.includes('Review'));

            // Check for complex personal forms to skip
            if (await this.checkForComplexForms(modal)) {
                this.log('Complex personal form detected (Disability/Veteran/Race). Skipping job.');

                // Close modal and discard
                const closeBtn = modal.querySelector('button[aria-label="Dismiss"]') as HTMLElement;
                if (closeBtn) {
                    closeBtn.click();
                    await randomDelay(500, 1000); // Optimized
                    await this.handleExitModal();
                }
                return false; // Job skipped
            }

            // Fill form fields before clicking Next
            await this.fillFormFields(modal);

            // Handle any errors from previous step
            const hasErrors = modal.querySelectorAll('.artdeco-inline-feedback--error').length > 0;
            if (hasErrors) {
                consecutiveErrorRetries++;
                if (consecutiveErrorRetries > 3) {
                    this.log('Too many consecutive errors (3). Skipping job.');
                    // Close modal and discard
                    const closeBtn = modal.querySelector('button[aria-label="Dismiss"]') as HTMLElement;
                    if (closeBtn) {
                        closeBtn.click();
                        await randomDelay(500, 1000); // Optimized
                        await this.handleExitModal();
                    }
                    return false;
                }
                await this.handleErrors(modal);
            } else {
                consecutiveErrorRetries = 0;
            }

            if (nextBtn) {
                this.log('Clicking Next/Review...');
                await randomDelay(500, 1000); // Optimized
                if (this.shouldStop) return false;
                nextBtn.click();
                await randomDelay(1500, 2000); // Optimized
                step++;
            } else {
                this.log('Stuck in modal. No Next/Submit button.');
                // Try to dismiss if stuck
                const closeBtn = modal.querySelector('button[aria-label="Dismiss"]') as HTMLElement;
                if (closeBtn) {
                    closeBtn.click();
                    await randomDelay(500, 1000); // Optimized
                    await this.handleExitModal();
                }
                break;
            }
        }

        return false;
    }

    private async checkForComplexForms(modal: HTMLElement): Promise<boolean> {
        const textContent = modal.innerText.toLowerCase();
        const keywords = [
            'disability',
            'veteran status',
            'race/ethnicity',
            'voluntary self-identification',
            'protected veteran'
        ];

        // 1. Quick Keyword Check (Client-side)
        if (!keywords.some(k => textContent.includes(k))) {
            return false;
        }

        this.log('Detected complex form keywords. Verifying with AI...');

        // 2. AI Check via new API
        const result = await this.checkComplexFormAPI(modal.innerText.substring(0, 2000));
        return result;
    }

    /**
     * Call backend API to check for complex forms
     */
    private async checkComplexFormAPI(formText: string): Promise<boolean> {
        return new Promise((resolve) => {
            chrome.runtime.sendMessage({
                action: "ai_calls",
                ai_call: "auto_apply_check_complex",
                payload: { form_text: formText }
            }, (response) => {
                if (chrome.runtime.lastError || !response?.success) {
                    resolve(false);
                    return;
                }
                resolve(response.data?.is_complex === true);
            });
        });
    }

    private async handleErrors(modal: HTMLElement) {
        const errorElements = modal.querySelectorAll('.artdeco-inline-feedback--error');
        if (errorElements.length === 0) return;

        this.log(`⚠️ Found ${errorElements.length} errors. Asking Leeco to fix...`);

        const data = await chrome.storage.local.get(['resumeUrl', 'currentJobDescription', 'careerProfile']);
        const resumeUrl = data.resumeUrl || '';
        const jobDescription = data.currentJobDescription || '';
        const careerProfile = data.careerProfile || {};

        // Collect all error fields for batch processing
        const errorFields: FormField[] = [];
        const errorInputMap: Map<string, HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement> = new Map();

        for (const errorEl of errorElements) {
            if ((errorEl as HTMLElement).style.display === 'none') continue;

            const container = errorEl.closest('.jobs-easy-apply-form-section__grouping') ||
                errorEl.closest('.fb-dash-form-element') ||
                errorEl.parentElement;

            if (!container) continue;

            const input = container.querySelector('input, select, textarea') as HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement;
            if (!input) continue;

            const question = this.getLabelText(input);
            const errorText = (errorEl as HTMLElement).innerText;
            const fieldId = `error_${errorFields.length}`;

            const field: FormField = {
                id: fieldId,
                field_type: input.tagName === 'SELECT' ? 'select' : 'text',
                label: question,
                error_message: errorText,
                current_value: input.value
            };

            if (input.tagName === 'SELECT') {
                const select = input as HTMLSelectElement;
                field.options = Array.from(select.options)
                    .map(o => o.text.trim())
                    .filter(t => t !== '' && !t.toLowerCase().includes('select') && !t.toLowerCase().includes('choose') && t !== '-' && t !== '--');
            }

            errorFields.push(field);
            errorInputMap.set(fieldId, input);
        }

        if (errorFields.length === 0) return;

        // Batch API call for all error fixes (include careerProfile)
        const answers = await this.fillBatchAPI(errorFields, resumeUrl, jobDescription, careerProfile);

        // Apply answers to fields
        for (const field of errorFields) {
            const answer = answers[field.id];
            const input = errorInputMap.get(field.id);

            if (!answer || !input) continue;

            this.log(`🔧 Fixed: "${field.label.substring(0, 35)}${field.label.length > 35 ? '...' : ''}" → ${answer.substring(0, 25)}${answer.length > 25 ? '...' : ''}`);
            await randomDelay(300, 600);

            if (input.tagName === 'SELECT') {
                const select = input as HTMLSelectElement;
                const lowerAnswer = answer.toLowerCase().trim();
                
                const matchingOption = Array.from(select.options).find(o =>
                    o.text.toLowerCase().trim() === lowerAnswer ||
                    o.text.toLowerCase().includes(lowerAnswer) ||
                    lowerAnswer.includes(o.text.toLowerCase())
                );
                
                if (matchingOption) {
                    select.value = matchingOption.value;
                } else {
                    // Fallback to first valid option
                    const firstValid = Array.from(select.options).find(o => {
                        const t = o.text.toLowerCase().trim();
                        return t !== '' && !t.includes('select') && !t.includes('choose') && t !== '-' && t !== '--';
                    });
                    if (firstValid) select.value = firstValid.value;
                }
                select.dispatchEvent(new Event('change', { bubbles: true }));
            } else {
                input.value = answer;
                input.dispatchEvent(new Event('input', { bubbles: true }));
                input.dispatchEvent(new Event('change', { bubbles: true }));
                input.dispatchEvent(new Event('blur', { bubbles: true }));
            }
        }
    }

    private async handleExitModal() {
        const dialogs = document.querySelectorAll('div[role="dialog"], .artdeco-modal');
        const exitModal = Array.from(dialogs).find(d => (d as HTMLElement).innerText.includes('Save this application?'));

        if (exitModal) {
            this.log('Exit modal detected. Clicking Discard...');
            const discardBtn = Array.from(exitModal.querySelectorAll('button')).find(b => b.innerText.includes('Discard'));
            if (discardBtn) {
                discardBtn.click();
                await randomDelay(400, 600); // Optimized
            }
        }
    }

    private async fillFormFields(modal: HTMLElement) {
        const data = await chrome.storage.local.get(['resumeUrl', 'currentJobDescription', 'careerProfile']);
        const resumeUrl = data.resumeUrl || '';
        const jobDescription = data.currentJobDescription || '';
        const careerProfile = data.careerProfile || {};

        // Collect all form fields for batch processing
        const fields: FormField[] = [];
        const fieldElementMap: Map<string, HTMLElement> = new Map();
        let fieldIndex = 0;

        // Helper to add field
        const addField = (element: HTMLElement, type: FormField['field_type'], label: string, options?: string[]) => {
            const fieldId = `field_${fieldIndex++}`;
            fields.push({ id: fieldId, field_type: type, label, options });
            fieldElementMap.set(fieldId, element);
        };

        // Helper to detect field type
        const detectFieldType = (input: HTMLInputElement, question: string): FormField['field_type'] => {
            const lowerQ = question.toLowerCase();
            
            // Location detection
            if (this.isLocationField(input, question)) return 'text_location';
            
            // Numeric detection
            if (input.type === 'number' ||
                lowerQ.includes('years of') || lowerQ.includes('experience') ||
                lowerQ.includes('how many') || lowerQ.includes('phone') ||
                lowerQ.includes('mobile') || lowerQ.includes('salary') ||
                lowerQ.includes('ctc') || lowerQ.includes('notice period')) {
                return 'text_numeric';
            }
            
            return 'text';
        };

        // 1. Collect Text Inputs & Textareas (excluding location fields for now)
        const textInputs = modal.querySelectorAll('input[type="text"], input[type="email"], input[type="tel"], input[type="number"], textarea');
        const locationFields: { element: HTMLInputElement; label: string }[] = [];
        
        for (const input of textInputs) {
            if ((input as HTMLInputElement).value) continue;
            const label = this.getLabelText(input as HTMLElement);
            if (!label) continue;
            
            const fieldType = detectFieldType(input as HTMLInputElement, label);
            
            // Collect location fields separately for special handling
            if (fieldType === 'text_location') {
                locationFields.push({ element: input as HTMLInputElement, label });
            } else {
                addField(input as HTMLElement, fieldType, label);
            }
        }

        // 2. Collect Select Dropdowns
        const selects = modal.querySelectorAll('select');
        for (const select of selects) {
            if (select.value) continue;
            const label = this.getLabelText(select);
            if (!label) continue;
            
            const options = Array.from(select.options)
                .map(o => o.text.trim())
                .filter(t => t !== '' && !t.toLowerCase().includes('select') && !t.toLowerCase().includes('choose') && t !== '-' && t !== '--');
            
            addField(select as HTMLElement, 'select', label, options);
        }

        // 3. Collect Radio Buttons
        const fieldsets = modal.querySelectorAll('fieldset');
        for (const fieldset of fieldsets) {
            const selected = fieldset.querySelector('input[type="radio"]:checked');
            if (selected) continue;
            
            const legend = fieldset.querySelector('legend');
            let label = legend ? legend.innerText : '';
            if (!label) {
                const textNode = fieldset.querySelector('.fb-dash-form-element__label') || fieldset.querySelector('span[aria-hidden="true"]');
                if (textNode) label = (textNode as HTMLElement).innerText;
            }
            if (!label) continue;
            
            addField(fieldset as HTMLElement, 'radio', label);
        }

        // 4. Collect Checkboxes
        const checkboxes = modal.querySelectorAll('input[type="checkbox"]');
        for (const checkbox of checkboxes) {
            if ((checkbox as HTMLInputElement).checked) continue;
            
            let label = this.getLabelText(checkbox as HTMLElement);
            if (!label) {
                const parentLabel = checkbox.closest('label');
                if (parentLabel) label = parentLabel.innerText;
            }
            if (!label) continue;
            
            const lowerLabel = label.toLowerCase();
            if (lowerLabel.includes('mark job as a top choice') ||
                lowerLabel.includes('follow') ||
                lowerLabel.includes('email me about similar jobs')) {
                continue; // Skip excluded checkboxes
            }
            
            addField(checkbox as HTMLElement, 'checkbox', label);
        }

        // 5. Make batch API call if we have fields
        if (fields.length > 0) {
            this.log(`🤖 Asking Leeco to fill ${fields.length} questions...`);
            const answers = await this.fillBatchAPI(fields, resumeUrl, jobDescription, careerProfile);
            
            // Apply answers to fields
            for (const field of fields) {
                const answer = answers[field.id];
                const element = fieldElementMap.get(field.id);
                
                if (!answer || !element) continue;
                if (this.shouldStop) return;

                this.log(`✍️ "${field.label.substring(0, 40)}${field.label.length > 40 ? '...' : ''}" → ${answer.substring(0, 30)}${answer.length > 30 ? '...' : ''}`);
                await randomDelay(...DELAYS.FORM_FIELDS.BETWEEN_FIELDS);

                switch (field.field_type) {
                    case 'text':
                    case 'text_numeric':
                        this.setInputValue(element as HTMLInputElement, field.field_type === 'text_numeric' ? this.extractNumber(answer) : answer);
                        break;
                    
                    case 'select':
                        this.setSelectValue(element as HTMLSelectElement, answer);
                        break;
                    
                    case 'radio':
                        this.setRadioValue(element as HTMLElement, answer);
                        break;
                    
                    case 'checkbox':
                        if (answer.toLowerCase().includes('yes')) {
                            (element as HTMLElement).click();
                            element.dispatchEvent(new Event('change', { bubbles: true }));
                        }
                        break;
                }
            }
        }

        // 6. Handle location fields with typeahead (requires special handling)
        for (const { element, label } of locationFields) {
            if (this.shouldStop) return;
            await this.handleLocationInput(element, label, resumeUrl, jobDescription);
        }

        // 7. Handle File Inputs (Resume Upload) - no AI needed
        await this.handleFileUploads(modal, resumeUrl);
    }

    /**
     * Call batch API to fill multiple fields at once
     */
    private async fillBatchAPI(fields: FormField[], resumeUrl: string, jobDescription: string, userProfile: any = {}): Promise<Record<string, string>> {
        return new Promise((resolve) => {
            chrome.runtime.sendMessage({
                action: "ai_calls",
                ai_call: "auto_apply_fill_batch",
                payload: { fields, resume_url: resumeUrl, job_description: jobDescription, user_profile: userProfile }
            }, (response) => {
                if (chrome.runtime.lastError) {
                    console.error("Runtime error in batch fill:", chrome.runtime.lastError);
                    resolve({});
                    return;
                }
                if (response?.success && response.data?.answers) {
                    resolve(response.data.answers);
                } else {
                    console.error("Batch fill failed:", response?.error);
                    resolve({});
                }
            });
        });
    }

    // ============ Helper Methods ============

    private isLocationField(input: HTMLElement, question: string): boolean {
        const lowerQuestion = question.toLowerCase();
        const placeholder = ((input as HTMLInputElement).placeholder || '').toLowerCase();
        const ariaLabel = (input.getAttribute('aria-label') || '').toLowerCase();
        const inputId = (input.id || '').toLowerCase();
        const inputName = ((input as HTMLInputElement).name || '').toLowerCase();
        
        return (
            lowerQuestion.includes('location') ||
            lowerQuestion.includes('city') ||
            lowerQuestion.includes('where are you located') ||
            placeholder.includes('location') ||
            placeholder.includes('city') ||
            ariaLabel.includes('location') ||
            ariaLabel.includes('city') ||
            inputId.includes('location') ||
            inputId.includes('city') ||
            inputName.includes('location') ||
            inputName.includes('city') ||
            input.closest('.basic-typeahead') !== null ||
            input.closest('[data-test-single-typeahead]') !== null
        );
    }

    private extractNumber(answer: string): string {
        const match = answer.match(/[\d,.]+/);
        return match ? match[0].replace(/,/g, '') : '0';
    }

    private setInputValue(input: HTMLInputElement | HTMLTextAreaElement, value: string) {
        input.value = value;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
        input.dispatchEvent(new Event('blur', { bubbles: true }));
    }

    private setSelectValue(select: HTMLSelectElement, answer: string) {
        const lowerAnswer = answer.toLowerCase().trim();
        
        const matchingOption = Array.from(select.options).find(o =>
            o.text.toLowerCase().trim() === lowerAnswer ||
            o.text.toLowerCase().includes(lowerAnswer) ||
            lowerAnswer.includes(o.text.toLowerCase())
        );

        if (matchingOption) {
            select.value = matchingOption.value;
        } else {
            // Fallback: select first valid option
            const firstValid = Array.from(select.options).find(o => {
                const t = o.text.toLowerCase().trim();
                return t !== '' && !t.includes('select') && !t.includes('choose') && t !== '-' && t !== '--';
            });
            if (firstValid) select.value = firstValid.value;
        }
        select.dispatchEvent(new Event('change', { bubbles: true }));
    }

    private setRadioValue(fieldset: HTMLElement, answer: string) {
        const isYes = answer.toLowerCase().includes('yes');
        const radios = Array.from(fieldset.querySelectorAll('input[type="radio"]')) as HTMLInputElement[];

        const targetRadio = radios.find(r => {
            const label = r.getAttribute('aria-label') || r.value || '';
            const nextSibling = r.nextElementSibling as HTMLElement;
            const siblingText = nextSibling ? nextSibling.innerText : '';

            return isYes
                ? (label.toLowerCase().includes('yes') || siblingText.toLowerCase().includes('yes'))
                : (label.toLowerCase().includes('no') || siblingText.toLowerCase().includes('no'));
        });

        if (targetRadio) {
            targetRadio.click();
            targetRadio.dispatchEvent(new Event('change', { bubbles: true }));
        } else if (radios.length >= 2) {
            (isYes ? radios[0] : radios[1]).click();
        }
    }

    private async handleLocationInput(input: HTMLInputElement, question: string, resumeUrl: string, jobDescription: string): Promise<boolean> {
        this.log(`[Location] Handling location field: ${question}`);
        
        // Get location from batch API (single field)
        const fields: FormField[] = [{ id: 'location', field_type: 'text_location', label: question }];
        const answers = await this.fillBatchAPI(fields, resumeUrl, jobDescription);
        
        let locationValue = answers['location'] || 'Bangalore';
        locationValue = locationValue.trim().replace(/['"]/g, '');
        
        if (!locationValue || locationValue.toLowerCase().includes('not') || locationValue.toLowerCase().includes('unknown')) {
            locationValue = 'Bangalore';
        }
        
        this.log(`[Location] Using location value: ${locationValue}`);

        // Clear and type character by character
        input.focus();
        input.value = '';
        input.dispatchEvent(new Event('input', { bubbles: true }));
        await randomDelay(...DELAYS.FORM_FIELDS.LOCATION_INITIAL);

        for (const char of locationValue) {
            if (this.shouldStop) return false;
            input.value += char;
            input.dispatchEvent(new Event('input', { bubbles: true }));
            input.dispatchEvent(new KeyboardEvent('keydown', { key: char, bubbles: true }));
            input.dispatchEvent(new KeyboardEvent('keyup', { key: char, bubbles: true }));
            await randomDelay(...DELAYS.FORM_FIELDS.LOCATION_CHAR_TYPE);
        }

        // Wait for autocomplete
        await randomDelay(...DELAYS.FORM_FIELDS.LOCATION_AUTOCOMPLETE);

        // Try to click first autocomplete option
        const autocompleteSelectors = [
            '.basic-typeahead__selectable',
            '.typeahead-result',
            '[role="listbox"] [role="option"]',
            '[role="listbox"] li',
            '.artdeco-typeahead__result',
            '.artdeco-typeahead__results-list li',
            '[data-test-single-typeahead-result]',
            '.basic-typeahead__triggered-content li'
        ];

        for (const selector of autocompleteSelectors) {
            const options = document.querySelectorAll(selector);
            if (options.length > 0) {
                this.log(`[Location] Found autocomplete options`);
                (options[0] as HTMLElement).click();
                await randomDelay(...DELAYS.FORM_FIELDS.LOCATION_SELECT);
                return true;
            }
        }

        // Fallback: press Enter/Tab
        input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, bubbles: true }));
        await randomDelay(...DELAYS.FORM_FIELDS.LOCATION_SELECT);
        input.dispatchEvent(new Event('blur', { bubbles: true }));
        
        return true;
    }

    private async handleFileUploads(modal: HTMLElement, resumeUrl: string) {
        const fileInputs = modal.querySelectorAll('input[type="file"]');
        
        for (const input of fileInputs) {
            const label = this.getLabelText(input as HTMLElement).toLowerCase();
            if (!label.includes('resume') && !label.includes('cv') && !label.includes('upload')) continue;
            if (!resumeUrl) continue;

            this.log(`[File] Uploading resume...`);
            
            const fileData = await new Promise<string | null>((resolve) => {
                chrome.runtime.sendMessage({
                    action: 'download_file',
                    url: resumeUrl
                }, (response) => {
                    resolve(response?.success ? response.data : null);
                });
            });

            if (fileData) {
                try {
                    const res = await fetch(fileData);
                    const blob = await res.blob();
                    const fileName = resumeUrl.split('/').pop()?.split('?')[0] || 'resume.pdf';
                    const file = new File([blob], fileName, { type: 'application/pdf' });

                    const dataTransfer = new DataTransfer();
                    dataTransfer.items.add(file);
                    (input as HTMLInputElement).files = dataTransfer.files;
                    input.dispatchEvent(new Event('change', { bubbles: true }));
                    
                    this.log(`[File] Successfully uploaded: ${fileName}`);
                } catch (error) {
                    this.log(`[File] Error uploading: ${error}`);
                }
            }
        }
    }

    /**
     * Capture job description from the current job listing page for AI context
     */
    private async captureJobDescription(): Promise<void> {
        try {
            // Selectors for job description content
            const descriptionSelectors = [
                '.jobs-description__content',
                '.jobs-description-content',
                '.job-details-jobs-unified-top-card__primary-description-container',
                '.jobs-details__main-content',
                '#job-details'
            ];

            let jobDescription = '';
            let jobTitle = '';
            let companyName = '';

            // Get job title
            const titleEl = document.querySelector('.jobs-unified-top-card__job-title, .job-details-jobs-unified-top-card__job-title, h1.t-24');
            if (titleEl) jobTitle = (titleEl as HTMLElement).innerText.trim();

            // Get company name
            const companyEl = document.querySelector('.jobs-unified-top-card__company-name, .job-details-jobs-unified-top-card__company-name');
            if (companyEl) companyName = (companyEl as HTMLElement).innerText.trim();

            // Get job description
            for (const selector of descriptionSelectors) {
                const el = document.querySelector(selector);
                if (el) {
                    jobDescription = (el as HTMLElement).innerText.trim();
                    if (jobDescription.length > 100) break;
                }
            }

            // Build context string
            const context = [
                jobTitle && `Job Title: ${jobTitle}`,
                companyName && `Company: ${companyName}`,
                jobDescription && `Description: ${jobDescription.substring(0, 2000)}`
            ].filter(Boolean).join('\n\n');

            // Store for use during form filling
            await chrome.storage.local.set({ currentJobDescription: context });
            
            if (context) {
                this.log(`[Job] Captured job context: ${jobTitle} at ${companyName}`);
            }
        } catch (error) {
            console.error('Error capturing job description:', error);
        }
    }

    private getLabelText(element: HTMLElement): string {
        if ((element as any).labels && (element as any).labels.length > 0) return (element as any).labels[0].innerText;
        if (element.getAttribute('aria-label')) return element.getAttribute('aria-label') || '';

        const container = element.closest('.jobs-easy-apply-form-section__grouping') || element.parentElement;
        if (container) {
            const label = container.querySelector('label');
            if (label) return label.innerText;

            const prev = container.previousElementSibling;
            if (prev && (prev.tagName === 'LABEL' || prev.tagName === 'H3' || prev.tagName === 'SPAN')) {
                return (prev as HTMLElement).innerText;
            }
        }

        return '';
    }
}

