import React, { useState } from 'react';
import { useCustomUI } from '../../../contexts/custom-ui-context/custom-ui-context';
import Button from '../../../../src/components/common/common-button';
import FocusMoreIcon from '../../../assets/icons/focus-more.svg';
import BuildConfidenceIcon from '../../../assets/icons/build-confidence.svg';
import AskManyQuestionsIcon from '../../../assets/icons/ask-many-questions.svg';
import Loading from "../../../../src/assets/loading.gif"
import { getStatus } from '../../../utils/get-tippy-status';
import { motion } from 'framer-motion';
import Tippy from '@tippyjs/react';
import TippyContent from '../learning-session-toggle/tippy-content';

const FirstTimeLearningSessionOverlay = () => {
    const { toggleLearningSession, playerMode, sessionCreationStatus } = useCustomUI();

    const isPlayerModeDefault = playerMode === 'DEFAULT';
    const [showTippy, setShowTippy] = useState(false)
    const tippyStatus = getStatus(sessionCreationStatus)
    const isCreating = (tippyStatus === "checkingTranscript" || tippyStatus === "sectionGenerating" || tippyStatus === "quizGenerating");

    const containerVariants = {
        hidden: {
            opacity: 0
        },
        visible: {
            opacity: 1,
            transition: {
                duration: 0.3,
                when: "beforeChildren",
                staggerChildren: 0.3,
                delayChildren: 0.1
            }
        }
    };

    const cardsContainerVariants = {
        hidden: {
            opacity: 0
        },
        visible: {
            opacity: 1,
            transition: {
                duration: 0.3,
                delay: 0.3 
            }
        }
    };

    const titleVariants = {
        hidden: {
            opacity: 0,
            y: 10
        },
        visible: {
            opacity: 1,
            y: 0,
            transition: {
                duration: 0.3
            }
        }
    };

    const firstCardVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: {
                duration: 0.3,
                delay: 0.6
            }
        }
    };

    const secondCardVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: {
                duration: 0.3,
                delay: 0.9
            }
        }
    };

    const thirdCardVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: {
                duration: 0.3,
                delay: 1.2
            }
        }
    };

    const ctaVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: {
                duration: 0.3,
                delay: 1.5
            }
        }
    };

    return (
        <motion.div
            className={`flex gap-x-[32px] items-center justify-center h-full ${isPlayerModeDefault ? 'flex-row' : 'flex-col'}`}
            variants={containerVariants}
            initial="hidden"
            animate="visible"
        >
            <div className="space-y-[16px]">
                <motion.div variants={titleVariants}>
                    {isPlayerModeDefault ?
                        <p className="text-[#DDDDDF] font-bold text-[24px] leading-[34px]">Turn passive watch into <br />active learning!</p>
                        : <p className="text-[#DDDDDF] font-bold text-[24px] leading-[34px]">Turn passive watch into active learning!</p>}
                </motion.div>
                {isPlayerModeDefault && (
                    <Tippy
                        visible={showTippy && (tippyStatus !== "idle")}
                        content={<TippyContent
                            tippyStatus={tippyStatus}
                        />}
                    >
                        <motion.div variants={ctaVariants}
                            onMouseEnter={() => {
                                setShowTippy(true)
                            }}
                            onMouseLeave={() => {
                                setShowTippy(false)
                            }}>
                            <Button className="py-[12px] px-[24px] text-[14px] font-medium leading-[22px] bg-[#5149F2] rounded-[12px]" onClick={toggleLearningSession} disabled={isCreating}>
                                {
                                    (isCreating) ?
                                        <div className="flex items-center justify-center gap-x-[8px]">
                                            <p className="text-[14px] leading-[22px] font-medium text-[#fff]"> Creating Session</p>
                                            <img src={Loading} alt="" style={{ width: 16, height: 16 }} />
                                        </div>
                                        : "Start Learning"
                                }
                            </Button>
                        </motion.div>
                    </Tippy>
                )}
            </div>

            <motion.div
                className={`${isPlayerModeDefault ? 'space-y-[8px]' : 'space-y-[16px] mt-[20px]'}`}
                variants={cardsContainerVariants}
            >
                <motion.div variants={firstCardVariants} className={`${isPlayerModeDefault ? 'max-w-[430px] p-[12px]' : 'max-w-[500px] p-[16px]'} rounded-xl bg-[rgba(20,22,31,0.75)] shadow-[0px_4px_12px_0px_rgba(0,0,0,0.12)] flex gap-[8px] items-start`}>
                    <div className='flex'>
                        <img src={FocusMoreIcon} alt="focus-more" className='h-[24px] w-[24px] shrink-0' />
                    </div>
                    <div className="space-y-[2px]">
                        <p className="text-[#DDDDDF] text-[14px] font-semibold leading-[22px] -tracking-[0.14px]">Focus more with bite-sized sections</p>
                        <p className="text-[14px] font-medium leading-[22px] text-[#94939F] tracking-[0.084px]">Long videos are hard to focus on. We'll instead focus on divided, smaller chunks. We can skip parts that don't matter.</p>
                    </div>
                </motion.div>
                <motion.div variants={secondCardVariants} className={`${isPlayerModeDefault ? 'max-w-[430px] p-[12px] ' : 'max-w-[500px] p-[16px]'} rounded-xl bg-[rgba(20,22,31,0.75)] shadow-[0px_4px_12px_0px_rgba(0,0,0,0.12)] flex gap-[8px] items-start`}>
                    <div className='flex'>
                        <img src={BuildConfidenceIcon} alt="build-confidence" className='h-[24px] w-[24px] shrink-0' />
                    </div>
                    <div className="space-y-[2px]">
                        <p className="text-[#DDDDDF] text-[14px] font-semibold leading-[22px] -tracking-[0.14px]">Build confidence with quizzes</p>
                        <p className="text-[14px] font-medium leading-[22px] text-[#94939F] tracking-[0.084px]">Evaluation builds confidence. Mini quizzes at the end of important sections will help you retain what you're learning.</p>
                    </div>
                </motion.div>
                <motion.div variants={thirdCardVariants} className={`${isPlayerModeDefault ? ' max-w-[430px] p-[12px] ' : 'max-w-[500px] p-[16px]'} rounded-xl bg-[rgba(20,22,31,0.75)] shadow-[0px_4px_12px_0px_rgba(0,0,0,0.12)] flex gap-[8px] items-start`}>
                    <div className='flex'>
                        <img src={AskManyQuestionsIcon} alt="ask-many-questions" className='h-[24px] w-[24px] shrink-0' />
                    </div>
                    <div className="space-y-[2px]">
                        <p className="text-[#DDDDDF] text-[14px] font-semibold leading-[22px] -tracking-[0.14px]">Ask as many questions as you need</p>
                        <p className="text-[14px] font-medium leading-[22px] text-[#94939F] tracking-[0.084px]">Clarify your doubts as they come up. Just pause the video and I'll be there!</p>
                    </div>
                </motion.div>
            </motion.div>

            {!isPlayerModeDefault && (
                <Tippy
                    visible={showTippy && (tippyStatus !== "idle")}
                    content={<TippyContent
                        tippyStatus={tippyStatus}
                    />}
                >
                    <motion.div variants={ctaVariants}
                        onMouseEnter={() => {
                            setShowTippy(true)
                        }}
                        onMouseLeave={() => {
                            setShowTippy(false)
                        }}>
                        <Button className="mt-[28px] py-[12px] px-[24px] text-[16px] font-medium leading-[24px] bg-[#5149F2] rounded-[12px] w-[500px]" onClick={toggleLearningSession} disabled={isCreating}>
                            {
                                (isCreating) ?
                                    <div className="flex items-center justify-center gap-x-[8px]">
                                        <p className="text-[16px] leading-[24px] font-medium text-[#fff]"> Creating Session</p>
                                        <img src={Loading} alt="" style={{ width: 16, height: 16 }} />
                                    </div>
                                    : "Start Learning"
                            }
                        </Button>
                    </motion.div>
                </Tippy>
            )}
        </motion.div>

    );
};

export default FirstTimeLearningSessionOverlay;