import React from 'react';
import { useCustomUI } from '../../../contexts/custom-ui-context/custom-ui-context';
import MentorAiActiveAvatar from '../../mentorai-active-avatar/mentorai-active-avatar';
import MentorAiButton from '../../../../common/button/mentorai-button';
import CompletedIcon from '../../../assets/icons/completed.svg';
import LoadingIcon from '../../../assets/gif/loading.gif';
import ErrorIcon from '../../../assets/icons/error-warning.svg';
import RefreshIcon from '../../../assets/icons/refresh-lin.svg';
// import { timeToSeconds } from '../../../../src/utils/str-time-to-seconds';
// import { formatTimeDurationFromSeconds } from '../../../utils/learning-session-helper';

const CreatingOverlay: React.FC = () => {
  const { sessionCreationStatus, mentoraiData, toggleLearningSession, playerMode } = useCustomUI();
  const status = sessionCreationStatus;
  const isPlayerModeDefault = playerMode === 'DEFAULT';
  // const currentVideoTimeInSeconds = document.querySelector("video")?.currentTime || 0;
  // const currentVideoTime = formatTimeDurationFromSeconds(document.querySelector("video")?.currentTime || 0);

  const steps = [
    {
      key: 'checking_transcription',
      title: 'Scanned video contents',
      subtitle: 'First, I need to dig deep into the video to understand its flow.',
    },
    {
      key: 'generating_section',
      title: 'Turning the video into bite-sized sections...',
      subtitle: `I'll organise this into small, easy-to-follow slides, each with a quick summary.`,
    },
    {
      key: 'generating_quiz',
      title: 'Finding the right quiz moments...',
      subtitle: `I'll add quick quizzes inside key sections to test your understanding as we move!`,
    },
  ];

  // Determine step status
  const getStepStatus = (stepKey: string) => {
    if (stepKey === 'checking_transcription') {
      if (status === 'checking_transcription') return 'current';
      if (status === 'transcription_failed') return 'failed';
      if (status !== null) return 'completed';
    }
    if (stepKey === 'generating_section') {
      if (status === 'generating_section') return 'current';
      if (status === 'section_creation_failed') return 'failed';
      if (status !== 'checking_transcription' && status !== null) return 'completed';
    }
    if (stepKey === 'generating_quiz') {
      if (status === 'generating_quiz') return 'current';
      if (status === 'quiz_creation_failed') return 'failed';
      if (status === 'completed') return 'completed';
    }
    return 'pending';
  };



  return (
    <div className='flex flex-col'  >
      <div style={{ display: 'flex', gap: 8, marginBottom: 16, marginTop: 16 }}>
        <MentorAiActiveAvatar mentoraiData={mentoraiData} avatarClassName={isPlayerModeDefault ? "h-[16px] w-[16px]" : "h-[20px] w-[20px]"} />
        <p style={{ fontWeight: 500, fontSize: isPlayerModeDefault ? 14 : 16, color: '#DDDDDF', letterSpacing: isPlayerModeDefault ? "0.084px" : "0.096px" }}>{mentoraiData?.name} <span style={{ color: '#94939F' }}>Creating Session...</span></p>
      </div>

      <div style={{ marginTop: 16 }}>
        {steps.map((step, idx) => {
          const stepStatus = getStepStatus(step.key)
          return (
            <div key={step.key} style={{
              display: 'flex', flexDirection: "column", alignItems: 'flex-start',
              gap: isPlayerModeDefault ? 4 : 8,
              marginBottom: isPlayerModeDefault ? 24 : (idx !== steps?.length - 1 ? 44 : 40)
            }}>
              <div className="flex gap-2">
                {stepStatus === 'completed' ? (
                  <img src={CompletedIcon} alt="completed" className='w-4 h-4' style={{ width: isPlayerModeDefault ? "16px" : "20px", height: isPlayerModeDefault ? "16px" : "20px", marginTop: "4px" }} />
                ) : stepStatus === 'current' ? (
                  <img src={LoadingIcon} alt="loading" className='w-4 h-4' style={{ width: isPlayerModeDefault ? "16px" : "20px", height: isPlayerModeDefault ? "16px" : "20px", marginTop: "4px" }} />
                ) : stepStatus === 'failed' ? (
                  <img src={ErrorIcon} alt="error" className='w-4 h-4' style={{ width: isPlayerModeDefault ? "16px" : "20px", height: isPlayerModeDefault ? "16px" : "20px", marginTop: "4px" }} />
                ) : (
                  <img src={LoadingIcon} alt="loading" className='w-4 h-4' style={{ width: isPlayerModeDefault ? "16px" : "20px", height: isPlayerModeDefault ? "16px" : "20px", marginTop: "4px" }} />
                )}

                <p style={{
                  fontWeight: 500,
                  lineHeight: isPlayerModeDefault ? '26px' : '30px',
                  fontSize: isPlayerModeDefault ? 18 : 20,
                  color: stepStatus === 'failed' ? '#FF6875' : '#DDDDDF'
                }}>
                  {stepStatus === 'failed' ? (idx === 1 ? 'Failed to divide video into bite-sized sections.' : 'Failed to add quizzes') : step.title}
                </p>
              </div>

              <p style={{
                color: '#94939F',
                fontSize: isPlayerModeDefault ? 14 : 16,
                letterSpacing: isPlayerModeDefault ? '0.084px' : '0.096px',
                lineHeight: isPlayerModeDefault ? '22px' : '26px',
                fontWeight: 500
              }}>
                {stepStatus === 'failed' ? 'Retrying should help this.' : step.subtitle}
              </p>

              {stepStatus === 'failed' &&
                <MentorAiButton type="secondary" size="large" classNames='!w-fit whitespace-nowrap' style={{ marginTop: "16px", height: isPlayerModeDefault ? "32px" : "40px" }} onClick={toggleLearningSession}>
                  <span style={{ fontWeight: 500, fontSize: 14, lineHeight: '22px', paddingLeft: isPlayerModeDefault ? "8px" : "18px", paddingRight: isPlayerModeDefault ? "12px" : "24px", display: "flex", whiteSpace: "nowrap", gap: "4px" }}>
                    <img src={RefreshIcon} alt="refresh" className='w-[18px] h-[18px] mt-1' style={{ width: "18px", height: "18px", marginTop: "2px" }} />
                    Retry
                  </span>
                </MentorAiButton>}
            </div>
          );
        })}
      </div>

      <div style={{ display: 'flex', gap: 12, marginTop: 24, flexWrap: "wrap" }}>
        <MentorAiButton type="primary" size="large" disabled={true} classNames='!w-fit whitespace-nowrap ' style={{ paddingLeft: isPlayerModeDefault ? "12px" : "24px", paddingRight: isPlayerModeDefault ? "12px" : "24px", height: isPlayerModeDefault ? "32px" : "40px" }} onClick={() => { }}>
          <span style={{ fontWeight: 500, fontSize: 14, lineHeight: '22px' }}>
            View First Section
          </span>
        </MentorAiButton>
      </div>
    </div>
  );
};

export default CreatingOverlay; 