import { useEffect, useState } from 'react'
import MentorAiActiveAvatar from '../../mentorai-active-avatar/mentorai-active-avatar'
import { useCustomUI } from '../../../contexts/custom-ui-context/custom-ui-context'

const SectionEndNotification = ({ mentorAiData }: { mentorAiData: any }) => {
    const [time, setTime] = useState<number>(5)
    const {
        sessionOverlayView,
        currentSection,
        setSessionOverlayView,
        setSectionEndScreen,
        pauseVideo,
        markSectionEndScreenShown,
        setShowSectionEndNotification,
    } = useCustomUI()

    useEffect(() => {
        const interval = setInterval(() => {
            if (time > 0) {
                setTime(time - 1)
            } else {
                setTime(0)
                pauseVideo();
                setSectionEndScreen('explore_quiz');
                setSessionOverlayView('section_end');
                markSectionEndScreenShown(currentSection);

                setShowSectionEndNotification(false);
                clearInterval(interval);
            }
        }, 1000)
        return () => clearInterval(interval)
    }, [time, pauseVideo, setSectionEndScreen, setSessionOverlayView, markSectionEndScreenShown, setShowSectionEndNotification, currentSection])

    return (time > 0 && sessionOverlayView === 'hidden') ? (
        <div className='absolute top-[28px] bg-yt-session-default-bg rounded-tr-xl rounded-br-xl flex justify-center items-center' style={{ padding: "16px", whiteSpace: "nowrap", height: '54px', gap: '4px', zIndex: '100' }}>
            <MentorAiActiveAvatar mentoraiData={mentorAiData} />
            <p style={{ fontSize: "16px", lineHeight: "24px", fontWeight: 500, color: "#DDDDDF", letterSpacing: "0.096px" }}>{mentorAiData?.name}</p>
            <p style={{ fontSize: "16px", lineHeight: "24px", fontWeight: 500, color: "#FFE097", letterSpacing: "0.096px", whiteSpace: "nowrap" }}>🏁 Section ending in {time}...</p>
        </div>
    ) : null
}

export default SectionEndNotification