import React from 'react'
import SectionDetailsWithCTA from './components/section-details-with-cta'
import MentorAiAvatarHeader from './components/mentorai-avatar-header'
import { useCustomUI } from '../../../contexts/custom-ui-context/custom-ui-context';
import SectionDurationAndDetails from './components/section-duration-and-details';
import MentorAiButton from '../../../../common/button/mentorai-button';
import PlayIcon from '../../../assets/icons/white-play.svg'
import SkipIcon from '../../../assets/icons/skip.svg'
import MentorAiActiveAvatar from '../../mentorai-active-avatar/mentorai-active-avatar';
// import { useChat } from '../../../contexts/chat-context/chat-context';

const SectionOngoingOverlay = ({ isSidePanelOpen }: { isSidePanelOpen: boolean }) => {
    const { mentoraiData, handleJumpToNextSection, playerMode, learningSession, handleResumeVideo, setSelectedSection, selectedSection, currentSection, trackCustomUIEvent, getCurrentSectionProperties, getSectionProperties } = useCustomUI();
    // const { sendMessage ,setSelectedYouTubeSideSectionTab} = useChat();
    const section = learningSession?.sections?.[selectedSection || 0]
    const isCurrentSectionSelected = currentSection === selectedSection
    const canJumpToNext = !isCurrentSectionSelected && (selectedSection || selectedSection === 0) && selectedSection < (learningSession?.sections?.length || 0) - 1;
    const handleBackToSection = () => {
        setSelectedSection(currentSection)
    }
    const showBackToSectionCta = currentSection !== selectedSection
    const isSelectedSectionComplete = (selectedSection !== null && selectedSection !== undefined) && learningSession?.sections?.[selectedSection]?.status === 'completed'
    const handleAskQuestion = () => {
        // sendMessage("I have a doubt in this section")
        // setSelectedYouTubeSideSectionTab('Chat')

        if (!isSidePanelOpen) {
            chrome.runtime.sendMessage({ action: "openSidePanel" }).then(() => {
                setTimeout(() => {
                    chrome.runtime.sendMessage({
                        action: "easyActionClicked",
                        easy_action: "Have a Doubt",
                        easy_action_title: "Have a Doubt",
                        url: window.location.href,
                        is_side_panel_opened: false,
                        section_title: "Section Ongoing Screen",
                        easy_action_message: "I have a doubt in this section",
                    });
                }, 3000);
            });
        } else {
            chrome.runtime.sendMessage({
                action: "easyActionClicked",
                easy_action: "Have a Doubt",
                easy_action_title: "Have a Doubt",
                url: window.location.href,
                is_side_panel_opened: true,
                section_title: "Section Ongoing Screen",
                easy_action_message: "I have a doubt in this section",
            });
        }

        // trackCustomUIEvent("Easy Action Clicked", {
        //     info: {
        //         easy_action: "Have a Doubt",
        //         easy_action_title: "Have a Doubt",
        //         section_title: "Section Ongoing Screen",
        //         easy_action_message: "I have a doubt in this section",
        //     }
        // })
    }

    const isPlayerModeDefault = playerMode === "DEFAULT";

    const handleWatchSection = (buttonType: string) => {
        handleResumeVideo()
        trackCustomUIEvent("MentorAi Section Played", {
            section: getSectionProperties(selectedSection || 0),
            action: buttonType
        })
    }

    return (
        <div className='flex flex-col '>
            {showBackToSectionCta ? <p className="text-primary-lighter hover:text-primary-light text-left  font-medium leading-6" style={{ cursor: 'pointer', fontSize: isPlayerModeDefault ? 14 : 16, lineHeight: isPlayerModeDefault ? '22px' : '24px', letterSpacing: isPlayerModeDefault ? '0.084px' : '0.964px', marginBottom: isPlayerModeDefault ? '12px' : '16px' }} onClick={handleBackToSection}> &larr; Back to Section {currentSection + 1}</p> : <div style={{ height: 40, width: '100%' }} />}

            <MentorAiAvatarHeader
                mentoraiData={mentoraiData}
                primaryStatus={isSelectedSectionComplete ?
                    <span style={{ color: "#84EBB4" }}>✅ Complete : </span> :
                    (!showBackToSectionCta ? <span style={{ color: "#94939F" }}>Now Watching : </span> : null)
                }
                secondaryStatus={<span style={{ color: "#94939F" }}>Section {(selectedSection || 0) + 1} of {learningSession?.sections?.length}</span>}
            />
            <SectionDetailsWithCTA
                sectionTitle={section?.sectionTitle}
                sectionDurationAndDetails={<SectionDurationAndDetails />}
                sectionDescription={section?.sectionDescription}
                sectionCTAs={
                    <div className="flex flex-row flex-wrap" style={{ gap: isPlayerModeDefault ? '8px' : "12px", marginTop: isPlayerModeDefault ? '28px' : "44px" }}>

                        {isCurrentSectionSelected ?
                            <>
                                <MentorAiButton
                                    type="secondary"
                                    size="large"
                                    rounded={true}
                                    onClick={() => handleWatchSection("Resumed")}
                                    style={{
                                        height: isPlayerModeDefault ? '32px' : '40px',
                                        width: isPlayerModeDefault ? '32px' : '40px',
                                        maxHeight: isPlayerModeDefault ? '32px' : '40px'
                                    }}
                                >
                                    <img src={PlayIcon} alt="play" style={{ width: 18, height: 18 }} />
                                </MentorAiButton>

                                <MentorAiButton
                                    type="primary"
                                    size="large"
                                    onClick={handleAskQuestion}
                                    classNames=' !w-fit whitespace-nowrap'
                                    style={{
                                        paddingLeft: isPlayerModeDefault ? "8px" : "18px",
                                        paddingRight: isPlayerModeDefault ? "12px" : "24px",
                                        height: isPlayerModeDefault ? '32px' : '40px',
                                        maxHeight: isPlayerModeDefault ? '32px' : '40px'
                                    }}
                                >
                                    <span style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 14, fontWeight: 500, lineHeight: "22px", letterSpacing: "0.084px", color: "#F2F2F2" }}>
                                        <MentorAiActiveAvatar mentoraiData={mentoraiData} indicatorClassName=' border-mentorai-primary-base' />
                                        Have a doubt
                                    </span>
                                </MentorAiButton>
                            </>
                            :
                            <>
                                <MentorAiButton
                                    type="primary"
                                    size="large"
                                    classNames='!w-fit whitespace-nowrap'
                                    onClick={() => handleWatchSection(isSelectedSectionComplete ? "Rewatched" : "Started")}
                                    style={{
                                        paddingLeft: isPlayerModeDefault ? "8px" : "18px",
                                        paddingRight: isPlayerModeDefault ? "12px" : "24px",
                                        height: isPlayerModeDefault ? '32px' : '40px'
                                    }}
                                >
                                    <span style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 14, fontWeight: 500, lineHeight: "22px", letterSpacing: "0.084px", color: "#F2F2F2" }}>
                                        <img src={PlayIcon} alt="play" style={{ width: 18, height: 18 }} />
                                        {isSelectedSectionComplete ? "Rewatch" : "Start Watching"}
                                    </span>
                                </MentorAiButton>

                                {canJumpToNext ? (
                                    <MentorAiButton
                                        type="secondary"
                                        size="large"
                                        onClick={handleJumpToNextSection}
                                        classNames=' !h-fit whitespace-nowrap'
                                        style={{
                                            paddingLeft: isPlayerModeDefault ? "8px" : "18px",
                                            paddingRight: isPlayerModeDefault ? "12px" : "24px",
                                            height: isPlayerModeDefault ? '32px' : '40px',
                                            maxHeight: isPlayerModeDefault ? '32px' : '40px'
                                        }}
                                    >
                                        <span style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 14, fontWeight: 500, lineHeight: "22px", letterSpacing: "0.084px", color: "#F2F2F2" }}>
                                            <img src={SkipIcon} alt="skip" style={{ width: 18, height: 18 }} />
                                            Jump to Next Section
                                        </span>
                                    </MentorAiButton>
                                ) : null}
                            </>
                        }
                    </div>
                }
            />

            <div style={{ height: 40, width: '100%' }} />
        </div >
    )
}

export default SectionOngoingOverlay