import React from 'react';

const TextSkeleton = ({ height, width, containerStyle, isYouTubeThemeDark }: { height: string, width: string, containerStyle?: React.CSSProperties, isYouTubeThemeDark?: boolean }) => {
  return <div style={{ ...containerStyle }}>
    <style>
      {`
      .shimmer {
        position: relative;
        overflow: hidden;
        background: ${isYouTubeThemeDark ? '#36394e' : 'linear-gradient(94deg, #FFE1CC 6.12%, #FADBFF 52.18%, #EAE5FF 96.4%)'};
      }
      .shimmer::after {
        content: '';
        position: absolute;
        top: 0;
        left: -150px;
        width: 150px;
        height: 100%;
        background: ${isYouTubeThemeDark 
          ? 'linear-gradient(90deg, rgba(54,57,78,0) 0%, rgba(255,255,255,0.15) 50%, rgba(54,57,78,0) 100%)'
          : 'linear-gradient(90deg, rgba(255,225,204,0) 0%, rgba(255,255,255,0.3) 50%, rgba(255,225,204,0) 100%)'
        };
        animation: shimmer 1.5s infinite;
      }
      @keyframes shimmer {
        100% {
          left: 100%;
        }
      }
    `}
    </style>
    <div style={{ width: width, height: height, borderRadius: '4px' }} className="shimmer" />
  </div>
};

export default TextSkeleton;
